-- =============================================
-- FULL DATABASE SCHEMA - FINANCE TRACKER
-- Consolidated reference synchronized with repository migration history.
-- Ordered schema history lives in server/migrations/.
-- This file does not prove the state of an external database.
-- =============================================
-- Table creation order respects FK dependencies.
-- RLS policies are included for the original 5 tables only.
-- =============================================


-- =============================================
-- SECTION 1: FOUNDATION TABLES (no domain deps)
-- =============================================

-- Categories: transaction classification with auto-learning keywords
CREATE TABLE IF NOT EXISTS categories (
  id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name        TEXT NOT NULL,
  type        TEXT NOT NULL DEFAULT 'expense' CHECK (type IN ('income', 'expense')),
  keywords    TEXT[] DEFAULT '{}',
  icon        TEXT,
  is_active   BOOLEAN NOT NULL DEFAULT true,
  created_at  TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text, now()),
  updated_at  TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text, now())
);

-- Payment sources: credit cards, bank accounts, cash, etc.
CREATE TABLE IF NOT EXISTS payment_sources (
  id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name        TEXT NOT NULL,
  method      TEXT NOT NULL CHECK (method IN ('credit_card', 'debit_card', 'cash', 'bank_transfer', 'digital_wallet', 'check')),
  owner       TEXT,
  slug        TEXT NOT NULL UNIQUE,
  is_active   BOOLEAN NOT NULL DEFAULT true,
  issuer      TEXT,
  last4       TEXT,
  created_at  TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text, now()),
  updated_at  TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text, now())
);

-- Shopping list templates (e.g. grocery, pharmacy)
CREATE TABLE IF NOT EXISTS shopping_list_types (
  id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name        TEXT NOT NULL,
  slug        TEXT NOT NULL UNIQUE,
  is_active   BOOLEAN NOT NULL DEFAULT true,
  created_at  TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text, now())
);

-- Shopping catalog categories (separate from financial categories)
CREATE TABLE IF NOT EXISTS shopping_catalog_categories (
  id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name        TEXT NOT NULL UNIQUE,
  icon        TEXT,
  is_active   BOOLEAN NOT NULL DEFAULT true,
  created_at  TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text, now()),
  updated_at  TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text, now())
);

-- Loans: must be defined before transactions due to FK on transactions.loan_id
CREATE TABLE IF NOT EXISTS loans (
  id                      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  created_at              TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text, now()),
  name                    TEXT NOT NULL,
  lender_name             TEXT,
  loan_type               TEXT,
  original_amount         NUMERIC NOT NULL,
  current_balance         NUMERIC NOT NULL,
  monthly_payment         NUMERIC,
  interest_rate           NUMERIC,
  linkage_type            TEXT,
  total_installments      INTEGER,
  remaining_installments  INTEGER,
  start_date              DATE,
  end_date                DATE,
  status                  TEXT DEFAULT 'active' CHECK (status IN ('active', 'paid', 'defaulted')),
  notes                   TEXT,
  amortization_type       TEXT DEFAULT 'spitzer',
  interest_type           TEXT DEFAULT 'fixed',
  prime_margin            NUMERIC DEFAULT 0,
  indexation_type         TEXT NOT NULL DEFAULT 'none'
                          CHECK (indexation_type IN ('none', 'cpi')),
  base_index              NUMERIC(18,4)
                          CHECK (base_index IS NULL OR base_index > 0),
  balloon_amount          NUMERIC DEFAULT 0,
  grace_months            INTEGER DEFAULT 0,
  calculation_mode        TEXT NOT NULL DEFAULT 'legacy'
                          CHECK (calculation_mode IN ('legacy', 'loan_payments')),
  next_payment_date       DATE,
  payment_source_id       BIGINT REFERENCES payment_sources(id),
  auto_payment_enabled    BOOLEAN NOT NULL DEFAULT true,
  closed_date             DATE
);

CREATE INDEX idx_loans_status ON loans (status);


-- =============================================
-- SECTION 2: CORE FINANCIAL TABLES
-- =============================================

-- Main transaction records.
-- Note: id uses the legacy serial/sequence style (INTEGER, not BIGINT IDENTITY).
-- payment_method and payment_source are legacy columns superseded by payment_source_id.
-- current_installment is a legacy field; installment_number/count are the current fields.
CREATE TABLE IF NOT EXISTS transactions (
  id                      SERIAL PRIMARY KEY,
  transaction_date        DATE NOT NULL,
  description             CHARACTER VARYING,
  movement_type           CHARACTER VARYING NOT NULL CHECK (movement_type IN ('expense', 'income')),
  total_amount            NUMERIC NOT NULL,
  charge_date             DATE NOT NULL DEFAULT CURRENT_DATE,
  category_id             BIGINT REFERENCES categories(id),
  payment_source_id       BIGINT REFERENCES payment_sources(id),
  loan_id                 BIGINT REFERENCES loans(id),
  global_discount         NUMERIC DEFAULT 0,
  global_discount_source  TEXT CHECK (
    global_discount_source IS NULL
    OR global_discount_source IN ('loyalty_points', 'coupon', 'store_credit', 'other')
  ),
  original_amount         NUMERIC,
  currency                TEXT DEFAULT 'ILS',
  exchange_rate           NUMERIC,
  installments_info       TEXT,
  installment_number      INTEGER,
  installment_count       INTEGER,
  parent_transaction_id   BIGINT REFERENCES transactions(id),
  current_installment     INTEGER,                    -- legacy field, superseded by installment_number
  payment_method          CHARACTER VARYING,          -- legacy field, superseded by payment_source_id
  payment_source          TEXT,                       -- legacy field, superseded by payment_source_id
  tags                    TEXT,
  external_id             TEXT,
  notes                   TEXT,
  created_at              TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
  updated_at              TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now())
);

CREATE INDEX idx_transactions_loan_id ON transactions (loan_id);
CREATE INDEX idx_transactions_payment_source_id ON transactions (payment_source_id);
CREATE UNIQUE INDEX idx_transactions_external_id
  ON transactions (external_id)
  WHERE external_id IS NOT NULL;

-- Added by migrations/003_transaction_pagination_and_aggregates.sql
-- Backs the default list branch: ORDER BY transaction_date DESC, id DESC, its
-- keyset seek, and the from/to range filter. One ordered index scan serves the
-- sort and the cursor together.
--
-- It does NOT fully serve the ascending branch, which orders by
-- (transaction_date ASC, id DESC): a backward scan of this index yields
-- (transaction_date ASC, id ASC), so Postgres adds a sort node there. The
-- id DESC tiebreaker is kept uniform across branches on purpose.
--
-- No index is defined for the amount or description sort branches; see the
-- migration for the cost analysis and the four indexes that would be needed.
CREATE INDEX idx_transactions_date_id_desc ON transactions (transaction_date DESC, id DESC);

-- Authoritative amortization/accounting entries for audited loans. Cash
-- activity remains in transactions; principal and interest live here.
CREATE TABLE IF NOT EXISTS loan_payments (
  id                    BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  loan_id               BIGINT NOT NULL REFERENCES loans(id) ON DELETE CASCADE,
  transaction_id        BIGINT REFERENCES transactions(id) ON DELETE SET NULL,
  installment_number    INTEGER,
  payment_date          DATE NOT NULL,
  payment_amount        NUMERIC(18, 2) NOT NULL CHECK (payment_amount >= 0),
  principal_amount      NUMERIC(24, 10) NOT NULL CHECK (principal_amount >= 0),
  interest_amount       NUMERIC(24, 10) NOT NULL CHECK (interest_amount >= 0),
  annual_interest_rate  NUMERIC(12, 6) CHECK (
    annual_interest_rate IS NULL OR annual_interest_rate >= 0
  ),
  source_kind           TEXT NOT NULL
                        CHECK (source_kind IN ('existing_transaction', 'reconstructed', 'manual', 'generated')),
  payment_kind          TEXT NOT NULL DEFAULT 'installment'
                        CHECK (payment_kind IN ('installment', 'catch_up', 'irregular_payment', 'balance_adjustment', 'early_payoff')),
  installments_covered  INTEGER NOT NULL DEFAULT 1,
  other_amount          NUMERIC(24, 10) NOT NULL DEFAULT 0,
  balance_adjustment_amount NUMERIC(24, 10) NOT NULL DEFAULT 0,
  scheduled_due_date    DATE,
  next_scheduled_due_date DATE,
  auto_payment_enabled_before BOOLEAN,
  notes                 TEXT,
  created_at            TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text, now()),
  updated_at            TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text, now()),
  UNIQUE (transaction_id),
  CHECK (
    (payment_kind = 'installment' AND installment_number IS NOT NULL
      AND installment_number > 0 AND installments_covered = 1)
    OR (payment_kind = 'catch_up' AND installment_number IS NULL
      AND installments_covered >= 1)
    OR (payment_kind IN ('irregular_payment', 'balance_adjustment', 'early_payoff')
      AND installment_number IS NULL AND installments_covered = 0)
  ),
  CONSTRAINT loan_payments_irregular_payment_shape_check CHECK (
    payment_kind <> 'irregular_payment'
    OR (payment_amount > 0 AND balance_adjustment_amount = 0)
  ),
  CONSTRAINT loan_payments_balance_adjustment_shape_check CHECK (
    payment_kind <> 'balance_adjustment'
    OR (transaction_id IS NULL AND payment_amount = 0
      AND principal_amount = 0 AND interest_amount = 0 AND other_amount = 0)
  ),
  CONSTRAINT loan_payments_components_reconcile CHECK (
    abs(payment_amount - principal_amount - interest_amount - other_amount)
      <= 0.00000001
  )
);

CREATE INDEX idx_loan_payments_loan_date
  ON loan_payments (loan_id, payment_date, installment_number);
CREATE UNIQUE INDEX loan_payments_unique_installment
  ON loan_payments (loan_id, installment_number)
  WHERE payment_kind = 'installment';
CREATE UNIQUE INDEX loan_payments_unique_early_payoff
  ON loan_payments (loan_id)
  WHERE payment_kind = 'early_payoff';

-- Line items for a transaction (individual products, LEGO sets, etc.)
-- Note: uses legacy SERIAL id. No created_at column in the real DB.
CREATE TABLE IF NOT EXISTS transaction_items (
  id                SERIAL PRIMARY KEY,
  transaction_id    INTEGER REFERENCES transactions(id),
  item_name         CHARACTER VARYING NOT NULL,
  quantity          INTEGER DEFAULT 1,
  price_per_unit    NUMERIC,
  total_item_price  NUMERIC,
  set_number        TEXT,
  theme             TEXT,
  brand             TEXT,
  pieces            INTEGER,
  image_url         TEXT,
  discount_type     TEXT DEFAULT 'amount' CHECK (discount_type IN ('amount', 'percent')),
  discount_value    NUMERIC DEFAULT 0,
  final_price       NUMERIC DEFAULT 0,
  allocated_global_discount NUMERIC NOT NULL DEFAULT 0 CHECK (allocated_global_discount >= 0),
  acquisition_type  TEXT NOT NULL DEFAULT 'purchase'
                    CHECK (acquisition_type IN ('purchase', 'gift', 'gwp')),
  tags              TEXT
);

-- LEGO set collection records. Created automatically on Lego-category transactions.
-- Note: id is UUID, not BIGINT. No CHECK constraints on status or brand in the DB.
CREATE TABLE IF NOT EXISTS lego_sets (
  id              UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  set_number      TEXT NOT NULL,
  name            TEXT NOT NULL,
  theme           TEXT,
  pieces          INTEGER,
  image_url       TEXT,
  purchase_price  NUMERIC,
  receipt_price   NUMERIC,
  original_price  NUMERIC DEFAULT 0,
  status          TEXT DEFAULT 'New',
  brand           TEXT DEFAULT 'LEGO',
  acquisition_type TEXT NOT NULL DEFAULT 'purchase'
                   CHECK (acquisition_type IN ('purchase', 'gift', 'gwp')),
  purchase_date   DATE,
  transaction_id  INTEGER REFERENCES transactions(id),
  created_at      TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now())
);

-- Monthly budget targets per category
CREATE TABLE IF NOT EXISTS budgets (
  id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  category_id  BIGINT REFERENCES categories(id),
  month        TEXT NOT NULL,               -- format: 'YYYY-MM'
  amount       NUMERIC NOT NULL DEFAULT 0,
  created_at   TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text, now()),
  updated_at   TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text, now()),
  UNIQUE (category_id, month)
);


-- =============================================
-- SECTION 3: SHOPPING MODULE
-- =============================================

-- Reusable product catalog, scoped to a shopping catalog category
CREATE TABLE IF NOT EXISTS shopping_catalog_items (
  id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  category_id    BIGINT NOT NULL REFERENCES shopping_catalog_categories(id),
  name           TEXT NOT NULL,
  default_unit   TEXT,
  default_price  NUMERIC,
  is_active      BOOLEAN NOT NULL DEFAULT true,
  created_at     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text, now()),
  updated_at     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text, now()),
  UNIQUE (category_id, name)
);

CREATE INDEX idx_catalog_items_category ON shopping_catalog_items (category_id);

-- M2M: which catalog categories are available for each list type
CREATE TABLE IF NOT EXISTS shopping_catalog_category_list_types (
  category_id   BIGINT NOT NULL REFERENCES shopping_catalog_categories(id),
  list_type_id  BIGINT NOT NULL REFERENCES shopping_list_types(id),
  created_at    TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text, now()),
  PRIMARY KEY (category_id, list_type_id)
);

CREATE INDEX idx_category_list_types_list_type ON shopping_catalog_category_list_types (list_type_id, category_id);

-- Shopping list headers
CREATE TABLE IF NOT EXISTS shopping_lists (
  id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  title         TEXT NOT NULL,
  list_type_id  BIGINT NOT NULL REFERENCES shopping_list_types(id),
  status        TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('draft', 'active', 'checked_out', 'archived')),
  created_at    TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text, now()),
  updated_at    TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text, now())
);

CREATE INDEX idx_shopping_lists_type_status ON shopping_lists (list_type_id, status);

-- Individual items within a shopping list.
-- Each item is either a catalog item (catalog_item_id set) or a custom entry (custom_name set), never both.
CREATE TABLE IF NOT EXISTS shopping_list_items (
  id               BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  list_id          BIGINT NOT NULL REFERENCES shopping_lists(id),
  catalog_item_id  BIGINT REFERENCES shopping_catalog_items(id),
  custom_name      TEXT,
  category_id      BIGINT NOT NULL REFERENCES shopping_catalog_categories(id),
  quantity         NUMERIC,
  unit             TEXT,
  price            NUMERIC,
  is_purchased     BOOLEAN NOT NULL DEFAULT false,
  purchased_at     TIMESTAMP WITH TIME ZONE,
  notes            TEXT,
  created_at       TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text, now()),
  updated_at       TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text, now()),
  CHECK (
    (catalog_item_id IS NOT NULL AND custom_name IS NULL)
    OR
    (catalog_item_id IS NULL AND custom_name IS NOT NULL AND trim(custom_name) <> '')
  )
);

CREATE INDEX idx_shopping_list_items_list ON shopping_list_items (list_id);
CREATE INDEX idx_shopping_list_items_list_category ON shopping_list_items (list_id, category_id);
CREATE INDEX idx_shopping_list_items_purchased ON shopping_list_items (list_id, is_purchased);

-- Records the checkout event for a shopping list.
-- One checkout per list (list_id is UNIQUE).
-- payment_source_id, category_id, transaction_id reference other tables but have no DB-level FK constraints.
CREATE TABLE IF NOT EXISTS shopping_checkouts (
  id                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  list_id           BIGINT NOT NULL UNIQUE REFERENCES shopping_lists(id),
  checkout_date     DATE NOT NULL DEFAULT (timezone('utc'::text, now()))::date,
  total_amount      NUMERIC NOT NULL CHECK (total_amount >= 0),
  payment_method    TEXT NOT NULL DEFAULT 'credit_card' CHECK (payment_method IN ('credit_card', 'cash', 'bank_transfer', 'direct_debit', 'bit', 'paypal', 'other')),
  payment_source_id BIGINT,
  category_id       BIGINT,
  transaction_id    BIGINT,
  created_at        TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text, now())
);

CREATE INDEX idx_shopping_checkouts_date ON shopping_checkouts (checkout_date DESC);


-- =============================================
-- SECTION 5: ROW LEVEL SECURITY
-- Confirmed for original 5 tables only.
-- All policies use permissive USING (true) —
-- access control is handled at the application layer.
-- =============================================

ALTER TABLE categories       ENABLE ROW LEVEL SECURITY;
ALTER TABLE payment_sources  ENABLE ROW LEVEL SECURITY;
ALTER TABLE transactions     ENABLE ROW LEVEL SECURITY;
ALTER TABLE transaction_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE loan_payments    ENABLE ROW LEVEL SECURITY;
ALTER TABLE budgets          ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Public Access Categories"      ON categories       FOR ALL USING (true);
CREATE POLICY "Public Access Payment Sources" ON payment_sources  FOR ALL USING (true);
CREATE POLICY "Public Access Transactions"    ON transactions     FOR ALL USING (true);
CREATE POLICY "Public Access Items"           ON transaction_items FOR ALL USING (true);
CREATE POLICY "Public Access Budgets"         ON budgets          FOR ALL USING (true);


-- =============================================
-- SECTION 5A: LOAN ACCOUNTING FUNCTIONS/TRIGGERS
-- Source: migrations/008_loan_payment_accounting.sql through
-- migrations/015_manual_loan_repayments.sql
-- =============================================

CREATE OR REPLACE FUNCTION public.refresh_loan_summary(p_loan_id BIGINT)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_loan public.loans%ROWTYPE;
  v_installments_covered BIGINT := 0;
  v_early_payoff_count BIGINT := 0;
  v_paid_principal NUMERIC := 0;
  v_balance_adjustment NUMERIC := 0;
  v_cash_total NUMERIC := 0;
  v_balance NUMERIC := 0;
  v_remaining INTEGER := 0;
  v_closed_date DATE;
BEGIN
  IF p_loan_id IS NULL THEN RETURN; END IF;

  SELECT * INTO v_loan
  FROM public.loans
  WHERE id = p_loan_id
  FOR UPDATE;
  IF NOT FOUND THEN RETURN; END IF;

  IF v_loan.calculation_mode = 'loan_payments' THEN
    SELECT
      coalesce(sum(installments_covered) FILTER (
        WHERE payment_kind IN ('installment', 'catch_up')
      ), 0),
      count(*) FILTER (WHERE payment_kind = 'early_payoff'),
      coalesce(sum(principal_amount), 0),
      coalesce(sum(balance_adjustment_amount), 0)
    INTO v_installments_covered, v_early_payoff_count,
      v_paid_principal, v_balance_adjustment
    FROM public.loan_payments
    WHERE loan_id = p_loan_id;

    IF v_installments_covered > coalesce(v_loan.total_installments, 0) THEN
      RAISE EXCEPTION 'Loan % payment coverage exceeds total installments', p_loan_id;
    END IF;

    v_balance := round(greatest(
      v_loan.original_amount - v_paid_principal - v_balance_adjustment,
      0
    ), 2);

    IF v_early_payoff_count > 0 AND v_balance > 0.005 THEN
      RAISE EXCEPTION 'Loan % early payoff does not clear its outstanding principal',
        p_loan_id;
    END IF;

    IF v_balance <= 0.005 THEN
      SELECT payment_date INTO v_closed_date
      FROM public.loan_payments
      WHERE loan_id = p_loan_id
      ORDER BY
        CASE WHEN payment_kind = 'early_payoff' THEN 0 ELSE 1 END,
        payment_date DESC,
        id DESC
      LIMIT 1;
      v_remaining := 0;
    ELSE
      v_closed_date := NULL;
      v_remaining := greatest(
        coalesce(v_loan.total_installments, 0) - v_installments_covered,
        0
      )::integer;
    END IF;

    UPDATE public.loans
    SET
      current_balance = CASE WHEN v_balance <= 0.005 THEN 0 ELSE v_balance END,
      remaining_installments = v_remaining,
      next_payment_date = CASE
        WHEN v_balance <= 0.005 THEN NULL
        ELSE next_payment_date
      END,
      auto_payment_enabled = CASE
        WHEN v_balance <= 0.005 THEN false
        ELSE auto_payment_enabled
      END,
      closed_date = v_closed_date,
      status = CASE
        WHEN v_balance <= 0.005 THEN 'paid'
        WHEN v_loan.status = 'defaulted' THEN 'defaulted'
        ELSE 'active'
      END
    WHERE id = p_loan_id;
  ELSE
    SELECT count(*), coalesce(sum(total_amount), 0)
    INTO v_installments_covered, v_cash_total
    FROM public.transactions
    WHERE loan_id = p_loan_id;

    UPDATE public.loans
    SET
      current_balance = v_loan.original_amount - v_cash_total,
      remaining_installments = coalesce(v_loan.total_installments, 0) - v_installments_covered
    WHERE id = p_loan_id;
  END IF;
END;
$$;

CREATE OR REPLACE FUNCTION public.recalculate_loan_status()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM public.refresh_loan_summary(NEW.loan_id);
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    PERFORM public.refresh_loan_summary(OLD.loan_id);
    RETURN OLD;
  END IF;
  IF OLD.loan_id IS DISTINCT FROM NEW.loan_id THEN
    PERFORM public.refresh_loan_summary(OLD.loan_id);
  END IF;
  PERFORM public.refresh_loan_summary(NEW.loan_id);
  RETURN NEW;
END;
$$;

CREATE TRIGGER on_transaction_change
AFTER INSERT OR UPDATE OR DELETE ON transactions
FOR EACH ROW
EXECUTE FUNCTION public.recalculate_loan_status();

CREATE OR REPLACE FUNCTION public.refresh_loan_summary_from_payment()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM public.refresh_loan_summary(NEW.loan_id);
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    PERFORM public.refresh_loan_summary(OLD.loan_id);
    RETURN OLD;
  END IF;
  IF OLD.loan_id IS DISTINCT FROM NEW.loan_id THEN
    PERFORM public.refresh_loan_summary(OLD.loan_id);
  END IF;
  PERFORM public.refresh_loan_summary(NEW.loan_id);
  RETURN NEW;
END;
$$;

CREATE TRIGGER on_loan_payment_change
AFTER INSERT OR UPDATE OR DELETE ON loan_payments
FOR EACH ROW
EXECUTE FUNCTION public.refresh_loan_summary_from_payment();

CREATE OR REPLACE FUNCTION public.sync_loan_payment_from_transaction(
  p_transaction_id BIGINT,
  p_record_loan_payment BOOLEAN DEFAULT true
)
RETURNS public.loan_payments
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_transaction public.transactions%ROWTYPE;
  v_loan public.loans%ROWTYPE;
  v_existing public.loan_payments%ROWTYPE;
  v_result public.loan_payments%ROWTYPE;
  v_installment_number INTEGER;
  v_installments_covered BIGINT := 0;
  v_opening_principal NUMERIC;
  v_payment NUMERIC;
  v_interest NUMERIC;
  v_principal NUMERIC;
BEGIN
  SELECT * INTO v_transaction FROM public.transactions
  WHERE id = p_transaction_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Transaction % does not exist', p_transaction_id;
  END IF;

  SELECT * INTO v_existing FROM public.loan_payments
  WHERE transaction_id = p_transaction_id FOR UPDATE;
  IF v_existing.id IS NOT NULL AND v_existing.source_kind <> 'existing_transaction' THEN
    RAISE EXCEPTION
      'Transaction % is linked to a % loan payment and cannot be synchronized automatically',
      p_transaction_id, v_existing.source_kind;
  END IF;

  IF NOT p_record_loan_payment OR v_transaction.loan_id IS NULL THEN
    IF v_existing.id IS NOT NULL THEN
      DELETE FROM public.loan_payments WHERE id = v_existing.id RETURNING * INTO v_result;
    END IF;
    RETURN v_result;
  END IF;

  SELECT * INTO v_loan FROM public.loans
  WHERE id = v_transaction.loan_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Loan % does not exist', v_transaction.loan_id;
  END IF;

  IF v_loan.calculation_mode <> 'loan_payments' THEN
    IF v_existing.id IS NOT NULL THEN
      DELETE FROM public.loan_payments WHERE id = v_existing.id RETURNING * INTO v_result;
    END IF;
    RETURN v_result;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.loan_payments
    WHERE loan_id = v_loan.id
      AND payment_kind = 'early_payoff'
      AND id IS DISTINCT FROM v_existing.id
  ) THEN
    RAISE EXCEPTION 'Loan % has an early payoff and cannot accept another regular installment',
      v_loan.id;
  END IF;

  SELECT coalesce(sum(installments_covered), 0)
  INTO v_installments_covered
  FROM public.loan_payments
  WHERE loan_id = v_loan.id
    AND payment_kind IN ('installment', 'catch_up')
    AND id IS DISTINCT FROM v_existing.id;

  IF v_transaction.installment_number IS NOT NULL
    AND v_transaction.installment_number > 0 THEN
    v_installment_number := v_transaction.installment_number;
  ELSIF v_existing.id IS NOT NULL AND v_existing.loan_id = v_loan.id THEN
    v_installment_number := v_existing.installment_number;
  ELSE
    v_installment_number := v_installments_covered + 1;
  END IF;

  IF v_loan.total_installments IS NOT NULL
    AND v_installment_number > v_loan.total_installments THEN
    RAISE EXCEPTION 'Installment % exceeds total installments % for loan %',
      v_installment_number, v_loan.total_installments, v_loan.id;
  END IF;

  IF EXISTS (SELECT 1 FROM public.loan_payments later
    WHERE later.loan_id = v_loan.id
      AND later.payment_kind = 'installment'
      AND later.installment_number > v_installment_number
      AND later.id IS DISTINCT FROM v_existing.id) THEN
    RAISE EXCEPTION
      'Cannot insert or reprice installment % while later loan payments exist',
      v_installment_number;
  END IF;

  SELECT greatest(
    v_loan.original_amount
      - coalesce(sum(principal_amount), 0)
      - coalesce(sum(balance_adjustment_amount), 0),
    0
  )
  INTO v_opening_principal FROM public.loan_payments
  WHERE loan_id = v_loan.id
    AND id IS DISTINCT FROM v_existing.id
    AND (
      (payment_kind = 'installment' AND installment_number < v_installment_number)
      OR (payment_kind IN ('catch_up', 'balance_adjustment')
        AND payment_date <= v_transaction.charge_date)
    );

  v_payment := round(abs(v_transaction.total_amount), 2);
  IF v_loan.interest_type = 'fixed' THEN
    v_interest := round(v_opening_principal * coalesce(v_loan.interest_rate, 0) / 1200, 2);
  ELSE
    v_interest := round(v_opening_principal * coalesce(v_loan.interest_rate, 0) / 1200, 10);
  END IF;
  v_principal := round(v_payment - v_interest, 10);
  IF v_principal < 0 THEN
    RAISE EXCEPTION 'Loan payment % is less than calculated interest % for transaction %',
      v_payment, v_interest, p_transaction_id;
  END IF;
  IF v_principal > v_opening_principal THEN
    v_principal := round(v_opening_principal, 10);
    v_interest := round(v_payment - v_principal, 10);
  END IF;

  INSERT INTO public.loan_payments (
    loan_id, transaction_id, installment_number, payment_date,
    payment_amount, principal_amount, interest_amount,
    annual_interest_rate, source_kind, notes,
    payment_kind, installments_covered, other_amount, balance_adjustment_amount
  ) VALUES (
    v_loan.id, v_transaction.id, v_installment_number,
    v_transaction.charge_date, v_payment, v_principal, v_interest,
    v_loan.interest_rate, 'existing_transaction',
    'Generated from an actual loan-linked ledger transaction',
    'installment', 1, 0, 0
  )
  ON CONFLICT (transaction_id) DO UPDATE SET
    loan_id = EXCLUDED.loan_id,
    installment_number = EXCLUDED.installment_number,
    payment_date = EXCLUDED.payment_date,
    payment_amount = EXCLUDED.payment_amount,
    principal_amount = EXCLUDED.principal_amount,
    interest_amount = EXCLUDED.interest_amount,
    annual_interest_rate = EXCLUDED.annual_interest_rate,
    source_kind = EXCLUDED.source_kind,
    payment_kind = 'installment',
    installments_covered = 1,
    other_amount = 0,
    balance_adjustment_amount = 0,
    updated_at = timezone('utc'::text, now())
  RETURNING * INTO v_result;

  UPDATE public.transactions SET
    installment_number = v_installment_number,
    installment_count = v_loan.total_installments,
    installments_info = CASE
      WHEN v_loan.total_installments IS NULL THEN v_installment_number::text
      ELSE v_installment_number::text || '/' || v_loan.total_installments::text
    END
  WHERE id = p_transaction_id;
  RETURN v_result;
END;
$$;

CREATE OR REPLACE FUNCTION public.create_transaction_with_loan_payment(
  p_transaction JSONB, p_record_loan_payment BOOLEAN DEFAULT true
)
RETURNS BIGINT LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE v_transaction_id BIGINT;
BEGIN
  IF p_transaction IS NULL THEN RAISE EXCEPTION 'Transaction payload is required'; END IF;
  INSERT INTO public.transactions (
    description, movement_type, category_id, total_amount, global_discount,
    global_discount_source, payment_source_id, transaction_date, charge_date,
    tags, loan_id, original_amount, currency, exchange_rate, installments_info,
    installment_number, installment_count, parent_transaction_id, notes
  ) VALUES (
    p_transaction->>'description', p_transaction->>'movement_type',
    nullif(p_transaction->>'category_id', '')::BIGINT,
    (p_transaction->>'total_amount')::NUMERIC,
    coalesce(nullif(p_transaction->>'global_discount', '')::NUMERIC, 0),
    nullif(p_transaction->>'global_discount_source', ''),
    nullif(p_transaction->>'payment_source_id', '')::BIGINT,
    (p_transaction->>'transaction_date')::DATE,
    coalesce(nullif(p_transaction->>'charge_date', '')::DATE,
      (p_transaction->>'transaction_date')::DATE),
    p_transaction->>'tags', nullif(p_transaction->>'loan_id', '')::BIGINT,
    nullif(p_transaction->>'original_amount', '')::NUMERIC,
    coalesce(nullif(p_transaction->>'currency', ''), 'ILS'),
    nullif(p_transaction->>'exchange_rate', '')::NUMERIC,
    nullif(p_transaction->>'installments_info', ''),
    nullif(p_transaction->>'installment_number', '')::INTEGER,
    nullif(p_transaction->>'installment_count', '')::INTEGER,
    nullif(p_transaction->>'parent_transaction_id', '')::BIGINT,
    p_transaction->>'notes'
  ) RETURNING id INTO v_transaction_id;
  IF nullif(p_transaction->>'loan_id', '') IS NOT NULL THEN
    PERFORM public.sync_loan_payment_from_transaction(v_transaction_id, p_record_loan_payment);
  END IF;
  RETURN v_transaction_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.update_transaction_with_loan_payment(
  p_transaction_id BIGINT, p_transaction JSONB,
  p_record_loan_payment BOOLEAN DEFAULT NULL
)
RETURNS BIGINT LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_old_transaction public.transactions%ROWTYPE;
  v_existing public.loan_payments%ROWTYPE;
  v_new_loan_id BIGINT;
  v_new_amount NUMERIC;
  v_requested_installment INTEGER;
  v_should_record_payment BOOLEAN;
  v_accounting_change BOOLEAN;
BEGIN
  SELECT * INTO v_old_transaction FROM public.transactions
  WHERE id = p_transaction_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Transaction % does not exist', p_transaction_id; END IF;
  SELECT * INTO v_existing FROM public.loan_payments
  WHERE transaction_id = p_transaction_id FOR UPDATE;

  v_new_loan_id := nullif(p_transaction->>'loan_id', '')::BIGINT;
  v_new_amount := (p_transaction->>'total_amount')::NUMERIC;
  v_requested_installment := CASE
    WHEN p_transaction ? 'installment_number'
      THEN nullif(p_transaction->>'installment_number', '')::INTEGER
    ELSE v_old_transaction.installment_number
  END;
  v_should_record_payment := coalesce(
    p_record_loan_payment,
    CASE
      WHEN v_existing.id IS NOT NULL THEN true
      WHEN v_old_transaction.loan_id = v_new_loan_id
        AND v_requested_installment IS NULL THEN false
      ELSE true
    END
  );
  PERFORM 1 FROM public.loans
  WHERE id IN (v_old_transaction.loan_id, v_new_loan_id)
  ORDER BY id FOR UPDATE;
  IF v_new_loan_id IS NOT NULL
    AND NOT EXISTS (SELECT 1 FROM public.loans WHERE id = v_new_loan_id) THEN
    RAISE EXCEPTION 'Loan % does not exist', v_new_loan_id;
  END IF;

  IF v_existing.id IS NOT NULL THEN
    v_accounting_change := v_old_transaction.loan_id IS DISTINCT FROM v_new_loan_id
      OR round(abs(v_old_transaction.total_amount), 2)
        IS DISTINCT FROM round(abs(v_new_amount), 2)
      OR (v_requested_installment IS NOT NULL
        AND v_requested_installment IS DISTINCT FROM v_existing.installment_number)
      OR NOT v_should_record_payment;
    IF v_existing.source_kind <> 'existing_transaction' AND v_accounting_change THEN
      RAISE EXCEPTION
        'Reconstructed/manual loan payment % cannot be repriced through transaction update',
        v_existing.id;
    END IF;
    IF v_existing.source_kind = 'existing_transaction' AND v_accounting_change
      AND EXISTS (SELECT 1 FROM public.loan_payments later
        WHERE later.loan_id = v_existing.loan_id
          AND later.installment_number > v_existing.installment_number) THEN
      RAISE EXCEPTION
        'Cannot change installment % while later loan payments exist; reconcile the schedule first',
        v_existing.installment_number;
    END IF;
  END IF;

  UPDATE public.transactions SET
    description = p_transaction->>'description',
    movement_type = p_transaction->>'movement_type',
    category_id = nullif(p_transaction->>'category_id', '')::BIGINT,
    total_amount = v_new_amount,
    global_discount = coalesce(nullif(p_transaction->>'global_discount', '')::NUMERIC, 0),
    global_discount_source = nullif(p_transaction->>'global_discount_source', ''),
    payment_source_id = nullif(p_transaction->>'payment_source_id', '')::BIGINT,
    transaction_date = (p_transaction->>'transaction_date')::DATE,
    charge_date = coalesce(nullif(p_transaction->>'charge_date', '')::DATE,
      (p_transaction->>'transaction_date')::DATE),
    tags = p_transaction->>'tags', loan_id = v_new_loan_id,
    original_amount = nullif(p_transaction->>'original_amount', '')::NUMERIC,
    currency = coalesce(nullif(p_transaction->>'currency', ''), 'ILS'),
    exchange_rate = nullif(p_transaction->>'exchange_rate', '')::NUMERIC,
    installments_info = nullif(p_transaction->>'installments_info', ''),
    installment_number = v_requested_installment,
    installment_count = CASE
      WHEN p_transaction ? 'installment_count'
        THEN nullif(p_transaction->>'installment_count', '')::INTEGER
      ELSE installment_count
    END,
    notes = p_transaction->>'notes', updated_at = timezone('utc'::text, now())
  WHERE id = p_transaction_id;

  IF v_existing.id IS NOT NULL AND v_existing.source_kind <> 'existing_transaction' THEN
    RETURN p_transaction_id;
  END IF;
  IF v_existing.id IS NOT NULL AND NOT v_accounting_change THEN
    UPDATE public.loan_payments SET
      payment_date = coalesce(nullif(p_transaction->>'charge_date', '')::DATE,
        (p_transaction->>'transaction_date')::DATE),
      updated_at = timezone('utc'::text, now())
    WHERE id = v_existing.id;
    RETURN p_transaction_id;
  END IF;
  PERFORM public.sync_loan_payment_from_transaction(p_transaction_id, v_should_record_payment);
  RETURN p_transaction_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.delete_transaction_with_loan_payment(p_transaction_id BIGINT)
RETURNS BIGINT LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_transaction public.transactions%ROWTYPE;
  v_existing public.loan_payments%ROWTYPE;
BEGIN
  SELECT * INTO v_transaction FROM public.transactions
  WHERE id = p_transaction_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Transaction % does not exist', p_transaction_id; END IF;
  SELECT * INTO v_existing FROM public.loan_payments
  WHERE transaction_id = p_transaction_id FOR UPDATE;
  IF v_existing.id IS NOT NULL AND v_existing.source_kind = 'existing_transaction' THEN
    IF EXISTS (SELECT 1 FROM public.loan_payments later
      WHERE later.loan_id = v_existing.loan_id
        AND later.installment_number > v_existing.installment_number) THEN
      RAISE EXCEPTION
        'Cannot delete installment % while later loan payments exist; reconcile the schedule first',
        v_existing.installment_number;
    END IF;
    DELETE FROM public.loan_payments WHERE id = v_existing.id;
  END IF;
  DELETE FROM public.lego_sets WHERE transaction_id = p_transaction_id;
  DELETE FROM public.transaction_items WHERE transaction_id = p_transaction_id;
  DELETE FROM public.transactions WHERE id = p_transaction_id;
  RETURN p_transaction_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.create_due_loan_payment(
  p_loan_id BIGINT,
  p_expected_due_date DATE,
  p_expected_installment_number INTEGER,
  p_payment_amount NUMERIC,
  p_principal_amount NUMERIC,
  p_interest_amount NUMERIC,
  p_annual_interest_rate NUMERIC,
  p_category_id BIGINT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_loan public.loans%ROWTYPE;
  v_existing public.loan_payments%ROWTYPE;
  v_transaction_id BIGINT;
  v_payment_id BIGINT;
  v_covered_count BIGINT := 0;
  v_precise_balance NUMERIC(24, 10) := 0;
  v_refreshed_balance NUMERIC := 0;
  v_refreshed_remaining INTEGER := 0;
  v_next_payment_date DATE;
  v_today DATE := (clock_timestamp() AT TIME ZONE 'Asia/Jerusalem')::date;
BEGIN
  SELECT * INTO v_loan FROM public.loans
  WHERE id = p_loan_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Loan % does not exist', p_loan_id; END IF;
  IF v_loan.calculation_mode <> 'loan_payments' THEN
    RAISE EXCEPTION 'Loan % is not in loan_payments mode', p_loan_id;
  END IF;
  SELECT * INTO v_existing FROM public.loan_payments
  WHERE loan_id = p_loan_id
    AND payment_kind = 'installment'
    AND installment_number = p_expected_installment_number
  FOR UPDATE;
  IF FOUND THEN
    SELECT coalesce(sum(installments_covered), 0)
    INTO v_covered_count
    FROM public.loan_payments
    WHERE loan_id = p_loan_id
      AND payment_kind IN ('installment', 'catch_up');
    IF v_existing.installment_number <> v_covered_count THEN
      RAISE EXCEPTION 'Loan % existing installment is not the latest accounting row', p_loan_id;
    END IF;
    IF p_expected_due_date > v_today THEN
      RAISE EXCEPTION 'Loan % is not due on Jerusalem business date %', p_loan_id, v_today;
    END IF;
    IF v_loan.next_payment_date IS DISTINCT FROM p_expected_due_date
      AND v_loan.next_payment_date IS DISTINCT FROM
        (p_expected_due_date + INTERVAL '1 month')::date
      AND v_loan.next_payment_date IS NOT NULL THEN
      RAISE EXCEPTION 'Loan % due date no longer matches the processed installment', p_loan_id;
    END IF;
    IF v_loan.next_payment_date = p_expected_due_date THEN
      IF NOT v_loan.auto_payment_enabled OR v_loan.status <> 'active' THEN
        RAISE EXCEPTION 'Loan % is not eligible for automatic payment', p_loan_id;
      END IF;
      UPDATE public.loans SET next_payment_date = CASE
        WHEN current_balance <= 0.005 OR remaining_installments <= 0 THEN NULL
        ELSE (p_expected_due_date + INTERVAL '1 month')::date
      END WHERE id = p_loan_id RETURNING next_payment_date INTO v_next_payment_date;
    ELSE
      v_next_payment_date := v_loan.next_payment_date;
    END IF;
    RETURN jsonb_build_object(
      'status', 'already_processed', 'loan_id', p_loan_id,
      'transaction_id', v_existing.transaction_id,
      'loan_payment_id', v_existing.id,
      'installment_number', v_existing.installment_number,
      'next_payment_date', v_next_payment_date
    );
  END IF;

  IF NOT v_loan.auto_payment_enabled THEN
    RAISE EXCEPTION 'Automatic payment is disabled for loan %', p_loan_id;
  END IF;
  IF v_loan.status <> 'active' THEN
    RAISE EXCEPTION 'Loan % is not active', p_loan_id;
  END IF;

  IF v_loan.remaining_installments IS NULL OR v_loan.remaining_installments <= 0 THEN
    RAISE EXCEPTION 'Loan % has no remaining installments', p_loan_id;
  END IF;
  IF v_loan.next_payment_date IS NULL OR v_loan.next_payment_date <> p_expected_due_date THEN
    RAISE EXCEPTION 'Loan % due date changed from expected %', p_loan_id, p_expected_due_date;
  END IF;
  IF p_expected_due_date > v_today THEN
    RAISE EXCEPTION 'Loan % is not due on Jerusalem business date %', p_loan_id, v_today;
  END IF;
  IF v_loan.payment_source_id IS NULL THEN
    RAISE EXCEPTION 'Loan % has no payment source', p_loan_id;
  END IF;
  IF v_loan.total_installments IS NULL OR v_loan.total_installments <= 0 THEN
    RAISE EXCEPTION 'Loan % has invalid total installments', p_loan_id;
  END IF;
  IF v_loan.monthly_payment IS NULL OR v_loan.monthly_payment <= 0 THEN
    RAISE EXCEPTION 'Loan % has invalid monthly payment', p_loan_id;
  END IF;
  IF v_loan.interest_rate IS NULL OR v_loan.interest_rate < 0 THEN
    RAISE EXCEPTION 'Loan % has invalid interest rate', p_loan_id;
  END IF;
  IF p_annual_interest_rate IS NULL
    OR abs(p_annual_interest_rate - v_loan.interest_rate) > 0.000001 THEN
    RAISE EXCEPTION 'Loan % interest rate changed during processing', p_loan_id;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.categories
    WHERE id = p_category_id AND type = 'expense' AND is_active = true) THEN
    RAISE EXCEPTION 'Loan payment category % is not an active expense category', p_category_id;
  END IF;

  SELECT
    coalesce(sum(installments_covered) FILTER (
      WHERE payment_kind IN ('installment', 'catch_up')
    ), 0),
    round(greatest(
      v_loan.original_amount
        - coalesce(sum(principal_amount), 0)
        - coalesce(sum(balance_adjustment_amount), 0),
      0
    ), 10)
  INTO v_covered_count, v_precise_balance
  FROM public.loan_payments WHERE loan_id = p_loan_id;
  IF v_covered_count > v_loan.total_installments THEN
    RAISE EXCEPTION 'Loan % payment coverage exceeds total installments', p_loan_id;
  END IF;
  IF v_loan.remaining_installments <> v_loan.total_installments - v_covered_count THEN
    RAISE EXCEPTION 'Loan % remaining-installment summary has drifted', p_loan_id;
  END IF;
  IF p_expected_installment_number <> v_covered_count + 1
    OR p_expected_installment_number > v_loan.total_installments THEN
    RAISE EXCEPTION 'Loan % expected installment % but received %',
      p_loan_id, v_covered_count + 1, p_expected_installment_number;
  END IF;
  IF p_payment_amount IS NULL OR round(p_payment_amount, 2) <= 0
    OR p_payment_amount <> round(p_payment_amount, 2)
    OR p_principal_amount IS NULL OR p_principal_amount < 0
    OR p_interest_amount IS NULL OR p_interest_amount < 0
    OR abs(p_payment_amount - p_principal_amount - p_interest_amount) > 0.00000001 THEN
    RAISE EXCEPTION 'Loan % payment components do not reconcile', p_loan_id;
  END IF;
  IF p_principal_amount > v_precise_balance + 0.00000001 THEN
    RAISE EXCEPTION 'Loan % principal component exceeds outstanding principal', p_loan_id;
  END IF;
  IF p_expected_installment_number < v_loan.total_installments
    AND abs(p_payment_amount - round(v_loan.monthly_payment, 2)) > 0.00000001 THEN
    RAISE EXCEPTION 'Loan % payment amount changed from configured monthly payment', p_loan_id;
  END IF;
  IF p_expected_installment_number = v_loan.total_installments
    AND abs(p_principal_amount - v_precise_balance) > 0.00000001 THEN
    RAISE EXCEPTION 'Loan % final installment does not clear principal', p_loan_id;
  END IF;

  INSERT INTO public.transactions (
    transaction_date, charge_date, description, movement_type, total_amount,
    category_id, payment_source_id, loan_id, original_amount, currency,
    installments_info, installment_number, installment_count, notes
  ) VALUES (
    p_expected_due_date, p_expected_due_date,
    'תשלום הלוואה אוטומטי - ' || v_loan.name, 'expense', p_payment_amount,
    p_category_id, v_loan.payment_source_id, v_loan.id, v_loan.original_amount, 'ILS',
    p_expected_installment_number::text || '/' || v_loan.total_installments::text,
    p_expected_installment_number, v_loan.total_installments,
    'Generated automatically when the loan installment became due'
  ) RETURNING id INTO v_transaction_id;

  INSERT INTO public.loan_payments (
    loan_id, transaction_id, installment_number, payment_date, payment_amount,
    principal_amount, interest_amount, annual_interest_rate, source_kind, notes,
    payment_kind, installments_covered, other_amount, balance_adjustment_amount
  ) VALUES (
    v_loan.id, v_transaction_id, p_expected_installment_number,
    p_expected_due_date, p_payment_amount, p_principal_amount, p_interest_amount,
    p_annual_interest_rate, 'generated',
    'Generated automatically from loans.next_payment_date',
    'installment', 1, 0, 0
  ) RETURNING id INTO v_payment_id;

  SELECT current_balance, remaining_installments
  INTO v_refreshed_balance, v_refreshed_remaining
  FROM public.loans WHERE id = p_loan_id;
  v_next_payment_date := CASE
    WHEN v_refreshed_balance <= 0.005 OR v_refreshed_remaining <= 0 THEN NULL
    ELSE (p_expected_due_date + INTERVAL '1 month')::date
  END;
  UPDATE public.loans SET next_payment_date = v_next_payment_date WHERE id = p_loan_id;
  RETURN jsonb_build_object(
    'status', 'processed', 'loan_id', p_loan_id,
    'transaction_id', v_transaction_id, 'loan_payment_id', v_payment_id,
    'installment_number', p_expected_installment_number,
    'next_payment_date', v_next_payment_date
  );
END;
$$;

-- Normalize Supabase default function grants. Internal helpers remain callable
-- only by their owner (including through triggers/SECURITY DEFINER RPCs); only
-- the bounded application entry points are exposed to service_role.
REVOKE ALL ON FUNCTION public.refresh_loan_summary(BIGINT)
  FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON FUNCTION public.recalculate_loan_status()
  FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON FUNCTION public.refresh_loan_summary_from_payment()
  FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON FUNCTION public.sync_loan_payment_from_transaction(BIGINT, BOOLEAN)
  FROM PUBLIC, anon, authenticated, service_role;

REVOKE ALL ON FUNCTION public.create_transaction_with_loan_payment(JSONB, BOOLEAN)
  FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON FUNCTION public.update_transaction_with_loan_payment(BIGINT, JSONB, BOOLEAN)
  FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON FUNCTION public.delete_transaction_with_loan_payment(BIGINT)
  FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON FUNCTION public.create_due_loan_payment(
  BIGINT, DATE, INTEGER, NUMERIC, NUMERIC, NUMERIC, NUMERIC, BIGINT
) FROM PUBLIC, anon, authenticated, service_role;

GRANT EXECUTE ON FUNCTION public.create_transaction_with_loan_payment(JSONB, BOOLEAN) TO service_role;
GRANT EXECUTE ON FUNCTION public.update_transaction_with_loan_payment(BIGINT, JSONB, BOOLEAN) TO service_role;
GRANT EXECUTE ON FUNCTION public.delete_transaction_with_loan_payment(BIGINT) TO service_role;
GRANT EXECUTE ON FUNCTION public.create_due_loan_payment(
  BIGINT, DATE, INTEGER, NUMERIC, NUMERIC, NUMERIC, NUMERIC, BIGINT
) TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.loan_payments TO service_role;
GRANT USAGE, SELECT ON SEQUENCE public.loan_payments_id_seq TO service_role;


-- =============================================
-- MANUAL LOAN REPAYMENTS
-- Source: migration 015_manual_loan_repayments.sql
-- =============================================

-- A manual installment can post on a different day than its contractual due
-- date. Persist the schedule state consumed by that payment so create, edit,
-- move, unlink and delete operations are deterministic and reversible.
CREATE OR REPLACE FUNCTION public.sync_manual_loan_payment_from_transaction(
  p_transaction_id BIGINT,
  p_loan_payment JSONB
)
RETURNS public.loan_payments
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_transaction public.transactions%ROWTYPE;
  v_loan public.loans%ROWTYPE;
  v_existing public.loan_payments%ROWTYPE;
  v_result public.loan_payments%ROWTYPE;
  v_old_loan_id BIGINT;
  v_old_scheduled_due_date DATE;
  v_old_auto_payment_enabled BOOLEAN;
  v_scheduled_due_date DATE;
  v_next_scheduled_due_date DATE;
  v_auto_payment_enabled_before BOOLEAN;
  v_has_later_covered BOOLEAN := false;
  v_installment_number INTEGER;
  v_covered_without_existing BIGINT := 0;
  v_current_covered BIGINT := 0;
  v_precise_balance NUMERIC(24, 10) := 0;
  v_balance_after NUMERIC(24, 10) := 0;
  v_remaining_after INTEGER := 0;
  v_payment NUMERIC(24, 10);
  v_principal NUMERIC(24, 10);
  v_interest NUMERIC(24, 10);
  v_other NUMERIC(24, 10);
  v_payment_date DATE;
BEGIN
  SELECT * INTO v_transaction
  FROM public.transactions
  WHERE id = p_transaction_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Transaction % does not exist', p_transaction_id;
  END IF;

  SELECT * INTO v_existing
  FROM public.loan_payments
  WHERE transaction_id = p_transaction_id
  FOR UPDATE;

  IF v_existing.id IS NOT NULL
    AND (v_existing.payment_kind <> 'installment'
      OR v_existing.source_kind NOT IN ('manual', 'existing_transaction')) THEN
    RAISE EXCEPTION
      'Transaction % is linked to protected %/% loan payment %',
      p_transaction_id, v_existing.source_kind, v_existing.payment_kind, v_existing.id;
  END IF;

  IF v_existing.id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.loan_payments later
      WHERE later.loan_id = v_existing.loan_id
        AND later.id <> v_existing.id
        AND later.payment_kind IN ('installment', 'catch_up')
        AND (
          (later.payment_kind = 'installment'
            AND later.installment_number > v_existing.installment_number)
          OR later.payment_date > v_existing.payment_date
        )
    ) INTO v_has_later_covered;
  END IF;

  -- A NULL payment specification is the explicit link-only mode. If this was
  -- previously a manual repayment, reverse only that authoritative entry.
  IF p_loan_payment IS NULL THEN
    IF v_existing.id IS NULL THEN
      RETURN NULL;
    END IF;

    IF v_has_later_covered THEN
      RAISE EXCEPTION
        'Cannot remove installment % while later covered payments exist',
        v_existing.installment_number;
    END IF;

    IF v_existing.source_kind <> 'manual'
      AND v_existing.scheduled_due_date IS NULL THEN
      RAISE EXCEPTION
        'Cannot remove loan payment % without a reversible schedule anchor',
        v_existing.id;
    END IF;

    v_old_loan_id := v_existing.loan_id;
    v_old_scheduled_due_date := v_existing.scheduled_due_date;
    v_old_auto_payment_enabled := v_existing.auto_payment_enabled_before;
    DELETE FROM public.loan_payments
    WHERE id = v_existing.id
    RETURNING * INTO v_result;

    UPDATE public.transactions
    SET installment_number = NULL,
        installment_count = NULL,
        installments_info = NULL,
        updated_at = timezone('utc'::text, now())
    WHERE id = p_transaction_id;

    -- Restore the exact schedule state consumed by this latest payment. This
    -- also reopens the schedule after reversing a payment that closed a loan.
    UPDATE public.loans
    SET next_payment_date = CASE
          WHEN current_balance <= 0.005 OR remaining_installments <= 0 THEN NULL
          ELSE v_old_scheduled_due_date
        END,
        auto_payment_enabled = CASE
          WHEN current_balance <= 0.005 THEN false
          ELSE coalesce(v_old_auto_payment_enabled, auto_payment_enabled)
        END
    WHERE id = v_old_loan_id
      AND NOT v_has_later_covered;
    RETURN v_result;
  END IF;

  IF v_existing.id IS NOT NULL
    AND v_existing.source_kind <> 'manual'
    AND v_existing.scheduled_due_date IS NULL THEN
    RAISE EXCEPTION
      'Cannot edit loan payment % without a reversible schedule anchor',
      v_existing.id;
  END IF;

  IF v_transaction.loan_id IS NULL THEN
    RAISE EXCEPTION 'A loan is required for a manual repayment';
  END IF;
  IF v_transaction.movement_type <> 'expense' THEN
    RAISE EXCEPTION 'A manual loan repayment must be an expense transaction';
  END IF;

  SELECT * INTO v_loan
  FROM public.loans
  WHERE id = v_transaction.loan_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Loan % does not exist', v_transaction.loan_id;
  END IF;
  IF v_loan.calculation_mode <> 'loan_payments' THEN
    RAISE EXCEPTION 'Loan % is not in loan_payments mode', v_loan.id;
  END IF;
  IF v_existing.id IS NULL AND v_loan.status <> 'active' THEN
    RAISE EXCEPTION 'Loan % is not active', v_loan.id;
  END IF;
  IF v_loan.total_installments IS NULL OR v_loan.total_installments <= 0 THEN
    RAISE EXCEPTION 'Loan % has invalid total installments', v_loan.id;
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.loan_payments
    WHERE loan_id = v_loan.id
      AND payment_kind = 'early_payoff'
      AND id IS DISTINCT FROM v_existing.id
  ) THEN
    RAISE EXCEPTION 'Loan % has an early payoff and cannot accept an installment', v_loan.id;
  END IF;

  v_payment := round(abs(v_transaction.total_amount), 2);
  v_principal := nullif(p_loan_payment->>'principal_amount', '')::NUMERIC;
  v_interest := nullif(p_loan_payment->>'interest_amount', '')::NUMERIC;
  v_other := coalesce(nullif(p_loan_payment->>'other_amount', '')::NUMERIC, 0);
  v_payment_date := coalesce(v_transaction.charge_date, v_transaction.transaction_date);

  IF v_payment <= 0
    OR v_principal IS NULL OR v_principal < 0 OR v_principal <> round(v_principal, 2)
    OR v_interest IS NULL OR v_interest < 0 OR v_interest <> round(v_interest, 2)
    OR v_other < 0 OR v_other <> round(v_other, 2)
    OR abs(v_payment - v_principal - v_interest - v_other) > 0.00000001 THEN
    RAISE EXCEPTION 'Manual loan payment components do not reconcile for transaction %',
      p_transaction_id;
  END IF;

  SELECT coalesce(sum(installments_covered), 0)
  INTO v_covered_without_existing
  FROM public.loan_payments
  WHERE loan_id = v_loan.id
    AND payment_kind IN ('installment', 'catch_up')
    AND id IS DISTINCT FROM v_existing.id;

  v_current_covered := v_covered_without_existing + CASE
    WHEN v_existing.id IS NOT NULL AND v_existing.loan_id = v_loan.id THEN 1
    ELSE 0
  END;
  IF v_current_covered > v_loan.total_installments
    OR v_loan.remaining_installments
      <> v_loan.total_installments - v_current_covered THEN
    RAISE EXCEPTION 'Loan % installment summary has drifted', v_loan.id;
  END IF;

  IF v_existing.id IS NOT NULL AND v_existing.loan_id = v_loan.id THEN
    v_installment_number := v_existing.installment_number;
  ELSE
    v_installment_number := v_covered_without_existing + 1;
  END IF;
  IF v_installment_number <= 0 OR v_installment_number > v_loan.total_installments THEN
    RAISE EXCEPTION 'Invalid next installment % for loan %',
      v_installment_number, v_loan.id;
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.loan_payments duplicate_payment
    WHERE duplicate_payment.loan_id = v_loan.id
      AND duplicate_payment.payment_kind = 'installment'
      AND duplicate_payment.installment_number = v_installment_number
      AND duplicate_payment.id IS DISTINCT FROM v_existing.id
  ) THEN
    RAISE EXCEPTION 'Installment % already exists for loan %',
      v_installment_number, v_loan.id;
  END IF;

  SELECT round(greatest(
    v_loan.original_amount
      - coalesce(sum(principal_amount), 0)
      - coalesce(sum(balance_adjustment_amount), 0),
    0
  ), 10)
  INTO v_precise_balance
  FROM public.loan_payments
  WHERE loan_id = v_loan.id
    AND id IS DISTINCT FROM v_existing.id;
  IF v_principal > v_precise_balance + 0.00000001 THEN
    RAISE EXCEPTION 'Principal component exceeds outstanding principal for loan %', v_loan.id;
  END IF;

  IF v_existing.id IS NOT NULL
    AND v_existing.loan_id IS DISTINCT FROM v_loan.id
    AND v_has_later_covered THEN
    RAISE EXCEPTION 'Cannot move installment % while later covered payments exist',
      v_existing.installment_number;
  END IF;

  v_old_loan_id := CASE
    WHEN v_existing.id IS NOT NULL THEN v_existing.loan_id
    ELSE NULL
  END;
  v_old_scheduled_due_date := CASE
    WHEN v_existing.id IS NOT NULL THEN v_existing.scheduled_due_date
    ELSE NULL
  END;
  v_old_auto_payment_enabled := CASE
    WHEN v_existing.id IS NOT NULL THEN v_existing.auto_payment_enabled_before
    ELSE NULL
  END;

  IF v_existing.id IS NOT NULL
    AND v_existing.loan_id = v_loan.id THEN
    -- Same-payment edits retain the contractual schedule anchor, regardless
    -- of changes to transaction_date, charge_date or component amounts.
    v_scheduled_due_date := v_existing.scheduled_due_date;
    v_auto_payment_enabled_before := v_existing.auto_payment_enabled_before;
    v_next_scheduled_due_date := CASE
      WHEN p_loan_payment ? 'next_scheduled_due_date'
        THEN nullif(p_loan_payment->>'next_scheduled_due_date', '')::DATE
      ELSE v_existing.next_scheduled_due_date
    END;
  ELSE
    -- A new payment (or the destination side of a move) consumes the target
    -- loan's current scheduled due date, not the transaction posting date.
    v_scheduled_due_date := v_loan.next_payment_date;
    v_auto_payment_enabled_before := v_loan.auto_payment_enabled;
    v_next_scheduled_due_date := nullif(
      p_loan_payment->>'next_scheduled_due_date', ''
    )::DATE;
  END IF;

  v_balance_after := greatest(v_precise_balance - v_principal, 0);
  v_remaining_after := greatest(
    v_loan.total_installments - (v_covered_without_existing + 1),
    0
  )::INTEGER;

  IF v_balance_after > 0.005 AND v_remaining_after > 0 THEN
    IF v_next_scheduled_due_date IS NULL THEN
      RAISE EXCEPTION 'Next scheduled due date is required for loan %', v_loan.id;
    END IF;
    IF v_scheduled_due_date IS NOT NULL
      AND v_next_scheduled_due_date <= v_scheduled_due_date THEN
      RAISE EXCEPTION
        'Next scheduled due date % must be later than covered due date % for loan %',
        v_next_scheduled_due_date, v_scheduled_due_date, v_loan.id;
    END IF;
  END IF;

  IF v_existing.id IS NOT NULL
    AND v_existing.loan_id = v_loan.id
    AND v_has_later_covered
    AND v_next_scheduled_due_date IS DISTINCT FROM v_existing.next_scheduled_due_date THEN
    RAISE EXCEPTION
      'Cannot change the schedule transition for installment % while later covered payments exist',
      v_existing.installment_number;
  END IF;

  IF v_existing.id IS NULL THEN
    INSERT INTO public.loan_payments (
      loan_id, transaction_id, installment_number, payment_date,
      payment_amount, principal_amount, interest_amount, annual_interest_rate,
      source_kind, notes, payment_kind, installments_covered,
      other_amount, balance_adjustment_amount, scheduled_due_date,
      next_scheduled_due_date, auto_payment_enabled_before
    ) VALUES (
      v_loan.id, v_transaction.id, v_installment_number, v_payment_date,
      v_payment, v_principal, v_interest, v_loan.interest_rate,
      'manual', 'Recorded manually through Add/Edit Transaction',
      'installment', 1, v_other, 0, v_scheduled_due_date,
      v_next_scheduled_due_date, v_auto_payment_enabled_before
    ) RETURNING * INTO v_result;
  ELSE
    UPDATE public.loan_payments
    SET loan_id = v_loan.id,
        installment_number = v_installment_number,
        payment_date = v_payment_date,
        payment_amount = v_payment,
        principal_amount = v_principal,
        interest_amount = v_interest,
        annual_interest_rate = v_loan.interest_rate,
        source_kind = 'manual',
        notes = 'Recorded manually through Add/Edit Transaction',
        payment_kind = 'installment',
        installments_covered = 1,
        other_amount = v_other,
        balance_adjustment_amount = 0,
        scheduled_due_date = v_scheduled_due_date,
        next_scheduled_due_date = v_next_scheduled_due_date,
        auto_payment_enabled_before = v_auto_payment_enabled_before,
        updated_at = timezone('utc'::text, now())
    WHERE id = v_existing.id
    RETURNING * INTO v_result;
  END IF;

  UPDATE public.transactions
  SET installment_number = v_installment_number,
      installment_count = v_loan.total_installments,
      installments_info = v_installment_number::text || '/' || v_loan.total_installments::text,
      updated_at = timezone('utc'::text, now())
  WHERE id = p_transaction_id;

  IF v_old_loan_id IS NOT NULL AND v_old_loan_id IS DISTINCT FROM v_loan.id THEN
    UPDATE public.loans
    SET next_payment_date = CASE
          WHEN current_balance <= 0.005 OR remaining_installments <= 0 THEN NULL
          ELSE v_old_scheduled_due_date
        END,
        auto_payment_enabled = CASE
          WHEN current_balance <= 0.005 THEN false
          ELSE coalesce(v_old_auto_payment_enabled, auto_payment_enabled)
        END
    WHERE id = v_old_loan_id
      AND NOT v_has_later_covered;
  END IF;

  -- New payments and moves apply the explicit persisted transition. Editing
  -- the latest payment may intentionally revise that transition; ordinary
  -- split/date edits submit the same value and cannot advance it again.
  IF v_existing.id IS NULL
    OR v_old_loan_id IS DISTINCT FROM v_loan.id
    OR NOT v_has_later_covered THEN
    UPDATE public.loans
    SET next_payment_date = CASE
          WHEN current_balance <= 0.005 OR remaining_installments <= 0 THEN NULL
          ELSE v_next_scheduled_due_date
        END,
        auto_payment_enabled = CASE
          WHEN current_balance <= 0.005 THEN false
          WHEN v_existing.id IS NOT NULL
            AND v_old_loan_id = v_loan.id
            AND v_loan.status = 'paid'
            THEN coalesce(v_auto_payment_enabled_before, auto_payment_enabled)
          ELSE auto_payment_enabled
        END
    WHERE id = v_loan.id;
  END IF;

  RETURN v_result;
END;
$$;

CREATE OR REPLACE FUNCTION public.create_transaction_with_manual_loan_payment(
  p_transaction JSONB,
  p_loan_payment JSONB
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_transaction_id BIGINT;
  v_transaction JSONB;
  v_payment JSONB;
  v_loan JSONB;
BEGIN
  IF p_transaction IS NULL THEN
    RAISE EXCEPTION 'Transaction payload is required';
  END IF;
  IF nullif(p_transaction->>'loan_id', '') IS NULL THEN
    RAISE EXCEPTION 'A loan-linked transaction requires a loan';
  END IF;

  INSERT INTO public.transactions (
    description, movement_type, category_id, total_amount, global_discount,
    global_discount_source, payment_source_id, transaction_date, charge_date,
    tags, loan_id, original_amount, currency, exchange_rate, installments_info,
    installment_number, installment_count, parent_transaction_id, notes
  ) VALUES (
    p_transaction->>'description', p_transaction->>'movement_type',
    nullif(p_transaction->>'category_id', '')::BIGINT,
    (p_transaction->>'total_amount')::NUMERIC,
    coalesce(nullif(p_transaction->>'global_discount', '')::NUMERIC, 0),
    nullif(p_transaction->>'global_discount_source', ''),
    nullif(p_transaction->>'payment_source_id', '')::BIGINT,
    (p_transaction->>'transaction_date')::DATE,
    coalesce(nullif(p_transaction->>'charge_date', '')::DATE,
      (p_transaction->>'transaction_date')::DATE),
    p_transaction->>'tags', nullif(p_transaction->>'loan_id', '')::BIGINT,
    nullif(p_transaction->>'original_amount', '')::NUMERIC,
    coalesce(nullif(p_transaction->>'currency', ''), 'ILS'),
    nullif(p_transaction->>'exchange_rate', '')::NUMERIC,
    nullif(p_transaction->>'installments_info', ''),
    nullif(p_transaction->>'installment_number', '')::INTEGER,
    nullif(p_transaction->>'installment_count', '')::INTEGER,
    nullif(p_transaction->>'parent_transaction_id', '')::BIGINT,
    p_transaction->>'notes'
  ) RETURNING id INTO v_transaction_id;

  PERFORM public.sync_manual_loan_payment_from_transaction(
    v_transaction_id, p_loan_payment
  );
  SELECT to_jsonb(t) INTO v_transaction
  FROM public.transactions t WHERE id = v_transaction_id;
  SELECT to_jsonb(lp) INTO v_payment
  FROM public.loan_payments lp WHERE transaction_id = v_transaction_id;
  SELECT to_jsonb(l) INTO v_loan
  FROM public.loans l WHERE id = (v_transaction->>'loan_id')::BIGINT;
  RETURN jsonb_build_object(
    'transaction', v_transaction,
    'loanPayment', v_payment,
    'loan', v_loan
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.update_transaction_with_manual_loan_payment(
  p_transaction_id BIGINT,
  p_transaction JSONB,
  p_loan_payment JSONB
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_old_transaction public.transactions%ROWTYPE;
  v_new_loan_id BIGINT;
  v_transaction JSONB;
  v_payment JSONB;
  v_loan JSONB;
BEGIN
  SELECT * INTO v_old_transaction
  FROM public.transactions
  WHERE id = p_transaction_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Transaction % does not exist', p_transaction_id;
  END IF;

  v_new_loan_id := nullif(p_transaction->>'loan_id', '')::BIGINT;
  PERFORM 1 FROM public.loans
  WHERE id IN (v_old_transaction.loan_id, v_new_loan_id)
  ORDER BY id
  FOR UPDATE;
  IF v_new_loan_id IS NOT NULL
    AND NOT EXISTS (SELECT 1 FROM public.loans WHERE id = v_new_loan_id) THEN
    RAISE EXCEPTION 'Loan % does not exist', v_new_loan_id;
  END IF;

  UPDATE public.transactions
  SET description = p_transaction->>'description',
      movement_type = p_transaction->>'movement_type',
      category_id = nullif(p_transaction->>'category_id', '')::BIGINT,
      total_amount = (p_transaction->>'total_amount')::NUMERIC,
      global_discount = coalesce(nullif(p_transaction->>'global_discount', '')::NUMERIC, 0),
      global_discount_source = nullif(p_transaction->>'global_discount_source', ''),
      payment_source_id = nullif(p_transaction->>'payment_source_id', '')::BIGINT,
      transaction_date = (p_transaction->>'transaction_date')::DATE,
      charge_date = coalesce(nullif(p_transaction->>'charge_date', '')::DATE,
        (p_transaction->>'transaction_date')::DATE),
      tags = p_transaction->>'tags',
      loan_id = v_new_loan_id,
      original_amount = nullif(p_transaction->>'original_amount', '')::NUMERIC,
      currency = coalesce(nullif(p_transaction->>'currency', ''), 'ILS'),
      exchange_rate = nullif(p_transaction->>'exchange_rate', '')::NUMERIC,
      installments_info = CASE
        WHEN p_transaction ? 'installments_info'
          THEN nullif(p_transaction->>'installments_info', '')
        ELSE installments_info
      END,
      installment_number = CASE
        WHEN p_transaction ? 'installment_number'
          THEN nullif(p_transaction->>'installment_number', '')::INTEGER
        ELSE installment_number
      END,
      installment_count = CASE
        WHEN p_transaction ? 'installment_count'
          THEN nullif(p_transaction->>'installment_count', '')::INTEGER
        ELSE installment_count
      END,
      notes = p_transaction->>'notes',
      updated_at = timezone('utc'::text, now())
  WHERE id = p_transaction_id;

  PERFORM public.sync_manual_loan_payment_from_transaction(
    p_transaction_id, p_loan_payment
  );
  SELECT to_jsonb(t) INTO v_transaction
  FROM public.transactions t WHERE id = p_transaction_id;
  SELECT to_jsonb(lp) INTO v_payment
  FROM public.loan_payments lp WHERE transaction_id = p_transaction_id;
  SELECT to_jsonb(l) INTO v_loan
  FROM public.loans l WHERE id = nullif(v_transaction->>'loan_id', '')::BIGINT;
  RETURN jsonb_build_object(
    'transaction', v_transaction,
    'loanPayment', v_payment,
    'loan', v_loan
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.delete_transaction_with_loan_payment(
  p_transaction_id BIGINT
)
RETURNS BIGINT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_transaction public.transactions%ROWTYPE;
  v_existing public.loan_payments%ROWTYPE;
  v_old_loan_id BIGINT;
  v_old_scheduled_due_date DATE;
  v_old_auto_payment_enabled BOOLEAN;
  v_has_later_covered BOOLEAN := false;
BEGIN
  SELECT * INTO v_transaction
  FROM public.transactions
  WHERE id = p_transaction_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Transaction % does not exist', p_transaction_id;
  END IF;
  SELECT * INTO v_existing
  FROM public.loan_payments
  WHERE transaction_id = p_transaction_id
  FOR UPDATE;

  IF v_existing.id IS NOT NULL THEN
    IF v_existing.payment_kind <> 'installment'
      OR v_existing.source_kind NOT IN ('manual', 'existing_transaction') THEN
      RAISE EXCEPTION
        'Transaction % is linked to protected %/% loan payment % and cannot be deleted',
        p_transaction_id, v_existing.source_kind, v_existing.payment_kind, v_existing.id;
    END IF;
    SELECT EXISTS (
      SELECT 1 FROM public.loan_payments later
      WHERE later.loan_id = v_existing.loan_id
        AND later.id <> v_existing.id
        AND later.payment_kind IN ('installment', 'catch_up')
        AND (
          (later.payment_kind = 'installment'
            AND later.installment_number > v_existing.installment_number)
          OR later.payment_date > v_existing.payment_date
        )
    ) INTO v_has_later_covered;
    IF v_has_later_covered THEN
      RAISE EXCEPTION 'Cannot delete installment % while later covered payments exist',
        v_existing.installment_number;
    END IF;

    IF v_existing.source_kind <> 'manual'
      AND v_existing.scheduled_due_date IS NULL THEN
      RAISE EXCEPTION
        'Cannot delete loan payment % without a reversible schedule anchor',
        v_existing.id;
    END IF;

    v_old_loan_id := v_existing.loan_id;
    v_old_scheduled_due_date := v_existing.scheduled_due_date;
    v_old_auto_payment_enabled := v_existing.auto_payment_enabled_before;
    DELETE FROM public.loan_payments WHERE id = v_existing.id;
  END IF;

  DELETE FROM public.lego_sets WHERE transaction_id = p_transaction_id;
  DELETE FROM public.transaction_items WHERE transaction_id = p_transaction_id;
  DELETE FROM public.transactions WHERE id = p_transaction_id;

  IF v_old_loan_id IS NOT NULL THEN
    UPDATE public.loans
    SET next_payment_date = CASE
          WHEN current_balance <= 0.005 OR remaining_installments <= 0 THEN NULL
          ELSE v_old_scheduled_due_date
        END,
        auto_payment_enabled = CASE
          WHEN current_balance <= 0.005 THEN false
          ELSE coalesce(v_old_auto_payment_enabled, auto_payment_enabled)
        END
    WHERE id = v_old_loan_id
      AND NOT v_has_later_covered;
  END IF;
  RETURN p_transaction_id;
END;
$$;

REVOKE ALL ON FUNCTION public.sync_manual_loan_payment_from_transaction(BIGINT, JSONB)
  FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON FUNCTION public.create_transaction_with_manual_loan_payment(JSONB, JSONB)
  FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON FUNCTION public.update_transaction_with_manual_loan_payment(BIGINT, JSONB, JSONB)
  FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON FUNCTION public.delete_transaction_with_loan_payment(BIGINT)
  FROM PUBLIC, anon, authenticated, service_role;

GRANT EXECUTE ON FUNCTION public.create_transaction_with_manual_loan_payment(JSONB, JSONB)
  TO service_role;
GRANT EXECUTE ON FUNCTION public.update_transaction_with_manual_loan_payment(BIGINT, JSONB, JSONB)
  TO service_role;
GRANT EXECUTE ON FUNCTION public.delete_transaction_with_loan_payment(BIGINT)
  TO service_role;


-- =============================================
-- SECTION 6: TASK JOURNAL
-- Added: 2026-05-01
-- =============================================

CREATE TABLE IF NOT EXISTS tasks (
  id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  title          TEXT NOT NULL,
  notes          TEXT,
  status         TEXT NOT NULL DEFAULT 'open'
                 CHECK (status IN ('open', 'in_progress', 'waiting', 'done', 'cancelled')),
  priority       TEXT NOT NULL DEFAULT 'medium'
                 CHECK (priority IN ('low', 'medium', 'high', 'urgent')),
  category       TEXT NOT NULL DEFAULT 'personal'
                 CHECK (category IN ('finance', 'personal', 'work', 'system', 'other')),
  due_date       DATE,
  completed_at   TIMESTAMP WITH TIME ZONE,
  source         TEXT NOT NULL DEFAULT 'manual'
                 CHECK (source IN ('manual', 'system', 'ai')),
  transaction_id INTEGER REFERENCES transactions(id) ON DELETE SET NULL,
  loan_id        BIGINT  REFERENCES loans(id)         ON DELETE SET NULL,
  created_at     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),
  updated_at     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()
);

CREATE INDEX idx_tasks_status   ON tasks (status);
CREATE INDEX idx_tasks_due_date ON tasks (due_date);
CREATE INDEX idx_tasks_priority ON tasks (priority);
CREATE INDEX idx_tasks_category ON tasks (category);



-- =============================================
-- SECTION 7: READ-ONLY FUNCTIONS (RPC)
-- Sources: migrations/003_transaction_pagination_and_aggregates.sql and
-- migrations/016_external_transaction_contract.sql
--
-- These are the authoritative definitions for transaction filtering, sorting
-- and financial aggregation. All are read-only (STABLE, or IMMUTABLE for the
-- pure string helper) and all are SECURITY INVOKER. None writes data.
--
-- The bodies below are kept byte-identical to the migration. If you change one,
-- change both — this file must stay a standalone reproducible schema.
--
-- =============================================

-- Canonical comma-separated TEXT tag autocomplete. The API server is the only
-- direct caller; SECURITY INVOKER means this function grants no table access.
CREATE OR REPLACE FUNCTION public.get_unique_tags()
RETURNS TABLE(tag TEXT)
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path = pg_catalog, public
AS $$
  SELECT DISTINCT
    pg_catalog.unnest(pg_catalog.string_to_array(t.tags, ',')) AS tag
  FROM public.transactions AS t;
$$;

REVOKE ALL ON FUNCTION public.get_unique_tags()
  FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.get_unique_tags()
  TO service_role;

-- 7.1 SEARCH PATTERN (single owner of the escaping rule)
-- =============================================

-- Turns raw user search text into an ILIKE pattern, escaping the LIKE wildcards
-- so a user searching for "50%" or "a_b" gets a literal match instead of a
-- pattern. Backslash is escaped first, or it would double-escape the escapes
-- added afterwards.
--
-- This exists as its own IMMUTABLE function rather than as a CTE inside
-- transactions_filtered() for two reasons:
--   * one owner for the escaping rule, referenced from every predicate;
--   * a CTE in the body would make transactions_filtered() ineligible for
--     planner inlining, which is what lets the index be used at all.
-- Being IMMUTABLE with a constant argument, it is folded once at plan time —
-- it is not evaluated per row.
CREATE OR REPLACE FUNCTION public.transactions_search_pattern(p_search text)
RETURNS text
LANGUAGE sql
IMMUTABLE
SECURITY INVOKER
AS $$
  SELECT CASE
           WHEN p_search IS NULL OR pg_catalog.btrim(p_search) = '' THEN NULL
           ELSE '%' || pg_catalog.replace(
                         pg_catalog.replace(
                           pg_catalog.replace(pg_catalog.btrim(p_search),
                             '\', '\\'),
                           '%', '\%'),
                         '_', '\_') || '%'
         END;
$$;


-- =============================================
-- 7.2 FILTERED TRANSACTION SET
-- =============================================

-- THE single owner of transaction filter semantics.
--
-- Both the page slice and the totals are derived from this one function, which
-- is what guarantees the summary bar can never disagree with the rows the user
-- is looking at. It is not a view because it is parameterised.
--
-- row_json is byte-compatible with the previous PostgREST response shape: the
-- full transactions row plus embedded `categories` and `payment_sources`
-- objects, so existing consumers need no field remapping.
--
-- Inlining contract (deliberate, do not "tidy" this away):
--   This function has NO `SET search_path`, because a SET clause makes a SQL
--   function ineligible for planner inlining — and without inlining the sort
--   and LIMIT could not use an index. To stay safe without a pinned search
--   path, every object referenced below is schema-qualified. It remains
--   SECURITY INVOKER, so it grants no privilege of its own.
CREATE OR REPLACE FUNCTION public.transactions_filtered(
  p_from                date    DEFAULT NULL,
  p_to                  date    DEFAULT NULL,
  p_category_id         bigint  DEFAULT NULL,
  p_payment_source_id   bigint  DEFAULT NULL,
  p_uncategorized_only  boolean DEFAULT false,
  p_search              text    DEFAULT NULL
)
RETURNS TABLE (
  id                integer,
  transaction_date  date,
  description       text,
  movement_type     text,
  total_amount      numeric,
  row_json          jsonb
)
LANGUAGE sql
STABLE
SECURITY INVOKER
AS $$
  SELECT
    t.id,
    t.transaction_date,
    t.description::text,
    t.movement_type::text,
    t.total_amount,
    pg_catalog.to_jsonb(t) || pg_catalog.jsonb_build_object(
      'categories',
      CASE WHEN c.id IS NULL THEN NULL
           ELSE pg_catalog.jsonb_build_object('name', c.name, 'icon', c.icon) END,
      'payment_sources',
      CASE WHEN ps.id IS NULL THEN NULL
           ELSE pg_catalog.jsonb_build_object(
             'id',     ps.id,
             'name',   ps.name,
             'method', ps.method,
             'slug',   ps.slug,
             'issuer', ps.issuer,
             'last4',  ps.last4
           ) END
    )
  FROM public.transactions t
  -- LEFT JOIN is required: transactions with no category or no payment source
  -- must still appear (the "uncategorized only" filter depends on it).
  LEFT JOIN public.categories      c  ON c.id  = t.category_id
  LEFT JOIN public.payment_sources ps ON ps.id = t.payment_source_id
  WHERE (p_from IS NULL OR t.transaction_date >= p_from)
    AND (p_to   IS NULL OR t.transaction_date <= p_to)
    AND (p_category_id IS NULL OR t.category_id = p_category_id)
    AND (p_payment_source_id IS NULL OR t.payment_source_id = p_payment_source_id)
    AND (NOT COALESCE(p_uncategorized_only, false) OR t.category_id IS NULL)
    AND (
      public.transactions_search_pattern(p_search) IS NULL
      -- Mirrors the previous client-side search exactly: description,
      -- amount-as-text, category name, payment source name. Notes are NOT
      -- searched, because the old implementation did not search them.
      OR t.description        ILIKE public.transactions_search_pattern(p_search) ESCAPE '\'
      OR t.total_amount::text ILIKE public.transactions_search_pattern(p_search) ESCAPE '\'
      OR c.name               ILIKE public.transactions_search_pattern(p_search) ESCAPE '\'
      OR ps.name              ILIKE public.transactions_search_pattern(p_search) ESCAPE '\'
    );
$$;


-- =============================================
-- 7.3 PAGINATED + SORTED TRANSACTION LIST
-- =============================================

-- Returns one jsonb object:
--   {
--     "data":     [ <transaction row>, ... ],   -- at most p_limit rows
--     "has_more": true | false,
--     "next_key": { ...keyset position... } | null,
--     "totals":   { "count": n, "income": n, "expense": n } | null
--   }
--
-- SORTING
--   Six fully static branches, one per (sort field, direction). There is no
--   dynamic SQL anywhere: p_sort_by and p_sort_direction only *select* a
--   branch, they are never interpolated into a statement. An unrecognised
--   combination raises, rather than silently falling through to an arbitrary
--   order — defence in depth behind the allowlist in
--   server/utils/transactionQuery.js.
--
--   Every branch ends with `id DESC`, a unique column, so the ordering is
--   always total and deterministic and no row can straddle a page boundary.
--
--   Description ordering uses COLLATE "C". That makes it deterministic and
--   independent of the database's locale, and it preserves the expected order
--   for this application's Hebrew and English descriptions. It is byte /
--   code-point ordering, whereas the old browser-side comparator used UTF-16
--   code units; those agree across the BMP but may differ for supplementary
--   characters such as some emoji. No claim of exact equivalence is made.
--
--   COLLATION INVARIANT (do not weaken): the description branches must apply
--   COLLATE "C" to BOTH SIDES of every description comparison — the inequality
--   AND the equality that guards the transaction_date/id tiebreakers — and in
--   the ORDER BY of both the inner LIMIT query and the outer jsonb_agg calls.
--   A cursor predicate that compared under the database-default collation while
--   the rows were ordered under "C" would place the boundary somewhere the sort
--   never put it, skipping and repeating rows across the page edge. The
--   NULL-block transition uses IS NULL, which is collation-independent.
--
--   NULL descriptions: `(description IS NULL) ASC` is promoted to the leading
--   sort key, so rows with no description sort to the BOTTOM in BOTH
--   directions. This is a deliberate product decision. Postgres' own defaults
--   (NULLS LAST for ASC, NULLS FIRST for DESC) would move them to the top on a
--   descending sort and would make the cursor predicate direction-dependent in
--   a much more error-prone way.
--
-- PAGINATION
--   Keyset (cursor), never OFFSET. The probe row lives entirely inside this
--   function: it selects p_limit + 1 rows, returns at most p_limit, and reports
--   has_more separately. The probe row is structurally incapable of reaching
--   the response.
--
--   next_key is built here rather than in JavaScript on purpose. total_amount
--   is NUMERIC; if the caller read it back off a JSON row it would already have
--   been through a double. It is emitted as ::text so the cursor boundary is
--   exact, and transaction_date via to_char so it is DateStyle-independent.
--
-- TOTALS
--   Computed only when asked for, inside a real IF. The previous version used
--   `CASE WHEN p_include_totals THEN (SELECT ...) END`, which Postgres may hoist
--   into an InitPlan and evaluate regardless of the condition — meaning every
--   "load more" would have re-aggregated the entire filtered set.
CREATE OR REPLACE FUNCTION public.transactions_page(
  p_from                        date    DEFAULT NULL,
  p_to                          date    DEFAULT NULL,
  p_category_id                 bigint  DEFAULT NULL,
  p_payment_source_id           bigint  DEFAULT NULL,
  p_uncategorized_only          boolean DEFAULT false,
  p_search                      text    DEFAULT NULL,
  p_limit                       integer DEFAULT 100,
  p_sort_by                     text    DEFAULT 'transaction_date',
  p_sort_direction              text    DEFAULT 'desc',
  p_cursor_id                   bigint  DEFAULT NULL,
  p_cursor_date                 date    DEFAULT NULL,
  p_cursor_amount               numeric DEFAULT NULL,
  p_cursor_description          text    DEFAULT NULL,
  p_cursor_description_is_null  boolean DEFAULT NULL,
  p_include_totals              boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_probe     integer;
  v_rows      jsonb;
  v_keys      jsonb;
  v_has_more  boolean := false;
  v_next_key  jsonb   := NULL;
  v_totals    jsonb   := NULL;
BEGIN
  IF p_limit IS NULL OR p_limit < 1 THEN
    RAISE EXCEPTION 'transactions_page: p_limit must be a positive integer, got %', p_limit;
  END IF;

  -- One row beyond the page, so has_more is derived from real data rather than
  -- guessed from a full page.
  v_probe := p_limit + 1;

  -- ---------------------------------------------------------------------
  -- transaction_date DESC, id DESC   (the default view)
  -- ---------------------------------------------------------------------
  IF p_sort_by = 'transaction_date' AND p_sort_direction = 'desc' THEN
    SELECT jsonb_agg(p.row_json ORDER BY p.transaction_date DESC, p.id DESC),
           jsonb_agg(p.k        ORDER BY p.transaction_date DESC, p.id DESC)
      INTO v_rows, v_keys
    FROM (
      SELECT f.transaction_date,
             f.id,
             f.row_json,
             jsonb_build_object(
               'td', to_char(f.transaction_date, 'YYYY-MM-DD'),
               'id', f.id
             ) AS k
      FROM public.transactions_filtered(
             p_from, p_to, p_category_id, p_payment_source_id,
             p_uncategorized_only, p_search) f
      WHERE p_cursor_id IS NULL
         OR f.transaction_date < p_cursor_date
         OR (f.transaction_date = p_cursor_date AND f.id < p_cursor_id)
      ORDER BY f.transaction_date DESC, f.id DESC
      LIMIT v_probe
    ) p;

  -- ---------------------------------------------------------------------
  -- transaction_date ASC, id DESC
  -- ---------------------------------------------------------------------
  ELSIF p_sort_by = 'transaction_date' AND p_sort_direction = 'asc' THEN
    SELECT jsonb_agg(p.row_json ORDER BY p.transaction_date ASC, p.id DESC),
           jsonb_agg(p.k        ORDER BY p.transaction_date ASC, p.id DESC)
      INTO v_rows, v_keys
    FROM (
      SELECT f.transaction_date,
             f.id,
             f.row_json,
             jsonb_build_object(
               'td', to_char(f.transaction_date, 'YYYY-MM-DD'),
               'id', f.id
             ) AS k
      FROM public.transactions_filtered(
             p_from, p_to, p_category_id, p_payment_source_id,
             p_uncategorized_only, p_search) f
      WHERE p_cursor_id IS NULL
         OR f.transaction_date > p_cursor_date
         OR (f.transaction_date = p_cursor_date AND f.id < p_cursor_id)
      ORDER BY f.transaction_date ASC, f.id DESC
      LIMIT v_probe
    ) p;

  -- ---------------------------------------------------------------------
  -- total_amount DESC, transaction_date DESC, id DESC
  -- ---------------------------------------------------------------------
  ELSIF p_sort_by = 'total_amount' AND p_sort_direction = 'desc' THEN
    SELECT jsonb_agg(p.row_json ORDER BY p.total_amount DESC, p.transaction_date DESC, p.id DESC),
           jsonb_agg(p.k        ORDER BY p.total_amount DESC, p.transaction_date DESC, p.id DESC)
      INTO v_rows, v_keys
    FROM (
      SELECT f.transaction_date,
             f.id,
             f.total_amount,
             f.row_json,
             jsonb_build_object(
               -- ::text, not a JSON number: NUMERIC must not round-trip a double.
               'av', f.total_amount::text,
               'td', to_char(f.transaction_date, 'YYYY-MM-DD'),
               'id', f.id
             ) AS k
      FROM public.transactions_filtered(
             p_from, p_to, p_category_id, p_payment_source_id,
             p_uncategorized_only, p_search) f
      WHERE p_cursor_id IS NULL
         OR f.total_amount < p_cursor_amount
         OR (f.total_amount = p_cursor_amount
             AND (f.transaction_date < p_cursor_date
                  OR (f.transaction_date = p_cursor_date AND f.id < p_cursor_id)))
      ORDER BY f.total_amount DESC, f.transaction_date DESC, f.id DESC
      LIMIT v_probe
    ) p;

  -- ---------------------------------------------------------------------
  -- total_amount ASC, transaction_date DESC, id DESC
  -- ---------------------------------------------------------------------
  ELSIF p_sort_by = 'total_amount' AND p_sort_direction = 'asc' THEN
    SELECT jsonb_agg(p.row_json ORDER BY p.total_amount ASC, p.transaction_date DESC, p.id DESC),
           jsonb_agg(p.k        ORDER BY p.total_amount ASC, p.transaction_date DESC, p.id DESC)
      INTO v_rows, v_keys
    FROM (
      SELECT f.transaction_date,
             f.id,
             f.total_amount,
             f.row_json,
             jsonb_build_object(
               'av', f.total_amount::text,
               'td', to_char(f.transaction_date, 'YYYY-MM-DD'),
               'id', f.id
             ) AS k
      FROM public.transactions_filtered(
             p_from, p_to, p_category_id, p_payment_source_id,
             p_uncategorized_only, p_search) f
      WHERE p_cursor_id IS NULL
         OR f.total_amount > p_cursor_amount
         OR (f.total_amount = p_cursor_amount
             AND (f.transaction_date < p_cursor_date
                  OR (f.transaction_date = p_cursor_date AND f.id < p_cursor_id)))
      ORDER BY f.total_amount ASC, f.transaction_date DESC, f.id DESC
      LIMIT v_probe
    ) p;

  -- ---------------------------------------------------------------------
  -- description ASC, transaction_date DESC, id DESC   (NULL descriptions last)
  -- ---------------------------------------------------------------------
  ELSIF p_sort_by = 'description' AND p_sort_direction = 'asc' THEN
    SELECT jsonb_agg(p.row_json ORDER BY (p.description IS NULL) ASC,
                                         p.description COLLATE "C" ASC,
                                         p.transaction_date DESC, p.id DESC),
           jsonb_agg(p.k        ORDER BY (p.description IS NULL) ASC,
                                         p.description COLLATE "C" ASC,
                                         p.transaction_date DESC, p.id DESC)
      INTO v_rows, v_keys
    FROM (
      SELECT f.transaction_date,
             f.id,
             f.description,
             f.row_json,
             jsonb_build_object(
               'dn', (f.description IS NULL),
               'dv', f.description,
               'td', to_char(f.transaction_date, 'YYYY-MM-DD'),
               'id', f.id
             ) AS k
      FROM public.transactions_filtered(
             p_from, p_to, p_category_id, p_payment_source_id,
             p_uncategorized_only, p_search) f
      WHERE p_cursor_id IS NULL
         OR (
           CASE
             -- Still inside the non-NULL block: everything that sorts after the
             -- cursor value, plus the entire NULL block that follows it.
             WHEN NOT p_cursor_description_is_null THEN
                  f.description IS NULL
               OR f.description COLLATE "C" > p_cursor_description COLLATE "C"
               OR (f.description COLLATE "C" = p_cursor_description COLLATE "C"
                   AND (f.transaction_date < p_cursor_date
                        OR (f.transaction_date = p_cursor_date AND f.id < p_cursor_id)))
             -- Already inside the trailing NULL block: only later NULL rows.
             ELSE
               f.description IS NULL
               AND (f.transaction_date < p_cursor_date
                    OR (f.transaction_date = p_cursor_date AND f.id < p_cursor_id))
           END
         )
      ORDER BY (f.description IS NULL) ASC,
               f.description COLLATE "C" ASC,
               f.transaction_date DESC, f.id DESC
      LIMIT v_probe
    ) p;

  -- ---------------------------------------------------------------------
  -- description DESC, transaction_date DESC, id DESC  (NULL descriptions last)
  -- ---------------------------------------------------------------------
  ELSIF p_sort_by = 'description' AND p_sort_direction = 'desc' THEN
    SELECT jsonb_agg(p.row_json ORDER BY (p.description IS NULL) ASC,
                                         p.description COLLATE "C" DESC,
                                         p.transaction_date DESC, p.id DESC),
           jsonb_agg(p.k        ORDER BY (p.description IS NULL) ASC,
                                         p.description COLLATE "C" DESC,
                                         p.transaction_date DESC, p.id DESC)
      INTO v_rows, v_keys
    FROM (
      SELECT f.transaction_date,
             f.id,
             f.description,
             f.row_json,
             jsonb_build_object(
               'dn', (f.description IS NULL),
               'dv', f.description,
               'td', to_char(f.transaction_date, 'YYYY-MM-DD'),
               'id', f.id
             ) AS k
      FROM public.transactions_filtered(
             p_from, p_to, p_category_id, p_payment_source_id,
             p_uncategorized_only, p_search) f
      WHERE p_cursor_id IS NULL
         OR (
           CASE
             WHEN NOT p_cursor_description_is_null THEN
                  f.description IS NULL
               OR f.description COLLATE "C" < p_cursor_description COLLATE "C"
               OR (f.description COLLATE "C" = p_cursor_description COLLATE "C"
                   AND (f.transaction_date < p_cursor_date
                        OR (f.transaction_date = p_cursor_date AND f.id < p_cursor_id)))
             ELSE
               f.description IS NULL
               AND (f.transaction_date < p_cursor_date
                    OR (f.transaction_date = p_cursor_date AND f.id < p_cursor_id))
           END
         )
      ORDER BY (f.description IS NULL) ASC,
               f.description COLLATE "C" DESC,
               f.transaction_date DESC, f.id DESC
      LIMIT v_probe
    ) p;

  ELSE
    RAISE EXCEPTION 'transactions_page: unsupported sort % %', p_sort_by, p_sort_direction;
  END IF;

  -- jsonb_agg over an empty set returns NULL, not '[]'.
  v_rows := COALESCE(v_rows, '[]'::jsonb);
  v_keys := COALESCE(v_keys, '[]'::jsonb);

  v_has_more := jsonb_array_length(v_rows) > p_limit;

  IF v_has_more THEN
    -- Drop the probe row. The explicit ORDER BY on the ordinality keeps the
    -- page order intact through the re-aggregation.
    SELECT jsonb_agg(e ORDER BY o)
      INTO v_rows
    FROM jsonb_array_elements(v_rows) WITH ORDINALITY AS x(e, o)
    WHERE o <= p_limit;

    -- Keyset position of the LAST ROW ACTUALLY RETURNED (0-based index),
    -- never the probe row.
    v_next_key := v_keys -> (p_limit - 1);
  END IF;

  -- Totals cover the whole filtered set, not the returned page: summing a
  -- single page would understate the user's real totals. Requested on the
  -- first page only, which is why this must be a real conditional.
  IF COALESCE(p_include_totals, false) THEN
    SELECT jsonb_build_object(
             'count',   COUNT(*),
             -- The income/expense split follows the existing movement_type
             -- contract: total_amount carries the magnitude and movement_type
             -- carries the direction. Unchanged from calculateSummaryStats.
             -- (Note: there is no CHECK constraint forcing total_amount >= 0;
             -- this mirrors whatever is stored, it does not assume a sign.)
             'income',  COALESCE(SUM(f.total_amount) FILTER (WHERE f.movement_type = 'income'),  0),
             'expense', COALESCE(SUM(f.total_amount) FILTER (WHERE f.movement_type = 'expense'), 0)
           )
      INTO v_totals
    FROM public.transactions_filtered(
           p_from, p_to, p_category_id, p_payment_source_id,
           p_uncategorized_only, p_search) f;
  END IF;

  RETURN jsonb_build_object(
    'data',     v_rows,
    'has_more', v_has_more,
    'next_key', v_next_key,
    'totals',   v_totals
  );
END;
$$;


-- =============================================
-- 7.4 DASHBOARD AGGREGATES
-- =============================================

-- Period totals for the Dashboard KPI cards.
-- Replaces downloading every transaction into the browser and summing it in
-- calculateSummaryStats(). Same income/expense/balance rule, computed in SQL.
CREATE OR REPLACE FUNCTION public.dashboard_summary(
  p_from date,
  p_to   date
)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
  SELECT jsonb_build_object(
    'income',   COALESCE(SUM(total_amount) FILTER (WHERE movement_type = 'income'),  0),
    'expenses', COALESCE(SUM(total_amount) FILTER (WHERE movement_type = 'expense'), 0),
    'balance',  COALESCE(SUM(total_amount) FILTER (WHERE movement_type = 'income'),  0)
              - COALESCE(SUM(total_amount) FILTER (WHERE movement_type = 'expense'), 0),
    'count',    COUNT(*)
  )
  FROM public.transactions
  WHERE (p_from IS NULL OR transaction_date >= p_from)
    AND (p_to   IS NULL OR transaction_date <= p_to);
$$;


-- Trailing-N-month income/expense series for the Dashboard trend chart.
-- Replaces prepareMonthlyChartData(), which bucketed the full downloaded array
-- in JavaScript. Months with no transactions are returned with zeros so the
-- chart keeps a continuous axis (generate_series + LEFT JOIN), matching the
-- previous behaviour where an empty month produced {income: 0, expenses: 0}.
CREATE OR REPLACE FUNCTION public.dashboard_monthly_series(
  p_months integer DEFAULT 6
)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
  WITH bounds AS (
    SELECT date_trunc('month', CURRENT_DATE)::date AS current_month_start,
           GREATEST(COALESCE(p_months, 6), 1)      AS months
  ),
  months AS (
    SELECT generate_series(
             (SELECT current_month_start - ((months - 1) || ' months')::interval FROM bounds),
             (SELECT current_month_start FROM bounds),
             '1 month'::interval
           )::date AS month_start
  ),
  per_month AS (
    SELECT
      m.month_start,
      COALESCE(SUM(t.total_amount) FILTER (WHERE t.movement_type = 'income'),  0) AS income,
      COALESCE(SUM(t.total_amount) FILTER (WHERE t.movement_type = 'expense'), 0) AS expenses
    FROM months m
    LEFT JOIN public.transactions t
      ON t.transaction_date >= m.month_start
     AND t.transaction_date <  (m.month_start + interval '1 month')
    GROUP BY m.month_start
  )
  SELECT COALESCE(jsonb_agg(
           jsonb_build_object(
             'month',    to_char(per_month.month_start, 'YYYY-MM'),
             'income',   per_month.income,
             'expenses', per_month.expenses
           )
           ORDER BY per_month.month_start
         ), '[]'::jsonb)
  FROM per_month;
$$;


-- =============================================
-- 7.5 GRANTS
-- =============================================
--
-- PostgreSQL grants EXECUTE to PUBLIC by default. Without the REVOKEs below,
-- every function above would be callable through PostgREST by `anon` and
-- `authenticated`, bypassing the Express requireAuth middleware entirely — and
-- the RLS policies on these tables are `USING (true)`, so RLS is no backstop.
--
-- These statements only NARROW access from the PostgreSQL default. They grant
-- nothing that was not already implicitly granted to everyone.
--
-- If SUPABASE_KEY on the server is ever changed to an anon key, these REVOKEs
-- will break every endpoint. Confirm the key's JWT `role` claim is
-- `service_role` before applying this migration.

REVOKE ALL ON FUNCTION public.transactions_search_pattern(text)
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.transactions_search_pattern(text)
  TO service_role;

REVOKE ALL ON FUNCTION public.transactions_filtered(date,date,bigint,bigint,boolean,text)
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.transactions_filtered(date,date,bigint,bigint,boolean,text)
  TO service_role;

REVOKE ALL ON FUNCTION public.transactions_page(date,date,bigint,bigint,boolean,text,integer,text,text,bigint,date,numeric,text,boolean,boolean)
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.transactions_page(date,date,bigint,bigint,boolean,text,integer,text,text,bigint,date,numeric,text,boolean,boolean)
  TO service_role;

REVOKE ALL ON FUNCTION public.dashboard_summary(date,date)
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.dashboard_summary(date,date)
  TO service_role;

REVOKE ALL ON FUNCTION public.dashboard_monthly_series(integer)
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.dashboard_monthly_series(integer)
  TO service_role;

-- =============================================
-- 8. FUNDED BUDGET FOUNDATION
-- =============================================
-- Source: migrations/017_funded_budget_foundation.sql
-- Migration 017: funded monthly budget foundation and immutable provenance.
--
-- IMPORTANT: this migration is intentionally self-contained and transactional.
-- It must be rehearsed against a disposable PostgreSQL database and verified
-- against the target catalog before any production execution. Finance Tracker
-- does not currently maintain an authoritative applied-migration ledger.

BEGIN;

-- ---------------------------------------------------------------------------
-- Legacy preflight. Never guess, merge, delete, or silently normalize rows.
-- ---------------------------------------------------------------------------

DO $$
DECLARE
  v_missing_columns TEXT;
  v_bad_rows TEXT;
BEGIN
  IF to_regclass('public.budgets') IS NULL THEN
    RAISE EXCEPTION 'Migration 017 preflight: public.budgets does not exist';
  END IF;

  SELECT string_agg(required.column_name, ', ' ORDER BY required.column_name)
  INTO v_missing_columns
  FROM (VALUES
    ('id'), ('category_id'), ('month'), ('amount'), ('created_at'), ('updated_at')
  ) AS required(column_name)
  WHERE NOT EXISTS (
    SELECT 1
    FROM information_schema.columns c
    WHERE c.table_schema = 'public'
      AND c.table_name = 'budgets'
      AND c.column_name = required.column_name
  );

  IF v_missing_columns IS NOT NULL THEN
    RAISE EXCEPTION
      'Migration 017 preflight: public.budgets has an unexpected shape; missing columns: %',
      v_missing_columns;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM information_schema.columns c
    WHERE c.table_schema = 'public'
      AND c.table_name = 'budgets'
      AND c.column_name = 'month'
      AND c.data_type = 'text'
  ) OR NOT EXISTS (
    SELECT 1
    FROM information_schema.columns c
    WHERE c.table_schema = 'public'
      AND c.table_name = 'budgets'
      AND c.column_name = 'amount'
      AND c.data_type = 'numeric'
  ) THEN
    RAISE EXCEPTION
      'Migration 017 preflight: expected budgets.month TEXT and budgets.amount NUMERIC';
  END IF;

  SELECT string_agg(format('id=%s month=%L', id, month), ', ' ORDER BY id)
  INTO v_bad_rows
  FROM public.budgets
  WHERE month !~ '^\d{4}-(0[1-9]|1[0-2])$';
  IF v_bad_rows IS NOT NULL THEN
    RAISE EXCEPTION 'Migration 017 preflight: invalid legacy budget month rows: %', v_bad_rows;
  END IF;

  SELECT string_agg(format('id=%s month=%L', id, month), ', ' ORDER BY id)
  INTO v_bad_rows
  FROM public.budgets
  WHERE to_char(to_date(month || '-01', 'YYYY-MM-DD'), 'YYYY-MM') <> month;
  IF v_bad_rows IS NOT NULL THEN
    RAISE EXCEPTION 'Migration 017 preflight: non-canonical calendar month rows: %', v_bad_rows;
  END IF;

  SELECT string_agg(format('id=%s month=%s', id, month), ', ' ORDER BY id)
  INTO v_bad_rows
  FROM public.budgets
  WHERE category_id IS NULL;
  IF v_bad_rows IS NOT NULL THEN
    RAISE EXCEPTION 'Migration 017 preflight: null legacy budget categories: %', v_bad_rows;
  END IF;

  SELECT string_agg(format('category_id=%s month=%s count=%s', category_id, month, row_count), ', ')
  INTO v_bad_rows
  FROM (
    SELECT category_id, month, count(*) AS row_count
    FROM public.budgets
    GROUP BY category_id, month
    HAVING count(*) > 1
  ) duplicates;
  IF v_bad_rows IS NOT NULL THEN
    RAISE EXCEPTION 'Migration 017 preflight: duplicate logical budget rows: %', v_bad_rows;
  END IF;

  SELECT string_agg(format('id=%s amount=%s', id, amount), ', ' ORDER BY id)
  INTO v_bad_rows
  FROM public.budgets
  WHERE amount < 0
     OR amount::text IN ('NaN', 'Infinity', '-Infinity')
     OR amount <> round(amount, 2)
     OR amount > 9999999999999999.99;
  IF v_bad_rows IS NOT NULL THEN
    RAISE EXCEPTION
      'Migration 017 preflight: invalid legacy budget amounts (must be finite, nonnegative NUMERIC(18,2)): %',
      v_bad_rows;
  END IF;

  SELECT string_agg(format('budget_id=%s category_id=%s', b.id, b.category_id), ', ' ORDER BY b.id)
  INTO v_bad_rows
  FROM public.budgets b
  LEFT JOIN public.categories c ON c.id = b.category_id
  WHERE c.id IS NULL;
  IF v_bad_rows IS NOT NULL THEN
    RAISE EXCEPTION 'Migration 017 preflight: legacy budgets reference missing categories: %', v_bad_rows;
  END IF;
END;
$$;

-- ---------------------------------------------------------------------------
-- Canonical month, immutable operations, funding, movements and lifecycle.
-- BIGINT identity operation IDs provide compact, monotonic database ordering;
-- request_key provides client-visible idempotency independently of ordering.
-- ---------------------------------------------------------------------------

CREATE TABLE public.budget_months (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  month_start DATE NOT NULL UNIQUE,
  currency_code TEXT NOT NULL DEFAULT 'ILS' CHECK (currency_code = 'ILS'),
  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text, now()),
  CONSTRAINT budget_months_canonical_month CHECK (
    month_start = date_trunc('month', month_start)::date
  )
);

CREATE TABLE public.budget_operations (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  budget_month_id BIGINT NOT NULL REFERENCES public.budget_months(id) ON DELETE RESTRICT,
  request_key UUID NOT NULL UNIQUE,
  request_fingerprint TEXT NOT NULL CHECK (btrim(request_fingerprint) <> ''),
  operation_type TEXT NOT NULL CHECK (operation_type IN (
    'legacy_import',
    'manual_funding',
    'establish_budget',
    'adjustment',
    'removal',
    'reactivation',
    'copy',
    'reversal'
  )),
  effective_date DATE NOT NULL,
  reason TEXT,
  reverses_operation_id BIGINT UNIQUE REFERENCES public.budget_operations(id) ON DELETE RESTRICT,
  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text, now()),
  CONSTRAINT budget_operations_not_self_reversing CHECK (
    reverses_operation_id IS NULL OR reverses_operation_id <> id
  )
);

CREATE TABLE public.budget_funding_entries (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  operation_id BIGINT NOT NULL UNIQUE REFERENCES public.budget_operations(id) ON DELETE RESTRICT,
  amount_delta NUMERIC(18, 2) NOT NULL,
  source_kind TEXT NOT NULL CHECK (source_kind IN ('manual_available_funds', 'legacy_import')),
  source_label TEXT NOT NULL CHECK (btrim(source_label) <> ''),
  reverses_funding_entry_id BIGINT UNIQUE REFERENCES public.budget_funding_entries(id) ON DELETE RESTRICT,
  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text, now()),
  CONSTRAINT budget_funding_entry_amount_shape CHECK (
    amount_delta::text NOT IN ('NaN', 'Infinity', '-Infinity')
    AND (
    (source_kind = 'legacy_import' AND amount_delta >= 0 AND reverses_funding_entry_id IS NULL)
    OR
    (source_kind = 'manual_available_funds' AND amount_delta <> 0)
    )
  )
);

ALTER TABLE public.budgets
  ADD COLUMN budget_month_id BIGINT REFERENCES public.budget_months(id) ON DELETE RESTRICT,
  ADD COLUMN starting_amount NUMERIC(18, 2),
  ADD COLUMN starting_kind TEXT,
  ADD COLUMN created_by_operation_id BIGINT REFERENCES public.budget_operations(id) ON DELETE RESTRICT;

CREATE TABLE public.budget_movements (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  operation_id BIGINT NOT NULL REFERENCES public.budget_operations(id) ON DELETE RESTRICT,
  source_budget_id BIGINT REFERENCES public.budgets(id) ON DELETE RESTRICT,
  destination_budget_id BIGINT REFERENCES public.budgets(id) ON DELETE RESTRICT,
  amount NUMERIC(18, 2) NOT NULL CHECK (
    amount::text NOT IN ('NaN', 'Infinity', '-Infinity') AND amount > 0
  ),
  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text, now()),
  CONSTRAINT budget_movements_endpoints CHECK (
    (source_budget_id IS NOT NULL OR destination_budget_id IS NOT NULL)
    AND source_budget_id IS DISTINCT FROM destination_budget_id
  )
);

CREATE TABLE public.budget_lifecycle_events (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  operation_id BIGINT NOT NULL REFERENCES public.budget_operations(id) ON DELETE RESTRICT,
  budget_id BIGINT NOT NULL REFERENCES public.budgets(id) ON DELETE RESTRICT,
  state TEXT NOT NULL CHECK (state IN ('active', 'inactive')),
  actual_spent_snapshot NUMERIC(18, 2),
  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text, now()),
  CONSTRAINT budget_lifecycle_actual_snapshot CHECK (
    (state = 'active' AND actual_spent_snapshot IS NULL)
    OR
    (state = 'inactive'
      AND actual_spent_snapshot IS NOT NULL
      AND actual_spent_snapshot::text NOT IN ('NaN', 'Infinity', '-Infinity')
      AND actual_spent_snapshot >= 0)
  ),
  CONSTRAINT budget_lifecycle_operation_budget_key UNIQUE (operation_id, budget_id)
);

CREATE INDEX idx_budget_operations_month_order
  ON public.budget_operations (budget_month_id, id);
CREATE INDEX idx_budget_movements_source
  ON public.budget_movements (source_budget_id, id);
CREATE INDEX idx_budget_movements_destination
  ON public.budget_movements (destination_budget_id, id);
CREATE INDEX idx_budget_lifecycle_budget_order
  ON public.budget_lifecycle_events (budget_id, id DESC);

-- ---------------------------------------------------------------------------
-- Deterministic legacy backfill. One operation and one funding entry per month.
-- ---------------------------------------------------------------------------

INSERT INTO public.budget_months (month_start, created_at)
SELECT
  to_date(b.month || '-01', 'YYYY-MM-DD'),
  min(b.created_at)
FROM public.budgets b
GROUP BY b.month
ORDER BY b.month;

INSERT INTO public.budget_operations (
  budget_month_id,
  request_key,
  request_fingerprint,
  operation_type,
  effective_date,
  reason,
  created_at
)
SELECT
  bm.id,
  (
    substr(md5('finance-tracker:legacy-budget:' || to_char(bm.month_start, 'YYYY-MM')), 1, 8) || '-' ||
    substr(md5('finance-tracker:legacy-budget:' || to_char(bm.month_start, 'YYYY-MM')), 9, 4) || '-' ||
    substr(md5('finance-tracker:legacy-budget:' || to_char(bm.month_start, 'YYYY-MM')), 13, 4) || '-' ||
    substr(md5('finance-tracker:legacy-budget:' || to_char(bm.month_start, 'YYYY-MM')), 17, 4) || '-' ||
    substr(md5('finance-tracker:legacy-budget:' || to_char(bm.month_start, 'YYYY-MM')), 21, 12)
  )::uuid,
  'legacy_import|' || to_char(bm.month_start, 'YYYY-MM'),
  'legacy_import',
  bm.month_start,
  'Migration 017 legacy budget opening-state import',
  bm.created_at
FROM public.budget_months bm
ORDER BY bm.month_start;

INSERT INTO public.budget_funding_entries (
  operation_id,
  amount_delta,
  source_kind,
  source_label,
  created_at
)
SELECT
  bo.id,
  coalesce(sum(b.amount), 0)::numeric(18, 2),
  'legacy_import',
  'Legacy budget import assumption; historical real-world funding source is unknown',
  bo.created_at
FROM public.budget_operations bo
JOIN public.budget_months bm ON bm.id = bo.budget_month_id
LEFT JOIN public.budgets b ON b.month = to_char(bm.month_start, 'YYYY-MM')
WHERE bo.operation_type = 'legacy_import'
GROUP BY bo.id, bo.created_at;

UPDATE public.budgets b
SET budget_month_id = bm.id,
    starting_amount = b.amount::numeric(18, 2),
    starting_kind = 'legacy_import',
    created_by_operation_id = bo.id
FROM public.budget_months bm
JOIN public.budget_operations bo
  ON bo.budget_month_id = bm.id
 AND bo.operation_type = 'legacy_import'
WHERE b.month = to_char(bm.month_start, 'YYYY-MM');

INSERT INTO public.budget_lifecycle_events (
  operation_id,
  budget_id,
  state,
  actual_spent_snapshot,
  created_at
)
SELECT
  b.created_by_operation_id,
  b.id,
  'active',
  NULL,
  b.created_at
FROM public.budgets b
ORDER BY b.id;

-- Preserve every legacy ID while ensuring the next generated snapshot ID cannot
-- collide with an explicitly imported historical ID. ALTER SEQUENCE ... RESTART
-- is transactional, unlike setval(), so a failed migration restores sequence state.
DO $$
DECLARE
  v_sequence REGCLASS;
  v_next_id BIGINT;
BEGIN
  v_sequence := pg_get_serial_sequence('public.budgets', 'id')::regclass;
  IF v_sequence IS NULL THEN
    RAISE EXCEPTION 'Migration 017 preflight: budgets.id has no owned sequence';
  END IF;
  SELECT greatest(coalesce(max(id), 0) + 1, 1) INTO v_next_id FROM public.budgets;
  EXECUTE format('ALTER SEQUENCE %s RESTART WITH %s', v_sequence, v_next_id);
END;
$$;

ALTER TABLE public.budgets
  ALTER COLUMN category_id SET NOT NULL,
  ALTER COLUMN budget_month_id SET NOT NULL,
  ALTER COLUMN starting_amount SET NOT NULL,
  ALTER COLUMN starting_kind SET NOT NULL,
  ALTER COLUMN created_by_operation_id SET NOT NULL,
  ADD CONSTRAINT budgets_starting_amount_nonnegative CHECK (
    starting_amount::text NOT IN ('NaN', 'Infinity', '-Infinity')
    AND starting_amount >= 0
  ),
  ADD CONSTRAINT budgets_starting_kind_check CHECK (
    starting_kind IN ('manual', 'legacy_import', 'copied')
  ),
  ADD CONSTRAINT budgets_legacy_starting_match CHECK (amount = starting_amount),
  ADD CONSTRAINT budgets_month_category_key UNIQUE (budget_month_id, category_id);

-- ---------------------------------------------------------------------------
-- Database-enforced validation and append-only protection.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.prevent_budget_history_mutation()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
BEGIN
  RAISE EXCEPTION '% is append-only; use a compensating budget operation', TG_TABLE_NAME
    USING ERRCODE = '55000';
END;
$$;

CREATE OR REPLACE FUNCTION public.validate_budget_snapshot_insert()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_month public.budget_months%ROWTYPE;
  v_operation public.budget_operations%ROWTYPE;
BEGIN
  SELECT * INTO v_month FROM public.budget_months WHERE id = NEW.budget_month_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Budget month % does not exist', NEW.budget_month_id;
  END IF;
  IF NEW.month <> to_char(v_month.month_start, 'YYYY-MM') THEN
    RAISE EXCEPTION 'Legacy month % does not match canonical month %', NEW.month, v_month.month_start;
  END IF;
  IF NEW.amount::text IN ('NaN', 'Infinity', '-Infinity')
     OR NEW.starting_amount::text IN ('NaN', 'Infinity', '-Infinity') THEN
    RAISE EXCEPTION 'Budget starting values must be finite';
  END IF;
  IF NEW.amount <> NEW.starting_amount THEN
    RAISE EXCEPTION 'Legacy amount must equal immutable starting_amount on insert';
  END IF;
  SELECT * INTO v_operation FROM public.budget_operations WHERE id = NEW.created_by_operation_id;
  IF NOT FOUND OR v_operation.budget_month_id <> NEW.budget_month_id THEN
    RAISE EXCEPTION 'Budget creation operation does not belong to the budget month';
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.validate_budget_operation_insert()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_month_start DATE;
BEGIN
  SELECT month_start INTO v_month_start
  FROM public.budget_months
  WHERE id = NEW.budget_month_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Budget month % does not exist', NEW.budget_month_id;
  END IF;
  IF NEW.effective_date < v_month_start
     OR NEW.effective_date >= (v_month_start + interval '1 month')::date THEN
    RAISE EXCEPTION 'Budget operation effective_date must be within its budget month';
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.validate_budget_movement_insert()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_operation_month BIGINT;
  v_source_month BIGINT;
  v_destination_month BIGINT;
BEGIN
  SELECT budget_month_id INTO v_operation_month
  FROM public.budget_operations
  WHERE id = NEW.operation_id;

  IF NEW.source_budget_id IS NOT NULL THEN
    SELECT budget_month_id INTO v_source_month
    FROM public.budgets
    WHERE id = NEW.source_budget_id;
    IF v_source_month IS DISTINCT FROM v_operation_month THEN
      RAISE EXCEPTION 'Movement source budget is outside the operation month';
    END IF;
  END IF;

  IF NEW.destination_budget_id IS NOT NULL THEN
    SELECT budget_month_id INTO v_destination_month
    FROM public.budgets
    WHERE id = NEW.destination_budget_id;
    IF v_destination_month IS DISTINCT FROM v_operation_month THEN
      RAISE EXCEPTION 'Movement destination budget is outside the operation month';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.validate_budget_lifecycle_insert()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_operation_month BIGINT;
  v_budget_month BIGINT;
  v_previous_state TEXT;
BEGIN
  SELECT budget_month_id INTO v_operation_month
  FROM public.budget_operations
  WHERE id = NEW.operation_id;
  SELECT budget_month_id INTO v_budget_month
  FROM public.budgets
  WHERE id = NEW.budget_id;

  IF v_operation_month IS DISTINCT FROM v_budget_month THEN
    RAISE EXCEPTION 'Lifecycle event budget is outside the operation month';
  END IF;

  SELECT state INTO v_previous_state
  FROM public.budget_lifecycle_events
  WHERE budget_id = NEW.budget_id
  ORDER BY id DESC
  LIMIT 1;

  IF v_previous_state IS NULL AND NEW.state <> 'active' THEN
    RAISE EXCEPTION 'A monthly category budget must begin active';
  END IF;
  IF v_previous_state = NEW.state THEN
    RAISE EXCEPTION 'Budget lifecycle transition % -> % is invalid', v_previous_state, NEW.state;
  END IF;

  RETURN NEW;
END;
$$;

CREATE TRIGGER budgets_validate_insert
BEFORE INSERT ON public.budgets
FOR EACH ROW EXECUTE FUNCTION public.validate_budget_snapshot_insert();
CREATE TRIGGER budgets_immutable
BEFORE UPDATE OR DELETE ON public.budgets
FOR EACH ROW EXECUTE FUNCTION public.prevent_budget_history_mutation();

CREATE TRIGGER budget_months_immutable
BEFORE UPDATE OR DELETE ON public.budget_months
FOR EACH ROW EXECUTE FUNCTION public.prevent_budget_history_mutation();
CREATE TRIGGER budget_operations_validate_insert
BEFORE INSERT ON public.budget_operations
FOR EACH ROW EXECUTE FUNCTION public.validate_budget_operation_insert();
CREATE TRIGGER budget_operations_immutable
BEFORE UPDATE OR DELETE ON public.budget_operations
FOR EACH ROW EXECUTE FUNCTION public.prevent_budget_history_mutation();
CREATE TRIGGER budget_funding_entries_immutable
BEFORE UPDATE OR DELETE ON public.budget_funding_entries
FOR EACH ROW EXECUTE FUNCTION public.prevent_budget_history_mutation();
CREATE TRIGGER budget_movements_validate_insert
BEFORE INSERT ON public.budget_movements
FOR EACH ROW EXECUTE FUNCTION public.validate_budget_movement_insert();
CREATE TRIGGER budget_movements_immutable
BEFORE UPDATE OR DELETE ON public.budget_movements
FOR EACH ROW EXECUTE FUNCTION public.prevent_budget_history_mutation();
CREATE TRIGGER budget_lifecycle_validate_insert
BEFORE INSERT ON public.budget_lifecycle_events
FOR EACH ROW EXECUTE FUNCTION public.validate_budget_lifecycle_insert();
CREATE TRIGGER budget_lifecycle_immutable
BEFORE UPDATE OR DELETE ON public.budget_lifecycle_events
FOR EACH ROW EXECUTE FUNCTION public.prevent_budget_history_mutation();

-- ---------------------------------------------------------------------------
-- Canonical derived state. No mutable current-amount cache is authoritative.
-- ---------------------------------------------------------------------------

CREATE VIEW public.budget_category_state AS
SELECT
  b.id AS budget_id,
  b.budget_month_id,
  to_char(bm.month_start, 'YYYY-MM') AS month,
  bm.month_start,
  bm.currency_code,
  b.category_id,
  c.name AS category_name,
  c.icon AS category_icon,
  c.type AS category_type,
  b.starting_amount,
  b.starting_amount::text AS starting_amount_text,
  b.starting_kind,
  coalesce(movements.incoming, 0)::numeric(18, 2)
    - coalesce(movements.outgoing, 0)::numeric(18, 2) AS adjustment_total,
  (coalesce(movements.incoming, 0)::numeric(18, 2)
    - coalesce(movements.outgoing, 0)::numeric(18, 2))::text AS adjustment_total_text,
  b.starting_amount
    + coalesce(movements.incoming, 0)::numeric(18, 2)
    - coalesce(movements.outgoing, 0)::numeric(18, 2) AS final_funded,
  (b.starting_amount
    + coalesce(movements.incoming, 0)::numeric(18, 2)
    - coalesce(movements.outgoing, 0)::numeric(18, 2))::text AS final_funded_text,
  lifecycle.state AS lifecycle_state,
  lifecycle.id AS lifecycle_event_id
FROM public.budgets b
JOIN public.budget_months bm ON bm.id = b.budget_month_id
JOIN public.categories c ON c.id = b.category_id
LEFT JOIN LATERAL (
  SELECT
    sum(m.amount) FILTER (WHERE m.destination_budget_id = b.id) AS incoming,
    sum(m.amount) FILTER (WHERE m.source_budget_id = b.id) AS outgoing
  FROM public.budget_movements m
  WHERE m.source_budget_id = b.id OR m.destination_budget_id = b.id
) movements ON true
JOIN LATERAL (
  SELECT le.id, le.state
  FROM public.budget_lifecycle_events le
  WHERE le.budget_id = b.id
  ORDER BY le.id DESC
  LIMIT 1
) lifecycle ON true;

CREATE VIEW public.budget_month_funding_state AS
SELECT
  bm.id AS budget_month_id,
  to_char(bm.month_start, 'YYYY-MM') AS month,
  bm.month_start,
  bm.currency_code,
  coalesce(f.available, 0)::numeric(18, 2) AS available,
  coalesce(s.starting_total, 0)::numeric(18, 2) AS starting_total,
  coalesce(s.total_allocated, 0)::numeric(18, 2) AS total_allocated,
  coalesce(s.active_allocated, 0)::numeric(18, 2) AS active_allocated,
  (coalesce(s.total_allocated, 0) - coalesce(s.active_allocated, 0))::numeric(18, 2)
    AS inactive_retained_funding,
  (coalesce(f.available, 0) - coalesce(s.total_allocated, 0))::numeric(18, 2)
    AS unallocated
FROM public.budget_months bm
LEFT JOIN LATERAL (
  SELECT sum(fe.amount_delta) AS available
  FROM public.budget_funding_entries fe
  JOIN public.budget_operations bo ON bo.id = fe.operation_id
  WHERE bo.budget_month_id = bm.id
) f ON true
LEFT JOIN LATERAL (
  SELECT
    sum(cs.starting_amount) AS starting_total,
    sum(cs.final_funded) AS total_allocated,
    sum(cs.final_funded) FILTER (WHERE cs.lifecycle_state = 'active') AS active_allocated
  FROM public.budget_category_state cs
  WHERE cs.budget_month_id = bm.id
) s ON true;

-- Exact annual/monthly compatibility input. The amount is aggregated in
-- PostgreSQL and exposed as text so PostgREST never converts NUMERIC to a
-- JavaScript floating-point value.
CREATE VIEW public.budget_month_category_actuals AS
SELECT
  to_char(date_trunc('month', t.transaction_date), 'YYYY-MM') AS month,
  t.category_id,
  c.name AS category_name,
  c.icon AS category_icon,
  sum(t.total_amount)::numeric(18, 2)::text AS actual_spent_text
FROM public.transactions t
LEFT JOIN public.categories c ON c.id = t.category_id
WHERE t.movement_type = 'expense'
GROUP BY date_trunc('month', t.transaction_date), t.category_id, c.name, c.icon;

CREATE OR REPLACE FUNCTION public.budget_month_start_from_key(p_month TEXT)
RETURNS DATE
LANGUAGE plpgsql
IMMUTABLE
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
BEGIN
  IF p_month IS NULL OR p_month !~ '^\d{4}-(0[1-9]|1[0-2])$' THEN
    RAISE EXCEPTION 'month must be a canonical YYYY-MM value' USING ERRCODE = '22023';
  END IF;
  RETURN pg_catalog.to_date(p_month || '-01', 'YYYY-MM-DD');
END;
$$;

CREATE OR REPLACE FUNCTION public.budget_assert_reconciled(p_budget_month_id BIGINT)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_state public.budget_month_funding_state%ROWTYPE;
  v_negative_budget BIGINT;
BEGIN
  SELECT * INTO v_state
  FROM public.budget_month_funding_state
  WHERE budget_month_id = p_budget_month_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Budget month % does not exist', p_budget_month_id;
  END IF;
  IF v_state.available::text IN ('NaN', 'Infinity', '-Infinity')
     OR v_state.starting_total::text IN ('NaN', 'Infinity', '-Infinity')
     OR v_state.total_allocated::text IN ('NaN', 'Infinity', '-Infinity')
     OR v_state.active_allocated::text IN ('NaN', 'Infinity', '-Infinity')
     OR v_state.inactive_retained_funding::text IN ('NaN', 'Infinity', '-Infinity')
     OR v_state.unallocated::text IN ('NaN', 'Infinity', '-Infinity')
     OR v_state.available < 0 OR v_state.total_allocated < 0 OR v_state.unallocated < 0 THEN
    RAISE EXCEPTION
      'Budget month % does not reconcile: available %, allocated %, unallocated %',
      p_budget_month_id, v_state.available, v_state.total_allocated, v_state.unallocated
      USING ERRCODE = '23514';
  END IF;

  SELECT budget_id INTO v_negative_budget
  FROM public.budget_category_state
  WHERE budget_month_id = p_budget_month_id
    AND (final_funded::text IN ('NaN', 'Infinity', '-Infinity') OR final_funded < 0)
  LIMIT 1;
  IF v_negative_budget IS NOT NULL THEN
    RAISE EXCEPTION 'Budget % has a negative final funded amount', v_negative_budget
      USING ERRCODE = '23514';
  END IF;
END;
$$;

CREATE OR REPLACE FUNCTION public.get_funded_budget_month(p_month TEXT)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_month_start DATE := public.budget_month_start_from_key(p_month);
  v_month_id BIGINT;
  v_funding JSONB;
  v_categories JSONB;
  v_history JSONB;
  v_total_actual NUMERIC(18, 2);
  v_budgeted_actual NUMERIC(18, 2);
BEGIN
  SELECT id INTO v_month_id
  FROM public.budget_months
  WHERE month_start = v_month_start;

  IF EXISTS (
    SELECT 1 FROM public.transactions
    WHERE movement_type = 'expense'
      AND transaction_date >= v_month_start
      AND transaction_date < (v_month_start + interval '1 month')::date
      AND total_amount::text IN ('NaN', 'Infinity', '-Infinity')
  ) THEN
    RAISE EXCEPTION 'Budget actual spending contains a non-finite amount' USING ERRCODE = '22003';
  END IF;

  SELECT jsonb_build_object(
    'available', coalesce(s.available, 0)::numeric(18, 2)::text,
    'starting_total', coalesce(s.starting_total, 0)::numeric(18, 2)::text,
    'total_allocated', coalesce(s.total_allocated, 0)::numeric(18, 2)::text,
    'active_allocated', coalesce(s.active_allocated, 0)::numeric(18, 2)::text,
    'inactive_retained_funding', coalesce(s.inactive_retained_funding, 0)::numeric(18, 2)::text,
    'unallocated', coalesce(s.unallocated, 0)::numeric(18, 2)::text
  ) INTO v_funding
  FROM (SELECT 1) seed
  LEFT JOIN public.budget_month_funding_state s ON s.budget_month_id = v_month_id;

  WITH actuals AS (
    SELECT category_id, sum(total_amount)::numeric(18, 2) AS actual_spent
    FROM public.transactions
    WHERE movement_type = 'expense'
      AND transaction_date >= v_month_start
      AND transaction_date < (v_month_start + interval '1 month')::date
    GROUP BY category_id
  ), category_keys AS (
    SELECT category_id FROM public.budget_category_state WHERE budget_month_id = v_month_id
    UNION
    SELECT category_id FROM actuals
  )
  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'budget_id', cs.budget_id,
    'category_id', keys.category_id,
    'categories', CASE WHEN keys.category_id IS NULL THEN NULL ELSE jsonb_build_object(
      'name', c.name,
      'icon', c.icon,
      'type', c.type
    ) END,
    'lifecycle_state', coalesce(cs.lifecycle_state, 'no_budget'),
    'is_active_budget', coalesce(cs.lifecycle_state = 'active', false),
    'is_active_zero', coalesce(cs.lifecycle_state = 'active' AND cs.final_funded = 0, false),
    'is_unbudgeted', coalesce(cs.lifecycle_state <> 'active', true),
    'starting_amount', CASE WHEN cs.starting_amount IS NULL THEN NULL ELSE cs.starting_amount::numeric(18, 2)::text END,
    'starting_kind', cs.starting_kind,
    'adjustment_total', coalesce(cs.adjustment_total, 0)::numeric(18, 2)::text,
    'final_funded', CASE WHEN cs.final_funded IS NULL THEN NULL ELSE cs.final_funded::numeric(18, 2)::text END,
    'amount', CASE WHEN cs.final_funded IS NULL THEN NULL ELSE cs.final_funded::numeric(18, 2)::text END,
    'actual_spent', coalesce(a.actual_spent, 0)::numeric(18, 2)::text,
    'remaining', CASE WHEN cs.lifecycle_state = 'active'
      THEN (cs.final_funded - coalesce(a.actual_spent, 0))::numeric(18, 2)::text ELSE NULL END,
    'deficit', CASE WHEN cs.lifecycle_state = 'active'
      THEN greatest(coalesce(a.actual_spent, 0) - cs.final_funded, 0)::numeric(18, 2)::text ELSE '0.00' END
  ) ORDER BY coalesce(c.name, ''), keys.category_id), '[]'::jsonb)
  INTO v_categories
  FROM category_keys keys
  LEFT JOIN public.budget_category_state cs
    ON cs.budget_month_id = v_month_id
   AND cs.category_id IS NOT DISTINCT FROM keys.category_id
  LEFT JOIN actuals a ON a.category_id IS NOT DISTINCT FROM keys.category_id
  LEFT JOIN public.categories c ON c.id = keys.category_id;

  SELECT coalesce(sum(total_amount), 0)::numeric(18, 2)
  INTO v_total_actual
  FROM public.transactions
  WHERE movement_type = 'expense'
    AND transaction_date >= v_month_start
    AND transaction_date < (v_month_start + interval '1 month')::date;

  SELECT coalesce(sum(t.total_amount), 0)::numeric(18, 2)
  INTO v_budgeted_actual
  FROM public.transactions t
  WHERE t.movement_type = 'expense'
    AND t.transaction_date >= v_month_start
    AND t.transaction_date < (v_month_start + interval '1 month')::date
    AND EXISTS (
      SELECT 1
      FROM public.budget_category_state cs
      WHERE cs.budget_month_id = v_month_id
        AND cs.lifecycle_state = 'active'
        AND cs.category_id = t.category_id
    );

  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'id', bo.id,
    'operation_type', bo.operation_type,
    'effective_date', bo.effective_date,
    'created_at', bo.created_at,
    'reason', bo.reason,
    'reverses_operation_id', bo.reverses_operation_id,
    'funding_entries', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'id', fe.id,
        'amount_delta', fe.amount_delta::numeric(18, 2)::text,
        'source_kind', fe.source_kind,
        'source_label', fe.source_label,
        'reverses_funding_entry_id', fe.reverses_funding_entry_id
      ) ORDER BY fe.id)
      FROM public.budget_funding_entries fe WHERE fe.operation_id = bo.id
    ), '[]'::jsonb),
    'movements', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'id', m.id,
        'source_budget_id', m.source_budget_id,
        'destination_budget_id', m.destination_budget_id,
        'amount', m.amount::numeric(18, 2)::text
      ) ORDER BY m.id)
      FROM public.budget_movements m WHERE m.operation_id = bo.id
    ), '[]'::jsonb),
    'lifecycle_events', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'id', le.id,
        'budget_id', le.budget_id,
        'state', le.state,
        'actual_spent_snapshot', CASE WHEN le.actual_spent_snapshot IS NULL
          THEN NULL ELSE le.actual_spent_snapshot::numeric(18, 2)::text END
      ) ORDER BY le.id)
      FROM public.budget_lifecycle_events le WHERE le.operation_id = bo.id
    ), '[]'::jsonb)
  ) ORDER BY bo.id), '[]'::jsonb)
  INTO v_history
  FROM public.budget_operations bo
  WHERE bo.budget_month_id = v_month_id;

  RETURN jsonb_build_object(
    'month', p_month,
    'currency', 'ILS',
    'funding', v_funding,
    'actuals', jsonb_build_object(
      'total', v_total_actual::numeric(18, 2)::text,
      'budgeted', v_budgeted_actual::numeric(18, 2)::text,
      'unbudgeted', (v_total_actual - v_budgeted_actual)::numeric(18, 2)::text
    ),
    'categories', v_categories,
    'history', v_history
  );
END;
$$;

-- ---------------------------------------------------------------------------
-- Bounded mutation RPCs. All financial arithmetic remains NUMERIC in PostgreSQL.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.add_manual_budget_funding(
  p_month TEXT,
  p_amount NUMERIC,
  p_source_label TEXT,
  p_request_key UUID,
  p_reason TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_month_start DATE := public.budget_month_start_from_key(p_month);
  v_month_id BIGINT;
  v_existing public.budget_operations%ROWTYPE;
  v_fingerprint TEXT;
BEGIN
  IF p_amount IS NULL OR p_amount::text IN ('NaN', 'Infinity', '-Infinity')
     OR p_amount <= 0 OR p_amount <> round(p_amount, 2)
     OR p_amount > 9999999999999999.99 THEN
    RAISE EXCEPTION 'Manual funding amount must be a positive two-decimal value' USING ERRCODE = '22023';
  END IF;
  IF p_source_label IS NULL OR btrim(p_source_label) = '' THEN
    RAISE EXCEPTION 'Manual funding source label is required' USING ERRCODE = '22023';
  END IF;
  IF p_request_key IS NULL THEN
    RAISE EXCEPTION 'request_key is required' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.budget_months (month_start) VALUES (v_month_start)
  ON CONFLICT (month_start) DO NOTHING;
  SELECT id INTO v_month_id FROM public.budget_months
  WHERE month_start = v_month_start FOR UPDATE;

  v_fingerprint := 'manual_funding|' || p_month || '|' || p_amount::numeric(18, 2)::text || '|' || btrim(p_source_label);
  SELECT * INTO v_existing FROM public.budget_operations WHERE request_key = p_request_key;
  IF FOUND THEN
    IF v_existing.budget_month_id <> v_month_id
       OR v_existing.operation_type <> 'manual_funding'
       OR v_existing.request_fingerprint <> v_fingerprint THEN
      RAISE EXCEPTION 'request_key was already used for a different budget operation' USING ERRCODE = '23505';
    END IF;
    RETURN public.get_funded_budget_month(p_month);
  END IF;

  INSERT INTO public.budget_operations (
    budget_month_id, request_key, request_fingerprint, operation_type,
    effective_date, reason
  ) VALUES (
    v_month_id, p_request_key, v_fingerprint, 'manual_funding', v_month_start, p_reason
  ) RETURNING id INTO v_existing.id;

  INSERT INTO public.budget_funding_entries (
    operation_id, amount_delta, source_kind, source_label
  ) VALUES (
    v_existing.id, p_amount::numeric(18, 2), 'manual_available_funds', btrim(p_source_label)
  );

  PERFORM public.budget_assert_reconciled(v_month_id);
  RETURN public.get_funded_budget_month(p_month);
END;
$$;

CREATE OR REPLACE FUNCTION public.establish_funded_budget(
  p_month TEXT,
  p_category_id BIGINT,
  p_starting_amount NUMERIC,
  p_starting_kind TEXT,
  p_request_key UUID,
  p_reason TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_month_start DATE := public.budget_month_start_from_key(p_month);
  v_month_id BIGINT;
  v_operation_id BIGINT;
  v_budget_id BIGINT;
  v_existing public.budget_operations%ROWTYPE;
  v_unallocated NUMERIC(18, 2);
  v_fingerprint TEXT;
BEGIN
  IF p_starting_amount IS NULL OR p_starting_amount::text IN ('NaN', 'Infinity', '-Infinity')
     OR p_starting_amount < 0 OR p_starting_amount <> round(p_starting_amount, 2)
     OR p_starting_amount > 9999999999999999.99 THEN
    RAISE EXCEPTION 'starting_amount must be a nonnegative two-decimal value' USING ERRCODE = '22023';
  END IF;
  IF p_starting_kind NOT IN ('manual', 'copied') THEN
    RAISE EXCEPTION 'Runtime starting_kind must be manual or copied' USING ERRCODE = '22023';
  END IF;
  IF p_request_key IS NULL THEN
    RAISE EXCEPTION 'request_key is required' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.categories WHERE id = p_category_id AND type = 'expense'
  ) THEN
    RAISE EXCEPTION 'Category % is not an expense category', p_category_id USING ERRCODE = '23503';
  END IF;

  INSERT INTO public.budget_months (month_start) VALUES (v_month_start)
  ON CONFLICT (month_start) DO NOTHING;
  SELECT id INTO v_month_id FROM public.budget_months
  WHERE month_start = v_month_start FOR UPDATE;

  v_fingerprint := 'establish|' || p_month || '|' || p_category_id || '|' || p_starting_amount::numeric(18, 2)::text || '|' || p_starting_kind;
  SELECT * INTO v_existing FROM public.budget_operations WHERE request_key = p_request_key;
  IF FOUND THEN
    IF v_existing.budget_month_id <> v_month_id
       OR v_existing.operation_type <> 'establish_budget'
       OR v_existing.request_fingerprint <> v_fingerprint THEN
      RAISE EXCEPTION 'request_key was already used for a different budget operation' USING ERRCODE = '23505';
    END IF;
    RETURN public.get_funded_budget_month(p_month);
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.budgets
    WHERE budget_month_id = v_month_id AND category_id = p_category_id
  ) THEN
    RAISE EXCEPTION 'A monthly budget snapshot already exists for category %', p_category_id USING ERRCODE = '23505';
  END IF;

  SELECT unallocated INTO v_unallocated
  FROM public.budget_month_funding_state
  WHERE budget_month_id = v_month_id;
  IF p_starting_amount > coalesce(v_unallocated, 0) THEN
    RAISE EXCEPTION 'Insufficient unallocated funds: requested %, available %', p_starting_amount, coalesce(v_unallocated, 0)
      USING ERRCODE = '23514';
  END IF;

  INSERT INTO public.budget_operations (
    budget_month_id, request_key, request_fingerprint, operation_type,
    effective_date, reason
  ) VALUES (
    v_month_id, p_request_key, v_fingerprint, 'establish_budget', v_month_start, p_reason
  ) RETURNING id INTO v_operation_id;

  INSERT INTO public.budgets (
    category_id, month, amount, budget_month_id, starting_amount,
    starting_kind, created_by_operation_id
  ) VALUES (
    p_category_id, p_month, p_starting_amount, v_month_id, p_starting_amount,
    p_starting_kind, v_operation_id
  ) RETURNING id INTO v_budget_id;

  INSERT INTO public.budget_lifecycle_events (operation_id, budget_id, state)
  VALUES (v_operation_id, v_budget_id, 'active');

  PERFORM public.budget_assert_reconciled(v_month_id);
  RETURN public.get_funded_budget_month(p_month);
END;
$$;

CREATE OR REPLACE FUNCTION public.set_funded_budget_amount(
  p_budget_id BIGINT,
  p_target_amount NUMERIC,
  p_request_key UUID,
  p_reason TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_budget public.budgets%ROWTYPE;
  v_month public.budget_months%ROWTYPE;
  v_state public.budget_category_state%ROWTYPE;
  v_latest_state TEXT;
  v_actual NUMERIC(18, 2);
  v_unallocated NUMERIC(18, 2);
  v_delta NUMERIC(18, 2);
  v_operation_id BIGINT;
  v_existing public.budget_operations%ROWTYPE;
  v_fingerprint TEXT;
BEGIN
  IF p_target_amount IS NULL OR p_target_amount::text IN ('NaN', 'Infinity', '-Infinity')
     OR p_target_amount < 0 OR p_target_amount <> round(p_target_amount, 2)
     OR p_target_amount > 9999999999999999.99 THEN
    RAISE EXCEPTION 'target_amount must be a nonnegative two-decimal value' USING ERRCODE = '22023';
  END IF;
  IF p_request_key IS NULL THEN RAISE EXCEPTION 'request_key is required' USING ERRCODE = '22023'; END IF;

  SELECT * INTO v_budget FROM public.budgets WHERE id = p_budget_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Budget % does not exist', p_budget_id USING ERRCODE = 'P0002'; END IF;
  SELECT * INTO v_month FROM public.budget_months WHERE id = v_budget.budget_month_id FOR UPDATE;
  SELECT * INTO v_budget FROM public.budgets WHERE id = p_budget_id FOR UPDATE;
  SELECT * INTO v_state FROM public.budget_category_state WHERE budget_id = p_budget_id;
  v_latest_state := v_state.lifecycle_state;

  v_fingerprint := 'set_amount|' || p_budget_id || '|' || p_target_amount::numeric(18, 2)::text;
  SELECT * INTO v_existing FROM public.budget_operations WHERE request_key = p_request_key;
  IF FOUND THEN
    IF v_existing.budget_month_id <> v_month.id
       OR v_existing.operation_type <> 'adjustment'
       OR v_existing.request_fingerprint <> v_fingerprint THEN
      RAISE EXCEPTION 'request_key was already used for a different budget operation' USING ERRCODE = '23505';
    END IF;
    RETURN public.get_funded_budget_month(to_char(v_month.month_start, 'YYYY-MM'));
  END IF;

  IF v_latest_state <> 'active' THEN
    RAISE EXCEPTION 'Budget % is inactive; reactivate it before adjusting funding', p_budget_id USING ERRCODE = '55000';
  END IF;
  v_delta := p_target_amount - v_state.final_funded;
  IF v_delta = 0 THEN
    INSERT INTO public.budget_operations (
      budget_month_id, request_key, request_fingerprint, operation_type, effective_date, reason
    ) VALUES (v_month.id, p_request_key, v_fingerprint, 'adjustment', v_month.month_start, p_reason);
    PERFORM public.budget_assert_reconciled(v_month.id);
    RETURN public.get_funded_budget_month(to_char(v_month.month_start, 'YYYY-MM'));
  END IF;

  SELECT unallocated INTO v_unallocated FROM public.budget_month_funding_state
  WHERE budget_month_id = v_month.id;
  IF EXISTS (
    SELECT 1 FROM public.transactions
    WHERE movement_type = 'expense' AND category_id = v_budget.category_id
      AND transaction_date >= v_month.month_start
      AND transaction_date < (v_month.month_start + interval '1 month')::date
      AND total_amount::text IN ('NaN', 'Infinity', '-Infinity')
  ) THEN
    RAISE EXCEPTION 'Budget actual spending contains a non-finite amount' USING ERRCODE = '22003';
  END IF;
  SELECT coalesce(sum(total_amount), 0)::numeric(18, 2) INTO v_actual
  FROM public.transactions
  WHERE movement_type = 'expense' AND category_id = v_budget.category_id
    AND transaction_date >= v_month.month_start
    AND transaction_date < (v_month.month_start + interval '1 month')::date;

  IF v_delta > 0 AND v_delta > v_unallocated THEN
    RAISE EXCEPTION 'Insufficient unallocated funds: requested %, available %', v_delta, v_unallocated USING ERRCODE = '23514';
  END IF;
  IF v_delta < 0 AND -v_delta > greatest(v_state.final_funded - v_actual, 0) THEN
    RAISE EXCEPTION 'Cannot release spent funding; eligible release is %', greatest(v_state.final_funded - v_actual, 0)
      USING ERRCODE = '23514';
  END IF;

  INSERT INTO public.budget_operations (
    budget_month_id, request_key, request_fingerprint, operation_type, effective_date, reason
  ) VALUES (v_month.id, p_request_key, v_fingerprint, 'adjustment', v_month.month_start, p_reason)
  RETURNING id INTO v_operation_id;

  INSERT INTO public.budget_movements (operation_id, source_budget_id, destination_budget_id, amount)
  VALUES (
    v_operation_id,
    CASE WHEN v_delta < 0 THEN p_budget_id ELSE NULL END,
    CASE WHEN v_delta > 0 THEN p_budget_id ELSE NULL END,
    abs(v_delta)
  );

  PERFORM public.budget_assert_reconciled(v_month.id);
  RETURN public.get_funded_budget_month(to_char(v_month.month_start, 'YYYY-MM'));
END;
$$;

CREATE OR REPLACE FUNCTION public.remove_funded_budget(
  p_budget_id BIGINT,
  p_request_key UUID,
  p_reason TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_budget public.budgets%ROWTYPE;
  v_month public.budget_months%ROWTYPE;
  v_state public.budget_category_state%ROWTYPE;
  v_actual NUMERIC(18, 2);
  v_release NUMERIC(18, 2);
  v_operation_id BIGINT;
  v_existing public.budget_operations%ROWTYPE;
  v_fingerprint TEXT;
BEGIN
  IF p_request_key IS NULL THEN RAISE EXCEPTION 'request_key is required' USING ERRCODE = '22023'; END IF;
  SELECT * INTO v_budget FROM public.budgets WHERE id = p_budget_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Budget % does not exist', p_budget_id USING ERRCODE = 'P0002'; END IF;
  SELECT * INTO v_month FROM public.budget_months WHERE id = v_budget.budget_month_id FOR UPDATE;
  SELECT * INTO v_budget FROM public.budgets WHERE id = p_budget_id FOR UPDATE;
  v_fingerprint := 'remove|' || p_budget_id;
  SELECT * INTO v_existing FROM public.budget_operations WHERE request_key = p_request_key;
  IF FOUND THEN
    IF v_existing.budget_month_id <> v_month.id OR v_existing.operation_type <> 'removal'
       OR v_existing.request_fingerprint <> v_fingerprint THEN
      RAISE EXCEPTION 'request_key was already used for a different budget operation' USING ERRCODE = '23505';
    END IF;
    RETURN public.get_funded_budget_month(to_char(v_month.month_start, 'YYYY-MM'));
  END IF;

  SELECT * INTO v_state FROM public.budget_category_state WHERE budget_id = p_budget_id;
  IF v_state.lifecycle_state <> 'active' THEN
    RAISE EXCEPTION 'Budget % is not active', p_budget_id USING ERRCODE = '55000';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.transactions
    WHERE movement_type = 'expense' AND category_id = v_budget.category_id
      AND transaction_date >= v_month.month_start
      AND transaction_date < (v_month.month_start + interval '1 month')::date
      AND total_amount::text IN ('NaN', 'Infinity', '-Infinity')
  ) THEN
    RAISE EXCEPTION 'Budget actual spending contains a non-finite amount' USING ERRCODE = '22003';
  END IF;
  SELECT coalesce(sum(total_amount), 0)::numeric(18, 2) INTO v_actual
  FROM public.transactions
  WHERE movement_type = 'expense' AND category_id = v_budget.category_id
    AND transaction_date >= v_month.month_start
    AND transaction_date < (v_month.month_start + interval '1 month')::date;
  v_release := greatest(v_state.final_funded - v_actual, 0);

  INSERT INTO public.budget_operations (
    budget_month_id, request_key, request_fingerprint, operation_type, effective_date, reason
  ) VALUES (v_month.id, p_request_key, v_fingerprint, 'removal', v_month.month_start, p_reason)
  RETURNING id INTO v_operation_id;
  IF v_release > 0 THEN
    INSERT INTO public.budget_movements (operation_id, source_budget_id, destination_budget_id, amount)
    VALUES (v_operation_id, p_budget_id, NULL, v_release);
  END IF;
  INSERT INTO public.budget_lifecycle_events (operation_id, budget_id, state, actual_spent_snapshot)
  VALUES (v_operation_id, p_budget_id, 'inactive', v_actual);

  PERFORM public.budget_assert_reconciled(v_month.id);
  RETURN public.get_funded_budget_month(to_char(v_month.month_start, 'YYYY-MM'));
END;
$$;

CREATE OR REPLACE FUNCTION public.reactivate_funded_budget(
  p_budget_id BIGINT,
  p_additional_amount NUMERIC,
  p_request_key UUID,
  p_reason TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_budget public.budgets%ROWTYPE;
  v_month public.budget_months%ROWTYPE;
  v_state public.budget_category_state%ROWTYPE;
  v_unallocated NUMERIC(18, 2);
  v_operation_id BIGINT;
  v_existing public.budget_operations%ROWTYPE;
  v_fingerprint TEXT;
BEGIN
  IF p_additional_amount IS NULL OR p_additional_amount::text IN ('NaN', 'Infinity', '-Infinity')
     OR p_additional_amount < 0 OR p_additional_amount <> round(p_additional_amount, 2)
     OR p_additional_amount > 9999999999999999.99 THEN
    RAISE EXCEPTION 'additional_amount must be a nonnegative two-decimal value' USING ERRCODE = '22023';
  END IF;
  IF p_request_key IS NULL THEN RAISE EXCEPTION 'request_key is required' USING ERRCODE = '22023'; END IF;
  SELECT * INTO v_budget FROM public.budgets WHERE id = p_budget_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Budget % does not exist', p_budget_id USING ERRCODE = 'P0002'; END IF;
  SELECT * INTO v_month FROM public.budget_months WHERE id = v_budget.budget_month_id FOR UPDATE;
  SELECT * INTO v_budget FROM public.budgets WHERE id = p_budget_id FOR UPDATE;
  v_fingerprint := 'reactivate|' || p_budget_id || '|' || p_additional_amount::numeric(18, 2)::text;
  SELECT * INTO v_existing FROM public.budget_operations WHERE request_key = p_request_key;
  IF FOUND THEN
    IF v_existing.budget_month_id <> v_month.id OR v_existing.operation_type <> 'reactivation'
       OR v_existing.request_fingerprint <> v_fingerprint THEN
      RAISE EXCEPTION 'request_key was already used for a different budget operation' USING ERRCODE = '23505';
    END IF;
    RETURN public.get_funded_budget_month(to_char(v_month.month_start, 'YYYY-MM'));
  END IF;
  SELECT * INTO v_state FROM public.budget_category_state WHERE budget_id = p_budget_id;
  IF v_state.lifecycle_state <> 'inactive' THEN
    RAISE EXCEPTION 'Budget % is not inactive', p_budget_id USING ERRCODE = '55000';
  END IF;
  SELECT unallocated INTO v_unallocated FROM public.budget_month_funding_state WHERE budget_month_id = v_month.id;
  IF p_additional_amount > v_unallocated THEN
    RAISE EXCEPTION 'Insufficient unallocated funds: requested %, available %', p_additional_amount, v_unallocated
      USING ERRCODE = '23514';
  END IF;

  INSERT INTO public.budget_operations (
    budget_month_id, request_key, request_fingerprint, operation_type, effective_date, reason
  ) VALUES (v_month.id, p_request_key, v_fingerprint, 'reactivation', v_month.month_start, p_reason)
  RETURNING id INTO v_operation_id;
  IF p_additional_amount > 0 THEN
    INSERT INTO public.budget_movements (operation_id, destination_budget_id, amount)
    VALUES (v_operation_id, p_budget_id, p_additional_amount);
  END IF;
  INSERT INTO public.budget_lifecycle_events (operation_id, budget_id, state)
  VALUES (v_operation_id, p_budget_id, 'active');

  PERFORM public.budget_assert_reconciled(v_month.id);
  RETURN public.get_funded_budget_month(to_char(v_month.month_start, 'YYYY-MM'));
END;
$$;

CREATE OR REPLACE FUNCTION public.reverse_funded_budget_operation(
  p_operation_id BIGINT,
  p_request_key UUID,
  p_reason TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_original public.budget_operations%ROWTYPE;
  v_month public.budget_months%ROWTYPE;
  v_existing public.budget_operations%ROWTYPE;
  v_funding public.budget_funding_entries%ROWTYPE;
  v_movement public.budget_movements%ROWTYPE;
  v_source_state public.budget_category_state%ROWTYPE;
  v_actual NUMERIC(18, 2);
  v_unallocated NUMERIC(18, 2);
  v_reversal_id BIGINT;
  v_fingerprint TEXT;
BEGIN
  IF p_request_key IS NULL THEN RAISE EXCEPTION 'request_key is required' USING ERRCODE = '22023'; END IF;
  SELECT * INTO v_original FROM public.budget_operations WHERE id = p_operation_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Budget operation % does not exist', p_operation_id USING ERRCODE = 'P0002'; END IF;
  SELECT * INTO v_month FROM public.budget_months WHERE id = v_original.budget_month_id FOR UPDATE;
  SELECT * INTO v_original FROM public.budget_operations WHERE id = p_operation_id;
  v_fingerprint := 'reverse|' || p_operation_id;
  SELECT * INTO v_existing FROM public.budget_operations WHERE request_key = p_request_key;
  IF FOUND THEN
    IF v_existing.operation_type <> 'reversal' OR v_existing.reverses_operation_id <> p_operation_id
       OR v_existing.request_fingerprint <> v_fingerprint THEN
      RAISE EXCEPTION 'request_key was already used for a different budget operation' USING ERRCODE = '23505';
    END IF;
    RETURN public.get_funded_budget_month(to_char(v_month.month_start, 'YYYY-MM'));
  END IF;
  IF EXISTS (SELECT 1 FROM public.budget_operations WHERE reverses_operation_id = p_operation_id) THEN
    RAISE EXCEPTION 'Budget operation % has already been reversed', p_operation_id USING ERRCODE = '23505';
  END IF;

  IF v_original.operation_type = 'adjustment' THEN
    SELECT * INTO v_movement FROM public.budget_movements WHERE operation_id = p_operation_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Adjustment operation % has no movement', p_operation_id; END IF;
    PERFORM 1 FROM public.budgets
    WHERE id IN (v_movement.source_budget_id, v_movement.destination_budget_id)
    ORDER BY id FOR UPDATE;
  END IF;

  INSERT INTO public.budget_operations (
    budget_month_id, request_key, request_fingerprint, operation_type,
    effective_date, reason, reverses_operation_id
  ) VALUES (
    v_month.id, p_request_key, v_fingerprint, 'reversal', v_month.month_start,
    p_reason, p_operation_id
  ) RETURNING id INTO v_reversal_id;

  IF v_original.operation_type = 'manual_funding' THEN
    SELECT * INTO v_funding FROM public.budget_funding_entries WHERE operation_id = p_operation_id;
    IF v_funding.source_kind <> 'manual_available_funds' OR v_funding.amount_delta <= 0 THEN
      RAISE EXCEPTION 'Only positive manual funding operations can be reversed';
    END IF;
    SELECT unallocated INTO v_unallocated FROM public.budget_month_funding_state WHERE budget_month_id = v_month.id;
    IF v_funding.amount_delta > v_unallocated THEN
      RAISE EXCEPTION 'Funding reversal would make unallocated funds negative' USING ERRCODE = '23514';
    END IF;
    INSERT INTO public.budget_funding_entries (
      operation_id, amount_delta, source_kind, source_label, reverses_funding_entry_id
    ) VALUES (
      v_reversal_id, -v_funding.amount_delta, 'manual_available_funds',
      'Reversal: ' || v_funding.source_label, v_funding.id
    );
  ELSIF v_original.operation_type = 'adjustment' THEN
    IF v_movement.source_budget_id IS NULL THEN
      SELECT * INTO v_source_state FROM public.budget_category_state WHERE budget_id = v_movement.destination_budget_id;
      IF EXISTS (
        SELECT 1 FROM public.transactions t
        JOIN public.budgets b ON b.category_id = t.category_id
        WHERE b.id = v_movement.destination_budget_id
          AND t.movement_type = 'expense'
          AND t.transaction_date >= v_month.month_start
          AND t.transaction_date < (v_month.month_start + interval '1 month')::date
          AND t.total_amount::text IN ('NaN', 'Infinity', '-Infinity')
      ) THEN
        RAISE EXCEPTION 'Budget actual spending contains a non-finite amount' USING ERRCODE = '22003';
      END IF;
      SELECT coalesce(sum(t.total_amount), 0)::numeric(18, 2) INTO v_actual
      FROM public.transactions t
      JOIN public.budgets b ON b.category_id = t.category_id
      WHERE b.id = v_movement.destination_budget_id
        AND t.movement_type = 'expense'
        AND t.transaction_date >= v_month.month_start
        AND t.transaction_date < (v_month.month_start + interval '1 month')::date;
      IF v_movement.amount > greatest(v_source_state.final_funded - v_actual, 0) THEN
        RAISE EXCEPTION 'Adjustment reversal would release spent funding' USING ERRCODE = '23514';
      END IF;
    ELSE
      SELECT unallocated INTO v_unallocated FROM public.budget_month_funding_state WHERE budget_month_id = v_month.id;
      IF v_movement.amount > v_unallocated THEN
        RAISE EXCEPTION 'Adjustment reversal requires more unallocated funds than are available' USING ERRCODE = '23514';
      END IF;
    END IF;
    INSERT INTO public.budget_movements (
      operation_id, source_budget_id, destination_budget_id, amount
    ) VALUES (
      v_reversal_id, v_movement.destination_budget_id, v_movement.source_budget_id, v_movement.amount
    );
  ELSE
    RAISE EXCEPTION
      'Operation type % must be corrected through its lifecycle command, not generic reversal',
      v_original.operation_type USING ERRCODE = '0A000';
  END IF;

  PERFORM public.budget_assert_reconciled(v_month.id);
  RETURN public.get_funded_budget_month(to_char(v_month.month_start, 'YYYY-MM'));
END;
$$;

CREATE OR REPLACE FUNCTION public.copy_funded_budget_month(
  p_from_month TEXT,
  p_to_month TEXT,
  p_request_key UUID,
  p_reason TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_from_start DATE := public.budget_month_start_from_key(p_from_month);
  v_to_start DATE := public.budget_month_start_from_key(p_to_month);
  v_from_id BIGINT;
  v_to_id BIGINT;
  v_operation_id BIGINT;
  v_existing public.budget_operations%ROWTYPE;
  v_unallocated NUMERIC(18, 2);
  v_additions NUMERIC(18, 2) := 0;
  v_releases NUMERIC(18, 2) := 0;
  v_target_actual NUMERIC(18, 2);
  v_target_id BIGINT;
  v_target_final NUMERIC(18, 2);
  v_target_state TEXT;
  v_delta NUMERIC(18, 2);
  v_fingerprint TEXT;
  source_row RECORD;
BEGIN
  IF p_request_key IS NULL THEN RAISE EXCEPTION 'request_key is required' USING ERRCODE = '22023'; END IF;
  IF v_from_start = v_to_start THEN RAISE EXCEPTION 'Source and target budget months must differ' USING ERRCODE = '22023'; END IF;
  SELECT id INTO v_from_id FROM public.budget_months WHERE month_start = v_from_start;
  IF NOT FOUND THEN RAISE EXCEPTION 'Source month has no funded budget'; END IF;
  INSERT INTO public.budget_months (month_start) VALUES (v_to_start) ON CONFLICT (month_start) DO NOTHING;
  PERFORM 1 FROM public.budget_months WHERE id IN (v_from_id, (SELECT id FROM public.budget_months WHERE month_start = v_to_start)) ORDER BY id FOR UPDATE;
  SELECT id INTO v_to_id FROM public.budget_months WHERE month_start = v_to_start;
  PERFORM 1 FROM public.budgets
  WHERE budget_month_id IN (v_from_id, v_to_id)
  ORDER BY id FOR UPDATE;
  PERFORM public.budget_assert_reconciled(v_from_id);
  PERFORM public.budget_assert_reconciled(v_to_id);

  v_fingerprint := 'copy|' || p_from_month || '|' || p_to_month;
  SELECT * INTO v_existing FROM public.budget_operations WHERE request_key = p_request_key;
  IF FOUND THEN
    IF v_existing.budget_month_id <> v_to_id OR v_existing.operation_type <> 'copy'
       OR v_existing.request_fingerprint <> v_fingerprint THEN
      RAISE EXCEPTION 'request_key was already used for a different budget operation' USING ERRCODE = '23505';
    END IF;
    RETURN public.get_funded_budget_month(p_to_month);
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.budget_category_state
    WHERE budget_month_id = v_from_id AND lifecycle_state = 'active'
  ) THEN
    RAISE EXCEPTION 'Source month has no active category budgets';
  END IF;

  FOR source_row IN
    SELECT * FROM public.budget_category_state
    WHERE budget_month_id = v_from_id AND lifecycle_state = 'active'
    ORDER BY category_id
  LOOP
    SELECT cs.budget_id, cs.final_funded, cs.lifecycle_state
    INTO v_target_id, v_target_final, v_target_state
    FROM public.budget_category_state cs
    WHERE cs.budget_month_id = v_to_id AND cs.category_id = source_row.category_id;
    IF NOT FOUND THEN
      v_additions := v_additions + source_row.final_funded;
    ELSE
      v_delta := source_row.final_funded - v_target_final;
      IF v_delta > 0 THEN
        v_additions := v_additions + v_delta;
      ELSIF v_delta < 0 THEN
        IF EXISTS (
          SELECT 1 FROM public.transactions
          WHERE movement_type = 'expense' AND category_id = source_row.category_id
            AND transaction_date >= v_to_start
            AND transaction_date < (v_to_start + interval '1 month')::date
            AND total_amount::text IN ('NaN', 'Infinity', '-Infinity')
        ) THEN
          RAISE EXCEPTION 'Budget actual spending contains a non-finite amount' USING ERRCODE = '22003';
        END IF;
        SELECT coalesce(sum(total_amount), 0)::numeric(18, 2) INTO v_target_actual
        FROM public.transactions
        WHERE movement_type = 'expense' AND category_id = source_row.category_id
          AND transaction_date >= v_to_start
          AND transaction_date < (v_to_start + interval '1 month')::date;
        IF -v_delta > greatest(v_target_final - v_target_actual, 0) THEN
          RAISE EXCEPTION 'Copy cannot release spent funding from target category %', source_row.category_id USING ERRCODE = '23514';
        END IF;
        v_releases := v_releases + (-v_delta);
      END IF;
    END IF;
  END LOOP;

  SELECT unallocated INTO v_unallocated FROM public.budget_month_funding_state WHERE budget_month_id = v_to_id;
  IF v_additions > v_unallocated + v_releases THEN
    RAISE EXCEPTION 'Destination month needs % additional funded money; only % is available',
      v_additions, v_unallocated + v_releases USING ERRCODE = '23514';
  END IF;

  INSERT INTO public.budget_operations (
    budget_month_id, request_key, request_fingerprint, operation_type, effective_date, reason
  ) VALUES (v_to_id, p_request_key, v_fingerprint, 'copy', v_to_start, p_reason)
  RETURNING id INTO v_operation_id;

  FOR source_row IN
    SELECT * FROM public.budget_category_state
    WHERE budget_month_id = v_from_id AND lifecycle_state = 'active'
    ORDER BY category_id
  LOOP
    SELECT cs.budget_id, cs.final_funded, cs.lifecycle_state
    INTO v_target_id, v_target_final, v_target_state
    FROM public.budget_category_state cs
    WHERE cs.budget_month_id = v_to_id AND cs.category_id = source_row.category_id;
    IF NOT FOUND THEN
      INSERT INTO public.budgets (
        category_id, month, amount, budget_month_id, starting_amount,
        starting_kind, created_by_operation_id
      ) VALUES (
        source_row.category_id, p_to_month, source_row.final_funded, v_to_id,
        source_row.final_funded, 'copied', v_operation_id
      ) RETURNING id INTO v_target_id;
      INSERT INTO public.budget_lifecycle_events (operation_id, budget_id, state)
      VALUES (v_operation_id, v_target_id, 'active');
    ELSE
      v_delta := source_row.final_funded - v_target_final;
      IF v_delta <> 0 THEN
        INSERT INTO public.budget_movements (
          operation_id, source_budget_id, destination_budget_id, amount
        ) VALUES (
          v_operation_id,
          CASE WHEN v_delta < 0 THEN v_target_id ELSE NULL END,
          CASE WHEN v_delta > 0 THEN v_target_id ELSE NULL END,
          abs(v_delta)
        );
      END IF;
      IF v_target_state = 'inactive' THEN
        INSERT INTO public.budget_lifecycle_events (operation_id, budget_id, state)
        VALUES (v_operation_id, v_target_id, 'active');
      END IF;
    END IF;
  END LOOP;

  PERFORM public.budget_assert_reconciled(v_to_id);
  RETURN public.get_funded_budget_month(p_to_month);
END;
$$;

-- ---------------------------------------------------------------------------
-- RLS and narrow privileges. Application writes are RPC-only after cutover.
-- ---------------------------------------------------------------------------

ALTER TABLE public.budget_months ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.budget_operations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.budget_funding_entries ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.budget_movements ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.budget_lifecycle_events ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.budgets FROM PUBLIC, anon, authenticated, service_role;
GRANT SELECT ON public.budgets TO service_role;

REVOKE ALL ON public.budget_months, public.budget_operations,
  public.budget_funding_entries, public.budget_movements,
  public.budget_lifecycle_events
  FROM PUBLIC, anon, authenticated, service_role;
GRANT SELECT ON public.budget_months, public.budget_operations,
  public.budget_funding_entries, public.budget_movements,
  public.budget_lifecycle_events
  TO service_role;

REVOKE ALL ON public.budget_category_state, public.budget_month_funding_state,
  public.budget_month_category_actuals
  FROM PUBLIC, anon, authenticated, service_role;
GRANT SELECT ON public.budget_category_state, public.budget_month_funding_state,
  public.budget_month_category_actuals
  TO service_role;

REVOKE ALL ON FUNCTION public.prevent_budget_history_mutation(),
  public.validate_budget_snapshot_insert(), public.validate_budget_operation_insert(),
  public.validate_budget_movement_insert(), public.validate_budget_lifecycle_insert(),
  public.budget_month_start_from_key(TEXT), public.budget_assert_reconciled(BIGINT)
  FROM PUBLIC, anon, authenticated, service_role;

REVOKE ALL ON FUNCTION public.get_funded_budget_month(TEXT),
  public.add_manual_budget_funding(TEXT, NUMERIC, TEXT, UUID, TEXT),
  public.establish_funded_budget(TEXT, BIGINT, NUMERIC, TEXT, UUID, TEXT),
  public.set_funded_budget_amount(BIGINT, NUMERIC, UUID, TEXT),
  public.remove_funded_budget(BIGINT, UUID, TEXT),
  public.reactivate_funded_budget(BIGINT, NUMERIC, UUID, TEXT),
  public.reverse_funded_budget_operation(BIGINT, UUID, TEXT),
  public.copy_funded_budget_month(TEXT, TEXT, UUID, TEXT)
  FROM PUBLIC, anon, authenticated;

GRANT EXECUTE ON FUNCTION public.get_funded_budget_month(TEXT),
  public.add_manual_budget_funding(TEXT, NUMERIC, TEXT, UUID, TEXT),
  public.establish_funded_budget(TEXT, BIGINT, NUMERIC, TEXT, UUID, TEXT),
  public.set_funded_budget_amount(BIGINT, NUMERIC, UUID, TEXT),
  public.remove_funded_budget(BIGINT, UUID, TEXT),
  public.reactivate_funded_budget(BIGINT, NUMERIC, UUID, TEXT),
  public.reverse_funded_budget_operation(BIGINT, UUID, TEXT),
  public.copy_funded_budget_month(TEXT, TEXT, UUID, TEXT)
  TO service_role;

-- Post-backfill reconciliation is part of the migration transaction.
DO $$
DECLARE
  v_month RECORD;
  v_lifecycle_count BIGINT;
  v_budget_count BIGINT;
BEGIN
  FOR v_month IN SELECT id, month_start FROM public.budget_months ORDER BY month_start LOOP
    PERFORM public.budget_assert_reconciled(v_month.id);
  END LOOP;

  SELECT count(*) INTO v_budget_count FROM public.budgets;
  SELECT count(*) INTO v_lifecycle_count
  FROM public.budget_lifecycle_events
  WHERE state = 'active';
  IF v_lifecycle_count <> v_budget_count THEN
    RAISE EXCEPTION
      'Migration 017 reconciliation: expected one initial active lifecycle event per budget, got % for % budgets',
      v_lifecycle_count, v_budget_count;
  END IF;
END;
$$;

COMMIT;

-- Migration 018: recurring monthly budget defaults.
--
-- Recurring defaults are mutable future-planning configuration. Applying them
-- to a month is an explicit, atomic command that creates immutable opening
-- snapshots backed only by that month's existing unallocated funds.

BEGIN;

DO $$
BEGIN
  IF to_regclass('public.budget_months') IS NULL
     OR to_regclass('public.budget_operations') IS NULL
     OR to_regclass('public.budget_lifecycle_events') IS NULL
     OR to_regprocedure('public.get_funded_budget_month(text)') IS NULL
     OR to_regprocedure('public.budget_assert_reconciled(bigint)') IS NULL THEN
    RAISE EXCEPTION 'Migration 018 preflight: funded budget foundation from Migration 017 is required';
  END IF;
END;
$$;

ALTER TABLE public.budgets
  DROP CONSTRAINT budgets_starting_kind_check,
  ADD CONSTRAINT budgets_starting_kind_check CHECK (
    starting_kind IN ('manual', 'legacy_import', 'copied', 'recurring_default')
  );

ALTER TABLE public.budget_operations
  DROP CONSTRAINT budget_operations_operation_type_check,
  ADD CONSTRAINT budget_operations_operation_type_check CHECK (operation_type IN (
    'legacy_import',
    'manual_funding',
    'establish_budget',
    'adjustment',
    'removal',
    'reactivation',
    'copy',
    'reversal',
    'month_initialization'
  ));

CREATE UNIQUE INDEX budget_operations_month_initialization_key
  ON public.budget_operations (budget_month_id)
  WHERE operation_type = 'month_initialization';

CREATE TABLE public.budget_recurring_defaults (
  category_id BIGINT PRIMARY KEY REFERENCES public.categories(id) ON DELETE RESTRICT,
  amount NUMERIC(18, 2) NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text, now()),
  updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text, now()),
  CONSTRAINT budget_recurring_defaults_amount_check CHECK (
    amount::text NOT IN ('NaN', 'Infinity', '-Infinity')
    AND amount >= 0
  )
);

CREATE OR REPLACE FUNCTION public.validate_budget_recurring_default()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.categories
    WHERE id = NEW.category_id AND type = 'expense'
  ) THEN
    RAISE EXCEPTION 'Recurring budgets are available only for expense categories'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.amount::text IN ('NaN', 'Infinity', '-Infinity') OR NEW.amount < 0 THEN
    RAISE EXCEPTION 'Recurring budget amount must be a finite nonnegative NUMERIC(18,2) value'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER budget_recurring_defaults_validate
BEFORE INSERT OR UPDATE ON public.budget_recurring_defaults
FOR EACH ROW EXECUTE FUNCTION public.validate_budget_recurring_default();

CREATE OR REPLACE FUNCTION public.prevent_category_type_with_recurring_default()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
BEGIN
  IF OLD.type = 'expense' AND NEW.type <> 'expense' AND EXISTS (
    SELECT 1 FROM public.budget_recurring_defaults WHERE category_id = OLD.id
  ) THEN
    RAISE EXCEPTION 'Disable the recurring budget before changing this category type'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER categories_recurring_budget_type_guard
BEFORE UPDATE OF type ON public.categories
FOR EACH ROW EXECUTE FUNCTION public.prevent_category_type_with_recurring_default();

CREATE VIEW public.budget_recurring_defaults_read AS
SELECT
  rd.category_id,
  rd.amount::numeric(18, 2)::text AS amount_text,
  rd.created_at,
  rd.updated_at
FROM public.budget_recurring_defaults rd;

CREATE OR REPLACE FUNCTION public.set_budget_recurring_default(
  p_category_id BIGINT,
  p_amount NUMERIC
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_category public.categories%ROWTYPE;
BEGIN
  IF p_category_id IS NULL THEN
    RAISE EXCEPTION 'category_id is required' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_category
  FROM public.categories
  WHERE id = p_category_id
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Category % does not exist', p_category_id USING ERRCODE = 'P0002';
  END IF;
  IF v_category.type <> 'expense' THEN
    RAISE EXCEPTION 'Recurring budgets are available only for expense categories'
      USING ERRCODE = '23514';
  END IF;

  IF p_amount IS NULL THEN
    DELETE FROM public.budget_recurring_defaults WHERE category_id = p_category_id;
    RETURN jsonb_build_object('category_id', p_category_id, 'enabled', false, 'amount', NULL);
  END IF;

  IF p_amount::text IN ('NaN', 'Infinity', '-Infinity')
     OR p_amount < 0
     OR p_amount <> round(p_amount, 2)
     OR p_amount > 9999999999999999.99 THEN
    RAISE EXCEPTION 'Recurring budget amount must be a finite nonnegative two-decimal value'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.budget_recurring_defaults (category_id, amount)
  VALUES (p_category_id, p_amount::numeric(18, 2))
  ON CONFLICT (category_id) DO UPDATE
  SET amount = EXCLUDED.amount,
      updated_at = timezone('utc'::text, now());

  RETURN jsonb_build_object(
    'category_id', p_category_id,
    'enabled', true,
    'amount', p_amount::numeric(18, 2)::text
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.get_budget_recurring_preview(p_month TEXT)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_month_start DATE := public.budget_month_start_from_key(p_month);
  v_current_month DATE := date_trunc(
    'month', timezone('Asia/Jerusalem', statement_timestamp())
  )::date;
  v_month_id BIGINT;
  v_eligible BOOLEAN;
  v_initialized BOOLEAN := false;
  v_unallocated NUMERIC(18, 2) := 0;
  v_required NUMERIC(18, 2) := 0;
  v_shortfall NUMERIC(18, 2) := 0;
  v_pending JSONB := '[]'::jsonb;
BEGIN
  v_eligible := v_month_start >= v_current_month;
  SELECT id INTO v_month_id
  FROM public.budget_months
  WHERE month_start = v_month_start;

  IF v_month_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1 FROM public.budget_operations
      WHERE budget_month_id = v_month_id
        AND operation_type = 'month_initialization'
    ) INTO v_initialized;

    SELECT coalesce(unallocated, 0)::numeric(18, 2)
    INTO v_unallocated
    FROM public.budget_month_funding_state
    WHERE budget_month_id = v_month_id;
  END IF;

  IF v_eligible AND NOT v_initialized THEN
    SELECT
      coalesce(jsonb_agg(jsonb_build_object(
        'category_id', c.id,
        'category', jsonb_build_object('name', c.name, 'icon', c.icon, 'type', c.type),
        'amount', rd.amount::numeric(18, 2)::text
      ) ORDER BY c.name, c.id), '[]'::jsonb),
      coalesce(sum(rd.amount), 0)::numeric(18, 2)
    INTO v_pending, v_required
    FROM public.budget_recurring_defaults rd
    JOIN public.categories c ON c.id = rd.category_id
    LEFT JOIN public.budgets b
      ON b.budget_month_id = v_month_id
     AND b.category_id = rd.category_id
    WHERE c.type = 'expense'
      AND c.is_active = true
      AND b.id IS NULL;
  END IF;

  v_shortfall := greatest(v_required - v_unallocated, 0)::numeric(18, 2);
  RETURN jsonb_build_object(
    'eligible', v_eligible,
    'initialized', v_initialized,
    'pending_categories', v_pending,
    'pending_count', jsonb_array_length(v_pending),
    'required', v_required::numeric(18, 2)::text,
    'unallocated', v_unallocated::numeric(18, 2)::text,
    'shortfall', v_shortfall::numeric(18, 2)::text,
    'can_apply', v_eligible AND NOT v_initialized
      AND jsonb_array_length(v_pending) > 0 AND v_shortfall = 0
  );
END;
$$;

-- Preserve the Migration 017 read implementation as an internal foundation
-- helper and layer the recurring preview onto its JSON response. Both remain
-- STABLE: merely viewing a month never creates budget state.
ALTER FUNCTION public.get_funded_budget_month(TEXT)
  RENAME TO get_funded_budget_month_foundation;

CREATE OR REPLACE FUNCTION public.get_funded_budget_month(p_month TEXT)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
BEGIN
  RETURN public.get_funded_budget_month_foundation(p_month)
    || jsonb_build_object('recurring', public.get_budget_recurring_preview(p_month));
END;
$$;

CREATE OR REPLACE FUNCTION public.initialize_budget_recurring_defaults(
  p_month TEXT,
  p_request_key UUID,
  p_reason TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_month_start DATE := public.budget_month_start_from_key(p_month);
  v_current_month DATE := date_trunc(
    'month', timezone('Asia/Jerusalem', statement_timestamp())
  )::date;
  v_month_id BIGINT;
  v_operation_id BIGINT;
  v_budget_id BIGINT;
  v_existing public.budget_operations%ROWTYPE;
  v_required NUMERIC(18, 2) := 0;
  v_unallocated NUMERIC(18, 2) := 0;
  v_fingerprint TEXT;
  v_default RECORD;
BEGIN
  IF p_request_key IS NULL THEN
    RAISE EXCEPTION 'request_key is required' USING ERRCODE = '22023';
  END IF;
  IF v_month_start < v_current_month THEN
    RAISE EXCEPTION 'Recurring budgets cannot be initialized for a historical month'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.budget_months (month_start)
  VALUES (v_month_start)
  ON CONFLICT (month_start) DO NOTHING;

  -- Canonical lock order: month, existing budget rows by ID, configuration
  -- rows by category, then immutable operation/history inserts.
  SELECT id INTO v_month_id
  FROM public.budget_months
  WHERE month_start = v_month_start
  FOR UPDATE;

  PERFORM 1 FROM public.budgets
  WHERE budget_month_id = v_month_id
  ORDER BY id
  FOR UPDATE;

  PERFORM 1
  FROM public.categories c
  JOIN public.budget_recurring_defaults rd ON rd.category_id = c.id
  WHERE c.type = 'expense' AND c.is_active = true
  ORDER BY c.id
  FOR SHARE OF c;

  PERFORM 1
  FROM public.budget_recurring_defaults rd
  JOIN public.categories c ON c.id = rd.category_id
  WHERE c.type = 'expense' AND c.is_active = true
  ORDER BY rd.category_id
  FOR SHARE OF rd;

  v_fingerprint := 'month_initialization|' || p_month;
  SELECT * INTO v_existing
  FROM public.budget_operations
  WHERE request_key = p_request_key;
  IF FOUND THEN
    IF v_existing.budget_month_id <> v_month_id
       OR v_existing.operation_type <> 'month_initialization'
       OR v_existing.request_fingerprint <> v_fingerprint THEN
      RAISE EXCEPTION 'request_key was already used for a different budget operation'
        USING ERRCODE = '23505';
    END IF;
    RETURN public.get_funded_budget_month(p_month);
  END IF;

  -- A month is initialized once. A later command with a fresh key is also a
  -- harmless read of the already-established immutable state.
  IF EXISTS (
    SELECT 1 FROM public.budget_operations
    WHERE budget_month_id = v_month_id
      AND operation_type = 'month_initialization'
  ) THEN
    RETURN public.get_funded_budget_month(p_month);
  END IF;

  SELECT coalesce(sum(rd.amount), 0)::numeric(18, 2)
  INTO v_required
  FROM public.budget_recurring_defaults rd
  JOIN public.categories c ON c.id = rd.category_id
  LEFT JOIN public.budgets b
    ON b.budget_month_id = v_month_id
   AND b.category_id = rd.category_id
  WHERE c.type = 'expense'
    AND c.is_active = true
    AND b.id IS NULL;

  SELECT coalesce(unallocated, 0)::numeric(18, 2)
  INTO v_unallocated
  FROM public.budget_month_funding_state
  WHERE budget_month_id = v_month_id;

  IF v_required > v_unallocated THEN
    RAISE EXCEPTION 'Insufficient unallocated funds for recurring budgets: required %, available %, shortfall %',
      v_required, v_unallocated, v_required - v_unallocated
      USING ERRCODE = '23514';
  END IF;

  INSERT INTO public.budget_operations (
    budget_month_id, request_key, request_fingerprint, operation_type,
    effective_date, reason
  ) VALUES (
    v_month_id, p_request_key, v_fingerprint, 'month_initialization',
    v_month_start, p_reason
  ) RETURNING id INTO v_operation_id;

  FOR v_default IN
    SELECT rd.category_id, rd.amount
    FROM public.budget_recurring_defaults rd
    JOIN public.categories c ON c.id = rd.category_id
    LEFT JOIN public.budgets b
      ON b.budget_month_id = v_month_id
     AND b.category_id = rd.category_id
    WHERE c.type = 'expense'
      AND c.is_active = true
      AND b.id IS NULL
    ORDER BY rd.category_id
  LOOP
    INSERT INTO public.budgets (
      category_id, month, amount, budget_month_id, starting_amount,
      starting_kind, created_by_operation_id
    ) VALUES (
      v_default.category_id, p_month, v_default.amount, v_month_id,
      v_default.amount, 'recurring_default', v_operation_id
    ) RETURNING id INTO v_budget_id;

    INSERT INTO public.budget_lifecycle_events (operation_id, budget_id, state)
    VALUES (v_operation_id, v_budget_id, 'active');
  END LOOP;

  PERFORM public.budget_assert_reconciled(v_month_id);
  RETURN public.get_funded_budget_month(p_month);
END;
$$;

ALTER TABLE public.budget_recurring_defaults ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.budget_recurring_defaults,
  public.budget_recurring_defaults_read
  FROM PUBLIC, anon, authenticated, service_role;
GRANT SELECT ON public.budget_recurring_defaults,
  public.budget_recurring_defaults_read
  TO service_role;

REVOKE ALL ON FUNCTION public.validate_budget_recurring_default(),
  public.prevent_category_type_with_recurring_default(),
  public.get_budget_recurring_preview(TEXT),
  public.get_funded_budget_month_foundation(TEXT)
  FROM PUBLIC, anon, authenticated, service_role;

REVOKE ALL ON FUNCTION public.set_budget_recurring_default(BIGINT, NUMERIC),
  public.initialize_budget_recurring_defaults(TEXT, UUID, TEXT)
  FROM PUBLIC, anon, authenticated;

REVOKE EXECUTE ON FUNCTION public.get_funded_budget_month(TEXT)
  FROM PUBLIC, anon, authenticated;

-- Migration 017 granted the renamed read helper to service_role. It is now
-- internal, so remove that inherited grant and expose only the wrapper.
REVOKE EXECUTE ON FUNCTION public.get_funded_budget_month_foundation(TEXT)
  FROM service_role;

GRANT EXECUTE ON FUNCTION public.get_funded_budget_month(TEXT),
  public.set_budget_recurring_default(BIGINT, NUMERIC),
  public.initialize_budget_recurring_defaults(TEXT, UUID, TEXT)
  TO service_role;

COMMIT;
-- Migration 019: balanced category budget carryover between adjacent months.
--
-- Carryover is an explicit, immutable, cross-month transfer. The source month
-- releases category funding and records an equal negative funding entry; the
-- destination month records equal positive funding and category allocation.
-- No read path in this migration creates financial state.

BEGIN;

DO $$
BEGIN
  IF to_regclass('public.budget_months') IS NULL
     OR to_regclass('public.budget_operations') IS NULL
     OR to_regclass('public.budget_recurring_defaults') IS NULL
     OR to_regprocedure('public.get_funded_budget_month(text)') IS NULL
     OR to_regprocedure('public.get_budget_recurring_preview(text)') IS NULL
     OR to_regprocedure('public.budget_assert_reconciled(bigint)') IS NULL THEN
    RAISE EXCEPTION 'Migration 019 preflight: funded budget foundation and recurring defaults from Migrations 017 and 018 are required';
  END IF;

  IF to_regclass('public.budget_carryover_settings') IS NOT NULL
     OR to_regclass('public.budget_carryover_batches') IS NOT NULL
     OR to_regclass('public.budget_carryover_transfers') IS NOT NULL THEN
    RAISE EXCEPTION 'Migration 019 preflight: unexpected partial carryover schema exists';
  END IF;
END;
$$;

ALTER TABLE public.budgets
  DROP CONSTRAINT budgets_starting_kind_check,
  ADD CONSTRAINT budgets_starting_kind_check CHECK (
    starting_kind IN (
      'manual', 'legacy_import', 'copied', 'recurring_default', 'carryover_only'
    )
  );

ALTER TABLE public.budget_operations
  DROP CONSTRAINT budget_operations_operation_type_check,
  ADD CONSTRAINT budget_operations_operation_type_check CHECK (operation_type IN (
    'legacy_import',
    'manual_funding',
    'establish_budget',
    'adjustment',
    'removal',
    'reactivation',
    'copy',
    'reversal',
    'month_initialization',
    'carryover_out',
    'carryover_in'
  ));

ALTER TABLE public.budget_funding_entries
  DROP CONSTRAINT budget_funding_entries_source_kind_check,
  ADD CONSTRAINT budget_funding_entries_source_kind_check CHECK (
    source_kind IN ('manual_available_funds', 'legacy_import', 'carryover_transfer')
  ),
  DROP CONSTRAINT budget_funding_entry_amount_shape,
  ADD CONSTRAINT budget_funding_entry_amount_shape CHECK (
    amount_delta::text NOT IN ('NaN', 'Infinity', '-Infinity')
    AND (
      (source_kind = 'legacy_import' AND amount_delta >= 0 AND reverses_funding_entry_id IS NULL)
      OR (source_kind = 'manual_available_funds' AND amount_delta <> 0)
      OR (source_kind = 'carryover_transfer' AND amount_delta <> 0)
    )
  );

CREATE TABLE public.budget_carryover_settings (
  category_id BIGINT PRIMARY KEY REFERENCES public.categories(id) ON DELETE RESTRICT,
  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text, now()),
  updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text, now())
);

CREATE TABLE public.budget_carryover_batches (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  request_key UUID NOT NULL UNIQUE,
  request_fingerprint TEXT NOT NULL CHECK (btrim(request_fingerprint) <> ''),
  source_budget_month_id BIGINT NOT NULL REFERENCES public.budget_months(id) ON DELETE RESTRICT,
  destination_budget_month_id BIGINT NOT NULL REFERENCES public.budget_months(id) ON DELETE RESTRICT,
  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text, now()),
  CONSTRAINT budget_carryover_batches_distinct_months CHECK (
    source_budget_month_id <> destination_budget_month_id
  )
);

CREATE TABLE public.budget_carryover_transfers (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  batch_id BIGINT NOT NULL REFERENCES public.budget_carryover_batches(id) ON DELETE RESTRICT,
  source_budget_id BIGINT NOT NULL REFERENCES public.budgets(id) ON DELETE RESTRICT,
  destination_budget_id BIGINT NOT NULL REFERENCES public.budgets(id) ON DELETE RESTRICT,
  source_operation_id BIGINT NOT NULL UNIQUE REFERENCES public.budget_operations(id) ON DELETE RESTRICT,
  destination_operation_id BIGINT NOT NULL UNIQUE REFERENCES public.budget_operations(id) ON DELETE RESTRICT,
  amount NUMERIC(18, 2) NOT NULL,
  source_final_funded_snapshot NUMERIC(18, 2) NOT NULL,
  source_raw_actual_spent_snapshot NUMERIC(18, 2) NOT NULL,
  source_effective_actual_spent_snapshot NUMERIC(18, 2) NOT NULL,
  reverses_transfer_id BIGINT UNIQUE REFERENCES public.budget_carryover_transfers(id) ON DELETE RESTRICT,
  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text, now()),
  CONSTRAINT budget_carryover_transfer_amount_check CHECK (
    amount::text NOT IN ('NaN', 'Infinity', '-Infinity') AND amount > 0
  ),
  CONSTRAINT budget_carryover_transfer_final_snapshot_check CHECK (
    source_final_funded_snapshot::text NOT IN ('NaN', 'Infinity', '-Infinity')
    AND source_final_funded_snapshot >= 0
  ),
  CONSTRAINT budget_carryover_transfer_raw_actual_snapshot_check CHECK (
    source_raw_actual_spent_snapshot::text NOT IN ('NaN', 'Infinity', '-Infinity')
  ),
  CONSTRAINT budget_carryover_transfer_effective_actual_snapshot_check CHECK (
    source_effective_actual_spent_snapshot::text NOT IN ('NaN', 'Infinity', '-Infinity')
    AND source_effective_actual_spent_snapshot >= 0
  ),
  CONSTRAINT budget_carryover_transfer_distinct_budgets CHECK (
    source_budget_id <> destination_budget_id
  ),
  CONSTRAINT budget_carryover_transfer_not_self_reversing CHECK (
    reverses_transfer_id IS NULL OR reverses_transfer_id <> id
  )
);

CREATE INDEX idx_budget_carryover_batches_months
  ON public.budget_carryover_batches (source_budget_month_id, destination_budget_month_id, id);
CREATE INDEX idx_budget_carryover_transfers_source
  ON public.budget_carryover_transfers (source_budget_id, destination_budget_id, id);
CREATE INDEX idx_budget_carryover_transfers_destination
  ON public.budget_carryover_transfers (destination_budget_id, id);

CREATE OR REPLACE FUNCTION public.validate_budget_carryover_setting()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.categories
    WHERE id = NEW.category_id AND type = 'expense'
  ) THEN
    RAISE EXCEPTION 'Carryover is available only for expense categories'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER budget_carryover_settings_validate
BEFORE INSERT OR UPDATE ON public.budget_carryover_settings
FOR EACH ROW EXECUTE FUNCTION public.validate_budget_carryover_setting();

CREATE OR REPLACE FUNCTION public.prevent_category_type_with_carryover()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
BEGIN
  IF OLD.type = 'expense' AND NEW.type <> 'expense' AND EXISTS (
    SELECT 1 FROM public.budget_carryover_settings WHERE category_id = OLD.id
  ) THEN
    RAISE EXCEPTION 'Disable budget carryover before changing this category type'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER categories_carryover_type_guard
BEFORE UPDATE OF type ON public.categories
FOR EACH ROW EXECUTE FUNCTION public.prevent_category_type_with_carryover();

CREATE OR REPLACE FUNCTION public.validate_budget_carryover_batch_insert()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_source DATE;
  v_destination DATE;
BEGIN
  SELECT month_start INTO v_source FROM public.budget_months WHERE id = NEW.source_budget_month_id;
  SELECT month_start INTO v_destination FROM public.budget_months WHERE id = NEW.destination_budget_month_id;
  IF v_source IS NULL OR v_destination IS NULL
     OR v_destination <> (v_source + interval '1 month')::date THEN
    RAISE EXCEPTION 'Carryover must link consecutive calendar months'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER budget_carryover_batches_validate
BEFORE INSERT ON public.budget_carryover_batches
FOR EACH ROW EXECUTE FUNCTION public.validate_budget_carryover_batch_insert();

CREATE OR REPLACE FUNCTION public.validate_budget_carryover_transfer_insert()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_batch public.budget_carryover_batches%ROWTYPE;
  v_source public.budgets%ROWTYPE;
  v_destination public.budgets%ROWTYPE;
  v_source_operation public.budget_operations%ROWTYPE;
  v_destination_operation public.budget_operations%ROWTYPE;
  v_source_funding public.budget_funding_entries%ROWTYPE;
  v_destination_funding public.budget_funding_entries%ROWTYPE;
  v_source_movement public.budget_movements%ROWTYPE;
  v_destination_movement public.budget_movements%ROWTYPE;
BEGIN
  SELECT * INTO v_batch FROM public.budget_carryover_batches WHERE id = NEW.batch_id;
  SELECT * INTO v_source FROM public.budgets WHERE id = NEW.source_budget_id;
  SELECT * INTO v_destination FROM public.budgets WHERE id = NEW.destination_budget_id;
  SELECT * INTO v_source_operation FROM public.budget_operations WHERE id = NEW.source_operation_id;
  SELECT * INTO v_destination_operation FROM public.budget_operations WHERE id = NEW.destination_operation_id;

  IF v_source.category_id IS DISTINCT FROM v_destination.category_id THEN
    RAISE EXCEPTION 'Carryover source and destination budgets must use the same category';
  END IF;
  IF v_source.budget_month_id IS DISTINCT FROM v_batch.source_budget_month_id
     OR v_destination.budget_month_id IS DISTINCT FROM v_batch.destination_budget_month_id THEN
    RAISE EXCEPTION 'Carryover budgets do not match the batch months';
  END IF;

  IF NEW.reverses_transfer_id IS NULL THEN
    IF v_source_operation.operation_type <> 'carryover_out'
       OR v_destination_operation.operation_type <> 'carryover_in' THEN
      RAISE EXCEPTION 'Original carryover operations have invalid directions';
    END IF;
    IF EXISTS (
      SELECT 1
      FROM public.budget_carryover_transfers prior
      WHERE prior.source_budget_id = NEW.source_budget_id
        AND prior.destination_budget_id = NEW.destination_budget_id
        AND prior.reverses_transfer_id IS NULL
        AND NOT EXISTS (
          SELECT 1 FROM public.budget_carryover_transfers correction
          WHERE correction.reverses_transfer_id = prior.id
        )
    ) THEN
      RAISE EXCEPTION 'An unreversed carryover already exists for this category and month pair'
        USING ERRCODE = '23505';
    END IF;
  ELSE
    IF v_source_operation.operation_type <> 'carryover_in'
       OR v_destination_operation.operation_type <> 'carryover_out' THEN
      RAISE EXCEPTION 'Carryover reversal operations have invalid directions';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.budget_carryover_transfers original
      WHERE original.id = NEW.reverses_transfer_id
        AND original.reverses_transfer_id IS NULL
        AND original.source_budget_id = NEW.source_budget_id
        AND original.destination_budget_id = NEW.destination_budget_id
        AND original.amount = NEW.amount
    ) THEN
      RAISE EXCEPTION 'Carryover reversal does not match its original transfer';
    END IF;
  END IF;

  IF v_source_operation.budget_month_id IS DISTINCT FROM v_batch.source_budget_month_id
     OR v_destination_operation.budget_month_id IS DISTINCT FROM v_batch.destination_budget_month_id THEN
    RAISE EXCEPTION 'Carryover operations do not match the batch months';
  END IF;

  SELECT * INTO v_source_funding
  FROM public.budget_funding_entries WHERE operation_id = NEW.source_operation_id;
  SELECT * INTO v_destination_funding
  FROM public.budget_funding_entries WHERE operation_id = NEW.destination_operation_id;
  SELECT * INTO v_source_movement
  FROM public.budget_movements WHERE operation_id = NEW.source_operation_id;
  SELECT * INTO v_destination_movement
  FROM public.budget_movements WHERE operation_id = NEW.destination_operation_id;

  IF NEW.reverses_transfer_id IS NULL THEN
    IF v_source_funding.source_kind <> 'carryover_transfer'
       OR v_source_funding.amount_delta <> -NEW.amount
       OR v_source_movement.source_budget_id IS DISTINCT FROM NEW.source_budget_id
       OR v_source_movement.destination_budget_id IS NOT NULL
       OR v_source_movement.amount <> NEW.amount
       OR v_destination_funding.source_kind <> 'carryover_transfer'
       OR v_destination_funding.amount_delta <> NEW.amount
       OR v_destination_movement.source_budget_id IS NOT NULL
       OR v_destination_movement.destination_budget_id IS DISTINCT FROM NEW.destination_budget_id
       OR v_destination_movement.amount <> NEW.amount THEN
      RAISE EXCEPTION 'Carryover funding and movements are not balanced';
    END IF;
  ELSE
    IF v_source_funding.source_kind <> 'carryover_transfer'
       OR v_source_funding.amount_delta <> NEW.amount
       OR v_source_movement.source_budget_id IS NOT NULL
       OR v_source_movement.destination_budget_id IS DISTINCT FROM NEW.source_budget_id
       OR v_source_movement.amount <> NEW.amount
       OR v_destination_funding.source_kind <> 'carryover_transfer'
       OR v_destination_funding.amount_delta <> -NEW.amount
       OR v_destination_movement.source_budget_id IS DISTINCT FROM NEW.destination_budget_id
       OR v_destination_movement.destination_budget_id IS NOT NULL
       OR v_destination_movement.amount <> NEW.amount THEN
      RAISE EXCEPTION 'Carryover reversal funding and movements are not balanced';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

CREATE TRIGGER budget_carryover_transfers_validate
BEFORE INSERT ON public.budget_carryover_transfers
FOR EACH ROW EXECUTE FUNCTION public.validate_budget_carryover_transfer_insert();

CREATE TRIGGER budget_carryover_batches_immutable
BEFORE UPDATE OR DELETE ON public.budget_carryover_batches
FOR EACH ROW EXECUTE FUNCTION public.prevent_budget_history_mutation();

CREATE TRIGGER budget_carryover_transfers_immutable
BEFORE UPDATE OR DELETE ON public.budget_carryover_transfers
FOR EACH ROW EXECUTE FUNCTION public.prevent_budget_history_mutation();

CREATE VIEW public.budget_carryover_settings_read AS
SELECT category_id, true AS enabled, created_at, updated_at
FROM public.budget_carryover_settings;

CREATE VIEW public.budget_category_carryover_state AS
WITH signed AS (
  SELECT
    t.source_budget_id,
    t.destination_budget_id,
    CASE WHEN t.reverses_transfer_id IS NULL THEN t.amount ELSE -t.amount END AS amount
  FROM public.budget_carryover_transfers t
)
SELECT
  b.id AS budget_id,
  coalesce(sum(s.amount) FILTER (WHERE s.destination_budget_id = b.id), 0)::numeric(18, 2)
    AS incoming_carryover,
  coalesce(sum(s.amount) FILTER (WHERE s.source_budget_id = b.id), 0)::numeric(18, 2)
    AS outgoing_carryover
FROM public.budgets b
LEFT JOIN signed s ON s.source_budget_id = b.id OR s.destination_budget_id = b.id
GROUP BY b.id;

CREATE OR REPLACE FUNCTION public.set_budget_carryover_enabled(
  p_category_id BIGINT,
  p_enabled BOOLEAN
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_category public.categories%ROWTYPE;
BEGIN
  IF p_category_id IS NULL OR p_enabled IS NULL THEN
    RAISE EXCEPTION 'category_id and enabled are required' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_category FROM public.categories WHERE id = p_category_id FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Category % does not exist', p_category_id USING ERRCODE = 'P0002';
  END IF;
  IF v_category.type <> 'expense' THEN
    RAISE EXCEPTION 'Carryover is available only for expense categories' USING ERRCODE = '23514';
  END IF;

  IF p_enabled THEN
    INSERT INTO public.budget_carryover_settings (category_id)
    VALUES (p_category_id)
    ON CONFLICT (category_id) DO UPDATE
    SET updated_at = timezone('utc'::text, now());
  ELSE
    DELETE FROM public.budget_carryover_settings WHERE category_id = p_category_id;
  END IF;

  RETURN jsonb_build_object('category_id', p_category_id, 'enabled', p_enabled);
END;
$$;

CREATE OR REPLACE FUNCTION public.budget_carryover_candidate_rows(p_destination_month TEXT)
RETURNS TABLE (
  category_id BIGINT,
  category_name TEXT,
  category_icon TEXT,
  source_budget_id BIGINT,
  destination_budget_id BIGINT,
  source_final_funded NUMERIC(18, 2),
  source_raw_actual_spent NUMERIC(18, 2),
  source_effective_actual_spent NUMERIC(18, 2),
  eligible_amount NUMERIC(18, 2),
  status TEXT,
  blocked_reason TEXT
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_destination_start DATE := public.budget_month_start_from_key(p_destination_month);
  v_source_start DATE := (v_destination_start - interval '1 month')::date;
  v_source_id BIGINT;
  v_destination_id BIGINT;
  v_destination_initialized BOOLEAN := false;
BEGIN
  SELECT id INTO v_source_id FROM public.budget_months WHERE month_start = v_source_start;
  SELECT id INTO v_destination_id FROM public.budget_months WHERE month_start = v_destination_start;
  IF v_destination_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1 FROM public.budget_operations
      WHERE budget_month_id = v_destination_id AND operation_type = 'month_initialization'
    ) INTO v_destination_initialized;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.transactions
    WHERE movement_type = 'expense'
      AND transaction_date >= v_source_start
      AND transaction_date < v_destination_start
      AND total_amount::text IN ('NaN', 'Infinity', '-Infinity')
  ) OR EXISTS (
    SELECT 1 FROM public.transactions
    WHERE movement_type = 'expense'
      AND transaction_date >= v_destination_start
      AND transaction_date < (v_destination_start + interval '1 month')::date
      AND total_amount::text IN ('NaN', 'Infinity', '-Infinity')
  ) THEN
    RAISE EXCEPTION 'Carryover actual spending contains a non-finite amount' USING ERRCODE = '22003';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.transactions t
    WHERE t.movement_type = 'expense'
      AND t.transaction_date >= v_source_start
      AND t.transaction_date < (v_destination_start + interval '1 month')::date
    GROUP BY t.category_id, date_trunc('month', t.transaction_date)
    HAVING sum(t.total_amount) <> round(sum(t.total_amount), 2)
      OR abs(sum(t.total_amount)) > 9999999999999999.99
  ) THEN
    RAISE EXCEPTION 'Carryover actual spending must fit finite NUMERIC(18,2) exactly'
      USING ERRCODE = '22003';
  END IF;

  RETURN QUERY
  WITH source_actuals AS (
    SELECT t.category_id, coalesce(sum(t.total_amount), 0)::numeric(18, 2) AS actual
    FROM public.transactions t
    WHERE t.movement_type = 'expense'
      AND t.transaction_date >= v_source_start
      AND t.transaction_date < v_destination_start
    GROUP BY t.category_id
  ), destination_actuals AS (
    SELECT t.category_id, coalesce(sum(t.total_amount), 0)::numeric(18, 2) AS actual
    FROM public.transactions t
    WHERE t.movement_type = 'expense'
      AND t.transaction_date >= v_destination_start
      AND t.transaction_date < (v_destination_start + interval '1 month')::date
    GROUP BY t.category_id
  ), candidate AS (
    SELECT
      c.id AS category_id,
      c.name,
      c.icon,
      src.budget_id AS source_budget_id,
      dst.budget_id AS destination_budget_id,
      coalesce(src.final_funded, 0)::numeric(18, 2) AS source_final_funded,
      coalesce(sa.actual, 0)::numeric(18, 2) AS source_raw_actual_spent,
      greatest(coalesce(sa.actual, 0), 0)::numeric(18, 2) AS source_effective_actual_spent,
      greatest(
        coalesce(src.final_funded, 0) - greatest(coalesce(sa.actual, 0), 0),
        0
      )::numeric(18, 2) AS eligible_amount,
      c.is_active,
      src.lifecycle_state AS source_lifecycle,
      dst.lifecycle_state AS destination_lifecycle,
      coalesce(da.actual, 0)::numeric(18, 2) AS destination_actual,
      coalesce(dst.final_funded, 0)::numeric(18, 2) AS destination_final,
      rd.category_id IS NOT NULL AND NOT v_destination_initialized AS recurring_pending,
      EXISTS (
        SELECT 1
        FROM public.budget_carryover_transfers original
        WHERE original.source_budget_id = src.budget_id
          AND original.reverses_transfer_id IS NULL
          AND NOT EXISTS (
            SELECT 1 FROM public.budget_carryover_transfers correction
            WHERE correction.reverses_transfer_id = original.id
          )
      ) AS already_applied
    FROM public.budget_carryover_settings setting
    JOIN public.categories c ON c.id = setting.category_id
    LEFT JOIN public.budget_category_state src
      ON src.budget_month_id = v_source_id AND src.category_id = c.id
    LEFT JOIN source_actuals sa ON sa.category_id = c.id
    LEFT JOIN public.budget_category_state dst
      ON dst.budget_month_id = v_destination_id AND dst.category_id = c.id
    LEFT JOIN destination_actuals da ON da.category_id = c.id
    LEFT JOIN public.budget_recurring_defaults rd ON rd.category_id = c.id
    WHERE c.type = 'expense'
  )
  SELECT
    candidate.category_id,
    candidate.name,
    candidate.icon,
    candidate.source_budget_id,
    candidate.destination_budget_id,
    candidate.source_final_funded,
    candidate.source_raw_actual_spent,
    candidate.source_effective_actual_spent,
    candidate.eligible_amount,
    CASE
      WHEN candidate.already_applied THEN 'already_applied'
      WHEN NOT candidate.is_active THEN 'blocked'
      WHEN candidate.source_budget_id IS NULL THEN 'blocked'
      WHEN candidate.source_lifecycle <> 'active' THEN 'blocked'
      WHEN candidate.eligible_amount <= 0 THEN 'blocked'
      WHEN candidate.destination_budget_id IS NOT NULL
        AND candidate.destination_lifecycle <> 'active' THEN 'blocked'
      WHEN candidate.destination_budget_id IS NULL AND candidate.recurring_pending THEN 'blocked'
      WHEN candidate.destination_budget_id IS NULL AND candidate.destination_actual > 0 THEN 'blocked'
      WHEN candidate.destination_budget_id IS NOT NULL
        AND candidate.destination_actual > candidate.destination_final THEN 'blocked'
      ELSE 'ready'
    END,
    CASE
      WHEN candidate.already_applied THEN NULL
      WHEN NOT candidate.is_active THEN 'CATEGORY_INACTIVE'
      WHEN candidate.source_budget_id IS NULL THEN 'SOURCE_BUDGET_MISSING'
      WHEN candidate.source_lifecycle <> 'active' THEN 'SOURCE_BUDGET_INACTIVE'
      WHEN candidate.eligible_amount <= 0 THEN 'NO_ELIGIBLE_BALANCE'
      WHEN candidate.destination_budget_id IS NOT NULL
        AND candidate.destination_lifecycle <> 'active' THEN 'DESTINATION_BUDGET_INACTIVE'
      WHEN candidate.destination_budget_id IS NULL AND candidate.recurring_pending
        THEN 'RECURRING_INITIALIZATION_REQUIRED'
      WHEN candidate.destination_budget_id IS NULL AND candidate.destination_actual > 0
        THEN 'UNBUDGETED_ACTUAL_EXISTS'
      WHEN candidate.destination_budget_id IS NOT NULL
        AND candidate.destination_actual > candidate.destination_final THEN 'DESTINATION_DEFICIT'
      ELSE NULL
    END
  FROM candidate
  ORDER BY candidate.name, candidate.category_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.get_budget_carryover_preview(p_destination_month TEXT)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_destination_start DATE := public.budget_month_start_from_key(p_destination_month);
  v_source_start DATE := (v_destination_start - interval '1 month')::date;
  v_current_start DATE := date_trunc(
    'month', timezone('Asia/Jerusalem', statement_timestamp())
  )::date;
  v_ready JSONB := '[]'::jsonb;
  v_blocked JSONB := '[]'::jsonb;
  v_applied JSONB := '[]'::jsonb;
  v_total NUMERIC(18, 2) := 0;
  v_material TEXT;
  v_fingerprint TEXT;
BEGIN
  IF v_destination_start <> v_current_start THEN
    RETURN jsonb_build_object(
      'eligible', false,
      'reason', 'CURRENT_MONTH_ONLY',
      'source_month', to_char(v_source_start, 'YYYY-MM'),
      'destination_month', p_destination_month,
      'fingerprint', md5('carryover|' || p_destination_month || '|ineligible'),
      'ready_categories', '[]'::jsonb,
      'ready_count', 0,
      'total_incoming', '0.00',
      'already_applied_categories', '[]'::jsonb,
      'blocked_categories', '[]'::jsonb,
      'can_apply', false
    );
  END IF;

  WITH rows AS (
    SELECT * FROM public.budget_carryover_candidate_rows(p_destination_month)
  )
  SELECT
    coalesce(jsonb_agg(jsonb_build_object(
      'category_id', category_id,
      'category', jsonb_build_object('name', category_name, 'icon', category_icon, 'type', 'expense'),
      'source_budget_id', source_budget_id,
      'destination_budget_id', destination_budget_id,
      'source_final_funded', source_final_funded::numeric(18, 2)::text,
      'source_raw_actual_spent', source_raw_actual_spent::numeric(18, 2)::text,
      'source_effective_actual_spent', source_effective_actual_spent::numeric(18, 2)::text,
      'amount', eligible_amount::numeric(18, 2)::text
    ) ORDER BY category_name, category_id) FILTER (WHERE status = 'ready'), '[]'::jsonb),
    coalesce(jsonb_agg(jsonb_build_object(
      'category_id', category_id,
      'category', jsonb_build_object('name', category_name, 'icon', category_icon, 'type', 'expense'),
      'source_raw_actual_spent', source_raw_actual_spent::numeric(18, 2)::text,
      'source_effective_actual_spent', source_effective_actual_spent::numeric(18, 2)::text,
      'amount', eligible_amount::numeric(18, 2)::text,
      'reason', blocked_reason
    ) ORDER BY category_name, category_id) FILTER (WHERE status = 'blocked'), '[]'::jsonb),
    coalesce(jsonb_agg(jsonb_build_object(
      'category_id', category_id,
      'category', jsonb_build_object('name', category_name, 'icon', category_icon, 'type', 'expense')
    ) ORDER BY category_name, category_id) FILTER (WHERE status = 'already_applied'), '[]'::jsonb),
    coalesce(sum(eligible_amount) FILTER (WHERE status = 'ready'), 0)::numeric(18, 2),
    coalesce(string_agg(
      category_id || '|' || coalesce(source_budget_id::text, '') || '|'
      || coalesce(destination_budget_id::text, '') || '|' || status || '|'
      || source_final_funded::numeric(18, 2)::text || '|'
      || source_raw_actual_spent::numeric(18, 2)::text || '|'
      || source_effective_actual_spent::numeric(18, 2)::text || '|'
      || eligible_amount::numeric(18, 2)::text || '|' || coalesce(blocked_reason, ''),
      ';' ORDER BY category_id
    ), '')
  INTO v_ready, v_blocked, v_applied, v_total, v_material
  FROM rows;

  v_fingerprint := md5(
    'carryover|' || to_char(v_source_start, 'YYYY-MM') || '|'
    || p_destination_month || '|' || v_material
  );

  RETURN jsonb_build_object(
    'eligible', true,
    'reason', NULL,
    'source_month', to_char(v_source_start, 'YYYY-MM'),
    'destination_month', p_destination_month,
    'fingerprint', v_fingerprint,
    'ready_categories', v_ready,
    'ready_count', jsonb_array_length(v_ready),
    'total_incoming', v_total::numeric(18, 2)::text,
    'already_applied_categories', v_applied,
    'blocked_categories', v_blocked,
    'can_apply', jsonb_array_length(v_ready) > 0
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.budget_derived_request_key(p_parent UUID, p_suffix TEXT)
RETURNS UUID
LANGUAGE sql
IMMUTABLE
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
  SELECT (
    substr(md5(p_parent::text || '|' || p_suffix), 1, 8) || '-'
    || substr(md5(p_parent::text || '|' || p_suffix), 9, 4) || '-'
    || substr(md5(p_parent::text || '|' || p_suffix), 13, 4) || '-'
    || substr(md5(p_parent::text || '|' || p_suffix), 17, 4) || '-'
    || substr(md5(p_parent::text || '|' || p_suffix), 21, 12)
  )::uuid;
$$;

-- Preserve the recurring-aware Migration 018 read and add carryover preview,
-- per-category composition, and immutable transfer history.
ALTER FUNCTION public.get_funded_budget_month(TEXT)
  RENAME TO get_funded_budget_month_recurring;

CREATE OR REPLACE FUNCTION public.get_funded_budget_month(p_month TEXT)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_state JSONB := public.get_funded_budget_month_recurring(p_month);
  v_month_start DATE := public.budget_month_start_from_key(p_month);
  v_categories JSONB;
  v_history JSONB;
BEGIN
  SELECT coalesce(jsonb_agg(
    item || jsonb_build_object(
      'incoming_carryover', coalesce(cs.incoming_carryover, 0)::numeric(18, 2)::text,
      'outgoing_carryover', coalesce(cs.outgoing_carryover, 0)::numeric(18, 2)::text
    ) ORDER BY ordinality
  ), '[]'::jsonb)
  INTO v_categories
  FROM jsonb_array_elements(coalesce(v_state->'categories', '[]'::jsonb)) WITH ORDINALITY category(item, ordinality)
  LEFT JOIN public.budget_category_carryover_state cs
    ON cs.budget_id = NULLIF(item->>'budget_id', '')::bigint;

  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'transfer_id', t.id,
    'batch_id', t.batch_id,
    'source_month', to_char(source_month.month_start, 'YYYY-MM'),
    'destination_month', to_char(destination_month.month_start, 'YYYY-MM'),
    'category_id', source_budget.category_id,
    'amount', t.amount::numeric(18, 2)::text,
    'source_final_funded_snapshot', t.source_final_funded_snapshot::numeric(18, 2)::text,
    'source_raw_actual_spent_snapshot', t.source_raw_actual_spent_snapshot::numeric(18, 2)::text,
    'source_effective_actual_spent_snapshot', t.source_effective_actual_spent_snapshot::numeric(18, 2)::text,
    'reverses_transfer_id', t.reverses_transfer_id,
    'created_at', t.created_at
  ) ORDER BY t.id), '[]'::jsonb)
  INTO v_history
  FROM public.budget_carryover_transfers t
  JOIN public.budget_carryover_batches batch ON batch.id = t.batch_id
  JOIN public.budget_months source_month ON source_month.id = batch.source_budget_month_id
  JOIN public.budget_months destination_month ON destination_month.id = batch.destination_budget_month_id
  JOIN public.budgets source_budget ON source_budget.id = t.source_budget_id
  WHERE source_month.month_start = v_month_start OR destination_month.month_start = v_month_start;

  RETURN v_state
    || jsonb_build_object('categories', v_categories)
    || jsonb_build_object('carryover', public.get_budget_carryover_preview(p_month))
    || jsonb_build_object('carryover_history', v_history);
END;
$$;

CREATE OR REPLACE FUNCTION public.apply_budget_carryover(
  p_destination_month TEXT,
  p_request_key UUID,
  p_preview_fingerprint TEXT,
  p_reason TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_destination_start DATE := public.budget_month_start_from_key(p_destination_month);
  v_source_start DATE := (v_destination_start - interval '1 month')::date;
  v_current_start DATE := date_trunc(
    'month', timezone('Asia/Jerusalem', statement_timestamp())
  )::date;
  v_source_month_id BIGINT;
  v_destination_month_id BIGINT;
  v_batch_id BIGINT;
  v_existing public.budget_carryover_batches%ROWTYPE;
  v_preview JSONB;
  v_fingerprint TEXT;
  v_source_operation_id BIGINT;
  v_destination_operation_id BIGINT;
  v_destination_budget_id BIGINT;
  candidate RECORD;
BEGIN
  IF p_request_key IS NULL OR p_preview_fingerprint IS NULL
     OR p_preview_fingerprint !~ '^[0-9a-f]{32}$' THEN
    RAISE EXCEPTION 'request_key and a valid preview fingerprint are required' USING ERRCODE = '22023';
  END IF;
  IF v_destination_start <> v_current_start THEN
    RAISE EXCEPTION 'Carryover can be applied only to the current Asia/Jerusalem month'
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_existing FROM public.budget_carryover_batches WHERE request_key = p_request_key;
  IF FOUND THEN
    IF v_existing.request_fingerprint <> 'carryover_apply|' || p_destination_month || '|' || p_preview_fingerprint THEN
      RAISE EXCEPTION 'request_key was already used for a different carryover request'
        USING ERRCODE = '23505';
    END IF;
    RETURN jsonb_build_object(
      'source', public.get_funded_budget_month(to_char(v_source_start, 'YYYY-MM')),
      'destination', public.get_funded_budget_month(p_destination_month)
    );
  END IF;

  SELECT id INTO v_source_month_id FROM public.budget_months WHERE month_start = v_source_start;
  IF v_source_month_id IS NULL THEN
    RAISE EXCEPTION 'Previous month has no funded budget state' USING ERRCODE = '23514';
  END IF;

  -- Transaction writes take ROW EXCLUSIVE on this table. Taking SHARE before
  -- any budget-month lock gives apply a short, deadlock-safe serialization
  -- boundary: the captured actuals cannot change through the final write.
  LOCK TABLE public.transactions IN SHARE MODE;

  INSERT INTO public.budget_months (month_start) VALUES (v_destination_start)
  ON CONFLICT (month_start) DO NOTHING;
  SELECT id INTO v_destination_month_id FROM public.budget_months WHERE month_start = v_destination_start;

  -- Canonical cross-month order: month rows by ID, budget rows by ID,
  -- settings/categories, then immutable operations and history.
  PERFORM 1 FROM public.budget_months
  WHERE id IN (v_source_month_id, v_destination_month_id)
  ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.budgets
  WHERE budget_month_id IN (v_source_month_id, v_destination_month_id)
  ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.categories c
  JOIN public.budget_carryover_settings setting ON setting.category_id = c.id
  ORDER BY c.id FOR SHARE OF c;
  PERFORM 1 FROM public.budget_carryover_settings
  ORDER BY category_id FOR SHARE;

  PERFORM public.budget_assert_reconciled(v_source_month_id);
  PERFORM public.budget_assert_reconciled(v_destination_month_id);

  -- A concurrent retry may have observed no batch before waiting on the
  -- canonical month locks. Re-check after serialization before writing.
  SELECT * INTO v_existing FROM public.budget_carryover_batches WHERE request_key = p_request_key;
  IF FOUND THEN
    IF v_existing.request_fingerprint <> 'carryover_apply|' || p_destination_month || '|' || p_preview_fingerprint THEN
      RAISE EXCEPTION 'request_key was already used for a different carryover request'
        USING ERRCODE = '23505';
    END IF;
    RETURN jsonb_build_object(
      'source', public.get_funded_budget_month(to_char(v_source_start, 'YYYY-MM')),
      'destination', public.get_funded_budget_month(p_destination_month)
    );
  END IF;

  v_preview := public.get_budget_carryover_preview(p_destination_month);
  v_fingerprint := v_preview->>'fingerprint';
  IF v_fingerprint IS DISTINCT FROM p_preview_fingerprint THEN
    RAISE EXCEPTION 'CARRYOVER_PREVIEW_STALE: carryover candidate material changed; refresh before applying'
      USING ERRCODE = '40001';
  END IF;

  INSERT INTO public.budget_carryover_batches (
    request_key, request_fingerprint, source_budget_month_id, destination_budget_month_id
  ) VALUES (
    p_request_key,
    'carryover_apply|' || p_destination_month || '|' || p_preview_fingerprint,
    v_source_month_id,
    v_destination_month_id
  ) RETURNING id INTO v_batch_id;

  FOR candidate IN
    SELECT item
    FROM jsonb_array_elements(v_preview->'ready_categories') AS captured(item)
    ORDER BY (item->>'category_id')::bigint
  LOOP
    INSERT INTO public.budget_operations (
      budget_month_id, request_key, request_fingerprint, operation_type, effective_date, reason
    ) VALUES (
      v_source_month_id,
      public.budget_derived_request_key(p_request_key, 'source|' || (candidate.item->>'category_id')),
      'carryover_out|' || v_batch_id || '|' || (candidate.item->>'category_id') || '|' || (candidate.item->>'amount'),
      'carryover_out', v_source_start, p_reason
    ) RETURNING id INTO v_source_operation_id;

    INSERT INTO public.budget_funding_entries (
      operation_id, amount_delta, source_kind, source_label
    ) VALUES (
      v_source_operation_id, -(candidate.item->>'amount')::numeric(18, 2), 'carryover_transfer',
      'Carryover to ' || p_destination_month
    );
    INSERT INTO public.budget_movements (
      operation_id, source_budget_id, destination_budget_id, amount
    ) VALUES (
      v_source_operation_id, (candidate.item->>'source_budget_id')::bigint, NULL,
      (candidate.item->>'amount')::numeric(18, 2)
    );

    INSERT INTO public.budget_operations (
      budget_month_id, request_key, request_fingerprint, operation_type, effective_date, reason
    ) VALUES (
      v_destination_month_id,
      public.budget_derived_request_key(p_request_key, 'destination|' || (candidate.item->>'category_id')),
      'carryover_in|' || v_batch_id || '|' || (candidate.item->>'category_id') || '|' || (candidate.item->>'amount'),
      'carryover_in', v_destination_start, p_reason
    ) RETURNING id INTO v_destination_operation_id;

    IF candidate.item->>'destination_budget_id' IS NULL THEN
      INSERT INTO public.budgets (
        category_id, month, amount, budget_month_id, starting_amount,
        starting_kind, created_by_operation_id
      ) VALUES (
        (candidate.item->>'category_id')::bigint, p_destination_month, 0, v_destination_month_id,
        0, 'carryover_only', v_destination_operation_id
      ) RETURNING id INTO v_destination_budget_id;
      INSERT INTO public.budget_lifecycle_events (operation_id, budget_id, state)
      VALUES (v_destination_operation_id, v_destination_budget_id, 'active');
    ELSE
      v_destination_budget_id := (candidate.item->>'destination_budget_id')::bigint;
    END IF;

    INSERT INTO public.budget_funding_entries (
      operation_id, amount_delta, source_kind, source_label
    ) VALUES (
      v_destination_operation_id, (candidate.item->>'amount')::numeric(18, 2), 'carryover_transfer',
      'Carryover from ' || to_char(v_source_start, 'YYYY-MM')
    );
    INSERT INTO public.budget_movements (
      operation_id, source_budget_id, destination_budget_id, amount
    ) VALUES (
      v_destination_operation_id, NULL, v_destination_budget_id,
      (candidate.item->>'amount')::numeric(18, 2)
    );

    INSERT INTO public.budget_carryover_transfers (
      batch_id, source_budget_id, destination_budget_id,
      source_operation_id, destination_operation_id, amount,
      source_final_funded_snapshot, source_raw_actual_spent_snapshot,
      source_effective_actual_spent_snapshot
    ) VALUES (
      v_batch_id, (candidate.item->>'source_budget_id')::bigint, v_destination_budget_id,
      v_source_operation_id, v_destination_operation_id,
      (candidate.item->>'amount')::numeric(18, 2),
      (candidate.item->>'source_final_funded')::numeric(18, 2),
      (candidate.item->>'source_raw_actual_spent')::numeric(18, 2),
      (candidate.item->>'source_effective_actual_spent')::numeric(18, 2)
    );
  END LOOP;

  PERFORM public.budget_assert_reconciled(v_source_month_id);
  PERFORM public.budget_assert_reconciled(v_destination_month_id);
  RETURN jsonb_build_object(
    'source', public.get_funded_budget_month(to_char(v_source_start, 'YYYY-MM')),
    'destination', public.get_funded_budget_month(p_destination_month)
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.reverse_budget_carryover(
  p_transfer_id BIGINT,
  p_request_key UUID,
  p_reason TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_original public.budget_carryover_transfers%ROWTYPE;
  v_batch public.budget_carryover_batches%ROWTYPE;
  v_source public.budget_category_state%ROWTYPE;
  v_destination public.budget_category_state%ROWTYPE;
  v_source_month public.budget_months%ROWTYPE;
  v_destination_month public.budget_months%ROWTYPE;
  v_destination_actual NUMERIC(18, 2);
  v_existing public.budget_operations%ROWTYPE;
  v_source_operation_id BIGINT;
  v_destination_operation_id BIGINT;
  v_source_funding public.budget_funding_entries%ROWTYPE;
  v_destination_funding public.budget_funding_entries%ROWTYPE;
BEGIN
  IF p_transfer_id IS NULL OR p_request_key IS NULL THEN
    RAISE EXCEPTION 'transfer_id and request_key are required' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_original FROM public.budget_carryover_transfers WHERE id = p_transfer_id;
  IF NOT FOUND OR v_original.reverses_transfer_id IS NOT NULL THEN
    RAISE EXCEPTION 'Original carryover transfer % does not exist', p_transfer_id USING ERRCODE = 'P0002';
  END IF;
  SELECT * INTO v_batch FROM public.budget_carryover_batches WHERE id = v_original.batch_id;

  SELECT * INTO v_existing FROM public.budget_operations WHERE request_key = p_request_key;
  IF FOUND THEN
    IF v_existing.operation_type <> 'carryover_out'
       OR v_existing.request_fingerprint <> 'carryover_reverse|' || p_transfer_id THEN
      RAISE EXCEPTION 'request_key was already used for a different carryover request'
        USING ERRCODE = '23505';
    END IF;
    RETURN jsonb_build_object(
      'source', public.get_funded_budget_month((SELECT month FROM public.budget_month_funding_state WHERE budget_month_id = v_batch.source_budget_month_id)),
      'destination', public.get_funded_budget_month((SELECT month FROM public.budget_month_funding_state WHERE budget_month_id = v_batch.destination_budget_month_id))
    );
  END IF;
  IF EXISTS (SELECT 1 FROM public.budget_carryover_transfers WHERE reverses_transfer_id = p_transfer_id) THEN
    RAISE EXCEPTION 'Carryover transfer % has already been reversed', p_transfer_id USING ERRCODE = '23505';
  END IF;

  -- Keep the destination-spending safety check linearizable with transaction
  -- inserts, updates, and deletes for the duration of the compensating write.
  LOCK TABLE public.transactions IN SHARE MODE;

  PERFORM 1 FROM public.budget_months
  WHERE id IN (v_batch.source_budget_month_id, v_batch.destination_budget_month_id)
  ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.budgets
  WHERE id IN (v_original.source_budget_id, v_original.destination_budget_id)
  ORDER BY id FOR UPDATE;

  -- Re-check idempotency and prior reversal after the shared month/budget
  -- lock order has serialized concurrent correction attempts.
  SELECT * INTO v_existing FROM public.budget_operations WHERE request_key = p_request_key;
  IF FOUND THEN
    IF v_existing.operation_type <> 'carryover_out'
       OR v_existing.request_fingerprint <> 'carryover_reverse|' || p_transfer_id THEN
      RAISE EXCEPTION 'request_key was already used for a different carryover request'
        USING ERRCODE = '23505';
    END IF;
    RETURN jsonb_build_object(
      'source', public.get_funded_budget_month((SELECT month FROM public.budget_month_funding_state WHERE budget_month_id = v_batch.source_budget_month_id)),
      'destination', public.get_funded_budget_month((SELECT month FROM public.budget_month_funding_state WHERE budget_month_id = v_batch.destination_budget_month_id))
    );
  END IF;
  IF EXISTS (SELECT 1 FROM public.budget_carryover_transfers WHERE reverses_transfer_id = p_transfer_id) THEN
    RAISE EXCEPTION 'Carryover transfer % has already been reversed', p_transfer_id USING ERRCODE = '23505';
  END IF;

  SELECT * INTO v_source FROM public.budget_category_state WHERE budget_id = v_original.source_budget_id;
  SELECT * INTO v_destination FROM public.budget_category_state WHERE budget_id = v_original.destination_budget_id;
  SELECT * INTO v_source_month FROM public.budget_months WHERE id = v_batch.source_budget_month_id;
  SELECT * INTO v_destination_month FROM public.budget_months WHERE id = v_batch.destination_budget_month_id;
  IF v_source.lifecycle_state <> 'active' OR v_destination.lifecycle_state <> 'active' THEN
    RAISE EXCEPTION 'Carryover reversal requires active source and destination budgets'
      USING ERRCODE = '23514';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.transactions
    WHERE movement_type = 'expense'
      AND category_id = v_destination.category_id
      AND transaction_date >= v_destination_month.month_start
      AND transaction_date < (v_destination_month.month_start + interval '1 month')::date
      AND total_amount::text IN ('NaN', 'Infinity', '-Infinity')
  ) THEN
    RAISE EXCEPTION 'Carryover actual spending contains a non-finite amount' USING ERRCODE = '22003';
  END IF;
  SELECT greatest(coalesce(sum(total_amount), 0), 0)::numeric(18, 2)
  INTO v_destination_actual
  FROM public.transactions
  WHERE movement_type = 'expense'
    AND category_id = v_destination.category_id
    AND transaction_date >= v_destination_month.month_start
    AND transaction_date < (v_destination_month.month_start + interval '1 month')::date;
  IF v_original.amount > greatest(v_destination.final_funded - v_destination_actual, 0) THEN
    RAISE EXCEPTION 'Carryover reversal would release spent destination funding'
      USING ERRCODE = '23514';
  END IF;

  SELECT * INTO v_source_funding FROM public.budget_funding_entries
  WHERE operation_id = v_original.source_operation_id;
  SELECT * INTO v_destination_funding FROM public.budget_funding_entries
  WHERE operation_id = v_original.destination_operation_id;

  INSERT INTO public.budget_operations (
    budget_month_id, request_key, request_fingerprint, operation_type,
    effective_date, reason, reverses_operation_id
  ) VALUES (
    v_batch.destination_budget_month_id, p_request_key,
    'carryover_reverse|' || p_transfer_id, 'carryover_out',
    v_destination_month.month_start, p_reason, v_original.destination_operation_id
  ) RETURNING id INTO v_destination_operation_id;
  INSERT INTO public.budget_funding_entries (
    operation_id, amount_delta, source_kind, source_label, reverses_funding_entry_id
  ) VALUES (
    v_destination_operation_id, -v_original.amount, 'carryover_transfer',
    'Carryover reversal to ' || to_char(v_source_month.month_start, 'YYYY-MM'),
    v_destination_funding.id
  );
  INSERT INTO public.budget_movements (operation_id, source_budget_id, amount)
  VALUES (v_destination_operation_id, v_original.destination_budget_id, v_original.amount);

  INSERT INTO public.budget_operations (
    budget_month_id, request_key, request_fingerprint, operation_type,
    effective_date, reason, reverses_operation_id
  ) VALUES (
    v_batch.source_budget_month_id,
    public.budget_derived_request_key(p_request_key, 'source-return'),
    'carryover_reverse_return|' || p_transfer_id, 'carryover_in',
    v_source_month.month_start, p_reason, v_original.source_operation_id
  ) RETURNING id INTO v_source_operation_id;
  INSERT INTO public.budget_funding_entries (
    operation_id, amount_delta, source_kind, source_label, reverses_funding_entry_id
  ) VALUES (
    v_source_operation_id, v_original.amount, 'carryover_transfer',
    'Carryover reversal from ' || to_char(v_destination_month.month_start, 'YYYY-MM'),
    v_source_funding.id
  );
  INSERT INTO public.budget_movements (operation_id, destination_budget_id, amount)
  VALUES (v_source_operation_id, v_original.source_budget_id, v_original.amount);

  INSERT INTO public.budget_carryover_transfers (
    batch_id, source_budget_id, destination_budget_id,
    source_operation_id, destination_operation_id, amount,
    source_final_funded_snapshot, source_raw_actual_spent_snapshot,
    source_effective_actual_spent_snapshot,
    reverses_transfer_id
  ) VALUES (
    v_original.batch_id, v_original.source_budget_id, v_original.destination_budget_id,
    v_source_operation_id, v_destination_operation_id, v_original.amount,
    v_original.source_final_funded_snapshot, v_original.source_raw_actual_spent_snapshot,
    v_original.source_effective_actual_spent_snapshot,
    v_original.id
  );

  PERFORM public.budget_assert_reconciled(v_batch.source_budget_month_id);
  PERFORM public.budget_assert_reconciled(v_batch.destination_budget_month_id);
  RETURN jsonb_build_object(
    'source', public.get_funded_budget_month(to_char(v_source_month.month_start, 'YYYY-MM')),
    'destination', public.get_funded_budget_month(to_char(v_destination_month.month_start, 'YYYY-MM'))
  );
END;
$$;

ALTER TABLE public.budget_carryover_settings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.budget_carryover_batches ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.budget_carryover_transfers ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.budget_carryover_settings,
  public.budget_carryover_batches,
  public.budget_carryover_transfers,
  public.budget_carryover_settings_read,
  public.budget_category_carryover_state
  FROM PUBLIC, anon, authenticated, service_role;
GRANT SELECT ON public.budget_carryover_settings,
  public.budget_carryover_batches,
  public.budget_carryover_transfers,
  public.budget_carryover_settings_read,
  public.budget_category_carryover_state
  TO service_role;

REVOKE ALL ON FUNCTION public.validate_budget_carryover_setting(),
  public.prevent_category_type_with_carryover(),
  public.validate_budget_carryover_batch_insert(),
  public.validate_budget_carryover_transfer_insert(),
  public.budget_carryover_candidate_rows(TEXT),
  public.get_budget_carryover_preview(TEXT),
  public.budget_derived_request_key(UUID, TEXT),
  public.get_funded_budget_month_recurring(TEXT)
  FROM PUBLIC, anon, authenticated, service_role;

REVOKE ALL ON FUNCTION public.set_budget_carryover_enabled(BIGINT, BOOLEAN),
  public.apply_budget_carryover(TEXT, UUID, TEXT, TEXT),
  public.reverse_budget_carryover(BIGINT, UUID, TEXT)
  FROM PUBLIC, anon, authenticated;

REVOKE EXECUTE ON FUNCTION public.get_funded_budget_month(TEXT)
  FROM PUBLIC, anon, authenticated;

GRANT EXECUTE ON FUNCTION public.get_funded_budget_month(TEXT),
  public.set_budget_carryover_enabled(BIGINT, BOOLEAN),
  public.apply_budget_carryover(TEXT, UUID, TEXT, TEXT),
  public.reverse_budget_carryover(BIGINT, UUID, TEXT)
  TO service_role;

-- The Migration 018 wrapper is now internal; the service role calls only the
-- Migration 019 canonical wrapper.
REVOKE EXECUTE ON FUNCTION public.get_funded_budget_month_recurring(TEXT)
  FROM service_role;

COMMIT;
-- Migration 020: month-specific funded-budget base overrides.
--
-- Override rows are mutable planning configuration. Once a category snapshot
-- exists, the funded result is represented only by immutable operations,
-- movements, lifecycle events, and append-only override provenance.

BEGIN;

DO $$
BEGIN
  IF to_regclass('public.budget_months') IS NULL
     OR to_regclass('public.budget_carryover_transfers') IS NULL
     OR to_regclass('public.budget_recurring_defaults') IS NULL
     OR to_regprocedure('public.get_funded_budget_month(text)') IS NULL
     OR to_regprocedure('public.budget_derived_request_key(uuid,text)') IS NULL THEN
    RAISE EXCEPTION 'Migration 020 preflight: Migrations 017, 018, and 019 are required';
  END IF;
  IF to_regclass('public.budget_month_overrides') IS NOT NULL
     OR to_regclass('public.budget_month_override_events') IS NOT NULL
     OR to_regclass('public.budget_category_base_state') IS NOT NULL
     OR to_regprocedure('public.set_budget_month_override(text,bigint,numeric,uuid,text)') IS NOT NULL
     OR to_regprocedure('public.remove_budget_month_override(text,bigint,uuid,text)') IS NOT NULL THEN
    RAISE EXCEPTION 'Migration 020 preflight: unexpected partial month-override schema exists';
  END IF;
END;
$$;

ALTER TABLE public.budgets
  DROP CONSTRAINT budgets_starting_kind_check,
  ADD CONSTRAINT budgets_starting_kind_check CHECK (
    starting_kind IN (
      'manual', 'legacy_import', 'copied', 'recurring_default',
      'carryover_only', 'monthly_override'
    )
  );

ALTER TABLE public.budget_operations
  DROP CONSTRAINT budget_operations_operation_type_check,
  ADD CONSTRAINT budget_operations_operation_type_check CHECK (operation_type IN (
    'legacy_import', 'manual_funding', 'establish_budget', 'adjustment',
    'removal', 'reactivation', 'copy', 'reversal', 'month_initialization',
    'carryover_out', 'carryover_in', 'monthly_override_set',
    'monthly_override_remove'
  ));

CREATE TABLE public.budget_month_overrides (
  budget_month_id BIGINT NOT NULL REFERENCES public.budget_months(id) ON DELETE RESTRICT,
  category_id BIGINT NOT NULL REFERENCES public.categories(id) ON DELETE RESTRICT,
  amount NUMERIC(18, 2) NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text, now()),
  updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text, now()),
  PRIMARY KEY (budget_month_id, category_id),
  CONSTRAINT budget_month_overrides_amount_check CHECK (
    amount::text NOT IN ('NaN', 'Infinity', '-Infinity') AND amount >= 0
  )
);

CREATE TABLE public.budget_month_override_events (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  request_key UUID NOT NULL UNIQUE,
  request_fingerprint TEXT NOT NULL CHECK (btrim(request_fingerprint) <> ''),
  budget_month_id BIGINT NOT NULL REFERENCES public.budget_months(id) ON DELETE RESTRICT,
  category_id BIGINT NOT NULL REFERENCES public.categories(id) ON DELETE RESTRICT,
  budget_id BIGINT REFERENCES public.budgets(id) ON DELETE RESTRICT,
  financial_operation_id BIGINT REFERENCES public.budget_operations(id) ON DELETE RESTRICT,
  action TEXT NOT NULL CHECK (action IN ('set', 'remove', 'initialize')),
  requested_override_amount NUMERIC(18, 2),
  previous_effective_base NUMERIC(18, 2) NOT NULL,
  resulting_effective_base NUMERIC(18, 2) NOT NULL,
  fallback_base_snapshot NUMERIC(18, 2) NOT NULL,
  fallback_source TEXT NOT NULL CHECK (fallback_source IN (
    'none', 'manual', 'legacy_import', 'copied', 'recurring_default',
    'carryover_only', 'monthly_override'
  )),
  applied_base_delta NUMERIC(18, 2) NOT NULL,
  reverses_event_id BIGINT UNIQUE REFERENCES public.budget_month_override_events(id) ON DELETE RESTRICT,
  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text, now()),
  CONSTRAINT budget_month_override_events_money_check CHECK (
    previous_effective_base::text NOT IN ('NaN', 'Infinity', '-Infinity')
    AND resulting_effective_base::text NOT IN ('NaN', 'Infinity', '-Infinity')
    AND fallback_base_snapshot::text NOT IN ('NaN', 'Infinity', '-Infinity')
    AND applied_base_delta::text NOT IN ('NaN', 'Infinity', '-Infinity')
    AND previous_effective_base >= 0
    AND resulting_effective_base >= 0
    AND fallback_base_snapshot >= 0
    AND (requested_override_amount IS NULL OR (
      requested_override_amount::text NOT IN ('NaN', 'Infinity', '-Infinity')
      AND requested_override_amount >= 0
    ))
  ),
  CONSTRAINT budget_month_override_events_action_amount_check CHECK (
    (action IN ('set', 'initialize') AND requested_override_amount IS NOT NULL)
    OR (action = 'remove' AND requested_override_amount IS NULL)
  ),
  CONSTRAINT budget_month_override_events_not_self_reversing CHECK (
    reverses_event_id IS NULL OR reverses_event_id <> id
  )
);

CREATE INDEX idx_budget_month_override_events_month_category
  ON public.budget_month_override_events (budget_month_id, category_id, id);
CREATE INDEX idx_budget_month_override_events_budget
  ON public.budget_month_override_events (budget_id, id)
  WHERE budget_id IS NOT NULL;

CREATE OR REPLACE FUNCTION public.validate_budget_month_override()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.categories
    WHERE id = NEW.category_id AND type = 'expense' AND is_active = true
  ) THEN
    RAISE EXCEPTION 'Month overrides are available only for active expense categories'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.amount::text IN ('NaN', 'Infinity', '-Infinity') OR NEW.amount < 0 THEN
    RAISE EXCEPTION 'Month override amount must be a finite nonnegative NUMERIC(18,2) value'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.prevent_category_type_with_month_override()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
BEGIN
  IF (OLD.type = 'expense' AND NEW.type <> 'expense'
      OR OLD.is_active = true AND NEW.is_active = false)
     AND EXISTS (
       SELECT 1 FROM public.budget_month_overrides WHERE category_id = OLD.id
     ) THEN
    RAISE EXCEPTION 'Remove month overrides before changing this category type or active state'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.validate_budget_month_override_event()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_budget public.budgets%ROWTYPE;
  v_operation public.budget_operations%ROWTYPE;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.categories WHERE id = NEW.category_id AND type = 'expense') THEN
    RAISE EXCEPTION 'Month override events require an expense category' USING ERRCODE = '23514';
  END IF;
  IF NEW.budget_id IS NOT NULL THEN
    SELECT * INTO v_budget FROM public.budgets WHERE id = NEW.budget_id;
    IF NOT FOUND OR v_budget.budget_month_id <> NEW.budget_month_id
       OR v_budget.category_id <> NEW.category_id THEN
      RAISE EXCEPTION 'Month override event budget does not match its month/category'
        USING ERRCODE = '23514';
    END IF;
  END IF;
  IF NEW.financial_operation_id IS NOT NULL THEN
    SELECT * INTO v_operation FROM public.budget_operations WHERE id = NEW.financial_operation_id;
    IF NOT FOUND OR v_operation.budget_month_id <> NEW.budget_month_id
       OR v_operation.operation_type NOT IN ('monthly_override_set', 'monthly_override_remove', 'month_initialization') THEN
      RAISE EXCEPTION 'Month override event operation does not match its month/action'
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER budget_month_overrides_validate
BEFORE INSERT OR UPDATE ON public.budget_month_overrides
FOR EACH ROW EXECUTE FUNCTION public.validate_budget_month_override();
CREATE TRIGGER categories_month_override_guard
BEFORE UPDATE OF type, is_active ON public.categories
FOR EACH ROW EXECUTE FUNCTION public.prevent_category_type_with_month_override();
CREATE TRIGGER budget_month_override_events_validate
BEFORE INSERT ON public.budget_month_override_events
FOR EACH ROW EXECUTE FUNCTION public.validate_budget_month_override_event();
CREATE TRIGGER budget_month_override_events_immutable
BEFORE UPDATE OR DELETE ON public.budget_month_override_events
FOR EACH ROW EXECUTE FUNCTION public.prevent_budget_history_mutation();

CREATE VIEW public.budget_month_overrides_read AS
SELECT
  mo.budget_month_id,
  to_char(bm.month_start, 'YYYY-MM') AS month,
  mo.category_id,
  mo.amount::numeric(18, 2)::text AS amount_text,
  mo.created_at,
  mo.updated_at
FROM public.budget_month_overrides mo
JOIN public.budget_months bm ON bm.id = mo.budget_month_id;

-- This view is the authoritative base/carryover/other-adjustment decomposition.
-- Starting snapshots and all movements remain immutable; no mutable override row
-- is used to calculate funded history.
CREATE VIEW public.budget_category_base_state AS
WITH override_events AS (
  SELECT
    e.budget_id,
    coalesce(sum(e.applied_base_delta) FILTER (
      WHERE e.financial_operation_id IS NOT NULL
        AND e.action IN ('set', 'remove')
    ), 0)::numeric(18, 2) AS override_adjustment_total
  FROM public.budget_month_override_events e
  WHERE e.budget_id IS NOT NULL
  GROUP BY e.budget_id
), initialization AS (
  SELECT DISTINCT ON (e.budget_id)
    e.budget_id, e.fallback_base_snapshot, e.fallback_source
  FROM public.budget_month_override_events e
  WHERE e.action = 'initialize' AND e.budget_id IS NOT NULL
  ORDER BY e.budget_id, e.id
)
SELECT
  cs.budget_id,
  cs.budget_month_id,
  cs.month,
  cs.month_start,
  cs.category_id,
  CASE WHEN cs.starting_kind = 'monthly_override'
    THEN coalesce(init.fallback_base_snapshot, 0)
    ELSE cs.starting_amount
  END::numeric(18, 2) AS fallback_base,
  CASE WHEN cs.starting_kind = 'monthly_override'
    THEN coalesce(init.fallback_source, 'none')
    ELSE cs.starting_kind
  END AS fallback_source,
  mo.amount AS current_override,
  coalesce(events.override_adjustment_total, 0)::numeric(18, 2) AS override_adjustment_total,
  (cs.starting_amount + coalesce(events.override_adjustment_total, 0))::numeric(18, 2)
    AS effective_base,
  coalesce(carry.incoming_carryover, 0)::numeric(18, 2) AS incoming_carryover,
  coalesce(carry.outgoing_carryover, 0)::numeric(18, 2) AS outgoing_carryover,
  (
    cs.adjustment_total - coalesce(events.override_adjustment_total, 0)
    - coalesce(carry.incoming_carryover, 0) + coalesce(carry.outgoing_carryover, 0)
  )::numeric(18, 2) AS other_adjustments,
  cs.final_funded,
  cs.lifecycle_state
FROM public.budget_category_state cs
LEFT JOIN override_events events ON events.budget_id = cs.budget_id
LEFT JOIN initialization init ON init.budget_id = cs.budget_id
LEFT JOIN public.budget_month_overrides mo
  ON mo.budget_month_id = cs.budget_month_id AND mo.category_id = cs.category_id
LEFT JOIN public.budget_category_carryover_state carry ON carry.budget_id = cs.budget_id;

CREATE OR REPLACE FUNCTION public.get_budget_month_override_preview(p_month TEXT)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_month_start DATE := public.budget_month_start_from_key(p_month);
  v_current_start DATE := date_trunc('month', timezone('Asia/Jerusalem', statement_timestamp()))::date;
  v_month_id BIGINT;
  v_rows JSONB;
BEGIN
  SELECT id INTO v_month_id FROM public.budget_months WHERE month_start = v_month_start;
  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'category_id', mo.category_id,
    'category', jsonb_build_object('name', c.name, 'icon', c.icon, 'type', c.type),
    'amount', mo.amount::numeric(18, 2)::text,
    'initialized', base.budget_id IS NOT NULL,
    'fallback_base', coalesce(base.fallback_base, rd.amount, 0)::numeric(18, 2)::text,
    'fallback_source', coalesce(base.fallback_source,
      CASE WHEN rd.category_id IS NULL THEN 'none' ELSE 'recurring_default' END),
    'effective_base', coalesce(base.effective_base, mo.amount)::numeric(18, 2)::text
  ) ORDER BY c.name, mo.category_id), '[]'::jsonb)
  INTO v_rows
  FROM public.budget_month_overrides mo
  JOIN public.categories c ON c.id = mo.category_id
  LEFT JOIN public.budget_category_base_state base
    ON base.budget_month_id = mo.budget_month_id AND base.category_id = mo.category_id
  LEFT JOIN public.budget_recurring_defaults rd ON rd.category_id = mo.category_id
  WHERE mo.budget_month_id = v_month_id;
  RETURN jsonb_build_object(
    'eligible', v_month_start >= v_current_start,
    'month', p_month,
    'overrides', v_rows,
    'count', jsonb_array_length(v_rows)
  );
END;
$$;

-- Preserve the Migration 019 read and extend it with a truthful base
-- composition. This function remains STABLE and creates no planning or
-- financial state when a month is opened.
ALTER FUNCTION public.get_funded_budget_month(TEXT)
  RENAME TO get_funded_budget_month_carryover;

CREATE OR REPLACE FUNCTION public.get_funded_budget_month(p_month TEXT)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_state JSONB := public.get_funded_budget_month_carryover(p_month);
  v_categories JSONB;
BEGIN
  SELECT coalesce(jsonb_agg(
    item || jsonb_build_object(
      'fallback_base', CASE WHEN base.budget_id IS NULL THEN NULL ELSE base.fallback_base::numeric(18, 2)::text END,
      'fallback_source', base.fallback_source,
      'recurring_default', CASE WHEN rd.amount IS NULL THEN NULL ELSE rd.amount::numeric(18, 2)::text END,
      'month_override', CASE WHEN base.current_override IS NULL THEN NULL ELSE base.current_override::numeric(18, 2)::text END,
      'override_adjustment_total', coalesce(base.override_adjustment_total, 0)::numeric(18, 2)::text,
      'effective_base', CASE WHEN base.budget_id IS NULL THEN NULL ELSE base.effective_base::numeric(18, 2)::text END,
      'incoming_carryover', coalesce(base.incoming_carryover, 0)::numeric(18, 2)::text,
      'outgoing_carryover', coalesce(base.outgoing_carryover, 0)::numeric(18, 2)::text,
      'other_adjustments', coalesce(base.other_adjustments, 0)::numeric(18, 2)::text
    ) ORDER BY ordinality
  ), '[]'::jsonb)
  INTO v_categories
  FROM jsonb_array_elements(coalesce(v_state->'categories', '[]'::jsonb))
    WITH ORDINALITY category(item, ordinality)
  LEFT JOIN public.budget_category_base_state base
    ON base.budget_id = NULLIF(item->>'budget_id', '')::bigint
  LEFT JOIN public.budget_recurring_defaults rd
    ON rd.category_id = NULLIF(item->>'category_id', '')::bigint;

  RETURN v_state
    || jsonb_build_object('categories', v_categories)
    || jsonb_build_object('month_overrides', public.get_budget_month_override_preview(p_month));
END;
$$;

CREATE OR REPLACE FUNCTION public.set_budget_month_override(
  p_month TEXT,
  p_category_id BIGINT,
  p_amount NUMERIC,
  p_request_key UUID,
  p_reason TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_month_start DATE := public.budget_month_start_from_key(p_month);
  v_current_start DATE := date_trunc('month', timezone('Asia/Jerusalem', statement_timestamp()))::date;
  v_month_id BIGINT;
  v_budget public.budget_category_state%ROWTYPE;
  v_base public.budget_category_base_state%ROWTYPE;
  v_existing_event public.budget_month_override_events%ROWTYPE;
  v_initialized BOOLEAN;
  v_fingerprint TEXT;
  v_operation_id BIGINT;
  v_delta NUMERIC(18, 2);
  v_unallocated NUMERIC(18, 2);
  v_raw_actual NUMERIC;
  v_effective_actual NUMERIC(18, 2);
  v_base_headroom NUMERIC(18, 2);
  v_total_headroom NUMERIC(18, 2);
  v_eligible_release NUMERIC(18, 2);
  v_fallback NUMERIC(18, 2);
  v_fallback_source TEXT;
  v_prior_override NUMERIC(18, 2);
BEGIN
  IF p_request_key IS NULL OR p_category_id IS NULL OR p_amount IS NULL THEN
    RAISE EXCEPTION 'month, category_id, amount, and request_key are required' USING ERRCODE = '22023';
  END IF;
  IF p_amount::text IN ('NaN', 'Infinity', '-Infinity') OR p_amount < 0
     OR p_amount <> round(p_amount, 2) OR p_amount > 9999999999999999.99 THEN
    RAISE EXCEPTION 'Month override amount must be a finite nonnegative two-decimal value'
      USING ERRCODE = '22023';
  END IF;
  IF v_month_start < v_current_start THEN
    RAISE EXCEPTION 'HISTORICAL_MONTH_OVERRIDE_FORBIDDEN: month overrides are limited to current/future Asia/Jerusalem months'
      USING ERRCODE = '22023';
  END IF;
  v_fingerprint := 'month_override_set|' || p_month || '|' || p_category_id || '|'
    || p_amount::numeric(18, 2)::text;

  -- ROW EXCLUSIVE transaction mutations conflict with SHARE. Taking this
  -- first makes every release calculation stable through its final write and
  -- preserves the same global order used by carryover.
  LOCK TABLE public.transactions IN SHARE MODE;
  INSERT INTO public.budget_months (month_start) VALUES (v_month_start)
  ON CONFLICT (month_start) DO NOTHING;
  SELECT id INTO v_month_id FROM public.budget_months WHERE month_start = v_month_start FOR UPDATE;
  PERFORM 1 FROM public.budgets WHERE budget_month_id = v_month_id ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.categories WHERE id = p_category_id FOR SHARE;
  IF NOT EXISTS (
    SELECT 1 FROM public.categories
    WHERE id = p_category_id AND type = 'expense' AND is_active = true
  ) THEN
    RAISE EXCEPTION 'Month overrides are available only for active expense categories'
      USING ERRCODE = '23514';
  END IF;
  PERFORM 1 FROM public.budget_recurring_defaults WHERE category_id = p_category_id FOR SHARE;
  PERFORM 1 FROM public.budget_month_overrides
    WHERE budget_month_id = v_month_id AND category_id = p_category_id FOR UPDATE;

  SELECT * INTO v_existing_event
  FROM public.budget_month_override_events WHERE request_key = p_request_key;
  IF FOUND THEN
    IF v_existing_event.request_fingerprint <> v_fingerprint THEN
      RAISE EXCEPTION 'request_key was already used for a different month override request'
        USING ERRCODE = '23505';
    END IF;
    RETURN public.get_funded_budget_month(p_month);
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.budget_operations
    WHERE budget_month_id = v_month_id AND operation_type = 'month_initialization'
  ) INTO v_initialized;
  SELECT * INTO v_budget FROM public.budget_category_state
    WHERE budget_month_id = v_month_id AND category_id = p_category_id;
  SELECT amount INTO v_prior_override FROM public.budget_month_overrides
    WHERE budget_month_id = v_month_id AND category_id = p_category_id;

  IF v_budget.budget_id IS NULL AND NOT v_initialized THEN
    SELECT coalesce(amount, 0)::numeric(18, 2),
      CASE WHEN amount IS NULL THEN 'none' ELSE 'recurring_default' END
    INTO v_fallback, v_fallback_source
    FROM (SELECT (SELECT amount FROM public.budget_recurring_defaults
                  WHERE category_id = p_category_id) AS amount) recurring;
    INSERT INTO public.budget_month_overrides (budget_month_id, category_id, amount)
    VALUES (v_month_id, p_category_id, p_amount::numeric(18, 2))
    ON CONFLICT (budget_month_id, category_id) DO UPDATE
    SET amount = EXCLUDED.amount, updated_at = timezone('utc'::text, now());
    INSERT INTO public.budget_month_override_events (
      request_key, request_fingerprint, budget_month_id, category_id, action,
      requested_override_amount, previous_effective_base, resulting_effective_base,
      fallback_base_snapshot, fallback_source, applied_base_delta
    ) VALUES (
      p_request_key, v_fingerprint, v_month_id, p_category_id, 'set', p_amount,
      coalesce(v_prior_override, v_fallback), p_amount, v_fallback, v_fallback_source, 0
    );
    RETURN public.get_funded_budget_month(p_month);
  END IF;

  IF v_budget.budget_id IS NULL THEN
    SELECT coalesce(amount, 0)::numeric(18, 2),
      CASE WHEN amount IS NULL THEN 'none' ELSE 'recurring_default' END
    INTO v_fallback, v_fallback_source
    FROM (SELECT (SELECT amount FROM public.budget_recurring_defaults
                  WHERE category_id = p_category_id) AS amount) recurring;
    SELECT coalesce(unallocated, 0)::numeric(18, 2) INTO v_unallocated
      FROM public.budget_month_funding_state WHERE budget_month_id = v_month_id;
    IF p_amount > v_unallocated THEN
      RAISE EXCEPTION 'MONTH_OVERRIDE_INSUFFICIENT_FUNDS: required %, available %, shortfall %',
        p_amount::numeric(18, 2), v_unallocated, (p_amount - v_unallocated)::numeric(18, 2)
        USING ERRCODE = '23514';
    END IF;
    INSERT INTO public.budget_operations (
      budget_month_id, request_key, request_fingerprint, operation_type, effective_date, reason
    ) VALUES (
      v_month_id, p_request_key, v_fingerprint, 'monthly_override_set', v_month_start, p_reason
    ) RETURNING id INTO v_operation_id;
    INSERT INTO public.budgets (
      category_id, month, amount, budget_month_id, starting_amount, starting_kind, created_by_operation_id
    ) VALUES (
      p_category_id, p_month, p_amount, v_month_id, p_amount, 'monthly_override', v_operation_id
    ) RETURNING id INTO v_budget.budget_id;
    INSERT INTO public.budget_lifecycle_events (operation_id, budget_id, state)
    VALUES (v_operation_id, v_budget.budget_id, 'active');
    INSERT INTO public.budget_month_overrides (budget_month_id, category_id, amount)
    VALUES (v_month_id, p_category_id, p_amount);
    INSERT INTO public.budget_month_override_events (
      request_key, request_fingerprint, budget_month_id, category_id, budget_id,
      financial_operation_id, action, requested_override_amount,
      previous_effective_base, resulting_effective_base, fallback_base_snapshot,
      fallback_source, applied_base_delta
    ) VALUES (
      p_request_key, v_fingerprint, v_month_id, p_category_id, v_budget.budget_id,
      v_operation_id, 'initialize', p_amount, v_fallback, p_amount, v_fallback,
      v_fallback_source, 0
    );
    PERFORM public.budget_assert_reconciled(v_month_id);
    RETURN public.get_funded_budget_month(p_month);
  END IF;

  IF v_budget.lifecycle_state <> 'active' THEN
    RAISE EXCEPTION 'Month override requires an active category budget' USING ERRCODE = '23514';
  END IF;
  SELECT * INTO v_base FROM public.budget_category_base_state WHERE budget_id = v_budget.budget_id;
  v_delta := p_amount::numeric(18, 2) - v_base.effective_base;
  SELECT coalesce(unallocated, 0)::numeric(18, 2) INTO v_unallocated
    FROM public.budget_month_funding_state WHERE budget_month_id = v_month_id;
  IF v_delta > 0 AND v_delta > v_unallocated THEN
    RAISE EXCEPTION 'MONTH_OVERRIDE_INSUFFICIENT_FUNDS: required %, available %, shortfall %',
      v_delta, v_unallocated, (v_delta - v_unallocated)::numeric(18, 2)
      USING ERRCODE = '23514';
  END IF;
  IF v_delta < 0 THEN
    IF EXISTS (
      SELECT 1 FROM public.transactions
      WHERE movement_type = 'expense' AND category_id = p_category_id
        AND transaction_date >= v_month_start
        AND transaction_date < (v_month_start + interval '1 month')::date
        AND total_amount::text IN ('NaN', 'Infinity', '-Infinity')
    ) THEN
      RAISE EXCEPTION 'Month override actual spending contains a non-finite amount' USING ERRCODE = '22003';
    END IF;
    SELECT coalesce(sum(total_amount), 0) INTO v_raw_actual
    FROM public.transactions
    WHERE movement_type = 'expense' AND category_id = p_category_id
      AND transaction_date >= v_month_start
      AND transaction_date < (v_month_start + interval '1 month')::date;
    IF v_raw_actual <> round(v_raw_actual, 2) OR abs(v_raw_actual) > 9999999999999999.99 THEN
      RAISE EXCEPTION 'Month override actual spending must fit finite NUMERIC(18,2) exactly'
        USING ERRCODE = '22003';
    END IF;
    v_effective_actual := greatest(v_raw_actual, 0)::numeric(18, 2);
    v_base_headroom := greatest(v_base.effective_base - v_effective_actual, 0)::numeric(18, 2);
    v_total_headroom := greatest(v_base.final_funded - v_effective_actual, 0)::numeric(18, 2);
    v_eligible_release := least(v_base_headroom, v_total_headroom)::numeric(18, 2);
    IF -v_delta > v_eligible_release THEN
      RAISE EXCEPTION 'MONTH_OVERRIDE_RELEASE_BLOCKED: requested release %, eligible release %, shortfall %',
        -v_delta, v_eligible_release, (-v_delta - v_eligible_release)::numeric(18, 2)
        USING ERRCODE = '23514';
    END IF;
  END IF;

  INSERT INTO public.budget_operations (
    budget_month_id, request_key, request_fingerprint, operation_type, effective_date, reason
  ) VALUES (
    v_month_id, p_request_key, v_fingerprint, 'monthly_override_set', v_month_start, p_reason
  ) RETURNING id INTO v_operation_id;
  IF v_delta <> 0 THEN
    INSERT INTO public.budget_movements (operation_id, source_budget_id, destination_budget_id, amount)
    VALUES (
      v_operation_id,
      CASE WHEN v_delta < 0 THEN v_budget.budget_id ELSE NULL END,
      CASE WHEN v_delta > 0 THEN v_budget.budget_id ELSE NULL END,
      abs(v_delta)
    );
  END IF;
  INSERT INTO public.budget_month_overrides (budget_month_id, category_id, amount)
  VALUES (v_month_id, p_category_id, p_amount::numeric(18, 2))
  ON CONFLICT (budget_month_id, category_id) DO UPDATE
  SET amount = EXCLUDED.amount, updated_at = timezone('utc'::text, now());
  INSERT INTO public.budget_month_override_events (
    request_key, request_fingerprint, budget_month_id, category_id, budget_id,
    financial_operation_id, action, requested_override_amount,
    previous_effective_base, resulting_effective_base, fallback_base_snapshot,
    fallback_source, applied_base_delta
  ) VALUES (
    p_request_key, v_fingerprint, v_month_id, p_category_id, v_budget.budget_id,
    v_operation_id, 'set', p_amount, v_base.effective_base, p_amount,
    v_base.fallback_base, v_base.fallback_source, v_delta
  );
  PERFORM public.budget_assert_reconciled(v_month_id);
  RETURN public.get_funded_budget_month(p_month);
END;
$$;

CREATE OR REPLACE FUNCTION public.remove_budget_month_override(
  p_month TEXT,
  p_category_id BIGINT,
  p_request_key UUID,
  p_reason TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_month_start DATE := public.budget_month_start_from_key(p_month);
  v_current_start DATE := date_trunc('month', timezone('Asia/Jerusalem', statement_timestamp()))::date;
  v_month_id BIGINT;
  v_override NUMERIC(18, 2);
  v_budget public.budget_category_state%ROWTYPE;
  v_base public.budget_category_base_state%ROWTYPE;
  v_existing_event public.budget_month_override_events%ROWTYPE;
  v_fingerprint TEXT;
  v_operation_id BIGINT;
  v_delta NUMERIC(18, 2);
  v_unallocated NUMERIC(18, 2);
  v_raw_actual NUMERIC;
  v_effective_actual NUMERIC(18, 2) := 0;
  v_eligible_release NUMERIC(18, 2);
  v_fallback NUMERIC(18, 2);
  v_fallback_source TEXT;
  v_new_final NUMERIC(18, 2);
BEGIN
  IF p_request_key IS NULL OR p_category_id IS NULL THEN
    RAISE EXCEPTION 'month, category_id, and request_key are required' USING ERRCODE = '22023';
  END IF;
  IF v_month_start < v_current_start THEN
    RAISE EXCEPTION 'HISTORICAL_MONTH_OVERRIDE_FORBIDDEN: month overrides are limited to current/future Asia/Jerusalem months'
      USING ERRCODE = '22023';
  END IF;
  v_fingerprint := 'month_override_remove|' || p_month || '|' || p_category_id;
  LOCK TABLE public.transactions IN SHARE MODE;
  INSERT INTO public.budget_months (month_start) VALUES (v_month_start)
  ON CONFLICT (month_start) DO NOTHING;
  SELECT id INTO v_month_id FROM public.budget_months WHERE month_start = v_month_start FOR UPDATE;
  PERFORM 1 FROM public.budgets WHERE budget_month_id = v_month_id ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.categories WHERE id = p_category_id FOR SHARE;
  IF NOT EXISTS (SELECT 1 FROM public.categories WHERE id = p_category_id AND type = 'expense') THEN
    RAISE EXCEPTION 'Month overrides are available only for expense categories' USING ERRCODE = '23514';
  END IF;
  PERFORM 1 FROM public.budget_recurring_defaults WHERE category_id = p_category_id FOR SHARE;
  PERFORM 1 FROM public.budget_month_overrides
    WHERE budget_month_id = v_month_id AND category_id = p_category_id FOR UPDATE;

  SELECT * INTO v_existing_event FROM public.budget_month_override_events WHERE request_key = p_request_key;
  IF FOUND THEN
    IF v_existing_event.request_fingerprint <> v_fingerprint THEN
      RAISE EXCEPTION 'request_key was already used for a different month override request'
        USING ERRCODE = '23505';
    END IF;
    RETURN public.get_funded_budget_month(p_month);
  END IF;

  SELECT amount INTO v_override FROM public.budget_month_overrides
    WHERE budget_month_id = v_month_id AND category_id = p_category_id;
  SELECT * INTO v_budget FROM public.budget_category_state
    WHERE budget_month_id = v_month_id AND category_id = p_category_id;
  SELECT coalesce(amount, 0)::numeric(18, 2),
    CASE WHEN amount IS NULL THEN 'none' ELSE 'recurring_default' END
  INTO v_fallback, v_fallback_source
  FROM (SELECT (SELECT amount FROM public.budget_recurring_defaults
                WHERE category_id = p_category_id) AS amount) recurring;

  IF v_budget.budget_id IS NULL THEN
    IF v_override IS NOT NULL THEN
      DELETE FROM public.budget_month_overrides
      WHERE budget_month_id = v_month_id AND category_id = p_category_id;
    END IF;
    INSERT INTO public.budget_month_override_events (
      request_key, request_fingerprint, budget_month_id, category_id, action,
      previous_effective_base, resulting_effective_base, fallback_base_snapshot,
      fallback_source, applied_base_delta
    ) VALUES (
      p_request_key, v_fingerprint, v_month_id, p_category_id, 'remove',
      coalesce(v_override, v_fallback), v_fallback, v_fallback, v_fallback_source, 0
    );
    RETURN public.get_funded_budget_month(p_month);
  END IF;
  SELECT * INTO v_base FROM public.budget_category_base_state WHERE budget_id = v_budget.budget_id;
  IF v_override IS NULL THEN
    INSERT INTO public.budget_month_override_events (
      request_key, request_fingerprint, budget_month_id, category_id, budget_id,
      action, previous_effective_base, resulting_effective_base,
      fallback_base_snapshot, fallback_source, applied_base_delta
    ) VALUES (
      p_request_key, v_fingerprint, v_month_id, p_category_id, v_budget.budget_id,
      'remove', v_base.effective_base, v_base.effective_base,
      v_base.fallback_base, v_base.fallback_source, 0
    );
    RETURN public.get_funded_budget_month(p_month);
  END IF;
  IF v_budget.lifecycle_state <> 'active' THEN
    RAISE EXCEPTION 'Month override removal requires an active category budget' USING ERRCODE = '23514';
  END IF;
  v_delta := v_base.fallback_base - v_base.effective_base;
  IF EXISTS (
    SELECT 1 FROM public.transactions
    WHERE movement_type = 'expense' AND category_id = p_category_id
      AND transaction_date >= v_month_start
      AND transaction_date < (v_month_start + interval '1 month')::date
      AND total_amount::text IN ('NaN', 'Infinity', '-Infinity')
  ) THEN
    RAISE EXCEPTION 'Month override actual spending contains a non-finite amount' USING ERRCODE = '22003';
  END IF;
  SELECT coalesce(sum(total_amount), 0) INTO v_raw_actual
  FROM public.transactions
  WHERE movement_type = 'expense' AND category_id = p_category_id
    AND transaction_date >= v_month_start
    AND transaction_date < (v_month_start + interval '1 month')::date;
  IF v_raw_actual <> round(v_raw_actual, 2) OR abs(v_raw_actual) > 9999999999999999.99 THEN
    RAISE EXCEPTION 'Month override actual spending must fit finite NUMERIC(18,2) exactly'
      USING ERRCODE = '22003';
  END IF;
  v_effective_actual := greatest(v_raw_actual, 0)::numeric(18, 2);
  SELECT coalesce(unallocated, 0)::numeric(18, 2) INTO v_unallocated
    FROM public.budget_month_funding_state WHERE budget_month_id = v_month_id;
  IF v_delta > 0 AND v_delta > v_unallocated THEN
    RAISE EXCEPTION 'MONTH_OVERRIDE_INSUFFICIENT_FUNDS: required %, available %, shortfall %',
      v_delta, v_unallocated, (v_delta - v_unallocated)::numeric(18, 2)
      USING ERRCODE = '23514';
  END IF;
  IF v_delta < 0 THEN
    v_eligible_release := least(
      greatest(v_base.effective_base - v_effective_actual, 0),
      greatest(v_base.final_funded - v_effective_actual, 0)
    )::numeric(18, 2);
    IF -v_delta > v_eligible_release THEN
      RAISE EXCEPTION 'MONTH_OVERRIDE_RELEASE_BLOCKED: requested release %, eligible release %, shortfall %',
        -v_delta, v_eligible_release, (-v_delta - v_eligible_release)::numeric(18, 2)
        USING ERRCODE = '23514';
    END IF;
  END IF;

  INSERT INTO public.budget_operations (
    budget_month_id, request_key, request_fingerprint, operation_type, effective_date, reason
  ) VALUES (
    v_month_id, p_request_key, v_fingerprint, 'monthly_override_remove', v_month_start, p_reason
  ) RETURNING id INTO v_operation_id;
  IF v_delta <> 0 THEN
    INSERT INTO public.budget_movements (operation_id, source_budget_id, destination_budget_id, amount)
    VALUES (
      v_operation_id,
      CASE WHEN v_delta < 0 THEN v_budget.budget_id ELSE NULL END,
      CASE WHEN v_delta > 0 THEN v_budget.budget_id ELSE NULL END,
      abs(v_delta)
    );
  END IF;
  DELETE FROM public.budget_month_overrides
    WHERE budget_month_id = v_month_id AND category_id = p_category_id;
  INSERT INTO public.budget_month_override_events (
    request_key, request_fingerprint, budget_month_id, category_id, budget_id,
    financial_operation_id, action, previous_effective_base, resulting_effective_base,
    fallback_base_snapshot, fallback_source, applied_base_delta
  ) VALUES (
    p_request_key, v_fingerprint, v_month_id, p_category_id, v_budget.budget_id,
    v_operation_id, 'remove', v_base.effective_base, v_base.fallback_base,
    v_base.fallback_base, v_base.fallback_source, v_delta
  );

  v_new_final := v_base.final_funded + v_delta;
  IF v_base.fallback_base = 0 AND v_new_final = 0 AND v_effective_actual = 0
     AND v_base.incoming_carryover = 0 AND v_base.outgoing_carryover = 0
     AND v_base.other_adjustments = 0 THEN
    INSERT INTO public.budget_lifecycle_events (
      operation_id, budget_id, state, actual_spent_snapshot
    ) VALUES (v_operation_id, v_budget.budget_id, 'inactive', 0);
  END IF;
  PERFORM public.budget_assert_reconciled(v_month_id);
  RETURN public.get_funded_budget_month(p_month);
END;
$$;

-- Override-aware recurring preview. A pending override wins even when there is
-- no recurring default, and its exact zero is distinct from no override.
CREATE OR REPLACE FUNCTION public.get_budget_recurring_preview(p_month TEXT)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_month_start DATE := public.budget_month_start_from_key(p_month);
  v_current_month DATE := date_trunc('month', timezone('Asia/Jerusalem', statement_timestamp()))::date;
  v_month_id BIGINT;
  v_eligible BOOLEAN;
  v_initialized BOOLEAN := false;
  v_unallocated NUMERIC(18, 2) := 0;
  v_required NUMERIC(18, 2) := 0;
  v_shortfall NUMERIC(18, 2) := 0;
  v_pending JSONB := '[]'::jsonb;
BEGIN
  v_eligible := v_month_start >= v_current_month;
  SELECT id INTO v_month_id FROM public.budget_months WHERE month_start = v_month_start;
  IF v_month_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1 FROM public.budget_operations
      WHERE budget_month_id = v_month_id AND operation_type = 'month_initialization'
    ) INTO v_initialized;
    SELECT coalesce(unallocated, 0)::numeric(18, 2) INTO v_unallocated
    FROM public.budget_month_funding_state WHERE budget_month_id = v_month_id;
  END IF;

  IF v_eligible AND NOT v_initialized THEN
    WITH category_config AS (
      SELECT category_id FROM public.budget_recurring_defaults
      UNION
      SELECT category_id FROM public.budget_month_overrides WHERE budget_month_id = v_month_id
    ), candidates AS (
      SELECT
        c.id AS category_id, c.name, c.icon, c.type,
        CASE WHEN mo.category_id IS NOT NULL THEN mo.amount ELSE rd.amount END::numeric(18, 2) AS amount,
        CASE WHEN mo.category_id IS NOT NULL THEN 'monthly_override' ELSE 'recurring_default' END AS starting_kind,
        coalesce(rd.amount, 0)::numeric(18, 2) AS fallback_base,
        CASE WHEN rd.category_id IS NULL THEN 'none' ELSE 'recurring_default' END AS fallback_source
      FROM category_config keys
      JOIN public.categories c ON c.id = keys.category_id
      LEFT JOIN public.budget_recurring_defaults rd ON rd.category_id = keys.category_id
      LEFT JOIN public.budget_month_overrides mo
        ON mo.budget_month_id = v_month_id AND mo.category_id = keys.category_id
      LEFT JOIN public.budgets b
        ON b.budget_month_id = v_month_id AND b.category_id = keys.category_id
      WHERE c.type = 'expense' AND c.is_active = true AND b.id IS NULL
    )
    SELECT
      coalesce(jsonb_agg(jsonb_build_object(
        'category_id', category_id,
        'category', jsonb_build_object('name', name, 'icon', icon, 'type', type),
        'amount', amount::numeric(18, 2)::text,
        'starting_kind', starting_kind,
        'fallback_base', fallback_base::numeric(18, 2)::text,
        'fallback_source', fallback_source
      ) ORDER BY name, category_id), '[]'::jsonb),
      coalesce(sum(amount), 0)::numeric(18, 2)
    INTO v_pending, v_required
    FROM candidates;
  END IF;

  v_shortfall := greatest(v_required - v_unallocated, 0)::numeric(18, 2);
  RETURN jsonb_build_object(
    'eligible', v_eligible,
    'initialized', v_initialized,
    'pending_categories', v_pending,
    'pending_count', jsonb_array_length(v_pending),
    'required', v_required::numeric(18, 2)::text,
    'unallocated', v_unallocated::numeric(18, 2)::text,
    'shortfall', v_shortfall::numeric(18, 2)::text,
    'can_apply', v_eligible AND NOT v_initialized
      AND jsonb_array_length(v_pending) > 0 AND v_shortfall = 0
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.initialize_budget_recurring_defaults(
  p_month TEXT,
  p_request_key UUID,
  p_reason TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_month_start DATE := public.budget_month_start_from_key(p_month);
  v_current_month DATE := date_trunc('month', timezone('Asia/Jerusalem', statement_timestamp()))::date;
  v_month_id BIGINT;
  v_operation_id BIGINT;
  v_budget_id BIGINT;
  v_existing public.budget_operations%ROWTYPE;
  v_required NUMERIC(18, 2) := 0;
  v_unallocated NUMERIC(18, 2) := 0;
  v_fingerprint TEXT := 'month_initialization|' || p_month;
  candidate RECORD;
BEGIN
  IF p_request_key IS NULL THEN
    RAISE EXCEPTION 'request_key is required' USING ERRCODE = '22023';
  END IF;
  IF v_month_start < v_current_month THEN
    RAISE EXCEPTION 'Recurring budgets cannot be initialized for a historical month'
      USING ERRCODE = '22023';
  END IF;
  INSERT INTO public.budget_months (month_start) VALUES (v_month_start)
  ON CONFLICT (month_start) DO NOTHING;
  SELECT id INTO v_month_id FROM public.budget_months WHERE month_start = v_month_start FOR UPDATE;
  PERFORM 1 FROM public.budgets WHERE budget_month_id = v_month_id ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.categories c
  WHERE c.id IN (
    SELECT category_id FROM public.budget_recurring_defaults
    UNION SELECT category_id FROM public.budget_month_overrides WHERE budget_month_id = v_month_id
  ) ORDER BY c.id FOR SHARE;
  PERFORM 1 FROM public.budget_recurring_defaults ORDER BY category_id FOR SHARE;
  PERFORM 1 FROM public.budget_month_overrides
    WHERE budget_month_id = v_month_id ORDER BY category_id FOR SHARE;

  SELECT * INTO v_existing FROM public.budget_operations WHERE request_key = p_request_key;
  IF FOUND THEN
    IF v_existing.budget_month_id <> v_month_id
       OR v_existing.operation_type <> 'month_initialization'
       OR v_existing.request_fingerprint <> v_fingerprint THEN
      RAISE EXCEPTION 'request_key was already used for a different budget operation'
        USING ERRCODE = '23505';
    END IF;
    RETURN public.get_funded_budget_month(p_month);
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.budget_operations
    WHERE budget_month_id = v_month_id AND operation_type = 'month_initialization'
  ) THEN
    RETURN public.get_funded_budget_month(p_month);
  END IF;

  WITH category_config AS (
    SELECT category_id FROM public.budget_recurring_defaults
    UNION SELECT category_id FROM public.budget_month_overrides WHERE budget_month_id = v_month_id
  )
  SELECT coalesce(sum(CASE WHEN mo.category_id IS NOT NULL THEN mo.amount ELSE rd.amount END), 0)::numeric(18, 2)
  INTO v_required
  FROM category_config keys
  JOIN public.categories c ON c.id = keys.category_id
  LEFT JOIN public.budget_recurring_defaults rd ON rd.category_id = keys.category_id
  LEFT JOIN public.budget_month_overrides mo
    ON mo.budget_month_id = v_month_id AND mo.category_id = keys.category_id
  LEFT JOIN public.budgets b
    ON b.budget_month_id = v_month_id AND b.category_id = keys.category_id
  WHERE c.type = 'expense' AND c.is_active = true AND b.id IS NULL;
  SELECT coalesce(unallocated, 0)::numeric(18, 2) INTO v_unallocated
  FROM public.budget_month_funding_state WHERE budget_month_id = v_month_id;
  IF v_required > v_unallocated THEN
    RAISE EXCEPTION 'MONTH_OVERRIDE_INSUFFICIENT_FUNDS: required %, available %, shortfall %',
      v_required, v_unallocated, (v_required - v_unallocated)::numeric(18, 2)
      USING ERRCODE = '23514';
  END IF;

  INSERT INTO public.budget_operations (
    budget_month_id, request_key, request_fingerprint, operation_type, effective_date, reason
  ) VALUES (
    v_month_id, p_request_key, v_fingerprint, 'month_initialization', v_month_start, p_reason
  ) RETURNING id INTO v_operation_id;

  FOR candidate IN
    WITH category_config AS (
      SELECT category_id FROM public.budget_recurring_defaults
      UNION SELECT category_id FROM public.budget_month_overrides WHERE budget_month_id = v_month_id
    )
    SELECT
      keys.category_id,
      CASE WHEN mo.category_id IS NOT NULL THEN mo.amount ELSE rd.amount END::numeric(18, 2) AS amount,
      CASE WHEN mo.category_id IS NOT NULL THEN 'monthly_override' ELSE 'recurring_default' END AS starting_kind,
      coalesce(rd.amount, 0)::numeric(18, 2) AS fallback_base,
      CASE WHEN rd.category_id IS NULL THEN 'none' ELSE 'recurring_default' END AS fallback_source,
      mo.category_id IS NOT NULL AS has_override
    FROM category_config keys
    JOIN public.categories c ON c.id = keys.category_id
    LEFT JOIN public.budget_recurring_defaults rd ON rd.category_id = keys.category_id
    LEFT JOIN public.budget_month_overrides mo
      ON mo.budget_month_id = v_month_id AND mo.category_id = keys.category_id
    LEFT JOIN public.budgets b
      ON b.budget_month_id = v_month_id AND b.category_id = keys.category_id
    WHERE c.type = 'expense' AND c.is_active = true AND b.id IS NULL
    ORDER BY keys.category_id
  LOOP
    INSERT INTO public.budgets (
      category_id, month, amount, budget_month_id, starting_amount, starting_kind, created_by_operation_id
    ) VALUES (
      candidate.category_id, p_month, candidate.amount, v_month_id,
      candidate.amount, candidate.starting_kind, v_operation_id
    ) RETURNING id INTO v_budget_id;
    INSERT INTO public.budget_lifecycle_events (operation_id, budget_id, state)
    VALUES (v_operation_id, v_budget_id, 'active');
    IF candidate.has_override THEN
      INSERT INTO public.budget_month_override_events (
        request_key, request_fingerprint, budget_month_id, category_id, budget_id,
        financial_operation_id, action, requested_override_amount,
        previous_effective_base, resulting_effective_base, fallback_base_snapshot,
        fallback_source, applied_base_delta
      ) VALUES (
        public.budget_derived_request_key(p_request_key, 'override-init|' || candidate.category_id),
        'month_override_initialize|' || p_month || '|' || candidate.category_id || '|' || candidate.amount,
        v_month_id, candidate.category_id, v_budget_id, v_operation_id, 'initialize',
        candidate.amount, candidate.fallback_base, candidate.amount,
        candidate.fallback_base, candidate.fallback_source, 0
      );
    END IF;
  END LOOP;
  PERFORM public.budget_assert_reconciled(v_month_id);
  RETURN public.get_funded_budget_month(p_month);
END;
$$;

-- A pending monthly override is a stronger initialization requirement than a
-- recurring default. Carryover may not create carryover_only behind it.
CREATE OR REPLACE FUNCTION public.budget_carryover_candidate_rows(p_destination_month TEXT)
RETURNS TABLE (
  category_id BIGINT, category_name TEXT, category_icon TEXT,
  source_budget_id BIGINT, destination_budget_id BIGINT,
  source_final_funded NUMERIC(18, 2), source_raw_actual_spent NUMERIC(18, 2),
  source_effective_actual_spent NUMERIC(18, 2), eligible_amount NUMERIC(18, 2),
  status TEXT, blocked_reason TEXT
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_destination_start DATE := public.budget_month_start_from_key(p_destination_month);
  v_source_start DATE := (v_destination_start - interval '1 month')::date;
  v_source_id BIGINT;
  v_destination_id BIGINT;
  v_destination_initialized BOOLEAN := false;
BEGIN
  SELECT id INTO v_source_id FROM public.budget_months WHERE month_start = v_source_start;
  SELECT id INTO v_destination_id FROM public.budget_months WHERE month_start = v_destination_start;
  IF v_destination_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1 FROM public.budget_operations
      WHERE budget_month_id = v_destination_id AND operation_type = 'month_initialization'
    ) INTO v_destination_initialized;
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.transactions
    WHERE movement_type = 'expense'
      AND transaction_date >= v_source_start
      AND transaction_date < (v_destination_start + interval '1 month')::date
      AND total_amount::text IN ('NaN', 'Infinity', '-Infinity')
  ) THEN
    RAISE EXCEPTION 'Carryover actual spending contains a non-finite amount' USING ERRCODE = '22003';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.transactions t
    WHERE t.movement_type = 'expense'
      AND t.transaction_date >= v_source_start
      AND t.transaction_date < (v_destination_start + interval '1 month')::date
    GROUP BY t.category_id, date_trunc('month', t.transaction_date)
    HAVING sum(t.total_amount) <> round(sum(t.total_amount), 2)
      OR abs(sum(t.total_amount)) > 9999999999999999.99
  ) THEN
    RAISE EXCEPTION 'Carryover actual spending must fit finite NUMERIC(18,2) exactly'
      USING ERRCODE = '22003';
  END IF;

  RETURN QUERY
  WITH source_actuals AS (
    SELECT t.category_id, coalesce(sum(t.total_amount), 0)::numeric(18, 2) AS actual
    FROM public.transactions t
    WHERE t.movement_type = 'expense'
      AND t.transaction_date >= v_source_start AND t.transaction_date < v_destination_start
    GROUP BY t.category_id
  ), destination_actuals AS (
    SELECT t.category_id, coalesce(sum(t.total_amount), 0)::numeric(18, 2) AS actual
    FROM public.transactions t
    WHERE t.movement_type = 'expense'
      AND t.transaction_date >= v_destination_start
      AND t.transaction_date < (v_destination_start + interval '1 month')::date
    GROUP BY t.category_id
  ), candidate AS (
    SELECT
      c.id AS category_id, c.name, c.icon,
      src.budget_id AS source_budget_id, dst.budget_id AS destination_budget_id,
      coalesce(src.final_funded, 0)::numeric(18, 2) AS source_final_funded,
      coalesce(sa.actual, 0)::numeric(18, 2) AS source_raw_actual_spent,
      greatest(coalesce(sa.actual, 0), 0)::numeric(18, 2) AS source_effective_actual_spent,
      greatest(coalesce(src.final_funded, 0) - greatest(coalesce(sa.actual, 0), 0), 0)::numeric(18, 2)
        AS eligible_amount,
      c.is_active, src.lifecycle_state AS source_lifecycle,
      dst.lifecycle_state AS destination_lifecycle,
      coalesce(da.actual, 0)::numeric(18, 2) AS destination_actual,
      coalesce(dst.final_funded, 0)::numeric(18, 2) AS destination_final,
      mo.category_id IS NOT NULL AND NOT v_destination_initialized AS override_pending,
      rd.category_id IS NOT NULL AND NOT v_destination_initialized AS recurring_pending,
      EXISTS (
        SELECT 1 FROM public.budget_carryover_transfers original
        WHERE original.source_budget_id = src.budget_id
          AND original.reverses_transfer_id IS NULL
          AND NOT EXISTS (
            SELECT 1 FROM public.budget_carryover_transfers correction
            WHERE correction.reverses_transfer_id = original.id
          )
      ) AS already_applied
    FROM public.budget_carryover_settings setting
    JOIN public.categories c ON c.id = setting.category_id
    LEFT JOIN public.budget_category_state src
      ON src.budget_month_id = v_source_id AND src.category_id = c.id
    LEFT JOIN source_actuals sa ON sa.category_id = c.id
    LEFT JOIN public.budget_category_state dst
      ON dst.budget_month_id = v_destination_id AND dst.category_id = c.id
    LEFT JOIN destination_actuals da ON da.category_id = c.id
    LEFT JOIN public.budget_recurring_defaults rd ON rd.category_id = c.id
    LEFT JOIN public.budget_month_overrides mo
      ON mo.budget_month_id = v_destination_id AND mo.category_id = c.id
    WHERE c.type = 'expense'
  )
  SELECT
    candidate.category_id, candidate.name, candidate.icon,
    candidate.source_budget_id, candidate.destination_budget_id,
    candidate.source_final_funded, candidate.source_raw_actual_spent,
    candidate.source_effective_actual_spent, candidate.eligible_amount,
    CASE
      WHEN candidate.already_applied THEN 'already_applied'
      WHEN NOT candidate.is_active OR candidate.source_budget_id IS NULL
        OR candidate.source_lifecycle <> 'active' OR candidate.eligible_amount <= 0 THEN 'blocked'
      WHEN candidate.destination_budget_id IS NOT NULL
        AND candidate.destination_lifecycle <> 'active' THEN 'blocked'
      WHEN candidate.destination_budget_id IS NULL
        AND (candidate.override_pending OR candidate.recurring_pending) THEN 'blocked'
      WHEN candidate.destination_budget_id IS NULL AND candidate.destination_actual > 0 THEN 'blocked'
      WHEN candidate.destination_budget_id IS NOT NULL
        AND candidate.destination_actual > candidate.destination_final THEN 'blocked'
      ELSE 'ready'
    END,
    CASE
      WHEN candidate.already_applied THEN NULL
      WHEN NOT candidate.is_active THEN 'CATEGORY_INACTIVE'
      WHEN candidate.source_budget_id IS NULL THEN 'SOURCE_BUDGET_MISSING'
      WHEN candidate.source_lifecycle <> 'active' THEN 'SOURCE_BUDGET_INACTIVE'
      WHEN candidate.eligible_amount <= 0 THEN 'NO_ELIGIBLE_BALANCE'
      WHEN candidate.destination_budget_id IS NOT NULL
        AND candidate.destination_lifecycle <> 'active' THEN 'DESTINATION_BUDGET_INACTIVE'
      WHEN candidate.destination_budget_id IS NULL AND candidate.override_pending
        THEN 'MONTH_OVERRIDE_INITIALIZATION_REQUIRED'
      WHEN candidate.destination_budget_id IS NULL AND candidate.recurring_pending
        THEN 'RECURRING_INITIALIZATION_REQUIRED'
      WHEN candidate.destination_budget_id IS NULL AND candidate.destination_actual > 0
        THEN 'UNBUDGETED_ACTUAL_EXISTS'
      WHEN candidate.destination_budget_id IS NOT NULL
        AND candidate.destination_actual > candidate.destination_final THEN 'DESTINATION_DEFICIT'
      ELSE NULL
    END
  FROM candidate
  ORDER BY candidate.name, candidate.category_id;
END;
$$;

-- Copy remains the existing funded operation, but categories with destination
-- override configuration are excluded from both its validation and writes.
CREATE OR REPLACE FUNCTION public.copy_funded_budget_month(
  p_from_month TEXT,
  p_to_month TEXT,
  p_request_key UUID,
  p_reason TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_from_start DATE := public.budget_month_start_from_key(p_from_month);
  v_to_start DATE := public.budget_month_start_from_key(p_to_month);
  v_from_id BIGINT;
  v_to_id BIGINT;
  v_operation_id BIGINT;
  v_existing public.budget_operations%ROWTYPE;
  v_unallocated NUMERIC(18, 2);
  v_additions NUMERIC(18, 2) := 0;
  v_releases NUMERIC(18, 2) := 0;
  v_target_actual NUMERIC(18, 2);
  v_target_id BIGINT;
  v_target_final NUMERIC(18, 2);
  v_target_state TEXT;
  v_delta NUMERIC(18, 2);
  v_fingerprint TEXT;
  v_result JSONB;
  v_skipped JSONB;
  source_row RECORD;
BEGIN
  IF p_request_key IS NULL THEN RAISE EXCEPTION 'request_key is required' USING ERRCODE = '22023'; END IF;
  IF v_from_start = v_to_start THEN
    RAISE EXCEPTION 'Source and target budget months must differ' USING ERRCODE = '22023';
  END IF;
  SELECT id INTO v_from_id FROM public.budget_months WHERE month_start = v_from_start;
  IF NOT FOUND THEN RAISE EXCEPTION 'Source month has no funded budget'; END IF;

  -- Copy can release target funding based on actual spending, so it shares the
  -- transaction-first serialization order used by carryover and overrides.
  LOCK TABLE public.transactions IN SHARE MODE;
  INSERT INTO public.budget_months (month_start) VALUES (v_to_start)
  ON CONFLICT (month_start) DO NOTHING;
  SELECT id INTO v_to_id FROM public.budget_months WHERE month_start = v_to_start;
  PERFORM 1 FROM public.budget_months WHERE id IN (v_from_id, v_to_id) ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.budgets
    WHERE budget_month_id IN (v_from_id, v_to_id) ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.budget_month_overrides
    WHERE budget_month_id = v_to_id ORDER BY category_id FOR SHARE;
  PERFORM public.budget_assert_reconciled(v_from_id);
  PERFORM public.budget_assert_reconciled(v_to_id);

  v_fingerprint := 'copy|' || p_from_month || '|' || p_to_month;
  SELECT * INTO v_existing FROM public.budget_operations WHERE request_key = p_request_key;
  IF FOUND THEN
    IF v_existing.budget_month_id <> v_to_id OR v_existing.operation_type <> 'copy'
       OR v_existing.request_fingerprint <> v_fingerprint THEN
      RAISE EXCEPTION 'request_key was already used for a different budget operation'
        USING ERRCODE = '23505';
    END IF;
    v_result := public.get_funded_budget_month(p_to_month);
    SELECT coalesce(jsonb_agg(jsonb_build_object(
      'category_id', mo.category_id, 'amount', mo.amount::numeric(18, 2)::text,
      'reason', 'MONTH_OVERRIDE_PRESERVED'
    ) ORDER BY mo.category_id), '[]'::jsonb) INTO v_skipped
    FROM public.budget_month_overrides mo
    WHERE mo.budget_month_id = v_to_id
      AND EXISTS (
        SELECT 1 FROM public.budget_category_state src
        WHERE src.budget_month_id = v_from_id AND src.category_id = mo.category_id
          AND src.lifecycle_state = 'active'
      );
    RETURN v_result || jsonb_build_object('copy_preserved_overrides', v_skipped);
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.budget_category_state
    WHERE budget_month_id = v_from_id AND lifecycle_state = 'active'
  ) THEN
    RAISE EXCEPTION 'Source month has no active category budgets';
  END IF;

  FOR source_row IN
    SELECT src.* FROM public.budget_category_state src
    WHERE src.budget_month_id = v_from_id AND src.lifecycle_state = 'active'
      AND NOT EXISTS (
        SELECT 1 FROM public.budget_month_overrides mo
        WHERE mo.budget_month_id = v_to_id AND mo.category_id = src.category_id
      )
    ORDER BY src.category_id
  LOOP
    SELECT cs.budget_id, cs.final_funded, cs.lifecycle_state
    INTO v_target_id, v_target_final, v_target_state
    FROM public.budget_category_state cs
    WHERE cs.budget_month_id = v_to_id AND cs.category_id = source_row.category_id;
    IF NOT FOUND THEN
      v_additions := v_additions + source_row.final_funded;
    ELSE
      v_delta := source_row.final_funded - v_target_final;
      IF v_delta > 0 THEN
        v_additions := v_additions + v_delta;
      ELSIF v_delta < 0 THEN
        IF EXISTS (
          SELECT 1 FROM public.transactions
          WHERE movement_type = 'expense' AND category_id = source_row.category_id
            AND transaction_date >= v_to_start
            AND transaction_date < (v_to_start + interval '1 month')::date
            AND total_amount::text IN ('NaN', 'Infinity', '-Infinity')
        ) THEN
          RAISE EXCEPTION 'Budget actual spending contains a non-finite amount' USING ERRCODE = '22003';
        END IF;
        SELECT greatest(coalesce(sum(total_amount), 0), 0)::numeric(18, 2)
        INTO v_target_actual
        FROM public.transactions
        WHERE movement_type = 'expense' AND category_id = source_row.category_id
          AND transaction_date >= v_to_start
          AND transaction_date < (v_to_start + interval '1 month')::date;
        IF -v_delta > greatest(v_target_final - v_target_actual, 0) THEN
          RAISE EXCEPTION 'Copy cannot release spent funding from target category %', source_row.category_id
            USING ERRCODE = '23514';
        END IF;
        v_releases := v_releases + (-v_delta);
      END IF;
    END IF;
  END LOOP;
  SELECT unallocated INTO v_unallocated FROM public.budget_month_funding_state WHERE budget_month_id = v_to_id;
  IF v_additions > v_unallocated + v_releases THEN
    RAISE EXCEPTION 'Destination month needs % additional funded money; only % is available',
      v_additions, v_unallocated + v_releases USING ERRCODE = '23514';
  END IF;

  INSERT INTO public.budget_operations (
    budget_month_id, request_key, request_fingerprint, operation_type, effective_date, reason
  ) VALUES (v_to_id, p_request_key, v_fingerprint, 'copy', v_to_start, p_reason)
  RETURNING id INTO v_operation_id;

  FOR source_row IN
    SELECT src.* FROM public.budget_category_state src
    WHERE src.budget_month_id = v_from_id AND src.lifecycle_state = 'active'
      AND NOT EXISTS (
        SELECT 1 FROM public.budget_month_overrides mo
        WHERE mo.budget_month_id = v_to_id AND mo.category_id = src.category_id
      )
    ORDER BY src.category_id
  LOOP
    SELECT cs.budget_id, cs.final_funded, cs.lifecycle_state
    INTO v_target_id, v_target_final, v_target_state
    FROM public.budget_category_state cs
    WHERE cs.budget_month_id = v_to_id AND cs.category_id = source_row.category_id;
    IF NOT FOUND THEN
      INSERT INTO public.budgets (
        category_id, month, amount, budget_month_id, starting_amount,
        starting_kind, created_by_operation_id
      ) VALUES (
        source_row.category_id, p_to_month, source_row.final_funded, v_to_id,
        source_row.final_funded, 'copied', v_operation_id
      ) RETURNING id INTO v_target_id;
      INSERT INTO public.budget_lifecycle_events (operation_id, budget_id, state)
      VALUES (v_operation_id, v_target_id, 'active');
    ELSE
      v_delta := source_row.final_funded - v_target_final;
      IF v_delta <> 0 THEN
        INSERT INTO public.budget_movements (
          operation_id, source_budget_id, destination_budget_id, amount
        ) VALUES (
          v_operation_id,
          CASE WHEN v_delta < 0 THEN v_target_id ELSE NULL END,
          CASE WHEN v_delta > 0 THEN v_target_id ELSE NULL END,
          abs(v_delta)
        );
      END IF;
      IF v_target_state = 'inactive' THEN
        INSERT INTO public.budget_lifecycle_events (operation_id, budget_id, state)
        VALUES (v_operation_id, v_target_id, 'active');
      END IF;
    END IF;
  END LOOP;

  PERFORM public.budget_assert_reconciled(v_to_id);
  v_result := public.get_funded_budget_month(p_to_month);
  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'category_id', mo.category_id, 'amount', mo.amount::numeric(18, 2)::text,
    'reason', 'MONTH_OVERRIDE_PRESERVED'
  ) ORDER BY mo.category_id), '[]'::jsonb) INTO v_skipped
  FROM public.budget_month_overrides mo
  WHERE mo.budget_month_id = v_to_id
    AND EXISTS (
      SELECT 1 FROM public.budget_category_state src
      WHERE src.budget_month_id = v_from_id AND src.category_id = mo.category_id
        AND src.lifecycle_state = 'active'
    );
  RETURN v_result || jsonb_build_object('copy_preserved_overrides', v_skipped);
END;
$$;

ALTER TABLE public.budget_month_overrides ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.budget_month_override_events ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.budget_month_overrides,
  public.budget_month_override_events,
  public.budget_month_overrides_read,
  public.budget_category_base_state
  FROM PUBLIC, anon, authenticated, service_role;
GRANT SELECT ON public.budget_month_overrides,
  public.budget_month_override_events,
  public.budget_month_overrides_read,
  public.budget_category_base_state
  TO service_role;

REVOKE ALL ON FUNCTION public.validate_budget_month_override(),
  public.prevent_category_type_with_month_override(),
  public.validate_budget_month_override_event(),
  public.get_funded_budget_month_carryover(TEXT),
  public.get_budget_recurring_preview(TEXT),
  public.budget_carryover_candidate_rows(TEXT)
  FROM PUBLIC, anon, authenticated, service_role;

REVOKE ALL ON FUNCTION public.get_budget_month_override_preview(TEXT),
  public.set_budget_month_override(TEXT, BIGINT, NUMERIC, UUID, TEXT),
  public.remove_budget_month_override(TEXT, BIGINT, UUID, TEXT),
  public.initialize_budget_recurring_defaults(TEXT, UUID, TEXT),
  public.copy_funded_budget_month(TEXT, TEXT, UUID, TEXT)
  FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION public.get_funded_budget_month(TEXT)
  FROM PUBLIC, anon, authenticated;

GRANT EXECUTE ON FUNCTION public.get_funded_budget_month(TEXT),
  public.get_budget_month_override_preview(TEXT),
  public.set_budget_month_override(TEXT, BIGINT, NUMERIC, UUID, TEXT),
  public.remove_budget_month_override(TEXT, BIGINT, UUID, TEXT),
  public.initialize_budget_recurring_defaults(TEXT, UUID, TEXT),
  public.copy_funded_budget_month(TEXT, TEXT, UUID, TEXT)
  TO service_role;
REVOKE EXECUTE ON FUNCTION public.get_funded_budget_month_carryover(TEXT)
  FROM service_role;

DO $$
DECLARE v_month RECORD;
BEGIN
  FOR v_month IN SELECT id FROM public.budget_months ORDER BY id LOOP
    PERFORM public.budget_assert_reconciled(v_month.id);
  END LOOP;
  IF EXISTS (
    SELECT 1 FROM public.budget_category_base_state
    WHERE final_funded <> effective_base + incoming_carryover
      - outgoing_carryover + other_adjustments
  ) THEN
    RAISE EXCEPTION 'Migration 020 reconciliation: base/carryover composition mismatch';
  END IF;
END;
$$;

COMMIT;

-- Migration 021: unified unused-budget policy, explicit month close, and savings.
--
-- A close moves eligible unused funded money out of the immediately completed
-- month. Carry-forward reuses Migration 019, return-to-unallocated transfers
-- funding into the current month's free pool, and savings leaves the monthly
-- envelope for one application-wide retained reserve.

BEGIN;

DO $$
BEGIN
  IF to_regclass('public.budget_months') IS NULL
     OR to_regclass('public.budget_carryover_settings') IS NULL
     OR to_regclass('public.budget_carryover_batches') IS NULL
     OR to_regclass('public.budget_carryover_transfers') IS NULL
     OR to_regclass('public.budget_month_overrides') IS NULL
     OR to_regclass('public.budget_month_override_events') IS NULL
     OR to_regclass('public.budget_category_base_state') IS NULL
     OR to_regprocedure('public.apply_budget_carryover(text,uuid,text,text)') IS NULL
     OR to_regprocedure('public.reverse_budget_carryover(bigint,uuid,text)') IS NULL
     OR to_regprocedure('public.budget_assert_reconciled(bigint)') IS NULL THEN
    RAISE EXCEPTION 'Migration 021 preflight: Migrations 017 through 020 are required';
  END IF;
  IF to_regclass('public.budget_unused_balance_policies') IS NOT NULL
     OR to_regclass('public.budget_month_disposition_batches') IS NOT NULL
     OR to_regclass('public.budget_unused_disposition_events') IS NOT NULL
     OR to_regclass('public.budget_savings_entries') IS NOT NULL
     OR to_regprocedure('public.apply_budget_month_disposition(text,uuid,text,text)') IS NOT NULL THEN
    RAISE EXCEPTION 'Migration 021 preflight: unexpected partial unused-disposition schema exists';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.budget_operations
    WHERE operation_type NOT IN (
      'legacy_import','manual_funding','establish_budget','adjustment','removal',
      'reactivation','copy','reversal','month_initialization','carryover_out',
      'carryover_in','monthly_override_set','monthly_override_remove'
    )
  ) OR EXISTS (
    SELECT 1 FROM public.budget_funding_entries
    WHERE source_kind NOT IN ('manual_available_funds','legacy_import','carryover_transfer')
  ) THEN
    RAISE EXCEPTION 'Migration 021 preflight: unexpected funded-budget domain value';
  END IF;
END;
$$;

ALTER TABLE public.budget_operations
  DROP CONSTRAINT budget_operations_operation_type_check,
  ADD CONSTRAINT budget_operations_operation_type_check CHECK (operation_type IN (
    'legacy_import','manual_funding','establish_budget','adjustment','removal',
    'reactivation','copy','reversal','month_initialization','carryover_out',
    'carryover_in','monthly_override_set','monthly_override_remove',
    'unused_return_out','unused_return_in','unused_to_savings',
    'unused_disposition_reversal'
  ));

ALTER TABLE public.budget_funding_entries
  DROP CONSTRAINT budget_funding_entries_source_kind_check,
  ADD CONSTRAINT budget_funding_entries_source_kind_check CHECK (
    source_kind IN (
      'manual_available_funds','legacy_import','carryover_transfer',
      'unused_disposition_transfer','savings_transfer'
    )
  ),
  DROP CONSTRAINT budget_funding_entry_amount_shape,
  ADD CONSTRAINT budget_funding_entry_amount_shape CHECK (
    amount_delta::text NOT IN ('NaN','Infinity','-Infinity')
    AND (
      (source_kind = 'legacy_import' AND amount_delta >= 0 AND reverses_funding_entry_id IS NULL)
      OR (source_kind <> 'legacy_import' AND amount_delta <> 0)
    )
  );

-- Existing rows are exactly the enabled carryover set. Adding the default
-- before the rename deterministically maps every one to carry_forward.
ALTER TABLE public.budget_carryover_settings
  ADD COLUMN policy TEXT NOT NULL DEFAULT 'carry_forward'
    CHECK (policy IN ('carry_forward','savings','return_to_unallocated'));
ALTER TABLE public.budget_carryover_settings RENAME TO budget_unused_balance_policies;
ALTER TABLE public.budget_unused_balance_policies ALTER COLUMN policy DROP DEFAULT;
ALTER TRIGGER budget_carryover_settings_validate ON public.budget_unused_balance_policies
  RENAME TO budget_unused_balance_policies_validate;

-- Migration 019 continues to see only carry-forward policies. This simple
-- compatibility view keeps its proven transfer engine and provenance intact.
CREATE VIEW public.budget_carryover_settings AS
SELECT category_id, created_at, updated_at
FROM public.budget_unused_balance_policies
WHERE policy = 'carry_forward';

DROP VIEW public.budget_carryover_settings_read;
CREATE VIEW public.budget_carryover_settings_read AS
SELECT category_id, true AS enabled, created_at, updated_at
FROM public.budget_unused_balance_policies
WHERE policy = 'carry_forward';

CREATE VIEW public.budget_unused_balance_policies_read AS
SELECT category_id, policy, created_at, updated_at
FROM public.budget_unused_balance_policies;

CREATE OR REPLACE FUNCTION public.validate_budget_carryover_setting()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.categories
    WHERE id = NEW.category_id AND type = 'expense'
  ) THEN
    RAISE EXCEPTION 'Unused-balance policies are available only for expense categories'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.prevent_category_type_with_carryover()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
BEGIN
  IF OLD.type = 'expense' AND NEW.type <> 'expense' AND EXISTS (
    SELECT 1 FROM public.budget_unused_balance_policies WHERE category_id = OLD.id
  ) THEN
    RAISE EXCEPTION 'Remove the unused-balance policy before changing this category type'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

DROP FUNCTION public.set_budget_carryover_enabled(BIGINT, BOOLEAN);

CREATE OR REPLACE FUNCTION public.set_budget_unused_balance_policy(
  p_category_id BIGINT,
  p_policy TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE v_category public.categories%ROWTYPE;
BEGIN
  IF p_category_id IS NULL THEN
    RAISE EXCEPTION 'category_id is required' USING ERRCODE = '22023';
  END IF;
  IF p_policy IS NOT NULL
     AND p_policy NOT IN ('carry_forward','savings','return_to_unallocated') THEN
    RAISE EXCEPTION 'Unknown unused-balance policy' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_category FROM public.categories WHERE id = p_category_id FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Category % does not exist', p_category_id USING ERRCODE = 'P0002';
  END IF;
  IF v_category.type <> 'expense' OR NOT v_category.is_active THEN
    RAISE EXCEPTION 'Unused-balance policies require an active expense category'
      USING ERRCODE = '23514';
  END IF;
  IF p_policy IS NULL THEN
    DELETE FROM public.budget_unused_balance_policies WHERE category_id = p_category_id;
  ELSE
    INSERT INTO public.budget_unused_balance_policies(category_id, policy)
    VALUES (p_category_id, p_policy)
    ON CONFLICT (category_id) DO UPDATE
    SET policy = EXCLUDED.policy, updated_at = timezone('utc'::text, now());
  END IF;
  RETURN jsonb_build_object('category_id', p_category_id, 'policy', p_policy);
END;
$$;

CREATE TABLE public.budget_month_disposition_batches (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  request_key UUID NOT NULL UNIQUE,
  request_fingerprint TEXT NOT NULL CHECK (btrim(request_fingerprint) <> ''),
  source_budget_month_id BIGINT NOT NULL REFERENCES public.budget_months(id) ON DELETE RESTRICT,
  destination_budget_month_id BIGINT NOT NULL REFERENCES public.budget_months(id) ON DELETE RESTRICT,
  reverses_batch_id BIGINT UNIQUE REFERENCES public.budget_month_disposition_batches(id) ON DELETE RESTRICT,
  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text, now()),
  CHECK (source_budget_month_id <> destination_budget_month_id),
  CHECK (reverses_batch_id IS NULL OR reverses_batch_id <> id)
);

CREATE TABLE public.budget_savings_entries (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  operation_id BIGINT NOT NULL UNIQUE REFERENCES public.budget_operations(id) ON DELETE RESTRICT,
  source_budget_month_id BIGINT NOT NULL REFERENCES public.budget_months(id) ON DELETE RESTRICT,
  source_budget_id BIGINT NOT NULL REFERENCES public.budgets(id) ON DELETE RESTRICT,
  category_id BIGINT NOT NULL REFERENCES public.categories(id) ON DELETE RESTRICT,
  amount_delta NUMERIC(18,2) NOT NULL,
  entry_kind TEXT NOT NULL CHECK (entry_kind IN ('deposit','reversal')),
  reverses_entry_id BIGINT UNIQUE REFERENCES public.budget_savings_entries(id) ON DELETE RESTRICT,
  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text, now()),
  CHECK (amount_delta::text NOT IN ('NaN','Infinity','-Infinity') AND amount_delta <> 0),
  CHECK ((entry_kind='deposit' AND amount_delta > 0 AND reverses_entry_id IS NULL)
      OR (entry_kind='reversal' AND amount_delta < 0 AND reverses_entry_id IS NOT NULL)),
  CHECK (reverses_entry_id IS NULL OR reverses_entry_id <> id)
);

CREATE TABLE public.budget_unused_disposition_events (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  batch_id BIGINT NOT NULL REFERENCES public.budget_month_disposition_batches(id) ON DELETE RESTRICT,
  category_id BIGINT NOT NULL REFERENCES public.categories(id) ON DELETE RESTRICT,
  source_budget_id BIGINT NOT NULL REFERENCES public.budgets(id) ON DELETE RESTRICT,
  event_kind TEXT NOT NULL CHECK (event_kind IN ('apply','reversal')),
  policy TEXT NOT NULL CHECK (policy IN ('carry_forward','savings','return_to_unallocated')),
  amount NUMERIC(18,2) NOT NULL,
  source_final_funded_snapshot NUMERIC(18,2) NOT NULL,
  source_raw_actual_snapshot NUMERIC(18,2) NOT NULL,
  source_effective_actual_snapshot NUMERIC(18,2) NOT NULL,
  source_operation_id BIGINT REFERENCES public.budget_operations(id) ON DELETE RESTRICT,
  destination_operation_id BIGINT REFERENCES public.budget_operations(id) ON DELETE RESTRICT,
  carryover_transfer_id BIGINT REFERENCES public.budget_carryover_transfers(id) ON DELETE RESTRICT,
  savings_entry_id BIGINT REFERENCES public.budget_savings_entries(id) ON DELETE RESTRICT,
  reverses_event_id BIGINT UNIQUE REFERENCES public.budget_unused_disposition_events(id) ON DELETE RESTRICT,
  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text, now()),
  CHECK (amount::text NOT IN ('NaN','Infinity','-Infinity') AND amount > 0),
  CHECK (source_final_funded_snapshot::text NOT IN ('NaN','Infinity','-Infinity')
         AND source_final_funded_snapshot >= 0),
  CHECK (source_raw_actual_snapshot::text NOT IN ('NaN','Infinity','-Infinity')),
  CHECK (source_effective_actual_snapshot::text NOT IN ('NaN','Infinity','-Infinity')
         AND source_effective_actual_snapshot >= 0),
  CHECK (reverses_event_id IS NULL OR reverses_event_id <> id),
  CHECK ((event_kind='apply' AND reverses_event_id IS NULL)
      OR (event_kind='reversal' AND reverses_event_id IS NOT NULL)),
  CHECK ((policy='carry_forward' AND carryover_transfer_id IS NOT NULL
          AND savings_entry_id IS NULL)
      OR (policy='savings' AND carryover_transfer_id IS NULL
          AND savings_entry_id IS NOT NULL AND destination_operation_id IS NULL)
      OR (policy='return_to_unallocated' AND carryover_transfer_id IS NULL
          AND savings_entry_id IS NULL AND destination_operation_id IS NOT NULL))
);

CREATE INDEX idx_budget_disposition_batches_months
  ON public.budget_month_disposition_batches(source_budget_month_id,destination_budget_month_id,id);
CREATE INDEX idx_budget_disposition_events_source
  ON public.budget_unused_disposition_events(source_budget_id,id);
CREATE INDEX idx_budget_savings_entries_source
  ON public.budget_savings_entries(source_budget_month_id,source_budget_id,id);

CREATE VIEW public.budget_savings_state AS
SELECT coalesce(sum(amount_delta),0)::numeric(18,2) AS balance,
       coalesce(sum(amount_delta),0)::numeric(18,2)::text AS balance_text
FROM public.budget_savings_entries;

CREATE VIEW public.budget_month_disposition_history AS
SELECT e.id AS event_id, e.batch_id, e.event_kind, e.policy,
       e.category_id, c.name AS category_name, e.source_budget_id,
       to_char(sm.month_start,'YYYY-MM') AS source_month,
       to_char(dm.month_start,'YYYY-MM') AS destination_month,
       e.amount::numeric(18,2)::text AS amount,
       e.source_final_funded_snapshot::numeric(18,2)::text AS source_final_funded_snapshot,
       e.source_raw_actual_snapshot::numeric(18,2)::text AS source_raw_actual_snapshot,
       e.source_effective_actual_snapshot::numeric(18,2)::text AS source_effective_actual_snapshot,
       e.source_operation_id, e.destination_operation_id, e.carryover_transfer_id,
       e.savings_entry_id, e.reverses_event_id, e.created_at
FROM public.budget_unused_disposition_events e
JOIN public.budget_month_disposition_batches b ON b.id=e.batch_id
JOIN public.budget_months sm ON sm.id=b.source_budget_month_id
JOIN public.budget_months dm ON dm.id=b.destination_budget_month_id
JOIN public.categories c ON c.id=e.category_id;

CREATE OR REPLACE FUNCTION public.validate_budget_disposition_batch()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE v_source DATE; v_destination DATE;
BEGIN
  SELECT month_start INTO v_source FROM public.budget_months WHERE id=NEW.source_budget_month_id;
  SELECT month_start INTO v_destination FROM public.budget_months WHERE id=NEW.destination_budget_month_id;
  IF v_destination IS DISTINCT FROM (v_source + interval '1 month')::date THEN
    RAISE EXCEPTION 'Month disposition must link consecutive calendar months' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END; $$;

CREATE OR REPLACE FUNCTION public.validate_budget_savings_entry()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE
  v_operation public.budget_operations%ROWTYPE;
  v_budget public.budgets%ROWTYPE;
  v_funding public.budget_funding_entries%ROWTYPE;
  v_movement public.budget_movements%ROWTYPE;
BEGIN
  SELECT * INTO v_operation FROM public.budget_operations WHERE id=NEW.operation_id;
  SELECT * INTO v_budget FROM public.budgets WHERE id=NEW.source_budget_id;
  SELECT * INTO v_funding FROM public.budget_funding_entries WHERE operation_id=NEW.operation_id;
  SELECT * INTO v_movement FROM public.budget_movements WHERE operation_id=NEW.operation_id;
  IF v_operation.budget_month_id IS DISTINCT FROM NEW.source_budget_month_id
     OR v_budget.budget_month_id IS DISTINCT FROM NEW.source_budget_month_id
     OR v_budget.category_id IS DISTINCT FROM NEW.category_id
     OR v_operation.operation_type NOT IN ('unused_to_savings','unused_disposition_reversal') THEN
    RAISE EXCEPTION 'Savings entry provenance does not match its source' USING ERRCODE='23514';
  END IF;
  IF NEW.entry_kind='reversal' AND NOT EXISTS (
    SELECT 1 FROM public.budget_savings_entries original
    WHERE original.id=NEW.reverses_entry_id AND original.entry_kind='deposit'
      AND original.source_budget_id=NEW.source_budget_id
      AND original.amount_delta=-NEW.amount_delta
  ) THEN
    RAISE EXCEPTION 'Savings reversal does not match its deposit' USING ERRCODE='23514';
  END IF;
  IF v_funding.source_kind<>'savings_transfer'
     OR (NEW.entry_kind='deposit' AND (
       v_funding.amount_delta<>-NEW.amount_delta
       OR v_movement.source_budget_id IS DISTINCT FROM NEW.source_budget_id
       OR v_movement.destination_budget_id IS NOT NULL
       OR v_movement.amount<>NEW.amount_delta
     ))
     OR (NEW.entry_kind='reversal' AND (
       v_funding.amount_delta<>-NEW.amount_delta
       OR v_movement.source_budget_id IS NOT NULL
       OR v_movement.destination_budget_id IS DISTINCT FROM NEW.source_budget_id
       OR v_movement.amount<>-NEW.amount_delta
     )) THEN
    RAISE EXCEPTION 'Savings funding and category movement are not balanced'
      USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END; $$;

CREATE TRIGGER budget_disposition_batches_validate BEFORE INSERT ON public.budget_month_disposition_batches
FOR EACH ROW EXECUTE FUNCTION public.validate_budget_disposition_batch();
CREATE TRIGGER budget_disposition_batches_immutable BEFORE UPDATE OR DELETE ON public.budget_month_disposition_batches
FOR EACH ROW EXECUTE FUNCTION public.prevent_budget_history_mutation();
CREATE TRIGGER budget_disposition_events_immutable BEFORE UPDATE OR DELETE ON public.budget_unused_disposition_events
FOR EACH ROW EXECUTE FUNCTION public.prevent_budget_history_mutation();
CREATE TRIGGER budget_savings_entries_validate BEFORE INSERT ON public.budget_savings_entries
FOR EACH ROW EXECUTE FUNCTION public.validate_budget_savings_entry();
CREATE TRIGGER budget_savings_entries_immutable BEFORE UPDATE OR DELETE ON public.budget_savings_entries
FOR EACH ROW EXECUTE FUNCTION public.prevent_budget_history_mutation();

CREATE OR REPLACE FUNCTION public.budget_month_disposition_candidate_rows(p_source_month TEXT)
RETURNS TABLE (
  category_id BIGINT, category_name TEXT, category_icon TEXT,
  source_budget_id BIGINT, policy TEXT,
  source_final_funded NUMERIC(18,2), source_raw_actual NUMERIC(18,2),
  source_effective_actual NUMERIC(18,2), eligible_amount NUMERIC(18,2),
  status TEXT, blocked_reason TEXT
)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE
  v_source_start DATE := public.budget_month_start_from_key(p_source_month);
  v_destination_start DATE := (v_source_start + interval '1 month')::date;
  v_source_id BIGINT;
BEGIN
  SELECT id INTO v_source_id FROM public.budget_months WHERE month_start=v_source_start;
  IF EXISTS (
    SELECT 1 FROM public.transactions
    WHERE movement_type='expense'
      AND transaction_date>=v_source_start AND transaction_date<v_destination_start
      AND total_amount::text IN ('NaN','Infinity','-Infinity')
  ) THEN
    RAISE EXCEPTION 'Month disposition actual spending contains a non-finite amount'
      USING ERRCODE='22003';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.transactions t
    WHERE t.movement_type='expense'
      AND t.transaction_date>=v_source_start AND t.transaction_date<v_destination_start
    GROUP BY t.category_id
    HAVING sum(t.total_amount)<>round(sum(t.total_amount),2)
       OR abs(sum(t.total_amount))>9999999999999999.99
  ) THEN
    RAISE EXCEPTION 'Month disposition actual spending must fit finite NUMERIC(18,2) exactly'
      USING ERRCODE='22003';
  END IF;

  RETURN QUERY
  WITH actuals AS (
    SELECT t.category_id, sum(t.total_amount)::numeric(18,2) AS actual
    FROM public.transactions t
    WHERE t.movement_type='expense'
      AND t.transaction_date>=v_source_start AND t.transaction_date<v_destination_start
    GROUP BY t.category_id
  ), base AS (
    SELECT cs.budget_id, cs.category_id, cs.category_name, cs.category_icon,
      cs.category_type, c.is_active, cs.lifecycle_state,
      cs.final_funded::numeric(18,2) AS final_funded,
      coalesce(a.actual,0)::numeric(18,2) AS raw_actual,
      greatest(coalesce(a.actual,0),0)::numeric(18,2) AS effective_actual,
      greatest(cs.final_funded-greatest(coalesce(a.actual,0),0),0)::numeric(18,2) AS unused,
      p.policy,
      EXISTS (
        SELECT 1 FROM public.budget_unused_disposition_events original
        WHERE original.source_budget_id=cs.budget_id AND original.event_kind='apply'
          AND NOT EXISTS (
            SELECT 1 FROM public.budget_unused_disposition_events correction
            WHERE correction.reverses_event_id=original.id
          )
      ) AS disposed,
      carry.status AS carry_status,
      carry.blocked_reason AS carry_blocked
    FROM public.budget_category_state cs
    JOIN public.categories c ON c.id=cs.category_id
    LEFT JOIN actuals a ON a.category_id=cs.category_id
    LEFT JOIN public.budget_unused_balance_policies p ON p.category_id=cs.category_id
    LEFT JOIN public.budget_carryover_candidate_rows(to_char(v_destination_start,'YYYY-MM')) carry
      ON p.policy='carry_forward' AND carry.category_id=cs.category_id
    WHERE cs.budget_month_id=v_source_id
  )
  SELECT b.category_id,b.category_name,b.category_icon,b.budget_id,b.policy,
    b.final_funded,b.raw_actual,b.effective_actual,b.unused,
    CASE
      WHEN b.disposed OR (b.policy='carry_forward' AND b.carry_status='already_applied')
        THEN 'already_applied'
      WHEN b.category_type<>'expense' OR NOT b.is_active THEN 'blocked'
      WHEN b.lifecycle_state<>'active' THEN 'blocked'
      WHEN b.unused<=0 THEN 'ineligible'
      WHEN b.policy IS NULL THEN 'blocked'
      WHEN b.policy='carry_forward' AND b.carry_status IS DISTINCT FROM 'ready' THEN 'blocked'
      ELSE 'ready'
    END,
    CASE
      WHEN b.disposed OR (b.policy='carry_forward' AND b.carry_status='already_applied') THEN NULL
      WHEN b.category_type<>'expense' THEN 'CATEGORY_NOT_EXPENSE'
      WHEN NOT b.is_active THEN 'CATEGORY_INACTIVE'
      WHEN b.lifecycle_state<>'active' THEN 'SOURCE_BUDGET_INACTIVE'
      WHEN b.unused<=0 THEN NULL
      WHEN b.policy IS NULL THEN 'POLICY_UNCONFIGURED'
      WHEN b.policy='carry_forward' AND b.carry_status IS DISTINCT FROM 'ready'
        THEN coalesce(b.carry_blocked,'CARRY_FORWARD_NOT_READY')
      ELSE NULL
    END
  FROM base b
  ORDER BY b.category_name,b.category_id;
END; $$;

CREATE OR REPLACE FUNCTION public.get_budget_month_disposition_preview(p_source_month TEXT)
RETURNS JSONB
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE
  v_source_start DATE := public.budget_month_start_from_key(p_source_month);
  v_destination_start DATE := (v_source_start + interval '1 month')::date;
  v_current_start DATE := date_trunc('month',timezone('Asia/Jerusalem',statement_timestamp()))::date;
  v_source_id BIGINT;
  v_destination_id BIGINT;
  v_rows JSONB := '[]'::jsonb;
  v_material TEXT := '';
  v_deficits JSONB := '[]'::jsonb;
  v_unbudgeted JSONB := '[]'::jsonb;
  v_carry NUMERIC(18,2) := 0;
  v_return NUMERIC(18,2) := 0;
  v_savings NUMERIC(18,2) := 0;
  v_destination_unallocated NUMERIC(18,2) := 0;
  v_destination_available NUMERIC(18,2) := 0;
  v_source_available NUMERIC(18,2) := 0;
  v_source_unallocated NUMERIC(18,2) := 0;
  v_savings_balance NUMERIC(18,2) := 0;
  v_fingerprint TEXT;
  v_timing BOOLEAN;
BEGIN
  v_timing := v_destination_start=v_current_start;
  SELECT id INTO v_source_id FROM public.budget_months WHERE month_start=v_source_start;
  SELECT id INTO v_destination_id FROM public.budget_months WHERE month_start=v_destination_start;

  WITH rows AS (SELECT * FROM public.budget_month_disposition_candidate_rows(p_source_month))
  SELECT coalesce(jsonb_agg(jsonb_build_object(
      'category_id',category_id,
      'category',jsonb_build_object('name',category_name,'icon',category_icon,'type','expense'),
      'source_budget_id',source_budget_id,'policy',policy,
      'source_final_funded',source_final_funded::text,
      'source_raw_actual',source_raw_actual::text,
      'source_effective_actual',source_effective_actual::text,
      'eligible_unused',eligible_amount::text,
      'status',status,'blocked_reason',blocked_reason
    ) ORDER BY category_name,category_id),'[]'::jsonb),
    coalesce(string_agg(category_id||'|'||source_budget_id||'|'||coalesce(policy,'')||'|'
      ||source_final_funded::text||'|'||source_raw_actual::text||'|'
      ||source_effective_actual::text||'|'||eligible_amount::text||'|'
      ||status||'|'||coalesce(blocked_reason,''),';' ORDER BY category_id),''),
    coalesce(sum(eligible_amount) FILTER (WHERE status='ready' AND policy='carry_forward'),0),
    coalesce(sum(eligible_amount) FILTER (WHERE status='ready' AND policy='return_to_unallocated'),0),
    coalesce(sum(eligible_amount) FILTER (WHERE status='ready' AND policy='savings'),0)
  INTO v_rows,v_material,v_carry,v_return,v_savings FROM rows;

  WITH actuals AS (
    SELECT t.category_id,sum(t.total_amount)::numeric(18,2) actual
    FROM public.transactions t
    WHERE t.movement_type='expense' AND t.transaction_date>=v_source_start
      AND t.transaction_date<v_destination_start
    GROUP BY t.category_id
  )
  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'category_id',cs.category_id,'category_name',cs.category_name,
    'funded',cs.final_funded::numeric(18,2)::text,'actual',a.actual::text,
    'deficit',(a.actual-cs.final_funded)::numeric(18,2)::text
  ) ORDER BY cs.category_name,cs.category_id),'[]'::jsonb)
  INTO v_deficits
  FROM actuals a JOIN public.budget_category_state cs
    ON cs.budget_month_id=v_source_id AND cs.category_id=a.category_id
  WHERE cs.lifecycle_state='active' AND a.actual>cs.final_funded;

  WITH actuals AS (
    SELECT t.category_id,sum(t.total_amount)::numeric(18,2) actual
    FROM public.transactions t
    WHERE t.movement_type='expense' AND t.transaction_date>=v_source_start
      AND t.transaction_date<v_destination_start
    GROUP BY t.category_id
  )
  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'category_id',a.category_id,'actual',a.actual::text
  ) ORDER BY a.category_id NULLS FIRST),'[]'::jsonb)
  INTO v_unbudgeted
  FROM actuals a
  WHERE a.actual>0 AND NOT EXISTS (
    SELECT 1 FROM public.budget_category_state cs
    WHERE cs.budget_month_id=v_source_id AND cs.category_id IS NOT DISTINCT FROM a.category_id
      AND cs.lifecycle_state='active'
  );

  SELECT coalesce(available,0)::numeric(18,2),coalesce(unallocated,0)::numeric(18,2)
  INTO v_destination_available,v_destination_unallocated
  FROM public.budget_month_funding_state WHERE budget_month_id=v_destination_id;
  IF NOT FOUND THEN v_destination_available:=0; v_destination_unallocated:=0; END IF;
  SELECT coalesce(available,0)::numeric(18,2),coalesce(unallocated,0)::numeric(18,2)
  INTO v_source_available,v_source_unallocated
  FROM public.budget_month_funding_state WHERE budget_month_id=v_source_id;
  IF NOT FOUND THEN v_source_available:=0; v_source_unallocated:=0; END IF;
  SELECT balance INTO v_savings_balance FROM public.budget_savings_state;

  v_fingerprint:=md5('month_disposition|'||p_source_month||'|'
    ||to_char(v_destination_start,'YYYY-MM')||'|'||v_material||'|deficits:'
    ||v_deficits::text||'|unbudgeted:'||v_unbudgeted::text
    ||'|source-funding:'||v_source_available::text||'|'||v_source_unallocated::text
    ||'|destination-funding:'||v_destination_available::text||'|'||v_destination_unallocated::text
    ||'|savings:'||v_savings_balance::text);

  RETURN jsonb_build_object(
    'eligible',v_timing AND v_source_id IS NOT NULL,
    'reason',CASE WHEN NOT v_timing THEN 'IMMEDIATELY_COMPLETED_MONTH_ONLY'
                  WHEN v_source_id IS NULL THEN 'SOURCE_MONTH_MISSING' ELSE NULL END,
    'source_month',p_source_month,
    'destination_month',to_char(v_destination_start,'YYYY-MM'),
    'fingerprint',v_fingerprint,
    'categories',v_rows,
    'carry_forward_total',v_carry::text,
    'return_to_unallocated_total',v_return::text,
    'savings_total',v_savings::text,
    'source_available',v_source_available::text,
    'source_unallocated',v_source_unallocated::text,
    'destination_unallocated_before',v_destination_unallocated::text,
    'destination_unallocated_after',(v_destination_unallocated+v_return)::numeric(18,2)::text,
    'savings_balance_before',v_savings_balance::text,
    'savings_balance_after',(v_savings_balance+v_savings)::numeric(18,2)::text,
    'deficit_blockers',v_deficits,
    'unbudgeted_expense_blockers',v_unbudgeted,
    'can_apply',v_timing AND v_source_id IS NOT NULL
      AND jsonb_array_length(v_deficits)=0 AND jsonb_array_length(v_unbudgeted)=0
      AND NOT EXISTS (
        SELECT 1 FROM public.budget_month_disposition_candidate_rows(p_source_month)
        WHERE status='blocked'
      )
      AND EXISTS (
        SELECT 1 FROM public.budget_month_disposition_candidate_rows(p_source_month)
        WHERE status='ready'
      )
  );
END; $$;

CREATE OR REPLACE FUNCTION public.apply_budget_month_disposition(
  p_source_month TEXT,
  p_request_key UUID,
  p_preview_fingerprint TEXT,
  p_reason TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE
  v_source_start DATE := public.budget_month_start_from_key(p_source_month);
  v_destination_start DATE := (v_source_start+interval '1 month')::date;
  v_current_start DATE := date_trunc('month',timezone('Asia/Jerusalem',statement_timestamp()))::date;
  v_source_month_id BIGINT;
  v_destination_month_id BIGINT;
  v_batch_id BIGINT;
  v_existing public.budget_month_disposition_batches%ROWTYPE;
  v_preview JSONB;
  v_expected TEXT := 'month_disposition_apply|'||p_source_month||'|'||coalesce(p_preview_fingerprint,'');
  v_carry_preview JSONB;
  v_carry_request UUID;
  v_carry_batch_id BIGINT;
  v_source_operation_id BIGINT;
  v_destination_operation_id BIGINT;
  v_transfer public.budget_carryover_transfers%ROWTYPE;
  v_savings_entry_id BIGINT;
  candidate RECORD;
BEGIN
  IF p_request_key IS NULL OR p_preview_fingerprint IS NULL
     OR p_preview_fingerprint !~ '^[0-9a-f]{32}$' THEN
    RAISE EXCEPTION 'request_key and a valid preview fingerprint are required'
      USING ERRCODE='22023';
  END IF;
  IF v_destination_start<>v_current_start THEN
    RAISE EXCEPTION 'MONTH_DISPOSITION_PERIOD_INVALID: source must be the immediately completed Asia/Jerusalem month'
      USING ERRCODE='22023';
  END IF;
  SELECT * INTO v_existing FROM public.budget_month_disposition_batches WHERE request_key=p_request_key;
  IF FOUND THEN
    IF v_existing.request_fingerprint<>v_expected THEN
      RAISE EXCEPTION 'request_key was already used for a different month disposition request'
        USING ERRCODE='23505';
    END IF;
    RETURN jsonb_build_object(
      'source',public.get_funded_budget_month(p_source_month),
      'destination',public.get_funded_budget_month(to_char(v_destination_start,'YYYY-MM')),
      'savings',jsonb_build_object('balance',(SELECT balance_text FROM public.budget_savings_state)),
      'batch_id',v_existing.id
    );
  END IF;
  SELECT id INTO v_source_month_id FROM public.budget_months WHERE month_start=v_source_start;
  IF v_source_month_id IS NULL THEN
    RAISE EXCEPTION 'Previous month has no funded budget state' USING ERRCODE='23514';
  END IF;

  -- Transaction mutations take ROW EXCLUSIVE. This table lock is acquired
  -- before month locks everywhere a transaction-dependent release is made.
  LOCK TABLE public.transactions IN SHARE MODE;
  -- Policy changes cannot pass between capture and write, including insertion
  -- of a previously absent (unconfigured) policy row.
  LOCK TABLE public.budget_unused_balance_policies IN SHARE MODE;
  -- One application-wide reserve has one short transaction-scoped mutex.
  -- It is acquired before month rows so deposits/corrections cannot race the
  -- derived Savings balance or invert the funded lock order.
  PERFORM pg_advisory_xact_lock(hashtext('finance_tracker_budget_savings'));

  INSERT INTO public.budget_months(month_start) VALUES(v_destination_start)
  ON CONFLICT(month_start) DO NOTHING;
  SELECT id INTO v_destination_month_id FROM public.budget_months WHERE month_start=v_destination_start;
  PERFORM 1 FROM public.budget_months
    WHERE id IN(v_source_month_id,v_destination_month_id) ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.budgets
    WHERE budget_month_id IN(v_source_month_id,v_destination_month_id) ORDER BY id FOR UPDATE;
  PERFORM public.budget_assert_reconciled(v_source_month_id);
  PERFORM public.budget_assert_reconciled(v_destination_month_id);

  SELECT * INTO v_existing FROM public.budget_month_disposition_batches WHERE request_key=p_request_key;
  IF FOUND THEN
    IF v_existing.request_fingerprint<>v_expected THEN
      RAISE EXCEPTION 'request_key was already used for a different month disposition request'
        USING ERRCODE='23505';
    END IF;
    RETURN jsonb_build_object(
      'source',public.get_funded_budget_month(p_source_month),
      'destination',public.get_funded_budget_month(to_char(v_destination_start,'YYYY-MM')),
      'savings',jsonb_build_object('balance',(SELECT balance_text FROM public.budget_savings_state)),
      'batch_id',v_existing.id
    );
  END IF;

  v_preview:=public.get_budget_month_disposition_preview(p_source_month);
  IF v_preview->>'fingerprint' IS DISTINCT FROM p_preview_fingerprint THEN
    RAISE EXCEPTION 'MONTH_DISPOSITION_PREVIEW_STALE: candidate material changed; refresh before applying'
      USING ERRCODE='40001';
  END IF;
  IF jsonb_array_length(v_preview->'deficit_blockers')>0 THEN
    RAISE EXCEPTION 'MONTH_DISPOSITION_DEFICITS_UNRESOLVED: resolve funded category deficits before closing the month'
      USING ERRCODE='23514';
  END IF;
  IF jsonb_array_length(v_preview->'unbudgeted_expense_blockers')>0 THEN
    RAISE EXCEPTION 'MONTH_DISPOSITION_UNBUDGETED_EXPENSES: budget or resolve unbudgeted expenses before closing the month'
      USING ERRCODE='23514';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_preview->'categories') row(item)
    WHERE item->>'status'='blocked'
  ) THEN
    RAISE EXCEPTION 'MONTH_DISPOSITION_BLOCKED: configure every eligible category and initialize carry-forward destinations'
      USING ERRCODE='23514';
  END IF;

  INSERT INTO public.budget_month_disposition_batches(
    request_key,request_fingerprint,source_budget_month_id,destination_budget_month_id
  ) VALUES(p_request_key,v_expected,v_source_month_id,v_destination_month_id)
  RETURNING id INTO v_batch_id;

  IF (v_preview->>'carry_forward_total')::numeric>0 THEN
    v_carry_preview:=public.get_budget_carryover_preview(to_char(v_destination_start,'YYYY-MM'));
    v_carry_request:=public.budget_derived_request_key(p_request_key,'carry-forward-batch');
    PERFORM public.apply_budget_carryover(
      to_char(v_destination_start,'YYYY-MM'),v_carry_request,
      v_carry_preview->>'fingerprint',coalesce(p_reason,'Month close: carry forward')
    );
    SELECT id INTO v_carry_batch_id FROM public.budget_carryover_batches
      WHERE request_key=v_carry_request;
  END IF;

  FOR candidate IN
    SELECT item FROM jsonb_array_elements(v_preview->'categories') captured(item)
    WHERE item->>'status'='ready'
    ORDER BY (item->>'category_id')::bigint
  LOOP
    v_source_operation_id:=NULL;
    v_destination_operation_id:=NULL;
    v_savings_entry_id:=NULL;
    v_transfer.id:=NULL;

    IF candidate.item->>'policy'='carry_forward' THEN
      SELECT * INTO v_transfer FROM public.budget_carryover_transfers
      WHERE batch_id=v_carry_batch_id
        AND source_budget_id=(candidate.item->>'source_budget_id')::bigint
        AND reverses_transfer_id IS NULL;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'Carry-forward orchestration did not create the captured transfer'
          USING ERRCODE='23514';
      END IF;
      v_source_operation_id:=v_transfer.source_operation_id;
      v_destination_operation_id:=v_transfer.destination_operation_id;
    ELSIF candidate.item->>'policy'='return_to_unallocated' THEN
      INSERT INTO public.budget_operations(
        budget_month_id,request_key,request_fingerprint,operation_type,effective_date,reason
      ) VALUES(
        v_source_month_id,
        public.budget_derived_request_key(p_request_key,'return-source|'||(candidate.item->>'category_id')),
        'unused_return_out|'||v_batch_id||'|'||(candidate.item->>'category_id')||'|'||(candidate.item->>'eligible_unused'),
        'unused_return_out',v_source_start,p_reason
      ) RETURNING id INTO v_source_operation_id;
      INSERT INTO public.budget_funding_entries(operation_id,amount_delta,source_kind,source_label)
      VALUES(v_source_operation_id,-(candidate.item->>'eligible_unused')::numeric,
        'unused_disposition_transfer','Return unused funding to '||to_char(v_destination_start,'YYYY-MM'));
      INSERT INTO public.budget_movements(operation_id,source_budget_id,amount)
      VALUES(v_source_operation_id,(candidate.item->>'source_budget_id')::bigint,
        (candidate.item->>'eligible_unused')::numeric);

      INSERT INTO public.budget_operations(
        budget_month_id,request_key,request_fingerprint,operation_type,effective_date,reason
      ) VALUES(
        v_destination_month_id,
        public.budget_derived_request_key(p_request_key,'return-destination|'||(candidate.item->>'category_id')),
        'unused_return_in|'||v_batch_id||'|'||(candidate.item->>'category_id')||'|'||(candidate.item->>'eligible_unused'),
        'unused_return_in',v_destination_start,p_reason
      ) RETURNING id INTO v_destination_operation_id;
      INSERT INTO public.budget_funding_entries(operation_id,amount_delta,source_kind,source_label)
      VALUES(v_destination_operation_id,(candidate.item->>'eligible_unused')::numeric,
        'unused_disposition_transfer','Unused funding returned from '||p_source_month);
    ELSE
      INSERT INTO public.budget_operations(
        budget_month_id,request_key,request_fingerprint,operation_type,effective_date,reason
      ) VALUES(
        v_source_month_id,
        public.budget_derived_request_key(p_request_key,'savings|'||(candidate.item->>'category_id')),
        'unused_to_savings|'||v_batch_id||'|'||(candidate.item->>'category_id')||'|'||(candidate.item->>'eligible_unused'),
        'unused_to_savings',v_source_start,p_reason
      ) RETURNING id INTO v_source_operation_id;
      INSERT INTO public.budget_funding_entries(operation_id,amount_delta,source_kind,source_label)
      VALUES(v_source_operation_id,-(candidate.item->>'eligible_unused')::numeric,
        'savings_transfer','Unused budget retained in Savings');
      INSERT INTO public.budget_movements(operation_id,source_budget_id,amount)
      VALUES(v_source_operation_id,(candidate.item->>'source_budget_id')::bigint,
        (candidate.item->>'eligible_unused')::numeric);
      INSERT INTO public.budget_savings_entries(
        operation_id,source_budget_month_id,source_budget_id,category_id,
        amount_delta,entry_kind
      ) VALUES(
        v_source_operation_id,v_source_month_id,(candidate.item->>'source_budget_id')::bigint,
        (candidate.item->>'category_id')::bigint,(candidate.item->>'eligible_unused')::numeric,'deposit'
      ) RETURNING id INTO v_savings_entry_id;
    END IF;

    INSERT INTO public.budget_unused_disposition_events(
      batch_id,category_id,source_budget_id,event_kind,policy,amount,
      source_final_funded_snapshot,source_raw_actual_snapshot,
      source_effective_actual_snapshot,source_operation_id,destination_operation_id,
      carryover_transfer_id,savings_entry_id
    ) VALUES(
      v_batch_id,(candidate.item->>'category_id')::bigint,
      (candidate.item->>'source_budget_id')::bigint,'apply',candidate.item->>'policy',
      (candidate.item->>'eligible_unused')::numeric,
      (candidate.item->>'source_final_funded')::numeric,
      (candidate.item->>'source_raw_actual')::numeric,
      (candidate.item->>'source_effective_actual')::numeric,
      v_source_operation_id,v_destination_operation_id,v_transfer.id,v_savings_entry_id
    );
  END LOOP;

  PERFORM public.budget_assert_reconciled(v_source_month_id);
  PERFORM public.budget_assert_reconciled(v_destination_month_id);
  IF (SELECT balance FROM public.budget_savings_state)<0 THEN
    RAISE EXCEPTION 'Savings ledger cannot have a negative balance' USING ERRCODE='23514';
  END IF;
  RETURN jsonb_build_object(
    'source',public.get_funded_budget_month(p_source_month),
    'destination',public.get_funded_budget_month(to_char(v_destination_start,'YYYY-MM')),
    'savings',jsonb_build_object('balance',(SELECT balance_text FROM public.budget_savings_state)),
    'batch_id',v_batch_id
  );
END; $$;

CREATE OR REPLACE FUNCTION public.reverse_budget_month_disposition(
  p_batch_id BIGINT,
  p_request_key UUID,
  p_reason TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE
  v_original public.budget_month_disposition_batches%ROWTYPE;
  v_reversal public.budget_month_disposition_batches%ROWTYPE;
  v_source_month public.budget_months%ROWTYPE;
  v_destination_month public.budget_months%ROWTYPE;
  v_fingerprint TEXT := 'month_disposition_reverse|'||coalesce(p_batch_id::text,'');
  v_destination_unallocated NUMERIC(18,2);
  v_savings_balance NUMERIC(18,2);
  v_source_operation_id BIGINT;
  v_destination_operation_id BIGINT;
  v_savings_entry_id BIGINT;
  v_transfer_id BIGINT;
  v_source_funding_id BIGINT;
  v_destination_funding_id BIGINT;
  original_event RECORD;
BEGIN
  IF p_batch_id IS NULL OR p_request_key IS NULL THEN
    RAISE EXCEPTION 'batch_id and request_key are required' USING ERRCODE='22023';
  END IF;
  SELECT * INTO v_original FROM public.budget_month_disposition_batches WHERE id=p_batch_id;
  IF NOT FOUND OR v_original.reverses_batch_id IS NOT NULL THEN
    RAISE EXCEPTION 'Original month disposition batch % does not exist',p_batch_id USING ERRCODE='P0002';
  END IF;
  SELECT * INTO v_reversal FROM public.budget_month_disposition_batches WHERE request_key=p_request_key;
  IF FOUND THEN
    IF v_reversal.request_fingerprint<>v_fingerprint OR v_reversal.reverses_batch_id<>p_batch_id THEN
      RAISE EXCEPTION 'request_key was already used for a different disposition reversal'
        USING ERRCODE='23505';
    END IF;
    RETURN jsonb_build_object(
      'source',public.get_funded_budget_month((SELECT month FROM public.budget_month_funding_state WHERE budget_month_id=v_original.source_budget_month_id)),
      'destination',public.get_funded_budget_month((SELECT month FROM public.budget_month_funding_state WHERE budget_month_id=v_original.destination_budget_month_id)),
      'savings',jsonb_build_object('balance',(SELECT balance_text FROM public.budget_savings_state)),
      'batch_id',v_reversal.id
    );
  END IF;

  LOCK TABLE public.transactions IN SHARE MODE;
  PERFORM pg_advisory_xact_lock(hashtext('finance_tracker_budget_savings'));
  PERFORM 1 FROM public.budget_months
    WHERE id IN(v_original.source_budget_month_id,v_original.destination_budget_month_id)
    ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.budgets
    WHERE budget_month_id IN(v_original.source_budget_month_id,v_original.destination_budget_month_id)
    ORDER BY id FOR UPDATE;

  IF EXISTS (
    SELECT 1 FROM public.budget_month_disposition_batches
    WHERE reverses_batch_id=p_batch_id
  ) THEN
    RAISE EXCEPTION 'Month disposition batch % has already been reversed',p_batch_id
      USING ERRCODE='23505';
  END IF;
  SELECT * INTO v_source_month FROM public.budget_months WHERE id=v_original.source_budget_month_id;
  SELECT * INTO v_destination_month FROM public.budget_months WHERE id=v_original.destination_budget_month_id;
  IF EXISTS (
    SELECT 1 FROM public.budget_unused_disposition_events e
    JOIN public.budget_category_state cs ON cs.budget_id=e.source_budget_id
    WHERE e.batch_id=p_batch_id AND e.event_kind='apply' AND cs.lifecycle_state<>'active'
  ) THEN
    RAISE EXCEPTION 'MONTH_DISPOSITION_REVERSAL_BLOCKED: source category budget is inactive'
      USING ERRCODE='23514';
  END IF;
  SELECT coalesce(unallocated,0)::numeric(18,2) INTO v_destination_unallocated
  FROM public.budget_month_funding_state WHERE budget_month_id=v_original.destination_budget_month_id;
  IF v_destination_unallocated < coalesce((
    SELECT sum(amount) FROM public.budget_unused_disposition_events
    WHERE batch_id=p_batch_id AND event_kind='apply' AND policy='return_to_unallocated'
  ),0) THEN
    RAISE EXCEPTION 'MONTH_DISPOSITION_REVERSAL_BLOCKED: destination unallocated funding is insufficient'
      USING ERRCODE='23514';
  END IF;
  SELECT balance INTO v_savings_balance FROM public.budget_savings_state;
  IF v_savings_balance < coalesce((
    SELECT sum(amount) FROM public.budget_unused_disposition_events
    WHERE batch_id=p_batch_id AND event_kind='apply' AND policy='savings'
  ),0) THEN
    RAISE EXCEPTION 'MONTH_DISPOSITION_REVERSAL_BLOCKED: Savings retained funds are insufficient'
      USING ERRCODE='23514';
  END IF;

  INSERT INTO public.budget_month_disposition_batches(
    request_key,request_fingerprint,source_budget_month_id,destination_budget_month_id,reverses_batch_id
  ) VALUES(
    p_request_key,v_fingerprint,v_original.source_budget_month_id,
    v_original.destination_budget_month_id,p_batch_id
  ) RETURNING * INTO v_reversal;

  FOR original_event IN
    SELECT * FROM public.budget_unused_disposition_events
    WHERE batch_id=p_batch_id AND event_kind='apply' ORDER BY id
  LOOP
    v_source_operation_id:=NULL;
    v_destination_operation_id:=NULL;
    v_savings_entry_id:=NULL;
    v_transfer_id:=NULL;
    IF original_event.policy='carry_forward' THEN
      PERFORM public.reverse_budget_carryover(
        original_event.carryover_transfer_id,
        public.budget_derived_request_key(p_request_key,'carry-forward|'||original_event.id),
        coalesce(p_reason,'Month close correction')
      );
      SELECT id,source_operation_id,destination_operation_id
      INTO v_transfer_id,v_source_operation_id,v_destination_operation_id
      FROM public.budget_carryover_transfers
      WHERE reverses_transfer_id=original_event.carryover_transfer_id;
    ELSIF original_event.policy='return_to_unallocated' THEN
      SELECT id INTO v_source_funding_id FROM public.budget_funding_entries
        WHERE operation_id=original_event.source_operation_id;
      SELECT id INTO v_destination_funding_id FROM public.budget_funding_entries
        WHERE operation_id=original_event.destination_operation_id;

      INSERT INTO public.budget_operations(
        budget_month_id,request_key,request_fingerprint,operation_type,
        effective_date,reason,reverses_operation_id
      ) VALUES(
        v_original.destination_budget_month_id,
        public.budget_derived_request_key(p_request_key,'return-destination|'||original_event.id),
        v_fingerprint||'|destination|'||original_event.id,'unused_disposition_reversal',
        v_destination_month.month_start,p_reason,original_event.destination_operation_id
      ) RETURNING id INTO v_destination_operation_id;
      INSERT INTO public.budget_funding_entries(
        operation_id,amount_delta,source_kind,source_label,reverses_funding_entry_id
      ) VALUES(v_destination_operation_id,-original_event.amount,'unused_disposition_transfer',
        'Reverse unused funding returned from '||to_char(v_source_month.month_start,'YYYY-MM'),
        v_destination_funding_id);

      INSERT INTO public.budget_operations(
        budget_month_id,request_key,request_fingerprint,operation_type,
        effective_date,reason,reverses_operation_id
      ) VALUES(
        v_original.source_budget_month_id,
        public.budget_derived_request_key(p_request_key,'return-source|'||original_event.id),
        v_fingerprint||'|source|'||original_event.id,'unused_disposition_reversal',
        v_source_month.month_start,p_reason,original_event.source_operation_id
      ) RETURNING id INTO v_source_operation_id;
      INSERT INTO public.budget_funding_entries(
        operation_id,amount_delta,source_kind,source_label,reverses_funding_entry_id
      ) VALUES(v_source_operation_id,original_event.amount,'unused_disposition_transfer',
        'Restore unused funding from '||to_char(v_destination_month.month_start,'YYYY-MM'),
        v_source_funding_id);
      INSERT INTO public.budget_movements(operation_id,destination_budget_id,amount)
      VALUES(v_source_operation_id,original_event.source_budget_id,original_event.amount);
    ELSE
      SELECT id INTO v_source_funding_id FROM public.budget_funding_entries
        WHERE operation_id=original_event.source_operation_id;
      INSERT INTO public.budget_operations(
        budget_month_id,request_key,request_fingerprint,operation_type,
        effective_date,reason,reverses_operation_id
      ) VALUES(
        v_original.source_budget_month_id,
        public.budget_derived_request_key(p_request_key,'savings|'||original_event.id),
        v_fingerprint||'|savings|'||original_event.id,'unused_disposition_reversal',
        v_source_month.month_start,p_reason,original_event.source_operation_id
      ) RETURNING id INTO v_source_operation_id;
      INSERT INTO public.budget_funding_entries(
        operation_id,amount_delta,source_kind,source_label,reverses_funding_entry_id
      ) VALUES(v_source_operation_id,original_event.amount,'savings_transfer',
        'Restore retained Savings to source budget',v_source_funding_id);
      INSERT INTO public.budget_movements(operation_id,destination_budget_id,amount)
      VALUES(v_source_operation_id,original_event.source_budget_id,original_event.amount);
      INSERT INTO public.budget_savings_entries(
        operation_id,source_budget_month_id,source_budget_id,category_id,
        amount_delta,entry_kind,reverses_entry_id
      ) VALUES(
        v_source_operation_id,v_original.source_budget_month_id,original_event.source_budget_id,
        original_event.category_id,-original_event.amount,'reversal',original_event.savings_entry_id
      ) RETURNING id INTO v_savings_entry_id;
    END IF;

    INSERT INTO public.budget_unused_disposition_events(
      batch_id,category_id,source_budget_id,event_kind,policy,amount,
      source_final_funded_snapshot,source_raw_actual_snapshot,
      source_effective_actual_snapshot,source_operation_id,destination_operation_id,
      carryover_transfer_id,savings_entry_id,reverses_event_id
    ) VALUES(
      v_reversal.id,original_event.category_id,original_event.source_budget_id,
      'reversal',original_event.policy,original_event.amount,
      original_event.source_final_funded_snapshot,original_event.source_raw_actual_snapshot,
      original_event.source_effective_actual_snapshot,v_source_operation_id,
      v_destination_operation_id,v_transfer_id,v_savings_entry_id,original_event.id
    );
  END LOOP;

  PERFORM public.budget_assert_reconciled(v_original.source_budget_month_id);
  PERFORM public.budget_assert_reconciled(v_original.destination_budget_month_id);
  IF (SELECT balance FROM public.budget_savings_state)<0 THEN
    RAISE EXCEPTION 'Savings ledger cannot have a negative balance' USING ERRCODE='23514';
  END IF;
  RETURN jsonb_build_object(
    'source',public.get_funded_budget_month(to_char(v_source_month.month_start,'YYYY-MM')),
    'destination',public.get_funded_budget_month(to_char(v_destination_month.month_start,'YYYY-MM')),
    'savings',jsonb_build_object('balance',(SELECT balance_text FROM public.budget_savings_state)),
    'batch_id',v_reversal.id
  );
END; $$;

CREATE OR REPLACE FUNCTION public.validate_budget_disposition_event()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE
  v_batch public.budget_month_disposition_batches%ROWTYPE;
  v_budget public.budgets%ROWTYPE;
  v_source_operation public.budget_operations%ROWTYPE;
  v_destination_operation public.budget_operations%ROWTYPE;
  v_source_funding public.budget_funding_entries%ROWTYPE;
  v_destination_funding public.budget_funding_entries%ROWTYPE;
  v_source_movement public.budget_movements%ROWTYPE;
BEGIN
  SELECT * INTO v_batch FROM public.budget_month_disposition_batches WHERE id=NEW.batch_id;
  SELECT * INTO v_budget FROM public.budgets WHERE id=NEW.source_budget_id;
  SELECT * INTO v_source_operation FROM public.budget_operations WHERE id=NEW.source_operation_id;
  SELECT * INTO v_source_funding FROM public.budget_funding_entries WHERE operation_id=NEW.source_operation_id;
  SELECT * INTO v_source_movement FROM public.budget_movements WHERE operation_id=NEW.source_operation_id;
  IF v_budget.budget_month_id IS DISTINCT FROM v_batch.source_budget_month_id
     OR v_budget.category_id IS DISTINCT FROM NEW.category_id
     OR v_source_operation.budget_month_id IS DISTINCT FROM v_batch.source_budget_month_id THEN
    RAISE EXCEPTION 'Disposition source provenance does not match its batch/category'
      USING ERRCODE='23514';
  END IF;
  IF NEW.destination_operation_id IS NOT NULL THEN
    SELECT * INTO v_destination_operation FROM public.budget_operations
      WHERE id=NEW.destination_operation_id;
    SELECT * INTO v_destination_funding FROM public.budget_funding_entries
      WHERE operation_id=NEW.destination_operation_id;
    IF v_destination_operation.budget_month_id IS DISTINCT FROM v_batch.destination_budget_month_id THEN
      RAISE EXCEPTION 'Disposition destination operation does not match its batch'
        USING ERRCODE='23514';
    END IF;
  END IF;
  IF NEW.policy='return_to_unallocated' AND NEW.event_kind='apply' AND (
       v_source_funding.source_kind<>'unused_disposition_transfer'
       OR v_source_funding.amount_delta<>-NEW.amount
       OR v_source_movement.source_budget_id IS DISTINCT FROM NEW.source_budget_id
       OR v_source_movement.destination_budget_id IS NOT NULL
       OR v_source_movement.amount<>NEW.amount
       OR v_destination_funding.source_kind<>'unused_disposition_transfer'
       OR v_destination_funding.amount_delta<>NEW.amount
       OR EXISTS(SELECT 1 FROM public.budget_movements WHERE operation_id=NEW.destination_operation_id)
     ) THEN
    RAISE EXCEPTION 'Return-to-unallocated operations are not a balanced cross-month transfer'
      USING ERRCODE='23514';
  END IF;
  IF NEW.event_kind='apply' AND (
    (NEW.policy='carry_forward' AND v_source_operation.operation_type<>'carryover_out')
    OR (NEW.policy='return_to_unallocated' AND
        (v_source_operation.operation_type<>'unused_return_out'
         OR v_destination_operation.operation_type<>'unused_return_in'))
    OR (NEW.policy='savings' AND v_source_operation.operation_type<>'unused_to_savings')
  ) THEN
    RAISE EXCEPTION 'Disposition operation types do not match the applied policy'
      USING ERRCODE='23514';
  END IF;
  IF NEW.event_kind='reversal' AND NEW.policy<>'carry_forward'
     AND v_source_operation.operation_type<>'unused_disposition_reversal' THEN
    RAISE EXCEPTION 'Disposition correction requires a compensating operation'
      USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END; $$;

CREATE TRIGGER budget_disposition_events_validate
BEFORE INSERT ON public.budget_unused_disposition_events
FOR EACH ROW EXECUTE FUNCTION public.validate_budget_disposition_event();

-- Preserve the Migration 020 canonical read and add policy, close history, and
-- the separate application-wide Savings balance. This wrapper remains STABLE.
ALTER FUNCTION public.get_funded_budget_month(TEXT)
  RENAME TO get_funded_budget_month_overrides;

CREATE OR REPLACE FUNCTION public.get_funded_budget_month(p_month TEXT)
RETURNS JSONB
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE
  v_state JSONB:=public.get_funded_budget_month_overrides(p_month);
  v_categories JSONB;
  v_history JSONB;
BEGIN
  SELECT coalesce(jsonb_agg(
    item||jsonb_build_object('unused_balance_policy',p.policy)
    ORDER BY ordinality
  ),'[]'::jsonb)
  INTO v_categories
  FROM jsonb_array_elements(coalesce(v_state->'categories','[]'::jsonb))
    WITH ORDINALITY category(item,ordinality)
  LEFT JOIN public.budget_unused_balance_policies p
    ON p.category_id=NULLIF(item->>'category_id','')::bigint;

  SELECT coalesce(jsonb_agg(to_jsonb(h) ORDER BY h.event_id),'[]'::jsonb)
  INTO v_history
  FROM public.budget_month_disposition_history h
  WHERE h.source_month=p_month OR h.destination_month=p_month;

  RETURN v_state
    ||jsonb_build_object('categories',v_categories)
    ||jsonb_build_object('unused_disposition_history',v_history)
    ||jsonb_build_object('savings',jsonb_build_object(
      'balance',(SELECT balance_text FROM public.budget_savings_state)
    ));
END; $$;

ALTER TABLE public.budget_unused_balance_policies ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.budget_month_disposition_batches ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.budget_unused_disposition_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.budget_savings_entries ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.budget_unused_balance_policies,
  public.budget_carryover_settings,
  public.budget_carryover_settings_read,
  public.budget_unused_balance_policies_read,
  public.budget_month_disposition_batches,
  public.budget_unused_disposition_events,
  public.budget_savings_entries,
  public.budget_savings_state,
  public.budget_month_disposition_history
  FROM PUBLIC,anon,authenticated,service_role;
GRANT SELECT ON public.budget_unused_balance_policies,
  public.budget_unused_balance_policies_read,
  public.budget_month_disposition_batches,
  public.budget_unused_disposition_events,
  public.budget_savings_entries,
  public.budget_savings_state,
  public.budget_month_disposition_history
  TO service_role;

REVOKE ALL ON FUNCTION public.validate_budget_carryover_setting(),
  public.prevent_category_type_with_carryover(),
  public.validate_budget_disposition_batch(),
  public.validate_budget_savings_entry(),
  public.validate_budget_disposition_event(),
  public.budget_month_disposition_candidate_rows(TEXT),
  public.get_funded_budget_month_overrides(TEXT)
  FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.set_budget_unused_balance_policy(BIGINT,TEXT),
  public.get_budget_month_disposition_preview(TEXT),
  public.apply_budget_month_disposition(TEXT,UUID,TEXT,TEXT),
  public.reverse_budget_month_disposition(BIGINT,UUID,TEXT)
  FROM PUBLIC,anon,authenticated;
REVOKE EXECUTE ON FUNCTION public.apply_budget_carryover(TEXT,UUID,TEXT,TEXT)
  FROM service_role;
REVOKE EXECUTE ON FUNCTION public.get_funded_budget_month(TEXT)
  FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.get_funded_budget_month(TEXT),
  public.set_budget_unused_balance_policy(BIGINT,TEXT),
  public.get_budget_month_disposition_preview(TEXT),
  public.apply_budget_month_disposition(TEXT,UUID,TEXT,TEXT),
  public.reverse_budget_month_disposition(BIGINT,UUID,TEXT)
  TO service_role;

DO $$
DECLARE v_month RECORD;
BEGIN
  FOR v_month IN SELECT id FROM public.budget_months ORDER BY id LOOP
    PERFORM public.budget_assert_reconciled(v_month.id);
  END LOOP;
  IF EXISTS(SELECT 1 FROM public.budget_savings_entries) THEN
    RAISE EXCEPTION 'Migration 021 must not create historical savings entries';
  END IF;
  IF EXISTS(SELECT 1 FROM public.budget_month_disposition_batches)
     OR EXISTS(SELECT 1 FROM public.budget_unused_disposition_events) THEN
    RAISE EXCEPTION 'Migration 021 must not create historical disposition provenance';
  END IF;
END; $$;

COMMIT;
-- Migration 022: funded reallocation and deficit resolution.
--
-- Planned moves are current-month only. Deficit resolution also supports the
-- immediately completed, still-unclosed month so Migration 021 close blockers
-- can be repaired explicitly. All financial history remains append-only.

BEGIN;

DO $$
BEGIN
  IF to_regclass('public.budget_months') IS NULL
     OR to_regclass('public.budget_category_base_state') IS NULL
     OR to_regclass('public.budget_month_disposition_batches') IS NULL
     OR to_regclass('public.budget_savings_entries') IS NULL
     OR to_regclass('public.budget_savings_state') IS NULL
     OR to_regprocedure('public.get_funded_budget_month(text)') IS NULL
     OR to_regprocedure('public.budget_assert_reconciled(bigint)') IS NULL THEN
    RAISE EXCEPTION 'Migration 022 preflight: Migrations 017 through 021 are required';
  END IF;
  IF to_regclass('public.budget_funding_actions') IS NOT NULL
     OR to_regclass('public.budget_funding_action_legs') IS NOT NULL
     OR to_regclass('public.budget_category_funding_action_state') IS NOT NULL
     OR to_regprocedure('public.get_budget_reallocation_preview(text,text,bigint,text,bigint,numeric)') IS NOT NULL
     OR to_regprocedure('public.get_budget_deficit_resolution_preview(text,bigint,jsonb)') IS NOT NULL THEN
    RAISE EXCEPTION 'Migration 022 preflight: unexpected partial reallocation schema exists';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.budget_operations
    WHERE operation_type NOT IN (
      'legacy_import','manual_funding','establish_budget','adjustment','removal',
      'reactivation','copy','reversal','month_initialization','carryover_out',
      'carryover_in','monthly_override_set','monthly_override_remove',
      'unused_return_out','unused_return_in','unused_to_savings',
      'unused_disposition_reversal'
    )
  ) OR EXISTS (
    SELECT 1 FROM public.budget_funding_entries
    WHERE source_kind NOT IN (
      'manual_available_funds','legacy_import','carryover_transfer',
      'unused_disposition_transfer','savings_transfer'
    )
  ) OR EXISTS (
    SELECT 1 FROM public.budget_savings_entries
    WHERE entry_kind NOT IN ('deposit','reversal')
  ) THEN
    RAISE EXCEPTION 'Migration 022 preflight: unexpected funded-budget domain value';
  END IF;
END;
$$;

ALTER TABLE public.budget_operations
  DROP CONSTRAINT budget_operations_operation_type_check,
  ADD CONSTRAINT budget_operations_operation_type_check CHECK (operation_type IN (
    'legacy_import','manual_funding','establish_budget','adjustment','removal',
    'reactivation','copy','reversal','month_initialization','carryover_out',
    'carryover_in','monthly_override_set','monthly_override_remove',
    'unused_return_out','unused_return_in','unused_to_savings',
    'unused_disposition_reversal','budget_reallocation','deficit_resolution',
    'funding_action_reversal'
  ));

ALTER TABLE public.budget_funding_entries
  DROP CONSTRAINT budget_funding_entries_source_kind_check,
  ADD CONSTRAINT budget_funding_entries_source_kind_check CHECK (
    source_kind IN (
      'manual_available_funds','legacy_import','carryover_transfer',
      'unused_disposition_transfer','savings_transfer','savings_withdrawal'
    )
  );

ALTER TABLE public.budget_savings_entries
  ADD COLUMN destination_budget_month_id BIGINT REFERENCES public.budget_months(id) ON DELETE RESTRICT,
  ADD COLUMN destination_budget_id BIGINT REFERENCES public.budgets(id) ON DELETE RESTRICT,
  ADD COLUMN movement_id BIGINT UNIQUE REFERENCES public.budget_movements(id) ON DELETE RESTRICT,
  ALTER COLUMN source_budget_month_id DROP NOT NULL,
  ALTER COLUMN source_budget_id DROP NOT NULL,
  DROP CONSTRAINT budget_savings_entries_entry_kind_check,
  DROP CONSTRAINT budget_savings_entries_check,
  ADD CONSTRAINT budget_savings_entries_entry_kind_check CHECK (
    entry_kind IN ('deposit','reversal','withdrawal','withdrawal_reversal')
  ),
  ADD CONSTRAINT budget_savings_entries_provenance_shape CHECK (
    (entry_kind='deposit' AND amount_delta>0 AND reverses_entry_id IS NULL
      AND source_budget_month_id IS NOT NULL AND source_budget_id IS NOT NULL
      AND destination_budget_month_id IS NULL AND destination_budget_id IS NULL
      AND movement_id IS NULL)
    OR
    (entry_kind='reversal' AND amount_delta<0 AND reverses_entry_id IS NOT NULL
      AND source_budget_month_id IS NOT NULL AND source_budget_id IS NOT NULL
      AND destination_budget_month_id IS NULL AND destination_budget_id IS NULL
      AND movement_id IS NULL)
    OR
    (entry_kind='withdrawal' AND amount_delta<0 AND reverses_entry_id IS NULL
      AND source_budget_month_id IS NULL AND source_budget_id IS NULL
      AND destination_budget_month_id IS NOT NULL AND destination_budget_id IS NOT NULL
      AND movement_id IS NOT NULL)
    OR
    (entry_kind='withdrawal_reversal' AND amount_delta>0 AND reverses_entry_id IS NOT NULL
      AND source_budget_month_id IS NULL AND source_budget_id IS NULL
      AND destination_budget_month_id IS NOT NULL AND destination_budget_id IS NOT NULL
      AND movement_id IS NOT NULL)
  );

CREATE TABLE public.budget_funding_actions (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  operation_id BIGINT NOT NULL UNIQUE REFERENCES public.budget_operations(id) ON DELETE RESTRICT,
  action_kind TEXT NOT NULL CHECK (action_kind IN (
    'planned_reallocation','deficit_resolution','reversal'
  )),
  budget_month_id BIGINT NOT NULL REFERENCES public.budget_months(id) ON DELETE RESTRICT,
  destination_budget_id BIGINT REFERENCES public.budgets(id) ON DELETE RESTRICT,
  requested_amount NUMERIC(18,2) NOT NULL,
  applied_amount NUMERIC(18,2) NOT NULL,
  destination_final_funded_snapshot NUMERIC(18,2),
  destination_raw_actual_snapshot NUMERIC(18,2),
  deficit_before NUMERIC(18,2),
  deficit_after NUMERIC(18,2),
  reversed_action_id BIGINT UNIQUE REFERENCES public.budget_funding_actions(id) ON DELETE RESTRICT,
  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text,now()),
  CHECK (requested_amount::text NOT IN ('NaN','Infinity','-Infinity') AND requested_amount>0),
  CHECK (applied_amount::text NOT IN ('NaN','Infinity','-Infinity') AND applied_amount>0),
  CHECK (requested_amount=applied_amount),
  CHECK (destination_final_funded_snapshot IS NULL OR destination_final_funded_snapshot>=0),
  CHECK (deficit_before IS NULL OR deficit_before>=0),
  CHECK (deficit_after IS NULL OR deficit_after>=0),
  CHECK ((action_kind='reversal')=(reversed_action_id IS NOT NULL)),
  CHECK (action_kind<>'deficit_resolution' OR (
    destination_budget_id IS NOT NULL AND deficit_before>0
    AND applied_amount<=deficit_before AND deficit_after=deficit_before-applied_amount
  ))
);

CREATE TABLE public.budget_funding_action_legs (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  action_id BIGINT NOT NULL REFERENCES public.budget_funding_actions(id) ON DELETE RESTRICT,
  source_kind TEXT NOT NULL CHECK (source_kind IN ('category','unallocated','savings')),
  source_budget_id BIGINT REFERENCES public.budgets(id) ON DELETE RESTRICT,
  amount NUMERIC(18,2) NOT NULL,
  source_final_funded_snapshot NUMERIC(18,2),
  source_raw_actual_snapshot NUMERIC(18,2),
  source_effective_actual_snapshot NUMERIC(18,2),
  source_capacity_snapshot NUMERIC(18,2) NOT NULL,
  movement_id BIGINT NOT NULL UNIQUE REFERENCES public.budget_movements(id) ON DELETE RESTRICT,
  savings_entry_id BIGINT UNIQUE REFERENCES public.budget_savings_entries(id) ON DELETE RESTRICT,
  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text,now()),
  CHECK (amount::text NOT IN ('NaN','Infinity','-Infinity') AND amount>0),
  CHECK (source_capacity_snapshot::text NOT IN ('NaN','Infinity','-Infinity')
         AND source_capacity_snapshot>=amount),
  CHECK (
    (source_kind='category' AND source_budget_id IS NOT NULL
      AND source_final_funded_snapshot IS NOT NULL
      AND source_raw_actual_snapshot IS NOT NULL
      AND source_effective_actual_snapshot IS NOT NULL
      AND savings_entry_id IS NULL)
    OR
    (source_kind='unallocated' AND source_budget_id IS NULL
      AND source_final_funded_snapshot IS NULL
      AND source_raw_actual_snapshot IS NULL
      AND source_effective_actual_snapshot IS NULL
      AND savings_entry_id IS NULL)
    OR
    (source_kind='savings' AND source_budget_id IS NULL
      AND source_final_funded_snapshot IS NULL
      AND source_raw_actual_snapshot IS NULL
      AND source_effective_actual_snapshot IS NULL
      AND savings_entry_id IS NOT NULL)
  )
);

CREATE INDEX idx_budget_funding_actions_month ON public.budget_funding_actions(budget_month_id,id);
CREATE INDEX idx_budget_funding_actions_destination ON public.budget_funding_actions(destination_budget_id,id);
CREATE INDEX idx_budget_funding_action_legs_action ON public.budget_funding_action_legs(action_id,id);
CREATE INDEX idx_budget_funding_action_legs_source ON public.budget_funding_action_legs(source_budget_id,id);

CREATE OR REPLACE FUNCTION public.budget_action_month_lifecycle(p_month TEXT)
RETURNS TEXT
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE
  v_month_start DATE:=public.budget_month_start_from_key(p_month);
  v_current_start DATE:=date_trunc('month',timezone('Asia/Jerusalem',statement_timestamp()))::date;
  v_month_id BIGINT;
BEGIN
  IF v_month_start=v_current_start THEN RETURN 'current'; END IF;
  SELECT id INTO v_month_id FROM public.budget_months WHERE month_start=v_month_start;
  IF v_month_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.budget_month_disposition_batches
    WHERE source_budget_month_id=v_month_id AND reverses_batch_id IS NULL
  ) THEN
    RETURN 'closed';
  END IF;
  IF v_month_start=(v_current_start-interval '1 month')::date THEN
    RETURN 'immediately_completed_unclosed';
  END IF;
  IF v_month_start<v_current_start THEN RETURN 'historical_forbidden'; END IF;
  RETURN 'future_forbidden';
END; $$;

CREATE OR REPLACE FUNCTION public.validate_budget_funding_action()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE v_operation public.budget_operations%ROWTYPE; v_destination public.budgets%ROWTYPE;
BEGIN
  SELECT * INTO v_operation FROM public.budget_operations WHERE id=NEW.operation_id;
  IF v_operation.budget_month_id IS DISTINCT FROM NEW.budget_month_id
     OR (NEW.action_kind='planned_reallocation' AND v_operation.operation_type<>'budget_reallocation')
     OR (NEW.action_kind='deficit_resolution' AND v_operation.operation_type<>'deficit_resolution')
     OR (NEW.action_kind='reversal' AND v_operation.operation_type<>'funding_action_reversal') THEN
    RAISE EXCEPTION 'Funding action does not match its operation' USING ERRCODE='23514';
  END IF;
  IF NEW.destination_budget_id IS NOT NULL THEN
    SELECT * INTO v_destination FROM public.budgets WHERE id=NEW.destination_budget_id;
    IF v_destination.budget_month_id IS DISTINCT FROM NEW.budget_month_id THEN
      RAISE EXCEPTION 'Funding action destination belongs to another month' USING ERRCODE='23514';
    END IF;
  END IF;
  IF NEW.action_kind='reversal' AND NOT EXISTS (
    SELECT 1 FROM public.budget_funding_actions original
    WHERE original.id=NEW.reversed_action_id AND original.action_kind<>'reversal'
      AND original.budget_month_id=NEW.budget_month_id
  ) THEN
    RAISE EXCEPTION 'Funding action reversal does not match an original action' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END; $$;

CREATE OR REPLACE FUNCTION public.validate_budget_funding_action_leg()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE
  v_action public.budget_funding_actions%ROWTYPE;
  v_movement public.budget_movements%ROWTYPE;
  v_source public.budgets%ROWTYPE;
BEGIN
  SELECT * INTO v_action FROM public.budget_funding_actions WHERE id=NEW.action_id;
  SELECT * INTO v_movement FROM public.budget_movements WHERE id=NEW.movement_id;
  IF v_movement.operation_id IS DISTINCT FROM v_action.operation_id THEN
    RAISE EXCEPTION 'Funding action leg movement belongs to another operation' USING ERRCODE='23514';
  END IF;
  IF NEW.source_kind='category' THEN
    SELECT * INTO v_source FROM public.budgets WHERE id=NEW.source_budget_id;
    IF v_source.budget_month_id IS DISTINCT FROM v_action.budget_month_id THEN
      RAISE EXCEPTION 'Funding action source belongs to another month' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END; $$;

CREATE TRIGGER budget_funding_actions_validate BEFORE INSERT ON public.budget_funding_actions
FOR EACH ROW EXECUTE FUNCTION public.validate_budget_funding_action();
CREATE TRIGGER budget_funding_actions_immutable BEFORE UPDATE OR DELETE ON public.budget_funding_actions
FOR EACH ROW EXECUTE FUNCTION public.prevent_budget_history_mutation();
CREATE TRIGGER budget_funding_action_legs_validate BEFORE INSERT ON public.budget_funding_action_legs
FOR EACH ROW EXECUTE FUNCTION public.validate_budget_funding_action_leg();
CREATE TRIGGER budget_funding_action_legs_immutable BEFORE UPDATE OR DELETE ON public.budget_funding_action_legs
FOR EACH ROW EXECUTE FUNCTION public.prevent_budget_history_mutation();

CREATE OR REPLACE FUNCTION public.validate_budget_savings_entry()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE
  v_operation public.budget_operations%ROWTYPE;
  v_budget public.budgets%ROWTYPE;
  v_funding public.budget_funding_entries%ROWTYPE;
  v_movement public.budget_movements%ROWTYPE;
BEGIN
  SELECT * INTO v_operation FROM public.budget_operations WHERE id=NEW.operation_id;
  SELECT * INTO v_funding FROM public.budget_funding_entries WHERE operation_id=NEW.operation_id;
  IF NEW.entry_kind IN ('deposit','reversal') THEN
    SELECT * INTO v_budget FROM public.budgets WHERE id=NEW.source_budget_id;
    SELECT * INTO v_movement FROM public.budget_movements WHERE operation_id=NEW.operation_id;
    IF v_operation.budget_month_id IS DISTINCT FROM NEW.source_budget_month_id
       OR v_budget.budget_month_id IS DISTINCT FROM NEW.source_budget_month_id
       OR v_budget.category_id IS DISTINCT FROM NEW.category_id
       OR v_operation.operation_type NOT IN ('unused_to_savings','unused_disposition_reversal') THEN
      RAISE EXCEPTION 'Savings entry provenance does not match its source' USING ERRCODE='23514';
    END IF;
    IF NEW.entry_kind='reversal' AND NOT EXISTS (
      SELECT 1 FROM public.budget_savings_entries original
      WHERE original.id=NEW.reverses_entry_id AND original.entry_kind='deposit'
        AND original.source_budget_id=NEW.source_budget_id
        AND original.amount_delta=-NEW.amount_delta
    ) THEN
      RAISE EXCEPTION 'Savings reversal does not match its deposit' USING ERRCODE='23514';
    END IF;
    IF v_funding.source_kind<>'savings_transfer'
       OR v_funding.amount_delta<>-NEW.amount_delta
       OR (NEW.entry_kind='deposit' AND (
         v_movement.source_budget_id IS DISTINCT FROM NEW.source_budget_id
         OR v_movement.destination_budget_id IS NOT NULL OR v_movement.amount<>NEW.amount_delta))
       OR (NEW.entry_kind='reversal' AND (
         v_movement.source_budget_id IS NOT NULL
         OR v_movement.destination_budget_id IS DISTINCT FROM NEW.source_budget_id
         OR v_movement.amount<>-NEW.amount_delta)) THEN
      RAISE EXCEPTION 'Savings funding and category movement are not balanced' USING ERRCODE='23514';
    END IF;
  ELSE
    SELECT * INTO v_budget FROM public.budgets WHERE id=NEW.destination_budget_id;
    SELECT * INTO v_movement FROM public.budget_movements WHERE id=NEW.movement_id;
    IF v_operation.budget_month_id IS DISTINCT FROM NEW.destination_budget_month_id
       OR v_budget.budget_month_id IS DISTINCT FROM NEW.destination_budget_month_id
       OR v_budget.category_id IS DISTINCT FROM NEW.category_id
       OR v_movement.operation_id IS DISTINCT FROM NEW.operation_id
       OR v_operation.operation_type NOT IN ('deficit_resolution','funding_action_reversal')
       OR v_funding.source_kind<>'savings_withdrawal'
       OR v_funding.amount_delta<>-NEW.amount_delta THEN
      RAISE EXCEPTION 'Savings withdrawal provenance is not balanced' USING ERRCODE='23514';
    END IF;
    IF NEW.entry_kind='withdrawal' AND (
      v_movement.source_budget_id IS NOT NULL
      OR v_movement.destination_budget_id IS DISTINCT FROM NEW.destination_budget_id
      OR v_movement.amount<>-NEW.amount_delta
    ) THEN
      RAISE EXCEPTION 'Savings withdrawal movement is not balanced' USING ERRCODE='23514';
    END IF;
    IF NEW.entry_kind='withdrawal_reversal' AND (
      v_movement.source_budget_id IS DISTINCT FROM NEW.destination_budget_id
      OR v_movement.destination_budget_id IS NOT NULL
      OR v_movement.amount<>NEW.amount_delta
      OR NOT EXISTS (
        SELECT 1 FROM public.budget_savings_entries original
        WHERE original.id=NEW.reverses_entry_id AND original.entry_kind='withdrawal'
          AND original.destination_budget_id=NEW.destination_budget_id
          AND original.amount_delta=-NEW.amount_delta
      )
    ) THEN
      RAISE EXCEPTION 'Savings withdrawal reversal does not match its withdrawal' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END; $$;

CREATE VIEW public.budget_category_funding_action_state AS
SELECT cs.budget_id,
  coalesce(sum(m.amount) FILTER (WHERE m.destination_budget_id=cs.budget_id),0)::numeric(18,2)
    AS incoming_reallocation_resolution,
  coalesce(sum(m.amount) FILTER (WHERE m.source_budget_id=cs.budget_id),0)::numeric(18,2)
    AS outgoing_reallocation,
  (coalesce(sum(m.amount) FILTER (WHERE m.destination_budget_id=cs.budget_id),0)
   -coalesce(sum(m.amount) FILTER (WHERE m.source_budget_id=cs.budget_id),0))::numeric(18,2)
    AS net_funding_action_adjustment
FROM public.budget_category_state cs
LEFT JOIN public.budget_movements m
  ON m.source_budget_id=cs.budget_id OR m.destination_budget_id=cs.budget_id
LEFT JOIN public.budget_funding_actions a ON a.operation_id=m.operation_id
WHERE a.id IS NOT NULL OR m.id IS NULL
GROUP BY cs.budget_id;

CREATE VIEW public.budget_funding_action_history AS
SELECT a.id AS action_id,a.action_kind,to_char(bm.month_start,'YYYY-MM') AS month,
  a.destination_budget_id,a.requested_amount::numeric(18,2)::text AS requested_amount,
  a.applied_amount::numeric(18,2)::text AS applied_amount,
  a.destination_final_funded_snapshot::numeric(18,2)::text AS destination_final_funded_snapshot,
  a.destination_raw_actual_snapshot::numeric(18,2)::text AS destination_raw_actual_snapshot,
  a.deficit_before::numeric(18,2)::text AS deficit_before,
  a.deficit_after::numeric(18,2)::text AS deficit_after,a.reversed_action_id,a.created_at,
  coalesce((SELECT jsonb_agg(jsonb_build_object(
    'id',l.id,'source_kind',l.source_kind,'source_budget_id',l.source_budget_id,
    'amount',l.amount::numeric(18,2)::text,
    'source_capacity_snapshot',l.source_capacity_snapshot::numeric(18,2)::text,
    'source_final_funded_snapshot',l.source_final_funded_snapshot::numeric(18,2)::text,
    'source_raw_actual_snapshot',l.source_raw_actual_snapshot::numeric(18,2)::text,
    'source_effective_actual_snapshot',l.source_effective_actual_snapshot::numeric(18,2)::text,
    'movement_id',l.movement_id,'savings_entry_id',l.savings_entry_id
  ) ORDER BY l.id) FROM public.budget_funding_action_legs l WHERE l.action_id=a.id),'[]'::jsonb) AS legs
FROM public.budget_funding_actions a JOIN public.budget_months bm ON bm.id=a.budget_month_id;

CREATE OR REPLACE FUNCTION public.get_budget_reallocation_preview(
  p_month TEXT,p_source_kind TEXT,p_source_category_id BIGINT,
  p_destination_kind TEXT,p_destination_category_id BIGINT,p_amount NUMERIC
)
RETURNS JSONB
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE
  v_lifecycle TEXT:=public.budget_action_month_lifecycle(p_month);
  v_month_start DATE:=public.budget_month_start_from_key(p_month);
  v_month_id BIGINT;
  v_source_budget_id BIGINT; v_source_final NUMERIC(18,2);
  v_source_lifecycle TEXT; v_source_type TEXT; v_source_active BOOLEAN;
  v_destination_budget_id BIGINT; v_destination_final NUMERIC(18,2);
  v_destination_lifecycle TEXT; v_destination_type TEXT; v_destination_active BOOLEAN;
  v_source_raw NUMERIC(18,2):=0; v_source_effective NUMERIC(18,2):=0;
  v_capacity NUMERIC(18,2):=0; v_unallocated NUMERIC(18,2):=0;
  v_destination_raw NUMERIC(18,2):=0; v_destination_after NUMERIC(18,2);
  v_reason TEXT; v_material TEXT; v_fingerprint TEXT;
BEGIN
  IF p_amount IS NULL OR p_amount::text IN ('NaN','Infinity','-Infinity')
     OR p_amount<=0 OR p_amount<>round(p_amount,2) OR p_amount>9999999999999999.99 THEN
    RAISE EXCEPTION 'Reallocation amount must be a positive two-decimal value' USING ERRCODE='22023';
  END IF;
  IF p_source_kind IS NULL OR p_source_kind NOT IN ('category','unallocated')
     OR p_destination_kind IS NULL OR p_destination_kind NOT IN ('category','unallocated')
     OR (p_source_kind='unallocated' AND p_destination_kind='unallocated')
     OR (p_source_kind='category')<>(p_source_category_id IS NOT NULL)
     OR (p_destination_kind='category')<>(p_destination_category_id IS NOT NULL)
     OR (p_source_category_id IS NOT NULL AND p_source_category_id=p_destination_category_id) THEN
    RAISE EXCEPTION 'Invalid reallocation endpoints' USING ERRCODE='22023';
  END IF;
  SELECT id INTO v_month_id FROM public.budget_months WHERE month_start=v_month_start;
  SELECT coalesce(unallocated,0)::numeric(18,2) INTO v_unallocated
  FROM public.budget_month_funding_state WHERE budget_month_id=v_month_id;
  IF NOT FOUND THEN v_unallocated:=0; END IF;

  IF p_source_kind='category' THEN
    SELECT cs.budget_id,cs.final_funded,cs.lifecycle_state,cs.category_type,c.is_active
    INTO v_source_budget_id,v_source_final,v_source_lifecycle,v_source_type,v_source_active
    FROM public.budget_category_state cs
    JOIN public.categories c ON c.id=cs.category_id
    WHERE cs.budget_month_id=v_month_id AND cs.category_id=p_source_category_id;
    IF NOT FOUND OR v_source_lifecycle<>'active' OR v_source_type<>'expense'
       OR NOT v_source_active THEN
      v_reason:='SOURCE_BUDGET_NOT_ACTIVE';
    ELSE
      SELECT coalesce(sum(total_amount),0)::numeric(18,2) INTO v_source_raw FROM public.transactions
      WHERE movement_type='expense' AND category_id=p_source_category_id
        AND transaction_date>=v_month_start AND transaction_date<(v_month_start+interval '1 month')::date;
      v_source_effective:=greatest(v_source_raw,0);
      v_capacity:=greatest(v_source_final-v_source_effective,0);
    END IF;
  ELSE v_capacity:=v_unallocated;
  END IF;

  IF p_destination_kind='category' THEN
    SELECT cs.budget_id,cs.final_funded,cs.lifecycle_state,cs.category_type,c.is_active
    INTO v_destination_budget_id,v_destination_final,v_destination_lifecycle,v_destination_type,v_destination_active
    FROM public.budget_category_state cs
    JOIN public.categories c ON c.id=cs.category_id
    WHERE cs.budget_month_id=v_month_id AND cs.category_id=p_destination_category_id;
    IF NOT FOUND OR v_destination_lifecycle<>'active' OR v_destination_type<>'expense'
       OR NOT v_destination_active THEN
      v_reason:=coalesce(v_reason,'DESTINATION_BUDGET_NOT_ACTIVE');
    ELSE
      SELECT coalesce(sum(total_amount),0)::numeric(18,2) INTO v_destination_raw FROM public.transactions
      WHERE movement_type='expense' AND category_id=p_destination_category_id
        AND transaction_date>=v_month_start AND transaction_date<(v_month_start+interval '1 month')::date;
      v_destination_after:=v_destination_final+p_amount;
    END IF;
  END IF;
  IF v_lifecycle='closed' THEN v_reason:='BUDGET_MONTH_ALREADY_CLOSED';
  ELSIF v_lifecycle='immediately_completed_unclosed' THEN v_reason:='COMPLETED_MONTH_REALLOCATION_FORBIDDEN';
  ELSIF v_lifecycle<>'current' THEN v_reason:='BUDGET_ACTION_MONTH_FORBIDDEN';
  ELSIF p_amount>v_capacity THEN v_reason:=coalesce(v_reason,'REALLOCATION_SOURCE_INSUFFICIENT');
  END IF;
  v_material:=concat_ws('|','reallocation',p_month,v_lifecycle,p_source_kind,
    coalesce(p_source_category_id::text,''),p_destination_kind,
    coalesce(p_destination_category_id::text,''),p_amount::numeric(18,2)::text,
    coalesce(v_source_budget_id::text,''),coalesce(v_source_final::text,''),
    v_source_raw::text,v_source_effective::text,v_capacity::text,
    coalesce(v_destination_budget_id::text,''),coalesce(v_destination_final::text,''),
    v_destination_raw::text,v_unallocated::text,coalesce(v_reason,''));
  v_fingerprint:=md5(v_material);
  RETURN jsonb_build_object(
    'month',p_month,'lifecycle',v_lifecycle,'source_kind',p_source_kind,
    'source_category_id',p_source_category_id,'source_budget_id',v_source_budget_id,
    'source_funded',coalesce(v_source_final,0)::numeric(18,2)::text,
    'source_raw_actual',v_source_raw::text,'source_effective_actual',v_source_effective::text,
    'source_capacity',v_capacity::text,'destination_kind',p_destination_kind,
    'destination_category_id',p_destination_category_id,'destination_budget_id',v_destination_budget_id,
    'destination_before',coalesce(v_destination_final,0)::numeric(18,2)::text,
    'destination_after',coalesce(v_destination_after,0)::numeric(18,2)::text,
    'destination_raw_actual',v_destination_raw::text,'unallocated_before',v_unallocated::text,
    'unallocated_after',(v_unallocated
      +CASE WHEN p_destination_kind='unallocated' THEN p_amount ELSE 0 END
      -CASE WHEN p_source_kind='unallocated' THEN p_amount ELSE 0 END)::numeric(18,2)::text,
    'requested_amount',p_amount::numeric(18,2)::text,'fingerprint',v_fingerprint,
    'can_apply',v_reason IS NULL,'reason',v_reason
  );
END; $$;

CREATE OR REPLACE FUNCTION public.apply_budget_reallocation(
  p_month TEXT,p_source_kind TEXT,p_source_category_id BIGINT,
  p_destination_kind TEXT,p_destination_category_id BIGINT,p_amount NUMERIC,
  p_request_key UUID,p_preview_fingerprint TEXT,p_reason TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE
  v_month_start DATE:=public.budget_month_start_from_key(p_month); v_month_id BIGINT;
  v_existing public.budget_operations%ROWTYPE; v_preview JSONB; v_operation_id BIGINT;
  v_action_id BIGINT; v_movement_id BIGINT;
BEGIN
  IF p_request_key IS NULL OR p_preview_fingerprint IS NULL OR p_preview_fingerprint!~'^[0-9a-f]{32}$' THEN
    RAISE EXCEPTION 'request_key and preview fingerprint are required' USING ERRCODE='22023';
  END IF;
  SELECT * INTO v_existing FROM public.budget_operations WHERE request_key=p_request_key;
  IF FOUND THEN
    IF v_existing.operation_type<>'budget_reallocation'
       OR v_existing.request_fingerprint<>p_preview_fingerprint THEN
      RAISE EXCEPTION 'request_key was already used for a different budget operation' USING ERRCODE='23505';
    END IF;
    RETURN jsonb_build_object('action_id',(SELECT id FROM public.budget_funding_actions WHERE operation_id=v_existing.id),
      'state',public.get_funded_budget_month(p_month));
  END IF;
  LOCK TABLE public.transactions IN SHARE MODE;
  SELECT id INTO v_month_id FROM public.budget_months WHERE month_start=v_month_start FOR UPDATE;
  PERFORM 1 FROM public.budgets WHERE budget_month_id=v_month_id
    AND category_id IN (p_source_category_id,p_destination_category_id) ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.categories
    WHERE id IN (p_source_category_id,p_destination_category_id) ORDER BY id FOR UPDATE;
  v_preview:=public.get_budget_reallocation_preview(p_month,p_source_kind,p_source_category_id,
    p_destination_kind,p_destination_category_id,p_amount);
  IF v_preview->>'fingerprint'<>p_preview_fingerprint THEN
    RAISE EXCEPTION 'BUDGET_REALLOCATION_PREVIEW_STALE: refresh the preview before applying'
      USING ERRCODE='40001';
  END IF;
  IF NOT (v_preview->>'can_apply')::boolean THEN
    RAISE EXCEPTION '%: reallocation cannot be applied',v_preview->>'reason' USING ERRCODE='23514';
  END IF;
  INSERT INTO public.budget_operations(
    budget_month_id,request_key,request_fingerprint,operation_type,effective_date,reason
  ) VALUES(v_month_id,p_request_key,p_preview_fingerprint,'budget_reallocation',v_month_start,p_reason)
  RETURNING id INTO v_operation_id;
  INSERT INTO public.budget_movements(operation_id,source_budget_id,destination_budget_id,amount)
  VALUES(v_operation_id,NULLIF(v_preview->>'source_budget_id','')::bigint,
    NULLIF(v_preview->>'destination_budget_id','')::bigint,p_amount)
  RETURNING id INTO v_movement_id;
  INSERT INTO public.budget_funding_actions(
    operation_id,action_kind,budget_month_id,destination_budget_id,requested_amount,applied_amount,
    destination_final_funded_snapshot,destination_raw_actual_snapshot,deficit_before,deficit_after
  ) VALUES(v_operation_id,'planned_reallocation',v_month_id,
    NULLIF(v_preview->>'destination_budget_id','')::bigint,p_amount,p_amount,
    CASE WHEN p_destination_kind='category' THEN (v_preview->>'destination_before')::numeric END,
    CASE WHEN p_destination_kind='category' THEN (v_preview->>'destination_raw_actual')::numeric END,
    CASE WHEN p_destination_kind='category' THEN greatest((v_preview->>'destination_raw_actual')::numeric-(v_preview->>'destination_before')::numeric,0) END,
    CASE WHEN p_destination_kind='category' THEN greatest((v_preview->>'destination_raw_actual')::numeric-(v_preview->>'destination_after')::numeric,0) END
  ) RETURNING id INTO v_action_id;
  INSERT INTO public.budget_funding_action_legs(
    action_id,source_kind,source_budget_id,amount,source_final_funded_snapshot,
    source_raw_actual_snapshot,source_effective_actual_snapshot,source_capacity_snapshot,movement_id
  ) VALUES(v_action_id,p_source_kind,NULLIF(v_preview->>'source_budget_id','')::bigint,p_amount,
    CASE WHEN p_source_kind='category' THEN (v_preview->>'source_funded')::numeric END,
    CASE WHEN p_source_kind='category' THEN (v_preview->>'source_raw_actual')::numeric END,
    CASE WHEN p_source_kind='category' THEN (v_preview->>'source_effective_actual')::numeric END,
    (v_preview->>'source_capacity')::numeric,v_movement_id);
  PERFORM public.budget_assert_reconciled(v_month_id);
  RETURN jsonb_build_object('action_id',v_action_id,'state',public.get_funded_budget_month(p_month));
END; $$;

CREATE OR REPLACE FUNCTION public.get_budget_deficit_resolution_preview(
  p_month TEXT,p_destination_category_id BIGINT,p_legs JSONB
)
RETURNS JSONB
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE
  v_lifecycle TEXT:=public.budget_action_month_lifecycle(p_month);
  v_month_start DATE:=public.budget_month_start_from_key(p_month); v_month_id BIGINT;
  v_destination RECORD; v_raw NUMERIC(18,2):=0; v_deficit NUMERIC(18,2):=0;
  v_unallocated NUMERIC(18,2):=0; v_savings NUMERIC(18,2):=0;
  v_selected JSONB:='[]'::jsonb; v_sources JSONB:='[]'::jsonb;
  v_total NUMERIC(18,2):=0; v_reason TEXT; v_material TEXT:=''; v_seen TEXT[]:='{}';
  item JSONB; v_kind TEXT; v_amount NUMERIC(18,2); v_key TEXT;
  v_source_category_id BIGINT; v_source_budget_id BIGINT;
  v_source_final NUMERIC(18,2); v_source_lifecycle TEXT; v_source_type TEXT; v_source_active BOOLEAN;
  v_source_raw NUMERIC(18,2); v_source_effective NUMERIC(18,2); v_capacity NUMERIC(18,2);
BEGIN
  IF p_legs IS NULL OR jsonb_typeof(p_legs)<>'array' OR jsonb_array_length(p_legs)=0 THEN
    RAISE EXCEPTION 'At least one deficit funding leg is required' USING ERRCODE='22023';
  END IF;
  SELECT id INTO v_month_id FROM public.budget_months WHERE month_start=v_month_start;
  SELECT cs.*,c.is_active INTO v_destination FROM public.budget_category_state cs
  JOIN public.categories c ON c.id=cs.category_id
  WHERE cs.budget_month_id=v_month_id AND cs.category_id=p_destination_category_id;
  IF NOT FOUND THEN v_reason:='NO_BUDGET_DESTINATION';
  ELSIF v_destination.lifecycle_state<>'active' OR v_destination.category_type<>'expense'
        OR NOT v_destination.is_active THEN v_reason:='DESTINATION_BUDGET_NOT_ACTIVE';
  ELSE
    SELECT coalesce(sum(total_amount),0)::numeric(18,2) INTO v_raw FROM public.transactions
    WHERE movement_type='expense' AND category_id=p_destination_category_id
      AND transaction_date>=v_month_start AND transaction_date<(v_month_start+interval '1 month')::date;
    v_deficit:=greatest(v_raw-v_destination.final_funded,0);
    IF v_deficit<=0 THEN v_reason:='NO_ACTIVE_DEFICIT'; END IF;
  END IF;
  SELECT coalesce(unallocated,0)::numeric(18,2) INTO v_unallocated
    FROM public.budget_month_funding_state WHERE budget_month_id=v_month_id;
  IF NOT FOUND THEN v_unallocated:=0; END IF;
  SELECT balance INTO v_savings FROM public.budget_savings_state;

  WITH actuals AS (
    SELECT category_id,coalesce(sum(total_amount),0)::numeric(18,2) raw_actual
    FROM public.transactions WHERE movement_type='expense'
      AND transaction_date>=v_month_start AND transaction_date<(v_month_start+interval '1 month')::date
    GROUP BY category_id
  )
  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'category_id',cs.category_id,'budget_id',cs.budget_id,'category_name',cs.category_name,
    'final_funded',cs.final_funded::text,'raw_actual',coalesce(a.raw_actual,0)::text,
    'effective_actual',greatest(coalesce(a.raw_actual,0),0)::text,
    'capacity',greatest(cs.final_funded-greatest(coalesce(a.raw_actual,0),0),0)::numeric(18,2)::text
  ) ORDER BY cs.category_name,cs.category_id),'[]'::jsonb) INTO v_sources
  FROM public.budget_category_state cs JOIN public.categories c ON c.id=cs.category_id
  LEFT JOIN actuals a ON a.category_id=cs.category_id
  WHERE cs.budget_month_id=v_month_id AND cs.category_id<>p_destination_category_id
    AND cs.lifecycle_state='active' AND cs.category_type='expense' AND c.is_active
    AND greatest(cs.final_funded-greatest(coalesce(a.raw_actual,0),0),0)>0;

  FOR item IN SELECT value FROM jsonb_array_elements(p_legs) LOOP
    v_kind:=item->>'source_kind';
    IF jsonb_typeof(item) IS DISTINCT FROM 'object'
       OR v_kind IS NULL OR v_kind NOT IN ('category','unallocated','savings')
       OR jsonb_typeof(item->'amount') IS DISTINCT FROM 'string'
       OR (item->>'amount')!~'^(0|[1-9][0-9]*)(\.[0-9]{1,2})?$' THEN
      RAISE EXCEPTION 'Deficit funding leg has an invalid source or money format' USING ERRCODE='22023';
    END IF;
    v_amount:=(item->>'amount')::numeric;
    IF v_amount<=0 OR v_amount>9999999999999999.99 THEN
      RAISE EXCEPTION 'Deficit funding leg amount must be positive' USING ERRCODE='22023';
    END IF;
    v_key:=v_kind||':'||coalesce(item->>'category_id','');
    IF v_key=ANY(v_seen) THEN RAISE EXCEPTION 'Duplicate deficit funding source' USING ERRCODE='22023'; END IF;
    v_seen:=array_append(v_seen,v_key);
    v_source_category_id:=NULL; v_source_budget_id:=NULL; v_source_final:=NULL;
    v_source_lifecycle:=NULL; v_source_type:=NULL; v_source_active:=NULL;
    v_source_raw:=NULL; v_source_effective:=NULL;
    IF v_kind='category' THEN
      SELECT cs.category_id,cs.budget_id,cs.final_funded,cs.lifecycle_state,cs.category_type,c.is_active
      INTO v_source_category_id,v_source_budget_id,v_source_final,v_source_lifecycle,v_source_type,v_source_active
      FROM public.budget_category_state cs
      JOIN public.categories c ON c.id=cs.category_id
      WHERE cs.budget_month_id=v_month_id AND cs.category_id=NULLIF(item->>'category_id','')::bigint;
      IF NOT FOUND OR v_source_category_id=p_destination_category_id
         OR v_source_lifecycle<>'active' OR v_source_type<>'expense' OR NOT v_source_active THEN
        v_reason:=coalesce(v_reason,'SOURCE_BUDGET_NOT_ACTIVE'); v_capacity:=0;
      ELSE
        SELECT coalesce(sum(total_amount),0)::numeric(18,2) INTO v_source_raw FROM public.transactions
        WHERE movement_type='expense' AND category_id=v_source_category_id
          AND transaction_date>=v_month_start AND transaction_date<(v_month_start+interval '1 month')::date;
        v_source_effective:=greatest(v_source_raw,0);
        v_capacity:=greatest(v_source_final-v_source_effective,0);
      END IF;
    ELSIF v_kind='unallocated' THEN v_capacity:=v_unallocated;
    ELSE v_capacity:=v_savings;
    END IF;
    IF v_amount>v_capacity THEN v_reason:=coalesce(v_reason,
      CASE WHEN v_kind='savings' THEN 'SAVINGS_INSUFFICIENT' ELSE 'DEFICIT_SOURCE_INSUFFICIENT' END);
    END IF;
    v_total:=v_total+v_amount;
    v_selected:=v_selected||jsonb_build_array(jsonb_build_object(
      'source_kind',v_kind,'category_id',CASE WHEN v_kind='category' THEN v_source_category_id END,
      'source_budget_id',CASE WHEN v_kind='category' THEN v_source_budget_id END,
      'amount',v_amount::numeric(18,2)::text,'source_final_funded',CASE WHEN v_kind='category' THEN v_source_final::text END,
      'source_raw_actual',CASE WHEN v_kind='category' THEN v_source_raw::text END,
      'source_effective_actual',CASE WHEN v_kind='category' THEN v_source_effective::text END,
      'source_capacity',v_capacity::numeric(18,2)::text));
    v_material:=v_material||'|'||v_key||'|'||v_amount::numeric(18,2)::text||'|'||v_capacity::text
      ||'|'||coalesce(v_source_budget_id::text,'')||'|'||coalesce(v_source_final::text,'')
      ||'|'||coalesce(v_source_raw::text,'')||'|'||coalesce(v_source_effective::text,'');
  END LOOP;
  IF v_lifecycle='closed' THEN v_reason:='BUDGET_MONTH_ALREADY_CLOSED';
  ELSIF v_lifecycle NOT IN ('current','immediately_completed_unclosed') THEN v_reason:='BUDGET_ACTION_MONTH_FORBIDDEN';
  ELSIF v_total>v_deficit THEN v_reason:=coalesce(v_reason,'DEFICIT_RESOLUTION_EXCEEDS_DEFICIT');
  END IF;
  RETURN jsonb_build_object(
    'month',p_month,'lifecycle',v_lifecycle,'destination_category_id',p_destination_category_id,
    'destination_budget_id',v_destination.budget_id,
    'current_funded',coalesce(v_destination.final_funded,0)::numeric(18,2)::text,
    'actual',v_raw::text,'deficit',v_deficit::text,'unallocated_capacity',v_unallocated::text,
    'savings_balance',v_savings::text,'eligible_source_categories',v_sources,
    'selected_legs',v_selected,'requested_resolution',v_total::numeric(18,2)::text,
    'resulting_funded',(coalesce(v_destination.final_funded,0)+v_total)::numeric(18,2)::text,
    'remaining_deficit',greatest(v_deficit-v_total,0)::numeric(18,2)::text,
    'fingerprint',md5(concat_ws('|','deficit',p_month,v_lifecycle,p_destination_category_id,
      coalesce(v_destination.budget_id::text,''),coalesce(v_destination.final_funded::text,''),
      v_raw::text,v_deficit::text,v_unallocated::text,v_savings::text,v_material,coalesce(v_reason,''))),
    'can_apply',v_reason IS NULL,'reason',v_reason
  );
END; $$;

CREATE OR REPLACE FUNCTION public.apply_budget_deficit_resolution(
  p_month TEXT,p_destination_category_id BIGINT,p_legs JSONB,p_request_key UUID,
  p_preview_fingerprint TEXT,p_reason TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE
  v_month_start DATE:=public.budget_month_start_from_key(p_month); v_month_id BIGINT;
  v_existing public.budget_operations%ROWTYPE; v_preview JSONB; v_operation_id BIGINT;
  v_action_id BIGINT; v_movement_id BIGINT; v_savings_entry_id BIGINT;
  v_savings_total NUMERIC(18,2):=0; v_funding_id BIGINT; item JSONB;
BEGIN
  IF p_request_key IS NULL OR p_preview_fingerprint IS NULL OR p_preview_fingerprint!~'^[0-9a-f]{32}$' THEN
    RAISE EXCEPTION 'request_key and preview fingerprint are required' USING ERRCODE='22023';
  END IF;
  IF p_legs IS NULL OR jsonb_typeof(p_legs)<>'array' OR jsonb_array_length(p_legs)=0 THEN
    RAISE EXCEPTION 'At least one deficit funding leg is required' USING ERRCODE='22023';
  END IF;
  SELECT * INTO v_existing FROM public.budget_operations WHERE request_key=p_request_key;
  IF FOUND THEN
    IF v_existing.operation_type<>'deficit_resolution'
       OR v_existing.request_fingerprint<>p_preview_fingerprint THEN
      RAISE EXCEPTION 'request_key was already used for a different budget operation' USING ERRCODE='23505';
    END IF;
    RETURN jsonb_build_object('action_id',(SELECT id FROM public.budget_funding_actions WHERE operation_id=v_existing.id),
      'state',public.get_funded_budget_month(p_month));
  END IF;
  LOCK TABLE public.transactions IN SHARE MODE;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_legs) AS leg(value)
    WHERE leg.value->>'source_kind'='savings') THEN
    PERFORM pg_advisory_xact_lock(hashtext('finance_tracker_budget_savings'));
  END IF;
  SELECT id INTO v_month_id FROM public.budget_months WHERE month_start=v_month_start FOR UPDATE;
  PERFORM 1 FROM public.budgets WHERE budget_month_id=v_month_id
    AND category_id IN (
      SELECT p_destination_category_id UNION
      SELECT NULLIF(leg.value->>'category_id','')::bigint
      FROM jsonb_array_elements(p_legs) AS leg(value)
      WHERE leg.value->>'source_kind'='category'
    ) ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.categories WHERE id IN (
      SELECT p_destination_category_id UNION
      SELECT NULLIF(leg.value->>'category_id','')::bigint
      FROM jsonb_array_elements(p_legs) AS leg(value)
      WHERE leg.value->>'source_kind'='category'
    ) ORDER BY id FOR UPDATE;
  v_preview:=public.get_budget_deficit_resolution_preview(p_month,p_destination_category_id,p_legs);
  IF v_preview->>'fingerprint'<>p_preview_fingerprint THEN
    RAISE EXCEPTION 'DEFICIT_RESOLUTION_PREVIEW_STALE: refresh the preview before applying'
      USING ERRCODE='40001';
  END IF;
  IF NOT (v_preview->>'can_apply')::boolean THEN
    RAISE EXCEPTION '%: deficit resolution cannot be applied',v_preview->>'reason' USING ERRCODE='23514';
  END IF;
  INSERT INTO public.budget_operations(
    budget_month_id,request_key,request_fingerprint,operation_type,effective_date,reason
  ) VALUES(v_month_id,p_request_key,p_preview_fingerprint,'deficit_resolution',v_month_start,p_reason)
  RETURNING id INTO v_operation_id;
  INSERT INTO public.budget_funding_actions(
    operation_id,action_kind,budget_month_id,destination_budget_id,requested_amount,applied_amount,
    destination_final_funded_snapshot,destination_raw_actual_snapshot,deficit_before,deficit_after
  ) VALUES(v_operation_id,'deficit_resolution',v_month_id,(v_preview->>'destination_budget_id')::bigint,
    (v_preview->>'requested_resolution')::numeric,(v_preview->>'requested_resolution')::numeric,
    (v_preview->>'current_funded')::numeric,(v_preview->>'actual')::numeric,
    (v_preview->>'deficit')::numeric,(v_preview->>'remaining_deficit')::numeric)
  RETURNING id INTO v_action_id;
  SELECT coalesce(sum((leg.value->>'amount')::numeric),0) INTO v_savings_total
  FROM jsonb_array_elements(v_preview->'selected_legs') AS leg(value)
  WHERE leg.value->>'source_kind'='savings';
  IF v_savings_total>0 THEN
    INSERT INTO public.budget_funding_entries(operation_id,amount_delta,source_kind,source_label)
    VALUES(v_operation_id,v_savings_total,'savings_withdrawal','Explicit Savings-funded deficit resolution')
    RETURNING id INTO v_funding_id;
  END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(v_preview->'selected_legs') LOOP
    INSERT INTO public.budget_movements(operation_id,source_budget_id,destination_budget_id,amount)
    VALUES(v_operation_id,NULLIF(item->>'source_budget_id','')::bigint,
      (v_preview->>'destination_budget_id')::bigint,(item->>'amount')::numeric)
    RETURNING id INTO v_movement_id;
    v_savings_entry_id:=NULL;
    IF item->>'source_kind'='savings' THEN
      INSERT INTO public.budget_savings_entries(
        operation_id,category_id,amount_delta,entry_kind,destination_budget_month_id,
        destination_budget_id,movement_id
      ) VALUES(v_operation_id,p_destination_category_id,-(item->>'amount')::numeric,'withdrawal',
        v_month_id,(v_preview->>'destination_budget_id')::bigint,v_movement_id)
      RETURNING id INTO v_savings_entry_id;
    END IF;
    INSERT INTO public.budget_funding_action_legs(
      action_id,source_kind,source_budget_id,amount,source_final_funded_snapshot,
      source_raw_actual_snapshot,source_effective_actual_snapshot,source_capacity_snapshot,
      movement_id,savings_entry_id
    ) VALUES(v_action_id,item->>'source_kind',NULLIF(item->>'source_budget_id','')::bigint,
      (item->>'amount')::numeric,NULLIF(item->>'source_final_funded','')::numeric,
      NULLIF(item->>'source_raw_actual','')::numeric,NULLIF(item->>'source_effective_actual','')::numeric,
      (item->>'source_capacity')::numeric,v_movement_id,v_savings_entry_id);
  END LOOP;
  PERFORM public.budget_assert_reconciled(v_month_id);
  IF (SELECT balance FROM public.budget_savings_state)<0 THEN
    RAISE EXCEPTION 'Savings ledger cannot have a negative balance' USING ERRCODE='23514';
  END IF;
  RETURN jsonb_build_object('action_id',v_action_id,
    'applied_amount',v_preview->>'requested_resolution','remaining_deficit',v_preview->>'remaining_deficit',
    'state',public.get_funded_budget_month(p_month));
END; $$;

CREATE OR REPLACE FUNCTION public.reverse_budget_funding_action(
  p_action_id BIGINT,p_request_key UUID,p_reason TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE
  v_original public.budget_funding_actions%ROWTYPE; v_existing public.budget_operations%ROWTYPE;
  v_month public.budget_months%ROWTYPE; v_operation_id BIGINT; v_action_id BIGINT;
  v_fingerprint TEXT:='funding_action_reverse|'||coalesce(p_action_id::text,'');
  v_required_unallocated NUMERIC(18,2):=0; v_unallocated NUMERIC(18,2):=0;
  v_savings_total NUMERIC(18,2):=0; v_original_funding public.budget_funding_entries%ROWTYPE;
  v_destination_release NUMERIC(18,2):=0; v_destination_raw NUMERIC(18,2):=0;
  v_destination_effective NUMERIC(18,2):=0; v_destination_final NUMERIC(18,2):=0;
  v_movement_id BIGINT; v_savings_entry_id BIGINT; original_leg RECORD;
BEGIN
  IF p_action_id IS NULL OR p_request_key IS NULL THEN
    RAISE EXCEPTION 'action_id and request_key are required' USING ERRCODE='22023';
  END IF;
  SELECT * INTO v_original FROM public.budget_funding_actions WHERE id=p_action_id AND action_kind<>'reversal';
  IF NOT FOUND THEN RAISE EXCEPTION 'Funding action does not exist' USING ERRCODE='P0002'; END IF;
  SELECT * INTO v_existing FROM public.budget_operations WHERE request_key=p_request_key;
  IF FOUND THEN
    IF v_existing.operation_type<>'funding_action_reversal' OR v_existing.request_fingerprint<>v_fingerprint THEN
      RAISE EXCEPTION 'request_key was already used for a different budget operation' USING ERRCODE='23505';
    END IF;
    RETURN jsonb_build_object('action_id',(SELECT id FROM public.budget_funding_actions WHERE operation_id=v_existing.id),
      'state',public.get_funded_budget_month((SELECT to_char(month_start,'YYYY-MM') FROM public.budget_months WHERE id=v_original.budget_month_id)));
  END IF;
  LOCK TABLE public.transactions IN SHARE MODE;
  IF EXISTS(SELECT 1 FROM public.budget_funding_action_legs WHERE action_id=p_action_id AND source_kind='savings') THEN
    PERFORM pg_advisory_xact_lock(hashtext('finance_tracker_budget_savings'));
  END IF;
  SELECT * INTO v_month FROM public.budget_months WHERE id=v_original.budget_month_id FOR UPDATE;
  PERFORM 1 FROM public.budgets WHERE budget_month_id=v_original.budget_month_id ORDER BY id FOR UPDATE;
  IF public.budget_action_month_lifecycle(to_char(v_month.month_start,'YYYY-MM'))='closed' THEN
    RAISE EXCEPTION 'BUDGET_MONTH_ALREADY_CLOSED: closed months require a historical correction workflow' USING ERRCODE='23514';
  ELSIF public.budget_action_month_lifecycle(to_char(v_month.month_start,'YYYY-MM'))
        NOT IN ('current','immediately_completed_unclosed') THEN
    RAISE EXCEPTION 'BUDGET_ACTION_MONTH_FORBIDDEN: action is outside the allowed month lifecycle' USING ERRCODE='23514';
  END IF;
  IF EXISTS(SELECT 1 FROM public.budget_funding_actions WHERE reversed_action_id=p_action_id) THEN
    RAISE EXCEPTION 'Funding action has already been reversed' USING ERRCODE='23505';
  END IF;
  SELECT coalesce(sum(l.amount),0) INTO v_required_unallocated
  FROM public.budget_funding_action_legs l JOIN public.budget_movements m ON m.id=l.movement_id
  WHERE l.action_id=p_action_id AND l.source_kind='category' AND m.destination_budget_id IS NULL;
  SELECT coalesce(unallocated,0)::numeric(18,2) INTO v_unallocated
  FROM public.budget_month_funding_state WHERE budget_month_id=v_original.budget_month_id;
  IF v_required_unallocated>v_unallocated THEN
    RAISE EXCEPTION 'FUNDING_ACTION_REVERSAL_BLOCKED: unallocated funding is insufficient' USING ERRCODE='23514';
  END IF;
  IF v_original.destination_budget_id IS NOT NULL THEN
    SELECT coalesce(sum(l.amount),0) INTO v_destination_release FROM public.budget_funding_action_legs l
    JOIN public.budget_movements m ON m.id=l.movement_id
    WHERE l.action_id=p_action_id AND m.destination_budget_id=v_original.destination_budget_id;
    SELECT final_funded INTO v_destination_final FROM public.budget_category_state
    WHERE budget_id=v_original.destination_budget_id;
    IF v_destination_release>v_destination_final THEN
      RAISE EXCEPTION 'FUNDING_ACTION_REVERSAL_BLOCKED: destination funding is insufficient' USING ERRCODE='23514';
    END IF;
    -- A planned move cannot be reversed by releasing money already spent at
    -- the destination. Reversing an explicit deficit resolution intentionally
    -- restores the recorded deficit and is therefore a distinct correction.
    IF v_original.action_kind='planned_reallocation' THEN
      SELECT coalesce(sum(t.total_amount),0)::numeric(18,2) INTO v_destination_raw
      FROM public.transactions t JOIN public.budgets b ON b.category_id=t.category_id
      WHERE b.id=v_original.destination_budget_id AND t.movement_type='expense'
        AND t.transaction_date>=v_month.month_start
        AND t.transaction_date<(v_month.month_start+interval '1 month')::date;
      v_destination_effective:=greatest(v_destination_raw,0);
      IF v_destination_release>greatest(v_destination_final-v_destination_effective,0) THEN
        RAISE EXCEPTION 'FUNDING_ACTION_REVERSAL_BLOCKED: destination funding has been spent' USING ERRCODE='23514';
      END IF;
    END IF;
  END IF;
  INSERT INTO public.budget_operations(
    budget_month_id,request_key,request_fingerprint,operation_type,effective_date,reason,reverses_operation_id
  ) VALUES(v_original.budget_month_id,p_request_key,v_fingerprint,'funding_action_reversal',
    v_month.month_start,p_reason,v_original.operation_id) RETURNING id INTO v_operation_id;
  INSERT INTO public.budget_funding_actions(
    operation_id,action_kind,budget_month_id,destination_budget_id,requested_amount,applied_amount,
    destination_final_funded_snapshot,destination_raw_actual_snapshot,deficit_before,deficit_after,reversed_action_id
  ) VALUES(v_operation_id,'reversal',v_original.budget_month_id,v_original.destination_budget_id,
    v_original.applied_amount,v_original.applied_amount,v_original.destination_final_funded_snapshot,
    v_original.destination_raw_actual_snapshot,v_original.deficit_before,v_original.deficit_after,p_action_id)
  RETURNING id INTO v_action_id;
  SELECT coalesce(sum(amount),0) INTO v_savings_total FROM public.budget_funding_action_legs
  WHERE action_id=p_action_id AND source_kind='savings';
  IF v_savings_total>0 THEN
    SELECT * INTO v_original_funding FROM public.budget_funding_entries WHERE operation_id=v_original.operation_id;
    INSERT INTO public.budget_funding_entries(
      operation_id,amount_delta,source_kind,source_label,reverses_funding_entry_id
    ) VALUES(v_operation_id,-v_savings_total,'savings_withdrawal','Reverse Savings-funded deficit resolution',v_original_funding.id);
  END IF;
  FOR original_leg IN
    SELECT l.*,m.source_budget_id AS original_source,m.destination_budget_id AS original_destination
    FROM public.budget_funding_action_legs l JOIN public.budget_movements m ON m.id=l.movement_id
    WHERE l.action_id=p_action_id ORDER BY l.id
  LOOP
    INSERT INTO public.budget_movements(operation_id,source_budget_id,destination_budget_id,amount)
    VALUES(v_operation_id,original_leg.original_destination,original_leg.original_source,original_leg.amount)
    RETURNING id INTO v_movement_id;
    v_savings_entry_id:=NULL;
    IF original_leg.source_kind='savings' THEN
      INSERT INTO public.budget_savings_entries(
        operation_id,category_id,amount_delta,entry_kind,reverses_entry_id,
        destination_budget_month_id,destination_budget_id,movement_id
      ) VALUES(v_operation_id,(SELECT category_id FROM public.budgets WHERE id=v_original.destination_budget_id),
        original_leg.amount,'withdrawal_reversal',original_leg.savings_entry_id,
        v_original.budget_month_id,v_original.destination_budget_id,v_movement_id)
      RETURNING id INTO v_savings_entry_id;
    END IF;
    INSERT INTO public.budget_funding_action_legs(
      action_id,source_kind,source_budget_id,amount,source_final_funded_snapshot,
      source_raw_actual_snapshot,source_effective_actual_snapshot,source_capacity_snapshot,
      movement_id,savings_entry_id
    ) VALUES(v_action_id,original_leg.source_kind,original_leg.source_budget_id,original_leg.amount,
      original_leg.source_final_funded_snapshot,original_leg.source_raw_actual_snapshot,
      original_leg.source_effective_actual_snapshot,original_leg.source_capacity_snapshot,
      v_movement_id,v_savings_entry_id);
  END LOOP;
  PERFORM public.budget_assert_reconciled(v_original.budget_month_id);
  IF (SELECT balance FROM public.budget_savings_state)<0 THEN
    RAISE EXCEPTION 'Savings ledger cannot have a negative balance' USING ERRCODE='23514';
  END IF;
  RETURN jsonb_build_object('action_id',v_action_id,
    'state',public.get_funded_budget_month(to_char(v_month.month_start,'YYYY-MM')));
END; $$;

ALTER FUNCTION public.get_funded_budget_month(TEXT) RENAME TO get_funded_budget_month_disposition;

CREATE OR REPLACE FUNCTION public.get_funded_budget_month(p_month TEXT)
RETURNS JSONB
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE v_state JSONB:=public.get_funded_budget_month_disposition(p_month); v_categories JSONB; v_history JSONB;
BEGIN
  SELECT coalesce(jsonb_agg(item||jsonb_build_object(
    'incoming_reallocation_resolution',coalesce(a.incoming_reallocation_resolution,0)::numeric(18,2)::text,
    'outgoing_reallocation',coalesce(a.outgoing_reallocation,0)::numeric(18,2)::text,
    'funding_action_adjustment_total',coalesce(a.net_funding_action_adjustment,0)::numeric(18,2)::text,
    'other_adjustments',(
      coalesce(NULLIF(item->>'other_adjustments','')::numeric,0)
      -coalesce(a.net_funding_action_adjustment,0)
    )::numeric(18,2)::text
  ) ORDER BY ordinality),'[]'::jsonb) INTO v_categories
  FROM jsonb_array_elements(coalesce(v_state->'categories','[]'::jsonb)) WITH ORDINALITY category(item,ordinality)
  LEFT JOIN public.budget_category_funding_action_state a
    ON a.budget_id=NULLIF(item->>'budget_id','')::bigint;
  SELECT coalesce(jsonb_agg(to_jsonb(h) ORDER BY h.action_id),'[]'::jsonb) INTO v_history
  FROM public.budget_funding_action_history h WHERE h.month=p_month;
  RETURN v_state||jsonb_build_object('categories',v_categories,'funding_action_history',v_history,
    'action_lifecycle',public.budget_action_month_lifecycle(p_month));
END; $$;

ALTER TABLE public.budget_funding_actions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.budget_funding_action_legs ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.budget_funding_actions,public.budget_funding_action_legs,
  public.budget_category_funding_action_state,public.budget_funding_action_history
  FROM PUBLIC,anon,authenticated,service_role;
GRANT SELECT ON public.budget_funding_actions,public.budget_funding_action_legs,
  public.budget_category_funding_action_state,public.budget_funding_action_history
  TO service_role;

REVOKE ALL ON FUNCTION public.budget_action_month_lifecycle(TEXT),
  public.validate_budget_funding_action(),public.validate_budget_funding_action_leg(),
  public.get_funded_budget_month_disposition(TEXT)
  FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.get_budget_reallocation_preview(TEXT,TEXT,BIGINT,TEXT,BIGINT,NUMERIC),
  public.apply_budget_reallocation(TEXT,TEXT,BIGINT,TEXT,BIGINT,NUMERIC,UUID,TEXT,TEXT),
  public.get_budget_deficit_resolution_preview(TEXT,BIGINT,JSONB),
  public.apply_budget_deficit_resolution(TEXT,BIGINT,JSONB,UUID,TEXT,TEXT),
  public.reverse_budget_funding_action(BIGINT,UUID,TEXT)
  FROM PUBLIC,anon,authenticated;
REVOKE EXECUTE ON FUNCTION public.get_funded_budget_month(TEXT) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.get_funded_budget_month(TEXT),
  public.get_budget_reallocation_preview(TEXT,TEXT,BIGINT,TEXT,BIGINT,NUMERIC),
  public.apply_budget_reallocation(TEXT,TEXT,BIGINT,TEXT,BIGINT,NUMERIC,UUID,TEXT,TEXT),
  public.get_budget_deficit_resolution_preview(TEXT,BIGINT,JSONB),
  public.apply_budget_deficit_resolution(TEXT,BIGINT,JSONB,UUID,TEXT,TEXT),
  public.reverse_budget_funding_action(BIGINT,UUID,TEXT)
  TO service_role;

DO $$
DECLARE v_month RECORD;
BEGIN
  FOR v_month IN SELECT id FROM public.budget_months ORDER BY id LOOP
    PERFORM public.budget_assert_reconciled(v_month.id);
  END LOOP;
  IF EXISTS(SELECT 1 FROM public.budget_funding_actions)
     OR EXISTS(SELECT 1 FROM public.budget_funding_action_legs)
     OR EXISTS(SELECT 1 FROM public.budget_savings_entries WHERE entry_kind IN ('withdrawal','withdrawal_reversal')) THEN
    RAISE EXCEPTION 'Migration 022 must not create historical reallocation or Savings withdrawal state';
  END IF;
END; $$;

COMMIT;
